window.UNIT_QUIZZES = {"islam-mezhepleri-tarihi": {"1": {"unit": 1, "unitTitle": "Din, Mezhep İlişkisi ve Mezhepleşme Süreci", "title": "İslam Mezhepleri Tarihi Quiz", "questions": [{"question": "Dinî anlayışlardaki farklılaşmaların zamanla kurumsallaşmasıyla ortaya çıkan mezheplerin yapısı göz önüne alındığında, aşağıdakilerden hangisi mezhepler hakkında doğru bir değerlendirmedir?", "answerOptions": [{"text": "Din anlayışındaki farklılaşmalar zorunlu olarak mensuplarının dinden çıkmasıyla sonuçlanır.", "isCorrect": false, "rationale": "Din anlayışındaki yorum farklılıkları dinden çıkış anlamına gelmeyip düşünsel zenginliği ve zihniyet çeşitliliğini ifade eder."}, {"text": "Mezhepler, ilahî vahyin kendisiyle birebir özdeş kabul edilmelidir.", "isCorrect": false, "rationale": "Mezhepler dinin değişmez metinlerinin kendisi değil, insanların bu metinleri anlama ve yorumlama biçimleridir."}, {"text": "Mezhepler, oluştukları coğrafi, kültürel ve siyasi vasatın izlerini bünyelerinde barındıran beşerî yapılardır.", "isCorrect": true, "rationale": "Mezhepler dinin sabit ilkelerinden ziyade insanların onu algılama biçimlerinin zamanla kurumlaşmasıyla şekillenen tarihsel ve beşerî oluşumlardır."}, {"text": "Bir mezhebin teşekkülü yalnızca tek bir tarihî olaya veya şahsa indirgenebilir.", "isCorrect": false, "rationale": "Mezheplerin ortaya çıkışında politik, sosyal, ekonomik ve insani birçok etken birlikte rol oynar."}], "hint": "Dinin sabit ilkeleri ile bu ilkelerin insanlar tarafından zaman ve mekâna bağlı olarak yorumlanması arasındaki nitelik farkını düşününüz.", "type": "multiple_choice"}, {"question": "İslam Mezhepleri Tarihi araştırmalarında betimleyici (tasviri) yöntem esastır. Buna göre aşağıdakilerden hangisi bu disiplinin temel amaçları arasında yer almaz?", "answerOptions": [{"text": "İncelenen dinî grupların hangilerinin 'hak', hangilerinin 'batıl' olduğunu hükme bağlamak", "isCorrect": true, "rationale": "Mezhepler Tarihi normatif değer yargılarında bulunmayı ve mezhepleri hak/batıl diye sınıflandırmayı Kelâm gibi kelamî/teolojik disiplinlere bırakır."}, {"text": "Müslüman toplumların sosyal ve psikolojik dinamiklerine dair verilere ulaşmak", "isCorrect": false, "rationale": "Toplumsal yapıyı ve grup davranışlarını anlamaya dönük veri toplamak mezhepler tarihçisinin görevlerindendir."}, {"text": "Dinî grupların zaman içerisinde tarihte bıraktıkları izleri tarafsızca görünür kılmak", "isCorrect": false, "rationale": "Tarihsel süreçteki izleri ve değişimleri tespit etmek araştırmacının temel sorumlulukları arasında bulunur."}, {"text": "Mezheplerin tarihî süreç içerisinde İslam medeniyetine sağladığı katkıları ortaya koymak", "isCorrect": false, "rationale": "Mezheplerin düşünsel ve kültürel mirasa katkılarını incelemek disiplinin ana hedeflerindendir."}], "hint": "Mezhepler Tarihi'nin tarafsız ve betimleyici bir bilim dalı olduğunu, yargılayıcı olmadığını hatırlayınız.", "type": "multiple_choice"}, {"question": "Sözlük anlamı itibarıyla 'daha önce benzeri olmayıp sonradan ortaya konulan şey' anlamına gelen, dinî bir terim olarak ise dinin aslından olmayan inanç veya uygulamaların dine eklenmesini ifade eden kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Bid’at", "isCorrect": true, "rationale": "Bid'at, dinin aslî kaynaklarında yer almadığı halde sonradan ihdas edilen ve dinî bir gereklilik gibi sunulan yenilikleri tanımlar."}, {"text": "İttifak", "isCorrect": false, "rationale": "İttifak, uyuşma ve görüş birliği sağlama durumunu ifade eden olumlu bir kavramdır."}, {"text": "Tefrika", "isCorrect": false, "rationale": "Tefrika, toplumdaki birlik ve beraberliğin bozulması ve gruplaşmaların meydana gelmesi anlamını taşır."}, {"text": "Makâlât", "isCorrect": false, "rationale": "Makâlât, mezheplerin görüş ve düşüncelerinin derlendiği klasik eser türlerine verilen addır."}], "hint": "Dinin aslî yapısına sonradan eklenen ve geleneksel dokuyu bozan yenilikleri tanımlayan terimi düşününüz.", "type": "multiple_choice"}, {"question": "İslam Mezhepleri Tarihi ile Din Sosyolojisi disiplinlerinin ortak inceleme alanları dikkate alındığında, aşağıdakilerden hangisi her iki disiplinin kesiştiği konulardan biri olamaz?", "answerOptions": [{"text": "İncelenen bir mezhebin inanç esaslarının mutlak doğruluğunun teolojik olarak kanıtlanması", "isCorrect": true, "rationale": "Bir mezhebin inançlarının doğruluğunu kanıtlamaya çalışmak normatif bir çaba olup betimleyici sosyal bilimlerin amacına aykırıdır."}, {"text": "Toplumsal kriz dönemlerinde ortaya çıkan 'kurtarıcı bekleme' (mehdilik) fikrinin psiko-sosyal nedenleri", "isCorrect": false, "rationale": "Toplumsal beklentiler ve psiko-sosyal tepkiler her iki disiplinin de ortaklaşa odaklandığı alanlardandır."}, {"text": "Bir dinî grupta cemaatsel hiyerarşinin ve örgütlenme yapısının teşekkülü", "isCorrect": false, "rationale": "Toplumsal hiyerarşi ve cemaatleşme süreçleri hem sosyolojinin hem de mezhepler tarihinin ortak konusudur."}, {"text": "Mezhep mensupları arasındaki grupsal dayanışma ve sosyal bağlar", "isCorrect": false, "rationale": "Grup içi bütünleşme ve dayanışma mekanizmaları sosyal bilim araştırmalarında ortaklaşa incelenir."}], "hint": "Sosyal bilimlerin betimleyici yaklaşımı ile teolojinin doğrulama çabası arasındaki sınırı göz önüne alınız.", "type": "multiple_choice"}, {"question": "Her insanın zihinsel kapasitesi, algılama biçimi, mizaç ve karakter yapısının birbirinden farklı olması dinî metinleri yorumlarken çeşitliliğe yol açar. Bu durum mezheplerin ortaya çıkış sebeplerinden hangisine doğrudan örnektir?", "answerOptions": [{"text": "Nassların tabiatı", "isCorrect": false, "rationale": "Nassların tabiatı, dinî metinlerin dilsel özellikleri ve anlam katmanlarıyla ilişkilidir."}, {"text": "Coğrafi ve çevresel şartlar", "isCorrect": false, "rationale": "Coğrafi şartlar, fiziki çevre ve iklim gibi dış unsurlarla bağlantılıdır."}, {"text": "Sosyo-politik gelişmeler", "isCorrect": false, "rationale": "Sosyo-politik gelişmeler iktidar, yönetim ve toplumsal olayları kapsar."}, {"text": "İnsanın tabiatı", "isCorrect": true, "rationale": "İnsanın kişisel, psikolojik ve zihinsel farkları metinleri anlama ve dünyayı algılama biçimlerini doğrudan yönlendirir."}], "hint": "Bireyin kendi kişisel psikolojisi ve zihinsel yapısının algı üzerindeki rolünü değerlendiriniz.", "type": "multiple_choice"}, {"question": "Kur'an-ı Kerim'de yer alan bazı ayetlerin muhkem, bazılarının müteşâbih olması veya dilsel açıdan farklı anlamlara gelmeye elverişli yapısı mezhepleşme sürecini hızlandırmıştır. Bu durum hangi temel sebeple açıklanır?", "answerOptions": [{"text": "İnsanın toplumsal bir varlık olması", "isCorrect": false, "rationale": "Toplumsal varlık olmak cemaatleşme ve kurumlaşma olgusunu açıklar."}, {"text": "Nassların tabiatı", "isCorrect": true, "rationale": "Dinî metinlerin açık, kapalı, mecaz veya yorumlanmaya elverişli dilsel özellikleri farklı içtihatların doğmasını sağlar."}, {"text": "Ekonomik faktörler", "isCorrect": false, "rationale": "Ekonomik faktörler ganimet, vergi ve gelir dağılımı gibi maddi süreçlerle ilişkilidir."}, {"text": "Farklı kültürlerle karşılaşılması", "isCorrect": false, "rationale": "Farklı kültürlerle karşılaşma, dış düşünce sistemlerinin İslam coğrafyasına girmesiyle ilgilidir."}], "hint": "Kutsal metinlerin anlamsal ve dilsel özelliklerinin yorum çeşitliliğine imkân tanımasını düşününüz.", "type": "multiple_choice"}, {"question": "Din Fenomenolojisi yaklaşımının İslam Mezhepleri Tarihi araştırmalarına sağladığı en belirgin katkı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Siyasi mücadelelerin mezhepleşmeye etkisini belgelere dayanarak açıklaması", "isCorrect": false, "rationale": "Tarihsel belgeleri analiz etmek genel tarih metodolojisinin konusudur."}, {"text": "Dinler ve mezhepler arasındaki ortak olguları, sembolleri ve tezahürleri tespit etmesi", "isCorrect": true, "rationale": "Din fenomenolojisi, dinî olgu ve tecrübeleri önyargısız bir şekilde tanımlayıp ortak sembol ve yapıları ortaya çıkarmayı sağlar."}, {"text": "Yalnızca fıkhi mezheplerin içtihat usullerini incelemesi", "isCorrect": false, "rationale": "Fenomenoloji belirli bir fıkhi usulle sınırlı olmayıp geniş çaplı dinî tezahürlerle ilgilenir."}, {"text": "Hangi mezhebin inanç ilkelerinin ayetlere daha uygun olduğunu ispatlaması", "isCorrect": false, "rationale": "Din fenomenolojisi normatif doğruluk veya yanlışlık değerlendirmesinde bulunmaz."}], "hint": "İnançların özündeki yapısal benzerlikleri ve ortak dinsel tecrübe biçimlerini inceleyen yöntemi düşününüz.", "type": "multiple_choice"}, {"question": "Dinin özünde yer alan birlik ruhunun ve toplumsal bütünlüğün bozulmasını, Müslümanlar arasında fikirsel ve siyasal ayrılıkların baş göstermesini ifade eden kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İttifak", "isCorrect": false, "rationale": "İttifak görüş birliği ve uzlaşma anlamı taşır."}, {"text": "Makâlât", "isCorrect": false, "rationale": "Makâlât, mezhep görüşlerini derleyen literatür türüdür."}, {"text": "Tefrika", "isCorrect": true, "rationale": "Tefrika, Müslüman toplum bünyesinde meydana gelen bölünmeleri ve anlaşmazlıkları tanımlayan temel kavramdır."}, {"text": "Celâdet", "isCorrect": false, "rationale": "Celâdet kahramanlık ve cesaret anlamına gelen bir sözcüktür."}], "hint": "Birlik ve beraberliğin zıddı olan bölünme ve gruplaşma durumunu ifade eden terimi hatırlayınız.", "type": "multiple_choice"}, {"question": "İslam Mezhepleri Tarihi araştırmalarında bir mezhebin doğuşunu tek bir olaya veya şahsa indirgemek metodolojik bir hata olarak kabul edilir. Buna göre mezhepleşme süreciyle ilgili en doğru yaklaşım aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mezhepler; psiko-sosyal, politik, ekonomik ve dinî etkenlerin zamanla birleşmesiyle oluşan süreçsel yapılardır.", "isCorrect": true, "rationale": "Mezhepleşme birdenbire değil, çok boyutlu unsurların uzun süreli etkileşimi sonucu kademeli olarak gerçekleşir."}, {"text": "Dinin anlaşılma biçimleri yaşanılan zaman ve coğrafyadan tamamen bağımsızdır.", "isCorrect": false, "rationale": "İnsanların dini algılama tarzları içinde bulundukları zamandan ve sosyo-kültürel ortamdan doğrudan etkilenir."}, {"text": "Mezhepler, Hz. Peygamber'in vefatının hemen ardından eksiksiz birer sistem olarak ortaya çıkmıştır.", "isCorrect": false, "rationale": "Mezhepler kısa sürede değil, tarihsel süreçte kurumsallaşarak oluşmuştur."}, {"text": "Politik çekişmeler mezheplerin teşekkülünde hiçbir rol oynamamıştır.", "isCorrect": false, "rationale": "Siyasal iktidar ve liderlik mücadeleleri mezhepleşmeyi tetikleyen ana unsurlardandır."}], "hint": "Mezheplerin oluşumundaki çok faktörlü ve zamana yayılan kurumsallaşma karakterini göz önüne alınız.", "type": "multiple_choice"}, {"question": "Mezhepler Tarihi kaynakları incelenirken mezheplerin birbirini tekfir etmesi veya suçlayıcı bir dil kullanması araştırmacı açısından bir zorluk oluşturur. Bu durum aşağıdakilerden hangisine yol açar?", "answerOptions": [{"text": "Mezheplerin tarihsel açıdan haklılığının bilimsel olarak kanıtlanmasını sağlar.", "isCorrect": false, "rationale": "Suçlayıcı ifadeler bilimsel kanıt sunmaz, aksine önyargı oluşturur."}, {"text": "Ana kaynaklardaki verilerin nesnel ve tarafsız biçimde analiz edilmesini zorlaştırır.", "isCorrect": true, "rationale": "Eserlerdeki tarafgir ve ötekileştirici ifadeler, olguların tarafsız bir gözle tespit edilmesini ve doğru verilere ulaşılmasını güçleştirir."}, {"text": "Metinlerin tek bir mutlak doğru yorumunun yapılmasına katkı sunar.", "isCorrect": false, "rationale": "Tarafgir üslup yorum zenginliğini objektif şekilde değerlendirmeyi engeller."}, {"text": "Farklı gruplar arasında bilimsel diyalog kurulmasını kolaylaştırır.", "isCorrect": false, "rationale": "Suçlayıcı ve tekfirci üslup diyalog imkânlarını ortadan kaldırır."}], "hint": "Tarafgir kaynakların nesnellik ve bilimsel tarafsızlık üzerindeki olumsuz etkisini düşününüz.", "type": "multiple_choice"}, {"question": "Hz. Peygamber'in vefatının ardından yaşanan halife seçimi tartışmaları, Sıffîn Savaşı ve Tahkim Olayı gibi tarihî gelişmeler mezheplerin ortaya çıkışında öncelikle hangi faktörün etkili olduğunu gösterir?", "answerOptions": [{"text": "Sosyo-politik faktörler", "isCorrect": true, "rationale": "Yönetim, hilafet ve iktidar mücadeleleri toplumsal ve siyasal nitelikte olup mezhepleşmeyi tetikleyen ana olaylardandır."}, {"text": "Farklı din ve kültürlerle temas", "isCorrect": false, "rationale": "Kültürel temas fetihler sonrasında dış dünyayla kurulan ilişkileri kapsar."}, {"text": "İnsanın tabiatı", "isCorrect": false, "rationale": "İnsanın tabiatı bireysel psikolojik ve zihinsel farklılıklarla ilgilidir."}, {"text": "Nassların tabiatı", "isCorrect": false, "rationale": "Nassların tabiatı metinsel yorum imkânlarını kapsar."}], "hint": "Devlet yönetimi, iktidar ve liderlik mücadelelerinin hangi alanla ilgili olduğunu hatırlayınız.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi 'mezhep' kavramının 'din' kavramı ile olan ilişkisini en doğru şekilde ifade eder?", "answerOptions": [{"text": "Belli bir mezhebe mensup olmak dine inanmanın mutlak şartıdır.", "isCorrect": false, "rationale": "Dinin temeli ilahi nasslardır; belirli bir beşerî ekolü benimsemek dinin varlık şartı değildir."}, {"text": "Mezhep dinin bizzat kendisidir ve hiçbir şekilde değiştirilemez.", "isCorrect": false, "rationale": "Mezhep dinin kendisi değil, insanların onu anlama ve uygulama biçimidir."}, {"text": "Mezhepler, dinin sabit metinlerinin insanlar tarafından zamana ve mekâna göre yapılan farklı anlayış ve yorum biçimleridir.", "isCorrect": true, "rationale": "Din vahye dayalı ilahi ilkeler bütünü iken mezhep bu ilkelerin beşerî düzlemde algılanış ve uygulanış şeklidir."}, {"text": "Mezhepler dinin aslına hiçbir katkısı olmayan yapay oluşumlardır.", "isCorrect": false, "rationale": "Mezhepler dinin farklı coğrafyalarda ve kültürlerde yaşanmasına imkân tanıyan düşünsel zenginliklerdir."}], "hint": "İlahî olan 'din' ile beşerî olan 'din anlayışı' arasındaki temel farkı göz önüne alınız.", "type": "multiple_choice"}]}, "2": {"unit": 2, "unitTitle": "Mezheplerin Ortaya Çıkış Nedenleri", "title": "İslam Mezhepleri Testi", "questions": [{"question": "Mezheplerin doğuşunda etkili olan bireysel unsurlar göz önüne alındığında, insanların aynı nassı veya olayı farklı şekillerde algılayıp yorumlamalarının temel sebebi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dini metinlerin sadece tek bir somut anlama izin verecek şekilde yazılması", "isCorrect": false, "rationale": "Nassların yapısında yorumlanmaya açık veya müteşâbih ifadelerin bulunması çeşitliliğe imkân tanır, bireysel farklılıklar ise bunu belirler."}, {"text": "İnsanın doğuştan gelen mizaç, zihinsel kapasite ve kişilik yapısının farklı olması", "isCorrect": true, "rationale": "İnsanın yapısının kendine özgü olması, kendisini ve dış dünyayı algılama ve yorumlama biçimlerini doğrudan etkiler."}, {"text": "Ekonomik gelir düzeyinin bireylerin mezhepsel tercihlerini tamamen belirlemesi", "isCorrect": false, "rationale": "Ekonomik faktörler toplumsal süreçlerde etkili olsa da bireysel algı ve yorum farkının öz kaynağı insanın mizaç ve kişilik yapısıdır."}, {"text": "Siyasi otoritenin toplumda tek tip düşünce yapısını zorunlu kılması", "isCorrect": false, "rationale": "Siyasi baskılar farklı yorumları bastırabilir ancak bireysel algı farklılıklarının temel nedeni insani mizaç ve kişisel yapıdır."}], "hint": "İnsanların düşünce ve tutumlarının oluşumunda doğuştan sahip oldukları bireysel özellikleri dikkate alınız.", "type": "multiple_choice"}, {"question": "Tarihte ortaya çıkan farklı mezheplerin kendi görüşlerini temellendirmek için Kur'an-ı Kerim ayetlerine başvurması, mezheplerin ortaya çıkışındaki hangi faktöre örnek teşkil eder?", "answerOptions": [{"text": "Nassların tabiatı", "isCorrect": true, "rationale": "Ayetlerin yorumlanmaya elverişli yapısı ve farklı anlam boyutları barındırması (müteşâbih/muhkem niteliği), mezheplerin kendi fikirlerini metne dayandırmasına imkân tanır."}, {"text": "Coğrafi ve fiziki şartlar", "isCorrect": false, "rationale": "İklim ve coğrafya yaşam tarzını etkiler ancak dini metinlerin farklı yorumlanmasıyla doğrudan ilgili değildir."}, {"text": "Farklı din ve kültürlerle karşılaşma", "isCorrect": false, "rationale": "Bu durum dış felsefi geleneklerle etkileşimi ifade eder, metinlerin kendi iç yapısıyla ilgili değildir."}, {"text": "Toplumsal tabakalaşma ve ekonomik dinamikler", "isCorrect": false, "rationale": "Ekonomik etkenler sosyal gruplaşmayı açıklayabilir ancak nasslara atıfta bulunarak görüş meşrulaştırma nassların yapısıyla ilgilidir."}], "hint": "Kutsal metinlerin dilsel, yorumsal ve anlamsal özelliklerini göz önünde bulundurunuz.", "type": "multiple_choice"}, {"question": "Neo-Platonist ve Gnostik felsefi düşüncelerin İsmailîlik aracılığıyla İslam düşüncesine taşınması, mezheplerin doğuşuna etki eden hangi unsurun sonucudur?", "answerOptions": [{"text": "Farklı din, inanç, kültür ve felsefelerle karşılaşma", "isCorrect": true, "rationale": "İslam coğrafyasının genişlemesiyle Yunan, Mısır ve İran felsefi birikimleriyle temas kurulmuş ve bu durum bazı mezheplerin fikir yapısını şekillendirmiştir."}, {"text": "Arap dilinin gramer ve edebi yapısındaki değişimler", "isCorrect": false, "rationale": "Dilsel yapı nassların anlaşılmasında etkili olmakla birlikte dış felsefi sistemlerin benimsenmesini açıklamakta yetersiz kalır."}, {"text": "İnsanın psikolojik yapısı ve mizaç farklılıkları", "isCorrect": false, "rationale": "Bireysel mizaç içsel bir etken olup dış medeniyetlerden ve felsefi akımlardan aktarılan düşünceler dış çevresel etkileşimdir."}, {"text": "Hz. Peygamber'in vefatından hemen sonraki halife seçimi tartışmaları", "isCorrect": false, "rationale": "Halife seçimleri iç sosyo-politik bir faktördür; felsefi akımların transferi ise kültürlerarası karşılaşmanın ürünüdür."}], "hint": "İslam fetihleri sonrası farklı medeniyet havzalarıyla kurulan fikir alışverişini düşününüz.", "type": "multiple_choice"}, {"question": "Sıffîn Savaşı'nın ardından gerçekleşen Tahkim Hadisesi sonucunda, Hz. Ali'nin hakem tayin etmesini kabul etmeyerek ondan ayrılan ve ilk siyasi/itikadi fırkalardan biri kabul edilen grup aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Eş'arîlik", "isCorrect": false, "rationale": "Eş'arîlik, Ebû'l-Hasan el-Eş'arî tarafından kurulan Ehl-i Sünnet kelam ekolüdür."}, {"text": "Mürcie", "isCorrect": false, "rationale": "Mürcie, iç çatışmalar karşısında tarafsız kalıp hükmü Allah'a ertelemeyi savunan gruptur; Tahkim'de ayrılan sert mizaçlı grup değildir."}, {"text": "Haricilik", "isCorrect": true, "rationale": "Tahkim olayını kabul ettiği gerekçesiyle Hz. Ali'ye karşı çıkan ve ordudan ayrılan topluluk Hariciler (Hâricîlik) olarak adlandırılmıştır."}, {"text": "Mu'tezile", "isCorrect": false, "rationale": "Mu'tezile daha sonraki dönemde Hasan-ı Basrî'nin meclisinden ayrılan Vâsıl b. Atâ tarafından kurulan kelami bir mezheptir."}], "hint": "Siyasi uzlaşıyı reddedip 'Hüküm ancak Allah'ındır' sloganıyla ortaya çıkan ayrılıkçı grubu hatırlayınız.", "type": "multiple_choice"}, {"question": "Hz. Osman'ın hilafetinin son yıllarında otoritesinin sarsılmasına ve toplumsal huzursuzlukların tırmanmasına yol açan temel sosyo-politik sebep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Yalancı peygamberler ve zekât vermeyen kabilelerle savaşmayı reddetmesi", "isCorrect": false, "rationale": "Yalancı peygamberler ve zekât vermeyenlerle mücadele Hz. Ebû Bekir döneminin ilk icraatıdır."}, {"text": "Devlet makamlarına akrabalarını getirmesiyle Hâşimî-Ümeyyeoğulları çekişmesinin yeniden canlanması", "isCorrect": true, "rationale": "Hz. Osman'ın akrabalarını önemli görevlere ataması İslam öncesi kabilevi rekabetleri tetiklemiş ve siyasi muhalefeti artırmıştır."}, {"text": "Kur'an metinlerinin tamamen yok edilerek yerine yeni bir kitabın yazılması", "isCorrect": false, "rationale": "Hz. Osman Kur'an'ı çoğaltıp ana merkezlere göndermiştir; yok etme gibi bir durum söz konusu değildir."}, {"text": "Orduyu tamamen dağıtarak fetih hareketlerini kalıcı olarak bitirmesi", "isCorrect": false, "rationale": "Hz. Osman döneminde fetihler genişlemiş, ilk dönemlerde büyük askeri başarılar kazanılmıştır."}], "hint": "İslam öncesi döneme kadar uzanan kabilevi aidiyetlerin devlet yönetimine yansımasını göz önünde bulundurunuz.", "type": "multiple_choice"}, {"question": "Mezheplerin 'dinin anlaşılma biçimleri' ve 'beşerî oluşumlar' olarak değerlendirilmesi, aşağıdakilerden hangisini doğrular?", "answerOptions": [{"text": "Mezheplerin dinin kendisiyle özdeşleştirilemeyeceğini ve içinde geliştikleri ortamın izlerini taşıdığını", "isCorrect": true, "rationale": "Dinin kendisi ilahi iken, mezhepler insanların dini anlama ve yorumlama süreçlerinin zamanla kurumsallaşmış beşerî ürünleridir."}, {"text": "Farklı mezhepsel yorumların insanları zorunlu olarak dinden çıkardığını", "isCorrect": false, "rationale": "Anlayış farklılıkları zenginlik veya beşerî yorum farkıdır, doğrudan dinden çıkma sebebi sayılamaz."}, {"text": "Mezheplerin mutlak ve değişmez ilahi vahiyler olduğunu", "isCorrect": false, "rationale": "Mezhepler beşerî anlayışlar olduğu için mutlak ilahi vahiy niteliğinde değildir."}, {"text": "Bir mezhebin ortaya çıkışının tek bir nedene veya kişiye indirgenebileceğini", "isCorrect": false, "rationale": "Mezheplerin doğuşunda psiko-sosyal, politik ve ekonomik pek çok etken birlikte rol oynar."}], "hint": "İlahi olan din ile beşeri olan yorum arasındaki farkı düşününüz.", "type": "multiple_choice"}, {"question": "Dinin özündeki ve Müslüman toplumun bütünlüğündeki bozulmayı ifade eden, sözlükte ise 'önceden olmadığı halde sonradan icat edilen şey' anlamına gelen kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Bid’at", "isCorrect": true, "rationale": "Bid'at sözlükte sonradan çıkarılan şey, terim olarak ise dinin aslında olmadığı halde dine eklenen veya eksiltilen hususları ifade eder."}, {"text": "İttifak", "isCorrect": false, "rationale": "İttifak birlik ve uyuşma anlamına gelir, bozulmayı değil bütünlüğü temsil eder."}, {"text": "Tefrika", "isCorrect": false, "rationale": "Tefrika ayrılık ve bölünme demektir; dinin özündeki icat edilmiş yenilik anlamını doğrudan karşılayan kavram Bid'attır."}, {"text": "Makâlât", "isCorrect": false, "rationale": "Makâlât, mezheplerin görüşlerini ve mezhep edebiyatını ifade eden klasik eser türüdür."}], "hint": "Din alanında sonradan ortaya çıkarılan usul veya inanç yenilikleri için kullanılan kavramı hatırlayınız.", "type": "multiple_choice"}, {"question": "Erken dönem İslam tarihinde yaşanan Cemel ve Sıffîn Savaşları sonrasında Müslümanların birbirini öldürmesi, ikilamda kalan Müslümanlar arasında aşağıdaki konulardan hangisinin tartışılmasına zemin hazırlamıştır?", "answerOptions": [{"text": "Kutsal mekânların ziyaret edilme usulleri", "isCorrect": false, "rationale": "Bu konu ibadet fıkhı ile ilgilidir, iç savaşların doğurduğu iman ve yönetim tartışmalarından bağımsızdır."}, {"text": "Yunan felsefi eserlerinin Arapçaya tercüme edilip edilmemesi", "isCorrect": false, "rationale": "Tercüme faaliyetleri Abbasiler döneminde yoğunlaşmıştır; ilk savaşların hemen arkasından çıkan temel sorun iman-küfür sınırıdır."}, {"text": "Büyük günah işleyen kişinin (mürtekib-i kebîre) dini statüsü ve iman-amel ilişkisi", "isCorrect": true, "rationale": "Müslümanların birbirleriyle savaşması 'büyük günah işleyen mümin midir, kâfir midir?' tartışmasını tetiklemiş ve ilk kelami kutuplaşmaları doğurmuştur."}, {"text": "Arapça gramer kurallarının tespiti ve sözlük çalışmaları", "isCorrect": false, "rationale": "Gramer çalışmaları dilsel bir ihtiyaçtır, iç savaşların yarattığı itikadi krizle doğrudan ilgili değildir."}], "hint": "Büyük günah işleyenin durumu etrafında şekillenen iman tartışmasını göz önünde bulundurunuz.", "type": "multiple_choice"}, {"question": "Bedevi kabilelerin sert ve tavizsiz yaşam tarzlarının dini metinleri okuma biçimlerine yansıması ve katı bir tutum takınmaları, mezheplerin doğuşunda etkili olan faktörlerden hangisine örnektir?", "answerOptions": [{"text": "Zekât vergilerinin toplanma yöntemlerindeki teknik değişimler", "isCorrect": false, "rationale": "İdari düzenlemeler mizaç ve katı dini tutum oluşumunun temel nedeni değildir."}, {"text": "Sadece yabancı felsefe metinlerinin tercüme edilmesi", "isCorrect": false, "rationale": "Çöl yaşamındaki bedevilerin tutumu felsefi tercümelerden ziyade kendi mizaç ve sosyal şartlarının ürünüdür."}, {"text": "İnsanın tabiatı ve sosyal çevresi", "isCorrect": true, "rationale": "Topluluğun yaşam şartları, kültürel yapısı ve mizaç özellikleri dini anlama ve yaşama biçimlerini doğrudan etkiler."}, {"text": "Kur'an ayetlerinin çoğaltılarak merkezlere gönderilmesi", "isCorrect": false, "rationale": "Metinlerin çoğaltılması standardize etme amacı taşır, bedevi mizacının sertliğini açıklamaz."}], "hint": "Karakter, mizaç ve yaşam çevresinin insan tutumlarına etkisini düşününüz.", "type": "multiple_choice"}, {"question": "İnsanın fiillerinde tamamen özgür olduğunu, Allah'ın belirlediği bir kader yerine insanın kendi kaderini kendisinin tayin ettiğini savunan ilk mezhep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mücessime", "isCorrect": false, "rationale": "Mücessime, Allah'ı cisimlere benzeterek somutlaştıran akımdır."}, {"text": "İbâdiyye", "isCorrect": false, "rationale": "İbâdiyye Hariciliğin günümüze ulaşan tek ılımlı koludur; kader tartışmasının merkezindeki ilk akım değildir."}, {"text": "Cebriyye", "isCorrect": false, "rationale": "Cebriyye, insanın hiçbir iradesi olmadığını ve rüzgâr önündeki yaprak gibi tamamen mecbur olduğunu savunur."}, {"text": "Kaderiyye", "isCorrect": true, "rationale": "Kaderiyye, kaderi reddederek insanın kendi fiillerinin yaratıcısı olduğunu ve kaderini kendisinin belirlediğini savunur."}], "hint": "İnsana fiil ve kader tayin etme gücü veren mezhebin adını hatırlayınız.", "type": "multiple_choice"}, {"question": "Emeviler döneminde yaşanan siyasi çatışmalar ve karşılıklı tekfir söylemleri karşısında; amel ile imanı ayırarak 'günah işleyen kimsenin durumunu Allah'a ertelemeyi' ilke edinen kuşatmacı anlayış aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Haricilik", "isCorrect": false, "rationale": "Haricilik günah işleyenleri doğrudan tekfir eden dışlayıcı ve radikal bir tutum sergilemiştir."}, {"text": "Mürcie", "isCorrect": true, "rationale": "Mürcie, 'ertelemek' anlamına gelir ve büyük günah işleyenlerin durumunu Allah'a bırakarak Müslüman toplumda bütünleştirici bir rol oynamıştır."}, {"text": "Cebriyye", "isCorrect": false, "rationale": "Cebriyye fiillerin insana değil Allah'a ait olduğunu savunur, imanı erteleme ilkesiyle öne çıkmaz."}, {"text": "Mu'tezile", "isCorrect": false, "rationale": "Mu'tezile büyük günah işleyeni ne mümin ne kâfir sayıp iki konum arasında bir yerde görür."}], "hint": "Kelime anlamı 'erteleyen / tehir eden' olan ve Müslümanları tekfir etmekten kaçınan mezhebi düşününüz.", "type": "multiple_choice"}, {"question": "Mu'tezile mezhebinin kurucusu Vâsıl b. Atâ'nın, büyük günah işleyen kimsenin ne tam mümin ne de tam kâfir olduğunu, iki konum arasında bir yerde (el-Menzile beyne'l-Menzileteyn) bulunacağını belirtmesi aşağıdaki tartışmalardan hangisine verilen bir yanıttır?", "answerOptions": [{"text": "Allah'ın sıfatlarının zâtı ile aynı olup olmadığı meselesi", "isCorrect": false, "rationale": "Bu konu Mu'tezile'nin Tevhid prensibi kapsamındadır."}, {"text": "Kötülüklerin engellenmesi ve iyiliğin emredilmesi ilkesi", "isCorrect": false, "rationale": "Bu konu Emir bi'l-Ma'rûf Nehiy 'ani'l-Münker ilkesi ile alakalıdır."}, {"text": "Ahirette müminlerin cennet ve cehenneme sevk edilmesi kararı", "isCorrect": false, "rationale": "Bu konu Va'd ve Vaîd prensibiyle açıklanır."}, {"text": "Büyük günah işleyenin (mürtekib-i kebîre) durumu meselesi", "isCorrect": true, "rationale": "el-Menzile beyne'l-Menzileteyn prensibi doğrudan büyük günah işleyen kişinin iman-küfür bakımından konumu ile alakalıdır."}], "hint": "Hasan-ı Basrî'nin meclisinde büyük günah işleyenin durumu tartışılırken Vâsıl b. Atâ'nın ortaya koyduğu görüşü hatırlayınız.", "type": "multiple_choice"}]}, "3": {"unit": 3, "unitTitle": "İlk Mezhepler (Haricilik, Şia, Maturidilik vb.)", "title": "İslâm Mezhepleri Testi", "questions": [{"question": "Dinî terim olarak Hz. Peygamber ve Ashâbı döneminde bulunmayıp sonradan ortaya çıkan, dinin özüne müdahale niteliğindeki yeni anlayış ve uygulamaları ifade eden kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dalâlet", "isCorrect": false, "rationale": "Doğru yoldan sapma ve hidayetin zıddı durumu ifade eden genel bir kavramdır."}, {"text": "Tefrika", "isCorrect": false, "rationale": "Birlik ve beraberliğin bozulması, ayrılık ve toplumsal bölünme anlamına gelir."}, {"text": "Bid’at", "isCorrect": true, "rationale": "Dinde Asr-ı Saadet'ten sonra ortaya çıkan ve şer'i dayanağı bulunmayan yenilikler bid’at olarak tanımlanır."}, {"text": "Celâdet", "isCorrect": false, "rationale": "Yiğitlik, cesaret ve sertlik anlamına gelen ahlaki bir vasıftır."}], "hint": "Sözlük anlamı 'önceden benzeri olmadan icat edilen şey' olan bu kavram, dinde sonradan ortaya çıkan yenilikleri ifade eder.", "type": "multiple_choice"}, {"question": "Sıffîn Savaşı sırasında yaşanan Tahkim Hadisesi'nin ardından, Hz. Ali'nin insanları hakem tayin etmesini kabul etmeyerek onun ordusundan ayrılan ilk siyasi fırka aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mürcie", "isCorrect": false, "rationale": "Sahabe arasındaki siyasi çekişmelerde tarafsız kalmayı ve hükmü Allah'a ertelemeyi tercih eden gruptur."}, {"text": "Zeydiyye", "isCorrect": false, "rationale": "Zeyd b. Ali'nin Emevilere karşı başlattığı hareketle şekillenen ılımlı Şiî koludur."}, {"text": "Mu’tezile", "isCorrect": false, "rationale": "Büyük günah tartışması sonucu Hasan-ı Basrî'nin meclisinden ayrılarak akılcı kelam ekolünü kurmuşlardır."}, {"text": "Haricilik", "isCorrect": true, "rationale": "Tahkim olayında insan hakemliğine itiraz ederek 'Hüküm ancak Allah'ındır' düşüncesiyle ana gövdeden ayrılan ilk gruptur."}], "hint": "Hakem olayına sert bir tutumla karşı çıkan ve ayrılıkçı bir yapı oluşturan gruptur.", "type": "multiple_choice"}, {"question": "Büyük günah işleyen kimsenin (mürtekib-i kebîre) durumu konusunda hocası Hasan-ı Basrî ile görüş ayrılığına düşerek onun ders halkasını terk eden ve Mu'tezile mezhebinin temellerini atan alim kimdir?", "answerOptions": [{"text": "Bişr b. el-Mu'temir", "isCorrect": false, "rationale": "Mu'tezile'nin Bağdat ekolünün kurucusu kabul edilen kelamcıdır."}, {"text": "Ebû'l-Hüzeyl el-Allâf", "isCorrect": false, "rationale": "Mu'tezile'nin sistemli kelam konularını geliştiren sonraki dönem alimlerindendir."}, {"text": "Cehm b. Safvân", "isCorrect": false, "rationale": "İnsanın fiillerinde tamamen mecbur olduğunu savunan Cebriyye düşüncesinin önde gelen ismidir."}, {"text": "Vâsıl b. Atâ", "isCorrect": true, "rationale": "Büyük günah işleyenin ne tam mümin ne de tam kafir olduğunu ileri sürerek hocasının meclisinden ayrılmış ve Mu'tezile'yi kurmuştur."}], "hint": "Hocası Hasan-ı Basrî'nin 'O bizden ayrıldı' ifadesiyle anılan kurucu şahsiyettir.", "type": "multiple_choice"}, {"question": "Mu'tezile ekolünün temel prensiplerinden biri olan 'el-Menzile beyne'l-menzileteyn' esası, kelam tarihindeki hangi temel tartışmayla doğrudan ilgilidir?", "answerOptions": [{"text": "Devlet başkanının Kureyş soyundan seçilmesi gerekliliği", "isCorrect": false, "rationale": "Bu husus imamet ve siyaset teorisine dair içtihadı bir konudur."}, {"text": "Büyük günah işleyen kişinin imandaki durumu", "isCorrect": true, "rationale": "Bu prensip, büyük günah işleyen kimsenin iman ile küfür arasında ara bir konumda yer aldığını savunur."}, {"text": "Kur'an-ı Kerim'in yaratılmışlığı meselesi", "isCorrect": false, "rationale": "Kur'an'ın kadim değil mahluk olduğu iddiası yine tevhid prensibine dayanır."}, {"text": "Allah'ın sıfatlarının ezeli olup olmaması", "isCorrect": false, "rationale": "Bu tartışma Mu'tezile'nin tevhid ilkesi çerçevesinde sıfatları zatın aynı sayması konusudur."}], "hint": "'İki konum arasında bir konum' anlamına gelen bu ilke, günahkar Müslümanın statüsünü konu edinir.", "type": "multiple_choice"}, {"question": "İnsan fiillerinin yaratılmasında ilahi kaderin belirleyiciliğini reddederek fiilleri tamamen insanın özgür iradesine ve kudretine isnat eden mezhep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Cebriyye", "isCorrect": false, "rationale": "İnsanın hiçbir irade ve güce sahip olmadığını, rüzgardaki yaprak gibi mecbur olduğunu savunur."}, {"text": "Mürcie", "isCorrect": false, "rationale": "İman ile ameli birbirinden ayırarak günahların imana zarar vermediğini ileri sürer."}, {"text": "Mücessime", "isCorrect": false, "rationale": "Allah'ı cismâni niteliklere ve insan uzuvlarına benzeterek tecsim eden akımdır."}, {"text": "Kaderiyye", "isCorrect": true, "rationale": "İnsanın kendi fiillerinin yaratıcısı olduğunu savunarak ilahi kaderin insan fiillerindeki mutlak belirleyiciliğini reddederler."}], "hint": "İnsanın kendi fiillerinin kadir ve yaratıcısı olduğunu iddia eden gruptur.", "type": "multiple_choice"}, {"question": "Büyük günah işleyenlerin durumunu Allah'a erteleyen, kapsayıcı ve bütünleştirici tutumu sayesinde Türk boylarının İslam dinini benimsemesinde olumlu rol oynayan mezhebi anlayış aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mürcie", "isCorrect": true, "rationale": "Ameli imandan bir cüz saymayıp Müslümanları tekfir etmekten kaçınması, farklı toplumların İslam'a girişini kolaylaştırmıştır."}, {"text": "Müşebbihe", "isCorrect": false, "rationale": "Somut ilah tasavvuru ile kelami tartışmalara odaklanmış olup kitlesel İslamlaşmada olumlu rol üstlenmemiştir."}, {"text": "Haricilik", "isCorrect": false, "rationale": "Katı tekfirci tutumları nedeniyle toplumsal bütünleşmeyi engelleyen dışlayıcı bir yaklaşım sergilemiştir."}, {"text": "Şîa", "isCorrect": false, "rationale": "İmamet esasını dinin merkezine koyarak siyasi ve itikadi şartlar öne sürmüştür."}], "hint": "Görüşleri 'ertelemek' anlamına gelen ve ameli imanın şartı görmeyen mezheptir.", "type": "multiple_choice"}, {"question": "Şîa düşüncesini diğer tüm İslâmî fırkalardan ayıran, dinî ve siyasi otoritenin Hz. Peygamber'in soyundan gelen masum şahıslara ait olduğu inancına dayanan temel itikat esası aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Adâlet", "isCorrect": false, "rationale": "Allah'ın adil olduğu prensibi Mu'tezile ve Şîa'da ortak temel ilkelerden biridir."}, {"text": "Meâd", "isCorrect": false, "rationale": "Ahiret hayatı ve yeniden dirilme inancı olup tüm İslam mezheplerinin ortak aslıdır."}, {"text": "Nübüvvet", "isCorrect": false, "rationale": "Peygamberlik müessesesi bütün Müslüman fırkalarca kabul edilen genel bir inanç esasıdır."}, {"text": "İmâmet", "isCorrect": true, "rationale": "Şîa'da imamet inancı dinin asıllarından kabul edilerek diğer mezheplerden temel ayrışma noktasını oluşturur."}], "hint": "Devlet başkanlığı ve dini rehberliğin nas ile Ehl-i Beyt'e aidiyetini savunan esastır.", "type": "multiple_choice"}, {"question": "Şiî gelenekte Hz. Peygamber'in Veda Haccı dönüşünde Hz. Ali'yi kendisinden sonraki imam ve halife olarak açıkça tayin ettiğine inanılan tarihi olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kırtas Hadisesi", "isCorrect": false, "rationale": "Hz. Peygamber'in vefatına yakın bir vasiyetyazdırmak istemesi ve çıkan tartışmayla ilgili olaydır."}, {"text": "Ridde Olayları", "isCorrect": false, "rationale": "Hz. Ebû Bekir döneminde dinden dönen ve zekat vermeyen kabilelere karşı yürütülen askeri harekatlardır."}, {"text": "Gadir Hum Hadisesi", "isCorrect": true, "rationale": "Şiî literatürde Hz. Peygamber'in Hz. Ali'yi açıkça veli ve halife tayin ettiği iddia edilen tarihi olaydır."}, {"text": "Ebvâ Toplantısı", "isCorrect": false, "rationale": "Emevîlerin son döneminde Haşimoğulları'nın halife adayını belirlemek üzere toplandığı buluşmadır."}], "hint": "Mekke ile Medine arasında bir su birikintisi konaklama yerinde vuku bulduğu rivayet edilen gelişmedir.", "type": "multiple_choice"}, {"question": "Hanefî çizgideki ameli anlayışı kelam düzeyinde sistemleştirerek Ehl-i Sünnet'in iki ana omurgasından birini oluşturan İmam Mâtürîdî'nin temel kelam eseri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Makâlâtü'l-İslâmiyyîn", "isCorrect": false, "rationale": "Ebû'l-Hasan el-Eş'arî'nin mezheplerin görüşlerini aktardığı eseridir."}, {"text": "el-Mevâkıf", "isCorrect": false, "rationale": "Adudüddin el-Îcî'ye ait müteahhirûn dönemi kelam kitabıdır."}, {"text": "Kitâbü't-Tevhîd", "isCorrect": true, "rationale": "Mâtürîdî kelam sisteminin temel ilkelerini metotlu bir şekilde ortaya koyan ana eserdir."}, {"text": "el-Fark beyne'l-Fırak", "isCorrect": false, "rationale": "Abdülkâhir el-Bağdâdî'nin mezhepler tarihine dair yazdığı klasik eserdir."}], "hint": "Allah'ın varlığı, birliği ve sıfatlarını ele alan, mezhebin temel metni niteliğindeki kitaptır.", "type": "multiple_choice"}, {"question": "Şîa'nın günümüze kadar varlığını sürdürmüş kollarından biri olan ve günümüzde Yemen'de resmi ve yaygın bir mezhep olarak varlığını koruyan fırka aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kerbiyye", "isCorrect": false, "rationale": "Muhammed b. el-Hanefiyye'nin gaybetine inanan erken dönem aşırı Şiî gruplardandır."}, {"text": "Bahailik", "isCorrect": false, "rationale": "19. yüzyılda Şiilik bünyesinden çıkıp müstakil yeni bir dine dönüşen harekettir."}, {"text": "Zeydiyye", "isCorrect": true, "rationale": "Dini ve hukuki görüşleriyle Ehl-i Sünnet'e en yakın duran Zeydiyye, Yemen bölgesinde varlığını sürdürmektedir."}, {"text": "İsmailiyye", "isCorrect": false, "rationale": "Yedi imam inancına dayanan ve bâtınî tevil anlayışıyla tanınan bir Şiî koldur."}], "hint": "Efdal dururken mefzulün imametini caiz gören ılımlı Şiî koldur.", "type": "multiple_choice"}, {"question": "Hz. Ebû Bekir'in halife seçildikten hemen sonra devlet otoritesini sağlamak ve toplum bütünlüğünü korumak adına öncelikle odaklandığı temel sorun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kur'ân-ı Kerim nüshalarını çoğaltıp eyalet merkezlerine göndermek", "isCorrect": false, "rationale": "Kur'an'ın çoğaltılıp dağıtılması Hz. Osman döneminde gerçekleşmiştir."}, {"text": "Bizans ve Sâsânî imparatorluklarına karşı fetih hareketlerini durdurmak", "isCorrect": false, "rationale": "Hz. Ebû Bekir döneminde fetihler durdurulmamış, Suriye ve Irak cephelerinde başlatılmıştır."}, {"text": "Kûfe ve Basra gibi ordu şehirlerini (emsâr) kurmak", "isCorrect": false, "rationale": "Bu ordu şehirleri Hz. Ömer'in hilafeti döneminde inşa edilmiştir."}, {"text": "Yalancı peygamberler ve zekat vermeyen kabilelerle mücadele etmek", "isCorrect": true, "rationale": "Hz. Ebû Bekir, hilafetinin ilk döneminde Ridde savaşları ile iç düzeni ve ümmet birliğini yeniden tesis etmiştir."}], "hint": "Dinden dönme emareleri gösteren ve zekat yükümlülüğüne başkaldıran gruplara karşı yürütülen mücadeledir.", "type": "multiple_choice"}, {"question": "Selefî anlayışı yeniden canlandırarak Suud hanedanı nezdinde siyasi bir güç haline getiren ve Vehhâbiyye hareketinin kurucusu olan şahsiyet kimdir?", "answerOptions": [{"text": "İbn Kayyım el-Cevziyye", "isCorrect": false, "rationale": "İbn Teymiyye'nin en tanınmış öğrencisidir."}, {"text": "Şevkânî", "isCorrect": false, "rationale": "Yemenli müctehid alim olup mutlak ictihadı savunmuştur."}, {"text": "İbn Teymiyye", "isCorrect": false, "rationale": "14. yüzyılda yaşamış ve Selefî düşüncenin teorik temellerini atmış Hanbelî alimdir."}, {"text": "Muhammed b. Abdülvahhâb", "isCorrect": true, "rationale": "İbn Teymiyye çizgisindeki Selefî anlayışı siyasallaştırarak Suud emirliği bünyesinde resmi mezhep haline getirmiştir."}], "hint": "18. yüzyılda Necid bölgesinde ortaya çıkan itikadi hareketin lideridir.", "type": "multiple_choice"}]}, "4": {"unit": 4, "unitTitle": "Ehl-i Sünnet ve Sonraki Mezhepler", "title": "İslam Mezhepleri Testi", "questions": [{"question": "Ehl-i Sünnet ekolünü tanımlamak ve Müslümanların ana gövdesini ifade etmek amacıyla tarih boyunca çeşitli unvan ve tanımlamalar kullanılmıştır. Aşağıdakilerden hangisi bu isimlerden biri değildir?", "answerOptions": [{"text": "Ehl-i Hak ve Ehl-i Hüdâ", "isCorrect": false, "rationale": "Doğru yol ve hak üzere olanları tanımlamak amacıyla kullanılan geleneksel Sünni Unvanlardandır."}, {"text": "Ehl-i Beyt", "isCorrect": true, "rationale": "Hz. Peygamber'in ev halkını ve soyunu ifade eden bir kavram olup Ehl-i Sünnet'i tanımlayan mezhepsel bir isim veya unvan değildir."}, {"text": "Sevâd-ı a'zam", "isCorrect": false, "rationale": "Toplumun büyük çoğunluğunu ve ana gövdesini ifade etmek için kullanılan klasik bir Ehl-i Sünnet unvanıdır."}, {"text": "Fırka-i nâciye", "isCorrect": false, "rationale": "Kurtuluşa eren topluluk anlamında Ehl-i Sünnet mensuplarını tanımlamada sıklıkla başvurulan bir nitelendirmedir."}], "hint": "Bu kavram mezhepsel bir çatı ismi olmaktan ziyade Hz. Peygamber'in yakın hane halkını ifade eder.", "type": "multiple_choice"}, {"question": "Kelam ve tefsir alanında kaleme aldığı 'Kitâbü't-Tevhîd' ve 'Te'vîlâtü'l-Kur'ân' isimli eserleriyle tanınan ve Ehl-i Sünnet itikadının sistemleşmesine öncülük eden alim aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İmam-ı A'zam Ebû Hanîfe", "isCorrect": false, "rationale": "Sünni fıkıh ve itikat geleneğinin öncülerindendir ancak 'Kitâbü't-Tevhîd' ve 'Te'vîlât' eserleri ona ait değildir."}, {"text": "Ebû'l-Mu'în en-Nesefî", "isCorrect": false, "rationale": "Mâtürîdî kelam düşüncesini daha sonraki dönemlerde sistemleştirip yayan alimlerden biridir."}, {"text": "Ebû Mansur el-Mâtürîdî", "isCorrect": true, "rationale": "Söz konusu iki temel eser Mâtürîdîlik ekolünün kurucusu sayılan Ebû Mansur el-Mâtürîdî tarafından kaleme alınmıştır."}, {"text": "Ebû'l-Hasan el-Eş'arî", "isCorrect": false, "rationale": "Eş'arî ekolünün kurucusu olup en meşhur mezhepler tarihi eseri 'Makâlâtü'l-İslâmiyyîn'dir."}], "hint": "Semerkand coğrafyasında yetişmiş, akıl ve nakil dengesini kuran Sünni kelam ekolünün kurucu figürüdür.", "type": "multiple_choice"}, {"question": "Selefî anlayışın 18. yüzyılda Vehhâbîlik hareketi çerçevesinde siyasallaşarak Suud hanedanlığı nezdinde resmi bir devlet mezhebine dönüşmesini sağlayan isim aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İbnü'l-Vezîr", "isCorrect": false, "rationale": "Hadis odaklı düşünceyi savunan ancak Vehhabilik hareketinin kurucusu olmayan bir alimdir."}, {"text": "Şevkânî", "isCorrect": false, "rationale": "Yemen bölgesinde yetişmiş bağımsız içtihat yanlısı ve Hadis ağırlıklı bir alimdir."}, {"text": "İbn Kayyım el-Cevziyye", "isCorrect": false, "rationale": "İbn Teymiyye'nin öğrencisi olup klasik Selefî çizginin orta çağdaki önemli temsilcilerindendir."}, {"text": "Muhammed b. Abdülvahhâb", "isCorrect": true, "rationale": "Selefi düşünceyi siyasi bir ittifakla Vehhabilik adı altında kurumsallaştırarak devlet mezhebi haline getirmiştir."}], "hint": "Kendi adından türetilen hareketle Suudi Arabistan'ın kuruluş sürecindeki dinsel ve siyasal temeli atmıştır.", "type": "multiple_choice"}, {"question": "İmam Rabbânî ile Mevlâna Hâlid Bağdâdî'nin Ehl-i Sünnet vurgusu ve tasavvufi yaklaşımı, aşağıdaki dönemlerin hangisinde kaleme alınan Mezhepler Tarihi eserlerine güçlü bir şekilde yansımıştır?", "answerOptions": [{"text": "Emeviler", "isCorrect": false, "rationale": "Söz konusu alimlerin yaşadığı dönemlerden çok daha önceki ilk siyasi mezhepleşme dönemidir."}, {"text": "Abbasiler", "isCorrect": false, "rationale": "Mu'tezile ve erken dönem mezhepleşme süreçlerinin öne çıktığı dönemi ifade eder."}, {"text": "Osmanlılar", "isCorrect": true, "rationale": "Nakşibendî geleneğin bu iki büyük figürünün Ehl-i Sünnet vurgusu Osmanlı son dönemi mezhepler tarihi metinlerini derinden etkilemiştir."}, {"text": "Safeviler", "isCorrect": false, "rationale": "İran coğrafyasında Şii-İmâmiyye anlayışını devlet mezhebi olarak benimseyen yapıya sahiptir."}], "hint": "Mücellid-i Elf-i Sânî ve Müceddidî kollarıyla Balkanlar ve Anadolu'da etkili olan devlet yapısını düşününüz.", "type": "multiple_choice"}, {"question": "Ebû'l-Hasan el-Eş'arî'nin, İslam mezheplerini ve bu fırkaların temel görüşlerini tarafsız bir üslupta ele aldığı meşhur kaynağı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "el-Milel ve'n-Nihal", "isCorrect": false, "rationale": "Şehristânî'nin dinler ve mezhepler tarihine dair ünlü çalışmasıdır."}, {"text": "Kitâbü't-Tevhîd", "isCorrect": false, "rationale": "Ebû Mansur el-Mâtürîdî'nin kelam konularını işlediği temel eseridir."}, {"text": "Makâlâtü'l-İslâmiyyîn", "isCorrect": true, "rationale": "Eş'arî'nin mezheplerin görüşlerini sistemli ve betimleyici tarzda sunduğu en bilinen klasik eseridir."}, {"text": "el-Fark beyne'l-Fırak", "isCorrect": false, "rationale": "Eş'arî kelamcısı Abdülkāhir el-Bağdâdî tarafından kaleme alınan mezhepler tarihi eseridir."}], "hint": "Eserin adı 'Müslümanların Makaleleri/Görüşleri' anlamına gelmektedir.", "type": "multiple_choice"}, {"question": "Şîa itikadında Hz. Ali'nin Hz. Peygamber tarafından açıkça vası tayin edildiği ve imametinin ilahi rıza ile kesinleştiği kabul edilen tarihi olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tahkim Olayı", "isCorrect": false, "rationale": "Sıffîn Savaşı sonrasında Hariciliğin doğuşuna zemin hazırlayan siyasi süreçtir."}, {"text": "Hayber'in Fethi", "isCorrect": false, "rationale": "Hz. Ali'nin kahramanlık gösterdiği askeri bir zafer olup imametin tespitiyle doğrudan ilgili değildir."}, {"text": "Kırtas Hadisesi", "isCorrect": false, "rationale": "Hz. Peygamber'in vefatına yakın vasiyet yazmak istemesi üzerine yaşanan tartışmalı olaydır."}, {"text": "Gadir Hum Hadisesi", "isCorrect": true, "rationale": "Şii anlayışa göre Hz. Peygamber'in Veda Haccı dönüşü Hz. Ali'yi veli ve halef ilan ettiği mekandır."}], "hint": "Veda Haccı dönüşünde Mekke ile Medine arasında yer alan bir su birikintisi ve mevki adıdır.", "type": "multiple_choice"}, {"question": "Şîa mezhebini diğer tüm İslami fırka ve ekollerden ayıran, dinin temel esaslarından biri (aslü'd-dîn) sayılan prensip aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tevhid", "isCorrect": false, "rationale": "Bütün İslami mezheplerin ortak kabul ettiği Allah'ın birliği esasıdır."}, {"text": "Nübüvvet", "isCorrect": false, "rationale": "Peygamberlik müessesesi tüm Müslüman gruplarca kabul gören ortak inanç esasıdır."}, {"text": "Meâd", "isCorrect": false, "rationale": "Ahiret gününe ve yeniden dirilişe iman İslam dininin genel ilkesidir."}, {"text": "İmâmet", "isCorrect": true, "rationale": "Devlet başkanlığı ve manevi rehberliğin nass ile tayin edilmiş masum imamlara ait olduğunu savunmak Şîa'nın belirleyici rüknüdür."}], "hint": "Hz. Ali ve soyundan gelenlerin dini ve siyasi liderliğini inanç esaslarına dahil eden görüştür.", "type": "multiple_choice"}, {"question": "Şîa'nın günümüze kadar varlığını sürdürmüş büyük kollarından biri olan ve Yemen'de resmi düzeyde temsil edilen fırka aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Muhammire", "isCorrect": false, "rationale": "Kızıl giysiler giyen ve günümüzde yaşayan ana Şii kollardan biri olmayan tarihi bir gruptur."}, {"text": "Kerbiyye", "isCorrect": false, "rationale": "Erken dönemde yok olmuş aşırı (gālî) Şii gruplardandır."}, {"text": "Zeydiyye", "isCorrect": true, "rationale": "Zeyd b. Ali'ye nispet edilen ve Ehl-i Sünnet'e en yakın Şii kol olarak Yemen'de varlığını sürdüren gruptur."}, {"text": "Beyâniyye", "isCorrect": false, "rationale": "Tarihte kalmış ve günümüze ulaşamamış gulat-ı Şîa teşekküllerindendir."}], "hint": "İmamet konusunda silahlı kıyamı şart koşan ve Zeyd b. Ali'nin imametini benimseyen fırkadır.", "type": "multiple_choice"}, {"question": "Mu'tezile mezhebinin temel ilkelerinden biri olan 'el-Menzile beyne'l-Menzileteyn' prensibi doğrudan hangi tartışma sonucunda ortaya çıkmıştır?", "answerOptions": [{"text": "Kulların kendi fiillerini yaratması", "isCorrect": false, "rationale": "Bu mesele Mu'tezile'nin 'Adalet' prensibiyle ilişkilidir."}, {"text": "Allah'ın sıfatlarının ezeli olup olmaması", "isCorrect": false, "rationale": "Bu konu Mu'tezile'nin 'Tevhid' prensibi kapsamında ele alınmaktadır."}, {"text": "İyiliği emredip kötülükten alıkoyma sorumluluğu", "isCorrect": false, "rationale": "Bu ilke 'Emir bi'l-Ma'rûf Nehiy ani'l-Münker' prensibini açıklar."}, {"text": "Büyük günah işleyen kişinin (mürtekib-i kebîre) imandaki durumu", "isCorrect": true, "rationale": "Büyük günah işleyenin ne tam mümin ne de tam kafir olup ikisi arasında bir konumda bulunacağını ifade eder."}], "hint": "Vâsıl b. Atâ'nın hocası Hasan-ı Basrî ile görüş ayrılığına düştüğü ana meseledir.", "type": "multiple_choice"}, {"question": "Dinin özündeki bütünlüğün bozulması, aslından olmayan şeylerin dine sonradan eklenmesi veya icat edilmesi durumunu ifade eden kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Celâdet", "isCorrect": false, "rationale": "Güçlükler karşısında yiğitlik, yiğitçe duruş ve sertlik anlamına gelen kavramdır."}, {"text": "Bid’at", "isCorrect": true, "rationale": "Sözlükte önceden benzeri olmadan sonradan icat edilen şey, dini terim olarak dine dahi edilen yenilik anlamındadır."}, {"text": "Dalâlet", "isCorrect": false, "rationale": "Doğru yoldan saptırma veya hak yoldan ayrılma durumunu anlatır."}, {"text": "Tefrika", "isCorrect": false, "rationale": "Toplumsal ve siyasal ayrışma, gruplaşma ve bölünmeyi ifade eder."}], "hint": "Sünnet kavramının zıttı olarak dinde sonradan ortaya çıkarılan uygulamaları tanımlar.", "type": "multiple_choice"}, {"question": "Mâtürîdî kelamcılarının; ilahi sıfatlar, Kur'an'ın yaratılmışlığı (halku'l-Kur'an) ve insan fiilleri gibi konularda aşırı ve tutarsız yorumlara giderek nasları göz ardı etmekle eleştirdikleri ekol aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hâricîler", "isCorrect": false, "rationale": "Aşırı katı lafızcı ve siyasi olarak tekfirci tutumlarıyla bilinen ilk muhalif fırkadır."}, {"text": "Selefiyye", "isCorrect": false, "rationale": "Müteşâbih naslarda tevil yapmayıp teslimiyeti seçen nakilci yaklaşımdır."}, {"text": "Mürcie", "isCorrect": false, "rationale": "Ameli imandan bir cüz saymayıp hükmü erteleyen ilk dönem fırkasıdır."}, {"text": "Mu'tezile", "isCorrect": true, "rationale": "Akılcı yorumları aşırıya kaçırarak nasların açık anlamlarını tahrif ettikleri gerekçesiyle Mâtürîdîlerce eleştirilmişlerdir."}], "hint": "Akla verdikleri aşırı önem ve 'Beş Esas' (El-Usûlü'l-Hamse) anlayışlarıyla bilinen kelam ekolüdür.", "type": "multiple_choice"}, {"question": "İsmailî düşünce sisteminin metinleri anlama ve yorumlamadaki en belirleyici prensibi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Aklın nasların önüne geçirilerek tamamen re'y ile hareket edilmesi", "isCorrect": false, "rationale": "İsmailîlik tamamen akılcılık yerine imamın gizli öğretisine ve batıni teviline dayanır."}, {"text": "Büyük günah işleyen kimsenin kafir kabul edilmesi", "isCorrect": false, "rationale": "Bu yaklaşım Haricilik ekolünün temel niteliğidir."}, {"text": "Kutsal metin ve şer'i hükümlerin zahir ve batın şeklinde iki boyutta değerlendirilmesi", "isCorrect": true, "rationale": "Ayet ve hükümlerin görünür (zahir) anlamının ötesinde gizli ve derin (batın) anlamları olduğunu savunurlar."}, {"text": "Kader konusunda insanın tamamen mecbur olduğunu savunmak", "isCorrect": false, "rationale": "İsmailîliğin temeli cebir anlayışı değil, masum imamın batıni rehberliğidir."}], "hint": "Bu sebeple söz konusu fırka tarihte sıklıkla 'Bâtınîlik' adıyla da anılmıştır.", "type": "multiple_choice"}]}, "5": {"unit": 5, "unitTitle": "Şîa Tarihi ve Çağdaş Akımlar", "title": "Şii Mezhebi Testi", "questions": [{"question": "Şîa gelenek ve literatüründe, Hz. Peygamber'in Veda Haccı dönüşünde Hz. Ali'yi kendisinden sonraki dini ve siyasi lider (imam) olarak tayin ettiğine inanılan tarihî olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Gadir Hum Hadisesi", "isCorrect": true, "rationale": "Gadir Hum, Şîa inancında Hz. Ali'nin açıkça velayet ve imametle görevlendirildiği belirleyici mekan ve olay olarak kabul edilir."}, {"text": "Kırtas Hadisesi", "isCorrect": false, "rationale": "Hz. Peygamber'in vefatına yakın bir kağıt ve kalem istemesi olayı olup doğrudan bir imam tayin merasimi şeklinde gerçekleşmemiştir."}, {"text": "Ebvâ Toplantısı", "isCorrect": false, "rationale": "Emeviler döneminde Haşimoğulları mensuplarının siyasi biat konusunu görüşmek üzere toplandığı özel bir buluşmadır."}, {"text": "Hakem Olayı", "isCorrect": false, "rationale": "Sıffîn Savaşı sonrasında Hz. Ali ile Muaviye taraftarları arasındaki halifelik anlaşmazlığını çözmek amacıyla kurulan tahkim sürecidir."}], "hint": "Hz. Peygamber'in Veda Haccı dönüşü yol üzerindeki bir su birikintisi mevkiinde gerçekleşen olayı düşününüz.", "type": "multiple_choice"}, {"question": "Klasik İslam mezhepleri tarihinde Şîa'yı Ehl-i Sünnet ve diğer ana İslami ekollerden ayıran ve dinin temel esasları (usûlü'd-dîn) arasında sayılan en belirleyici itikadi ilke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Adâlet", "isCorrect": false, "rationale": "Adalet ilkesi Mu'tezile ve Şîa'da ortak esaslardan biri olup Şîa'yı diğer tüm fırkalardan ayıran tekil unsur değildir."}, {"text": "Nübüvvet", "isCorrect": false, "rationale": "Peygamberlik müessesesi tüm Müslüman gruplarca kabul edilen genel bir İslam inanç esasıdır."}, {"text": "İmâmet", "isCorrect": true, "rationale": "Şîa mektebinde devlet başkanlığı sıradan bir siyasi seçim değil, Peygamberlik müessesesinin devamı niteliğinde ilahi bir tayindir."}, {"text": "Tevhid", "isCorrect": false, "rationale": "Tevhid bütün İslami ekollerin ortak inanç esası olduğundan Şîa'ya özgü ayrıştırıcı bir çizgi niteliği taşımaz."}], "hint": "Siyasi ve dini liderliğin ilahi bir nassa dayandığı inancını hatırlayınız.", "type": "multiple_choice"}, {"question": "Günümüzde nüfusunun önemli bir kısmını bünyesinde barındıran ve devletin resmi mezhepsel yapısında belirgin ağırlığı bulunan Zeydiyye mensupları yoğun olarak hangi ülkede yaşamaktadır?", "answerOptions": [{"text": "Yemen", "isCorrect": true, "rationale": "Zeydiyye mezhebi tarihsel süreçten günümüze kadar varlığını en güçlü şekilde Yemen coğrafyasında sürdürmüştür."}, {"text": "Hindistan", "isCorrect": false, "rationale": "Hindistan'da İsnâaşeriyye ve İsmailiyye kollarının toplulukları bulunmakta olup Zeydiyye hâkim mezhep değildir."}, {"text": "Mısır", "isCorrect": false, "rationale": "Mısır günümüzde ağırlıklı olarak Sünni nüfusun ve Sünni ameli mezheplerin yaygın olduğu bir ülkedir."}, {"text": "Azerbaycan", "isCorrect": false, "rationale": "Azerbaycan'daki Şii nüfusun büyük çoğunluğu On İki İmam (İsnâaşeriyye/Ca'feriyye) koluna mensuptur."}], "hint": "Güney Arap Yarımadası'nda yer alan ve Zeydi imamların tarih boyunca hüküm sürdüğü coğrafyayı anımsayınız.", "type": "multiple_choice"}, {"question": "İsmailiyye tarihinde, imamların kimliklerini gizlediği ve Ubeydullah el-Mehdî'nin Fatımi Devleti'ni kurduğu döneme kadar devam eden 'gizlenme dönemi' hangi terimle ifade edilir?", "answerOptions": [{"text": "Gaybet", "isCorrect": false, "rationale": "İsnâaşeriyye (On İki İmam) ekolünde son imamın gizlenmesi ve gözlerden uzaklaşması durumunu ifade eder."}, {"text": "Setr", "isCorrect": true, "rationale": "İsmaili geleneğinde devlet kurulana kadarki imamların gizli faaliyet yürüttüğü döneme 'dövrü's-setr' adı verilir."}, {"text": "Bâtın", "isCorrect": false, "rationale": "Ayet ve hadislerin dış anlamının ötesindeki gizli ve içsel derin anlamını simgeleyen kavramdır."}, {"text": "Rec'at", "isCorrect": false, "rationale": "Vefat eden imamın veya kişilerin ahir zamanda adaleti tesis etmek üzere tekrar dünyaya döneceği inancıdır."}], "hint": "Arapçada örtünme, gizlenme ve saklanma anlamına gelen kökten türeyen terimi düşününüz.", "type": "multiple_choice"}, {"question": "İsmailî düşünce sisteminin teşekkülünde Neo-Platonist ve Gnostik felsefi akımların etkisiyle öne çıkan ve dini metinlerin yorumlanmasında uygulanan temel yaklaşım aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hadis metinlerinin akli gerekçelerle tamamen reddedilmesi", "isCorrect": false, "rationale": "İsmailîlik hadisleri tümüyle reddetmez; kendi silsileleri üzerinden batıni tevil metoduna tabi tutarak aktarır."}, {"text": "Siyasi iktidarın halk oylamasıyla belirlenmesi zorunluluğu", "isCorrect": false, "rationale": "Şii/İsmailî anlayışta liderlik seçimle değil, nass ve ilahi tayinle belirlenir."}, {"text": "Kutsal metinlerin zahir ve batın şeklinde ayrıştırılması", "isCorrect": true, "rationale": "İsmailîlik, ayetlerin dış anlamının (zahir) yanında yalnızca masum imamın öğretebileceği gizli bir anlamının (batın) bulunduğunu savunur."}, {"text": "Nassların tamamen lafzi (zahiri) anlamlarıyla sınırlandırılması", "isCorrect": false, "rationale": "Lafzi ve şekilsel okuma Bâtınî/İsmailî felsefenin aksine Zahiriyye ve Selefiyye ekollerine aittir."}], "hint": "Dış görünüş ile gizli ve derin anlam arasındaki ikiliği kuran Bâtınî yorum yöntemini düşününüz.", "type": "multiple_choice"}, {"question": "Hz. Hüseyin'in Kerbela'da şehit edilmesinden sonra, pişmanlık duyarak Emeviler'e karşı vicdan azabıyla harekete geçen ve Şiiliğin duygusal/siyasi kimlik kazanmasında önemli rol oynayan kitlesel hareket aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ezrakiyye Ayaklanması", "isCorrect": false, "rationale": "Ezrakiyye, Şîa ile ilişkisi bulunmayan ve radikal eylemleriyle bilinen bir Harici fırkasıdır."}, {"text": "Ridde Savaşları", "isCorrect": false, "rationale": "Hz. Ebu Bekir döneminde dinden dönen ve zekat vermeyen kabilelere karşı yürütülen askeri mücadeledir."}, {"text": "Zeyd b. Ali İsyanı", "isCorrect": false, "rationale": "Tevvabun hareketinden daha sonraki bir dönemde Emevi yönetimine karşı gerçekleştirilmiş silahlı ihya hareketidir."}, {"text": "Tevvabun Hareketi", "isCorrect": true, "rationale": "Tevvabun Hareketi, Kerbela'da Hz. Hüseyin'i yalnız bırakan Kûfelilerin kefaret ödeme ve intikam alma amacıyla başlattıkları bir 'Tövbeler Edenler' eylemidir."}], "hint": "Kelime anlamı 'günahlarına pişman olup tövbe eden topluluk' olan grubu hatırlayınız.", "type": "multiple_choice"}, {"question": "Şîa’nın bazı kollarında görülen; vefat eden imamın ahir zamanda adaleti sağlamak üzere dünyaya yeniden döneceği yönündeki inanç kavramı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Bedâ", "isCorrect": false, "rationale": "Allah'ın önceden takdir ettiği veya bildirdiği bir durumun sonradan başka bir şekilde tecelli etmesi tezidir."}, {"text": "Tenâsüh", "isCorrect": false, "rationale": "Ruhun bir bedenden çıkıp ölümden sonra başka bir insan veya hayvan bedenine geçmesi inancıdır."}, {"text": "Hulûl", "isCorrect": false, "rationale": "İlahi varlığın veya ruhun bir insan bedenine girmesi ve onunla birleşmesi anlayışıdır."}, {"text": "Rec'at", "isCorrect": true, "rationale": "Rec'at, sözlükte 'geri dönmek' anlamına gelip Şii teolojisinde imamın ahir zamanda dünyaya rücu etmesi fikrini ifade eder."}], "hint": "Arapçada 'rücu etmek' veya 'geri dönmek' kökünden gelen terimi düşününüz.", "type": "multiple_choice"}, {"question": "Şîa’nın tarihsel teşekkül sürecinde, Müslümanlar arasındaki ilk büyük iç savaş olarak kabul edilen ve Hz. Ali ile Hz. Aişe taraftarları arasında gerçekleşen olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Nahrevan Savaşı", "isCorrect": false, "rationale": "Hz. Ali'nin ordusu ile ordusundan ayrılan Harici gruplar arasında yapılan mücadeledir."}, {"text": "Cemel Vak'ası", "isCorrect": true, "rationale": "Deve Olayı olarak da bilinen Cemel Vak'ası, Müslümanlar arasındaki ilk iç savaştır ve siyasi kutuplaşmayı derinleştirmiştir."}, {"text": "Sıffîn Savaşı", "isCorrect": false, "rationale": "Hz. Ali ile Muaviye b. Ebi Süfyan ordusu arasında gerçekleşen ikinci büyük iç savaştır."}, {"text": "Kerbela Hadisesi", "isCorrect": false, "rationale": "Emevi halifesi Yezid'in ordusu ile Hz. Hüseyin ve beraberindekiler arasında gerçekleşen trajik çatışmadır."}], "hint": "Hz. Aişe'nin devesinin etrafında cereyan ettiği için bu adla anılan olayı anımsayınız.", "type": "multiple_choice"}, {"question": "Şîa mezhebi içinde, günümüze kadar varlığını sürdürmüş ana kollar arasında yer alan ve ilk üç halifenin hilafetini tamamen reddetmeyip Hz. Ali'nin en üstün (efdal) olduğunu savunmakla yetinen ılımlı Şii kolu aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Zeydiyye", "isCorrect": true, "rationale": "Zeydiyye, Sünni ameli ve fikri yapıya en yakın Şii fırkasıdır; mefzulün (daha az üstün olanın) imametini caiz görerek ilk halifelerin idaresini kategorik olarak reddetmez."}, {"text": "Beyâniyye", "isCorrect": false, "rationale": "Beyan b. Sem'an'a nispet edilen ve uluhiyet iddiası barındıran yok olmuş radikal bir fırkadır."}, {"text": "Kerbiyye", "isCorrect": false, "rationale": "Muhammed b. el-Hanefiyye'nin ölmediğini savunan, aşırı fikirli ve tarihi süreçte yok olmuş bir koldur."}, {"text": "Muhammire", "isCorrect": false, "rationale": "Aşırı (Gulat) görüşler taşıyan ve günümüze ulaşamayan marjinal bir gruptur."}], "hint": "Zeyd b. Ali'ye mensup olan ve Sünniliğe en yakın kabul edilen Şii mezhebini düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi Şîa’nın tarihsel olarak teşekkül etmesinde ve Emeviler yönetimine karşı bir muhalefet odağı haline gelmesinde etkili olan gelişmelerden biri DEĞİLDİR?", "answerOptions": [{"text": "Muhtar es-Sakafi Hareketi", "isCorrect": false, "rationale": "Kûfe merkezli bu hareket Hz. Hüseyin'in intikamını alma vaadiyle Şii siyasi örgütlenmesini güçlendirmiştir."}, {"text": "Kerbela Hadisesi", "isCorrect": false, "rationale": "Kerbela, Şii bilincinin, matem kültürünün ve direniş kimliğinin oluşmasındaki ana milattır."}, {"text": "Ridde Hadiseleri", "isCorrect": true, "rationale": "Ridde Hadiseleri, Hz. Ebu Bekir döneminde zekat vermeyen ve sahte peygamberlerin peşinden giden kabilelere karşı yürütülmüş olup Şii teşekkülle doğrudan ilişkili değildir."}, {"text": "Hucr b. Adiyy İsyanı", "isCorrect": false, "rationale": "Emevi valilerinin Ali evladına lanet okuma politikasına karşı Şiilerin gösterdiği ilk açık tepki ve başkaldırılardandır."}], "hint": "Hz. Ebu Bekir'in halifeliğinin ilk zamanlarında yalancı peygamberler ve zekat vermeyen kabilelere karşı yapılan mücadeleyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Allah'ın bilmesinde veya takdirinde sonradan bir değişme olması, önceden ilan edilen bir durumun başka şekilde tecelli etmesi anlamına gelen ve bazı Şii grupların imamet nakillerindeki sapmaları açıklamakta başvurduğu kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Teşbîh", "isCorrect": false, "rationale": "Yaratıcıyı yaratılmış varlıklara ve insan organlarına benzetme anlayışıdır."}, {"text": "Hulûl", "isCorrect": false, "rationale": "İlahın insan bedenine intikal etmesi veya onda tecelli etmesi fikridir."}, {"text": "Bedâ", "isCorrect": true, "rationale": "Bedâ, sözlükte 'sonradan ortaya çıkmak' anlamında olup imamlara dair öngörülerin gerçekleşmemesini açıklamakta kullanılan teolojik bir terimdir."}, {"text": "Tenâsüh", "isCorrect": false, "rationale": "Ölen bir kimsenin ruhunun başka bir bedene geçerek yaşamaya devam etmesi inancıdır."}], "hint": "İmamet sırasının belirlenmesinde vuku bulan beklenmedik değişimleri açıklamak için kullanılan kavramı anımsayınız.", "type": "multiple_choice"}, {"question": "Şiilikte Ehl-i Beyt sevgisi ve imamet düşüncesinin kurumsallaşmasında, Hz. Peygamber'in soyunun devam ettiği ve evlilik bağıyla Hz. Ali ile birleştiği kilit kızı kimdir?", "answerOptions": [{"text": "Hz. Hatice", "isCorrect": false, "rationale": "Hz. Peygamber'in ilk eşidir; Peygamber soyunun Ali evladı üzerinden sürdüğü doğrudan halkanın anası Hz. Fatıma'dır."}, {"text": "Hz. Âişe", "isCorrect": false, "rationale": "Hz. Peygamber'in eşi olup Cemel Vak'ası'nda Hz. Ali'nin karşısındaki grupta yer almıştır."}, {"text": "Hz. Fatıma", "isCorrect": true, "rationale": "Hz. Fatıma, Hz. Peygamber'in soyunun devamını sağlayan ve Hz. Ali ile evliliğinden imamlar silsilesi doğan kilit şahsiyettir."}, {"text": "Hz. Zeyneb", "isCorrect": false, "rationale": "Hz. Ali ve Hz. Fatıma'nın kızıdır; Kerbela sonrası süreçte rol oynamış olmakla birlikte soy silsilesinin kökünü oluşturmaz."}], "hint": "Hz. Peygamber'in 'benden bir parçadır' dediği ve Hz. Hasan ile Hz. Hüseyin'in annesi olan kızı düşününüz.", "type": "multiple_choice"}]}, "6": {"unit": 6, "unitTitle": "Günümüz İslâm Mezhepleri", "title": "İslam Mezhepleri Tarihi Testi", "questions": [{"question": "İslam Mezhepleri Tarihi disiplininin temel metodolojisi ve akademik yaklaşımı göz önüne alındığında, aşağıdakilerden hangisi bu bilim dalının amaçları arasında yer almaz?", "answerOptions": [{"text": "Mezhep ve dinî grupların tarih boyunca bıraktıkları izleri görünür kılmak", "isCorrect": false, "rationale": "Dini hareketlerin ve mezheplerin tarihsel süreçteki etkilerini tespit etmek bu disiplinin temel hedeflerindendir."}, {"text": "Mezhepleri 'hak' veya 'batıl' olarak sınıflandırıp doğru inanç esaslarını tespit etmek", "isCorrect": true, "rationale": "Mezhepler Tarihi normatif ve teolojik değerlendirmeler yapmak yerine tarafsız, tasviri ve objektif bir inceleme yapmayı hedefler."}, {"text": "Müslümanlar arasındaki mezhepsel çatışma ve sorunlara yönelik yapıcı çözümler sunmak", "isCorrect": false, "rationale": "Toplumsal barışa katkı sunmak ve mezhepsel önyargıları gidermek akademik Mezhepler Tarihi çalışmalarının gayelerindendir."}, {"text": "Müslüman toplumların sosyo-psikolojik kuvvet ve zaaflarına dair verilere ulaşmak", "isCorrect": false, "rationale": "Toplumsal yapıların din anlayışıyla etkileşimini anlamak disiplinin veri toplama amaçları arasında yer alır."}], "hint": "Bu disiplinin normatif (yargılayıcı/kelamî) değil, tasvirî (betimleyici) bir bilim dalı olduğunu hatırlayınız.", "type": "multiple_choice"}, {"question": "Dinin özündeki uygulamalardan sapmayı/sonradan uydurulan şeyleri ve Müslüman toplumun bütünlüğündeki bozulmayı ifade eden temel kavramlar aşağıdakilerin hangisinde sırasıyla doğru verilmiştir?", "answerOptions": [{"text": "Furkat - İttifak", "isCorrect": false, "rationale": "İttifak, ayrışma veya bozulmayı değil aksine birlik ve uzlaşmayı simgeler."}, {"text": "Celâdet - Dalâlet", "isCorrect": false, "rationale": "Celâdet yiğitlik/sertlik anlamına gelir; dinin bozulması veya toplumsal bölünmeyle kavrayış olarak örtüşmez."}, {"text": "Bid’at - Tefrika", "isCorrect": true, "rationale": "Sözlükte önceden benzeri olmadan icat edilen şey anlamına gelen Bid’at dinin özündeki sonradan olma şeyleri, Tefrika ise toplum bütünlüğünün bozulmasını ifade eder."}, {"text": "Tefrika - Makâlât", "isCorrect": false, "rationale": "Makâlât, İslam düşüncesindeki görüşlerin derlendiği eser türlerini ifade eder, toplumsal ayrışmayla doğrudan ilgisi yoktur."}], "hint": "İlk kavram dinî yenilik/icadı, ikinci kavram ise toplumsal bölünmeyi ifade etmektedir.", "type": "multiple_choice"}, {"question": "Din Sosyolojisi ile İslam Mezhepleri Tarihi’nin ortak çalışma alanları değerlendirildiğinde, aşağıdakilerden hangisi bu iki disiplinin ortak odak noktalarından biri değildir?", "answerOptions": [{"text": "Bir mezhebin 'kurtarıcı bekleme' inancı geliştirmesinin sosyo-psikolojik sebepleri", "isCorrect": false, "rationale": "Kurtarıcı beklentisi ve mehdilik gibi inançların toplumsal zeminini araştırmak her iki disiplinin ortak konusudur."}, {"text": "Bir mezhepte cemaatsel hiyerarşinin nasıl teşekkül ettiği", "isCorrect": false, "rationale": "Dini gruplar içerisindeki otorite yapısı ve hiyerarşi hem sosyolojinin hem de mezhepler tarihinin inceleme alanıdır."}, {"text": "Bir mezhebin itikadi görüşlerinin kelami açıdan doğruluğunu kanıtlama", "isCorrect": true, "rationale": "İtikadi görüşlerin doğruluğunu kanıtlama çabası sosyolojik veya tarihsel bir analiz değil, Kelam ilminin konusudur."}, {"text": "Mezhep mensupları arasındaki grupsal dayanışma ve ekonomik yardımlaşma", "isCorrect": false, "rationale": "Grup içi bağlılık ve sosyal dayanışma mekanizmaları toplumsal ve mezhepsel incelemelerde ortak konudur."}], "hint": "Disiplinlerin betimleyici nitelikte mi yoksa inanç savunucusu (savunmacı/teolojik) nitelikte mi olduğunu göz önüne alınız.", "type": "multiple_choice"}, {"question": "İslam Mezhepleri Tarihi'nin klasik kaynaklarından kabul edilen 'el-Fark beyne'l-Fırak' ve 'Makâlâtü'l-İslâmiyyîn' adlı eserlerin yazarları sırasıyla aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ebû'l-Mu’în en-Nesefî - Ebû Yûsuf", "isCorrect": false, "rationale": "Nesefî Mâtürîdî kelamcısı, Ebû Yûsuf ise Hanefî fıkıh alimidir; sözü edilen eserler bu kişilere ait değildir."}, {"text": "Ebû Mansur el-Mâtürîdî - Vâsıl b. Atâ", "isCorrect": false, "rationale": "Ebû Mansur el-Mâtürîdî Kitâbü't-Tevhîd'in yazarıdır; bahsedilen klasik makâlât eserleri bu alimlere ait değildir."}, {"text": "İmam Rabbânî - Mevlâna Hâlid Bağdâdî", "isCorrect": false, "rationale": "Bu isimler tasavvufi geleneğin (Nakşibendiyye) önemli simaları olup klasik mezhepler tarihi makâlât literatürünün ana yazarları değillerdir."}, {"text": "Abdülkāhir el-Bağdâdî - Ebû'l-Hasan el-Eş'arî", "isCorrect": true, "rationale": "el-Fark beyne'l-Fırak Bağdâdî'nin, Makâlâtü'l-İslâmiyyîn ise Eş'arî'nin İslam fırkalarını ele alan en önemli klasik eserlerindendir."}], "hint": "Eserlerden biri Eş'arîliğin kurucusu olan ünlü kelamcıya aittir.", "type": "multiple_choice"}, {"question": "Sıffîn Savaşı sonrasında gerçekleşen Tahkim Hadisesi ve Hz. Ali'nin hakeme başvurmayı kabul etmesi neticesinde ortaya çıkan ilk siyasi mezhep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mürcie", "isCorrect": false, "rationale": "Mürcie, iç çatışmalar karşısında tarafsız kalıp büyük günah işleyenin durumunu Allah'a erteleyen fikri akımdır; doğrudan tahkim ayrışmasıyla doğmamıştır."}, {"text": "Mu'tezile", "isCorrect": false, "rationale": "Mu'tezile, Hasan-ı Basrî'nin ders halkasından ayrılan Vâsıl b. Atâ tarafından daha sonraki bir dönemde kurulmuştur."}, {"text": "İbâdiyye", "isCorrect": false, "rationale": "İbâdiyye, Hâricîliğin ılımlı bir kolu olarak daha sonra teşekkül etmiş, doğrudan tahkim olayının kendisinde bağımsız bir fırka olarak çıkmamıştır."}, {"text": "Hâricîlik", "isCorrect": true, "rationale": "Tahkim kararına 'Hüküm ancak Allah'ındır' diyerek karşı çıkan ve Hz. Ali'nin ordusundan ayrılan grup Hâricîliği oluşturmuştur."}], "hint": "Sloganları 'Hüküm ancak Allah'ındır' (Lâ hükme illâ lillâh) olan gruptur.", "type": "multiple_choice"}, {"question": "Hz. Ebû Bekir'in halife seçildikten hemen sonra toplumsal düzeni ve devlet otoritesini korumak adına üstlendiği ilk büyük mücadele aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sa’d b. Ubâde’yi cezalandırarak sürgüne göndermek", "isCorrect": false, "rationale": "Hz. Ebû Bekir Sa'd b. Ubâde'yi cezalandırma yoluna gitmemiş, siyasi uzlaşma zeminini korumuştur."}, {"text": "Emevi soyundan gelen yöneticileri görevden uzaklaştırmak", "isCorrect": false, "rationale": "Emevi valilerine yönelik tasfiye politikası Hz. Ebû Bekir döneminin bir önceliği veya ilk işi olmamıştır."}, {"text": "Hz. Ali'yi Kûfe valisi olarak atamak", "isCorrect": false, "rationale": "Hz. Ebû Bekir döneminde Kûfe şehri henüz kurulmamıştı ve Hz. Ali Kûfe valisi olarak atanmamıştır."}, {"text": "Yalancı peygamberlerle ve zekat vermeyen kabilelerle mücadele etmek", "isCorrect": true, "rationale": "Hz. Ebû Bekir hilafetinin başlangıcında dinî ve siyasi bütünlüğü tehdit eden dinden dönme (ridde) hareketleri, sahte peygamberler ve zekat karşıtlarıyla mücadele etmiştir."}], "hint": "İslam tarih literatüründe 'Ridde Savaşları' olarak adlandırılan olayları düşününüz.", "type": "multiple_choice"}, {"question": "Mu'tezile mezhebinin beş temel esasından biri olan 'el-Menzile beyne'l-Menzileteyn' (iki konum arasında bir konum) prensibi aşağıdaki tartışmalardan hangisiyle doğrudan ilgilidir?", "answerOptions": [{"text": "İnsan fiillerinin yaratıcısının kim olduğu sorunu", "isCorrect": false, "rationale": "Kulun fiilleri ve adalet konusu Mu'tezile'nin 'Adâlet' esasının kapsamına girer."}, {"text": "Allah'ın sıfatlarının zatı ile olan ilişkisi", "isCorrect": false, "rationale": "Sıfatlar meselesi Mu'tezile'nin 'Tevhid' prensibi altında incelenir."}, {"text": "Büyük günah işleyen Müslümanın (mürtekib-i kebîre) durumu", "isCorrect": true, "rationale": "Bu ilke, büyük günah işleyen kişinin ne tam mümin ne de tam kâfir olduğunu, imansızlık ile iman arasında fâsık bir konumda yer aldığını savunur."}, {"text": "İmanın artıp eksilmesi meselesi", "isCorrect": false, "rationale": "İmanın artması ve eksilmesi tartışması daha çok Mürcie, Ehl-i Hadis ve Mâtürîdî/Eş'arî kelamında ele alınan farklı bir konudur."}], "hint": "Vâsıl b. Atâ'nın Hasan-ı Basrî'nin meclisinden ayrılmasına neden olan ana meseledir.", "type": "multiple_choice"}, {"question": "Fiillerin yaratılmasında kaderin mutlak belirleyiciliğini reddederek insanın kendi fiillerinin yaratıcısı olduğunu savunan ve fiili Allah'a değil insana nispet eden mezhep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kaderiyye", "isCorrect": true, "rationale": "Kaderiyye, Allah'ın belirlediği kader anlayışına karşı çıkarak insanın özgür iradesiyle fiillerini yarattığını ileri süren mezheptir."}, {"text": "Mücessime", "isCorrect": false, "rationale": "Mücessime, Allah'ı cisim olarak tahayyül eden ve teşbihe düşen anlayıştır; kader tartışmasıyla doğrudan tanımlanmaz."}, {"text": "Mürcie", "isCorrect": false, "rationale": "Mürcie ana odağını amelin imandan bir cüz olmadığı ve hükmün tehir edilmesi fikrine oturtur."}, {"text": "Cebriyye", "isCorrect": false, "rationale": "Cebriyye tam tersine insanın hiçbir iradesinin bulunmadığını, rüzgarda yaprak gibi kaderin sürüklemesinde olduğunu savunur."}], "hint": "Kaderi kul lehine yorumlayıp, 'kader insan iradesidir' diyen fırkadır.", "type": "multiple_choice"}, {"question": "Mâtürîdîlerin; ilâhî sıfatlar, halku'l-Kur'ân, kader ve insan fiilleri gibi konularda nasları aşırı rasyonel zorlamalarla yorumlayarak sapmaya düştüğü iddiasıyla en çok eleştirdiği mezhep aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Haşviyye", "isCorrect": false, "rationale": "Haşviyye, aklı hiç kullanmayıp metinlerin yüzeysel anlamına takılan grubu ifade eder; akılcı yorum yapmakla suçlanmaz."}, {"text": "Selefiyye", "isCorrect": false, "rationale": "Selefiyye aklı ikincil plana atar; Mâtürîdîlerin aşırı akılcılıkla eleştirdiği grup Selefiyye değildir."}, {"text": "Mu'tezile", "isCorrect": true, "rationale": "Mâtürîdî kelamcılar akla verdikleri aşırı rolle nasların zahirini zedeledikleri gerekçesiyle Mu'tezile'yi tutarsız yorum yapmakla eleştirmişlerdir."}, {"text": "Eş'arîyye", "isCorrect": false, "rationale": "Eş'arîyye, Mâtürîdiyye ile birlikte Ehl-i Sünnet'in iki ana kolundan biridir; aralarında köklü zıtlıktan ziyade küçük cüz'i farklar bulunur."}], "hint": "Akılcılığı ve beş esası (Usûl-i Hamse) ile tanınan kelam mezhebidir.", "type": "multiple_choice"}, {"question": "XVIII. yüzyılda Muhammed b. Abdülvahhâb tarafından Selefî düşünce temellerine dayanarak sistemleştirilen ve Suud hanedanı nezdinde siyasi bir devlet mezhebine dönüştürülen akım aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Vehhâbiyye", "isCorrect": true, "rationale": "Muhammed b. Abdülvahhâb'ın fikirleri doğrultusunda siyasallaşan ve Arap Yarımadası'nda yaygınlaşan hareket Vehhâbiyye olarak adlandırılır."}, {"text": "Zâhiriyye", "isCorrect": false, "rationale": "Dâvûd ez-Zâhirî ve İbn Hazm ile özdeşleşen klasik hukuk ekolüdür."}, {"text": "Zeydiyye", "isCorrect": false, "rationale": "Zeydiyye Şîa'nın Mutedil koludur, XVIII. yüzyıl Suud devletleşmesiyle ilintili değildir."}, {"text": "Mâtürîdiyye", "isCorrect": false, "rationale": "Aklî-naklî dengeyi kuran Ehl-i Sünnet kelam ekolüdür, Vehhabîlik anlayışıyla örtüşmez."}], "hint": "Kurucusunun ismine nispetle adlandırılan ve günümüzde Suudi Arabistan'da resmi nitelik kazanan akımdır.", "type": "multiple_choice"}, {"question": "Mâtürîdiyye mezhebinin kurucusu Ebû Mansur el-Mâtürîdî'ye ait olan, sırasıyla kelam ve tefsir alanındaki iki temel eser aşağıdakilerden hangisinde doğru eşleştirilmiştir?", "answerOptions": [{"text": "el-İbâne - Usûlü'd-Dîn", "isCorrect": false, "rationale": "el-İbâne Eş'arî'ye ait bir kelam eseridir."}, {"text": "Kitâbü't-Tevhîd - Te'vîlâtü'l-Kur'ân", "isCorrect": true, "rationale": "Kitâbü't-Tevhîd Mâtürîdî'nin ana kelam eseri, Te'vîlâtü'l-Kur'ân (Te'vîlâtü Ehli's-Sünne) ise tefsir eseridir."}, {"text": "et-Tebsıra - Dürerü’l-Hukkâm", "isCorrect": false, "rationale": "et-Tebsıra Ebû'l-Mu'în en-Nesefî'ye ait bir kelam kaynağıdır."}, {"text": "el-Fiqhü'l-Ekber - Makâlâtü'l-İslâmiyyîn", "isCorrect": false, "rationale": "el-Fiqhü'l-Ekber Ebû Hanîfe'ye, Makâlâtü'l-İslâmiyyîn ise Eş'arî'ye aittir."}], "hint": "İlk eser tevhidi ve kelami konuları ele alırken, ikincisi bir Kur'an yorumlama çalışmasıdır.", "type": "multiple_choice"}, {"question": "Şîa düşüncesinde Hz. Ali'nin Hz. Peygamber tarafından kendisinden sonraki imam ve halife olarak açıkça tayin edildiğine inanılan tarihsel olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hayber'in Fethi", "isCorrect": false, "rationale": "Hayber'in fethi askeri bir gazvedir; imametin ilanı meselesi olarak temellendirilmez."}, {"text": "Kırtas Hadisesi", "isCorrect": false, "rationale": "Kırtas Hadisesi, Hz. Peygamber'in vefatına yakın kağıt ve kalem istemesi üzerine yaşanan tartışmayı ifade eder."}, {"text": "Sedd-i Ebvâb Olayı", "isCorrect": false, "rationale": "Mescid-i Nebevî'ye açılan kapıların kapatılmasıyla ilgili husustur, siyasi vasiyet ilanı kabul edilmez."}, {"text": "Gadir Hum Hadisesi", "isCorrect": true, "rationale": "Şiiler, Hz. Peygamber'in Veda Haccı dönüşü Gadir Hum denilen mevkide Hz. Ali'yi veli ve imam tayin ettiğini kabul ederler."}], "hint": "Veda Haccı dönüşünde su birikintisi/vaha yakınında gerçekleşen olayı hatırlayınız.", "type": "multiple_choice"}, {"question": "Şîa'yı Ehl-i Sünnet ve diğer tüm İslami fırkalardan ayıran, dinin asılları (Usûlü'd-Dîn) arasında gördükleri en temel itikadi esas aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Meâd", "isCorrect": false, "rationale": "Ahiret günü ve öldükten sonra dirilme (Meâd) İslam inanç esaslarının tamamında mevcuttur."}, {"text": "Tevhid", "isCorrect": false, "rationale": "Tevhid bütün İslami mezheplerin ortak inanç esasıdır, Şîa'yı diğerlerinden ayıran özgün esas değildir."}, {"text": "İmâmet", "isCorrect": true, "rationale": "İmamet, Şîa nezdinde sadece siyasi bir idare meselesi değil, dinin ve inancın temel rükünlerinden biridir."}, {"text": "Nübüvvet", "isCorrect": false, "rationale": "Peygamberlik kurumu tüm Müslüman mezheplerce kabul edilen ortak esastır."}], "hint": "Hz. Peygamber'den sonra Müslümanların dinî ve dünyevi liderliği/masum yöneticiliği ilkesidir.", "type": "multiple_choice"}, {"question": "Günümüzde ana nüfusu Yemen'de varlığını sürdüren, imametin Fatımi soyundan ilim ve kılıçla huruç eden kişiye ait olabileceğini savunan Şîa kolu aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kerbiyye", "isCorrect": false, "rationale": "Kerbiyye tarihte kalmış, günümüze ulaşamamış aşırı (gulat) Şiî kollardandır."}, {"text": "Zeydiyye", "isCorrect": true, "rationale": "Zeyd b. Ali'ye nispet edilen Zeydiyye, Yemen'de yaygın olan ve Ehl-i Sünnet'e görüş itibarıyla en yakın kabul edilen mütadil Şiî koldur."}, {"text": "İsmailiyye", "isCorrect": false, "rationale": "İsmailiyye daha çok Hindistan, Pakistan ve Kanada gibi ülkelerde dağınık yaşar ve yedi imam anlayışına/bâtınî yorumlara odaklanır."}, {"text": "İsnâaşeriyye", "isCorrect": false, "rationale": "İsnâaşeriyye (Ca'feriyye) İran, Irak ve Lübnan'da yaygındır; gizli imam anlayışına dayanır."}], "hint": "Şîa'nın Ehl-i Sünnet'e en yakın mütadil kolu kabul edilir.", "type": "multiple_choice"}, {"question": "İsmailiyye mezhebinin din ve metin anlayışındaki en karakteristik yaklaşım biçimi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Büyük günah işleyen kişileri dinden çıkmış kâfirler olarak nitelendirmek", "isCorrect": false, "rationale": "Bu katı yaklaşım Hâricîliğin genel tutumudur."}, {"text": "İman ile ameli tamamen birbirinden ayırarak ameli önemsizleştirmek", "isCorrect": false, "rationale": "Ameli imandan ayırıp erteleyen yaklaşım Mürcie'ye aittir."}, {"text": "Ayetlerin ve şer'i hükümlerin hem bir 'zahir' hem de gizli bir 'batın' anlamı olduğunu kabul etmek", "isCorrect": true, "rationale": "İsmailiyye, dinî metinlerin dış görünüşünün (zahir) ötesinde sadece imamların öğretebileceği derin bir bâtınî anlam taşıdığına inanır."}, {"text": "Hilafetin sadece Kureyş kabilesi arasında seçimle belirleneceğini savunmak", "isCorrect": false, "rationale": "Şiilikte ve İsmailiyye'de imamet seçimle değil nass ve tayinle gerçekleşir."}], "hint": "Bu sebeple bu mezhep tarihsel literatürde 'Bâtıniyye' adıyla da anılmaktadır.", "type": "multiple_choice"}]}}, "turk-dili-1": {"1": {"unit": 1, "unitTitle": "Dil ve Kültür", "title": "Dil Bilimi Quiz", "questions": [{"question": "Dilin doğuşunu, ilk insanların acı, korku, sevinç gibi içsel durumlarını dışa vururken çıkardıkları seslere ve duygularını ifade etmelerine bağlayan kuram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ding-dong kuramı", "isCorrect": false, "rationale": "Ding-dong kuramı nesnelerin insan zihninde yarattığı titreşim ve ses uyumuna odaklanır."}, {"text": "Ünlem kuramı", "isCorrect": true, "rationale": "Bu kuram, dilin kaynağını insanın sevinç, korku veya acı anlarında çıkardığı doğal ünlemlere ve duygusal tepkilere dayandırır."}, {"text": "Güneş dil kuramı", "isCorrect": false, "rationale": "Güneş dil kuramı, Türkçenin dünya dillerinin kökeninde yer aldığını savunan 20. yüzyıla ait antropolojik ve dil bilimsel bir hipotezdir."}, {"text": "Yansıma kuramı", "isCorrect": false, "rationale": "Yansıma kuramı duygusal tepkileri değil, doğadaki dış seslerin ve nesnelerin taklit edilmesini esas alır."}], "hint": "İnsanın ruh halini gösteren ani ses tepkilerini ve hislerin dışa vurumunu düşününüz.", "type": "multiple_choice"}, {"question": "Doğadaki seslerin, hayvan çığlıklarının ve çevredeki nesnelerin çıkardığı seslerin insanlar tarafından taklit edilmesi esasına dayanan dilin doğuşu kuramı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tek köken kuramı", "isCorrect": false, "rationale": "Tek köken kuramı dilin doğuş biçiminden ziyade tüm dillerin tek bir ata dilden türediğini savunur."}, {"text": "Yansıma kuramı", "isCorrect": true, "rationale": "Bu görüş, ilk kelimelerin insanların doğadaki gürültüleri, hayvan seslerini ve nesnelerin çıkardığı sesleri taklit etmesiyle oluştuğunu ileri sürer."}, {"text": "Ünlem kuramı", "isCorrect": false, "rationale": "Ünlem kuramı dış dünyadaki seslerin taklidinden ziyade insanın kendi duygusal çığlıklarını temel alır."}, {"text": "Etkileşim kuramı", "isCorrect": false, "rationale": "Etkileşim kuramı dilin doğuşunu toplumsal iş birliği ve birlikte çalışma sırasındaki sesleşmelere bağlar."}], "hint": "Doğada duyulan şırıltı, patırtı gibi yansıma seslerin oluşum mantığını hatırlayınız.", "type": "multiple_choice"}, {"question": "\"Tarihteki hiçbir dil günümüz modern dillerinden dil bilgisi yapıları bakımından geri değildir ve insan topluluklarının kullandığı tüm diller toplumun gereksinimlerine cevap verecek yeterliktedir.\" Bu durum bilimsel bakımdan dilin hangi özelliğini ifade eder?", "answerOptions": [{"text": "Dilin üretim yetisi sınırsızdır.", "isCorrect": false, "rationale": "Üretim yetisinin sınırsızlığı, sınırlı sayıda sesle sonsuz sayıda yeni cümle üretilebilmesi özelliğini anlatır."}, {"text": "İlkel dil, gelişmiş dil ayrımı yoktur.", "isCorrect": true, "rationale": "Dil bilimi ilkelerine göre her dil, ait olduğu toplumun ihtiyaçlarını karşılayabilecek gelişmişliktedir ve ilkel dil tanımı bilimsel olarak geçerli değildir."}, {"text": "Dilde nedensizlik ilkesi esastır.", "isCorrect": false, "rationale": "Nedensizlik ilkesi, gösterge ile gösterilen (kavram ile ses imgesi) arasında zorunlu bir bağ olmamasını ifade eder."}, {"text": "Dil, öncelikle yazılı bir anlatım aracıdır.", "isCorrect": false, "rationale": "Dil tarihsel ve bilimsel açıdan öncelikle sözlü bir sistemdir; yazı dili sonradan geliştirilmiştir."}], "hint": "Diller arasında gelişim seviyesi yönünden bir hiyerarşi bulunmadığı fikrine odaklanın.", "type": "multiple_choice"}, {"question": "Dilin sesli ve yazılı biçimleri ile ilgili aşağıdaki ifadelerden hangisi bilimsel olarak doğrudur?", "answerOptions": [{"text": "Dillerin öncelikli amacı yazılı belgeler oluşturmaktır.", "isCorrect": false, "rationale": "Dilin temel işlevi toplumsal iletişimi ve anlaşmayı sağlamaktır; yazılı belge oluşturmak ikincil bir araçtır."}, {"text": "Yazılı dil, konuşma dilinden mantıksal açıdan her zaman üstündür.", "isCorrect": false, "rationale": "Bilimsel olarak sözlü ve yazılı dil arasında niteliksel veya mantıksal bir üstünlük hiyerarşisi bulunmamaktadır."}, {"text": "Dilin temeli sestir ve tarihsel olarak konuşma dili yazıdan çok daha eskidir.", "isCorrect": true, "rationale": "İnsanlık tarihinde sözlü iletişim yazıdan çok daha önce var olmuştur ve dilin temel yapı taşını konuşma sesleri oluşturur."}, {"text": "Konuşma sesleri tek başlarına bağımsız birer anlam taşırlar.", "isCorrect": false, "rationale": "Tek başlarına konuşma sesleri anlamsızdır; anlam ancak seslerin belirli kurallarla dizilmesiyle ortaya çıkar."}], "hint": "İnsanlık tarihinin ilk iletişim biçimlerini ve konuşmanın yazıya göre önceliğini düşünün.", "type": "multiple_choice"}, {"question": "Herhangi bir dil ailesiyle akrabalık bağı kanıtlanamamış, bilinen diğer dillerden tamamen bağımsız yapıda olan diller \"izole dil\" olarak adlandırılır. Buna göre aşağıdakilerden hangisi izole dillerden biridir?", "answerOptions": [{"text": "Kazakça", "isCorrect": false, "rationale": "Kazakça, Türk dilleri ailesine ait Kıpçak grubu dillerindendir."}, {"text": "Farsça", "isCorrect": false, "rationale": "Farsça, izole bir dil olmayıp Hint-Avrupa dil ailesinin Hint-İran koluna mensuptur."}, {"text": "Gürcüce", "isCorrect": true, "rationale": "Gürcüce, bilinen büyük dil ailelerinin hiçbiriyle doğrudan akrabalık bağı kurulamayan izole diller kategorisindedir."}, {"text": "Yunanca", "isCorrect": false, "rationale": "Yunanca, Hint-Avrupa dil ailesine dahil olan köklü bir dildir."}], "hint": "Kafkas coğrafyasında konuşulan ve bilinen büyük dil ailelerinin hiçbirine dahil edilmeyen dili arayınız.", "type": "multiple_choice"}, {"question": "Tarihte dinî metinlerin yazıldığı, ibadet dili olarak kabul edildiği ve kutsallık atfedildiği bilinen dillerden biri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sanskritçe", "isCorrect": true, "rationale": "Sanskritçe, Eski Hindistan'da dinî metinlerin, duaların ve kutsal metinlerin dili olarak kabul edilmiş klasik bir kutsal dildir."}, {"text": "Almanca", "isCorrect": false, "rationale": "Almanca, Cermen dil grubuna ait ulusal ve resmî bir dildir, kutsal diller sınıflandırmasında yer almaz."}, {"text": "İsveççe", "isCorrect": false, "rationale": "İsveççe, Kuzey Cermen dilleri arasında yer alan ulusal bir konuşma dilidir."}, {"text": "Tatarca", "isCorrect": false, "rationale": "Tatarca, Kıpçak grubuna ait bir Türk dili olup kutsal dil statüsünde değerlendirilmez."}], "hint": "Eski Hindistan'da dinî ve felsefi metinlerin kaleme alındığı tarihi dili hatırlayın.", "type": "multiple_choice"}, {"question": "Ölçünlü (standart) dil kavramı ile ilgili aşağıdaki yargılardan hangisi yanlıştır?", "answerOptions": [{"text": "Bir dilin kurala bağlanmış, kurumlarca kabul görmüş standart özelliklerine ölçünlü dil denir.", "isCorrect": false, "rationale": "Ölçünlü dil terimi, dilin gramer ve imla kurallarıyla standartlaştırılmış biçimini doğru tanımlar."}, {"text": "Resmî yazışmalarda ve eğitimde kullanılan standart dil ölçünlü dildir.", "isCorrect": false, "rationale": "Eğitim, kamu yönetimi ve hukuk gibi resmî alanlarda karmaşayı önlemek için ölçünlü dil kullanılır."}, {"text": "Ölçünlü dil hem yazı hem de konuşma dilini kapsayan kurallaştırılmış yapıdır.", "isCorrect": false, "rationale": "Standart dil kuralları hem resmî konuşmalarda hem de yazılı anlatımda geçerlidir."}, {"text": "Ölçünlü Türkçe, Ankara ağzı esas alınarak oluşturulmuş bir konuşma dilidir.", "isCorrect": true, "rationale": "Ölçünlü (standart) Türkçe Ankara ağzına değil, İstanbul konuşma ağzına dayalı olarak biçimlenmiştir."}], "hint": "Türkiye Türkçesinin ölçünlü formunun tarihsel olarak hangi şehir ağzına dayandığını düşünün.", "type": "multiple_choice"}, {"question": "Kültürün kuşaktan kuşağa aktarılmasını sağlayan, taşıyıcısı ve en temel ögesi konumundaki unsur aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hukuk", "isCorrect": false, "rationale": "Hukuk toplumsal düzeni sağlayan kurallar bütünüdür, kültür aktarımının ana taşıyıcısı konumunda değildir."}, {"text": "Dil", "isCorrect": true, "rationale": "Dil, bir toplumun geçmişten getirdiği tüm maddi ve manevi değerleri muhafaza eden ve kuşaktan kuşağa aktaran ana vasıtadır."}, {"text": "Sanat", "isCorrect": false, "rationale": "Sanat kültürün önemli bir dışa vurumu olsa da birikimin aktarılmasını sağlayan temel araç dilin kendisidir."}, {"text": "Mimari", "isCorrect": false, "rationale": "Mimari maddi kültür ögesidir; soyut fikir, inanç ve değerlerin bütüncül aktarımını tek başına sağlayamaz."}], "hint": "Soyut duygu, düşünce ve birikimlerin sözel veya yazılı aktarım vasıtasını hatırlayın.", "type": "multiple_choice"}, {"question": "Kültürü oluşturan maddi ve manevi ögeler dikkate alındığında, aşağıdakilerden hangisi manevi ögeler arasında yer alır?", "answerOptions": [{"text": "Mimari yapılar ve binalar", "isCorrect": false, "rationale": "Fiziksel olarak inşa edilen tüm yapılar maddi kültürün somut tezahürleridir."}, {"text": "Geleneksel giysi ve kıyafetler", "isCorrect": false, "rationale": "Giysi ve kıyafetler somut ve nesnel nitelik taşıdıkları için maddi kültür ögeleri arasında sayılır."}, {"text": "Atasözleri ve inançlar", "isCorrect": true, "rationale": "Toplumun zihinsel birikimlerini, değer yargılarını, sözlü geleneklerini ve dünya görüşünü yansıtan unsurlar manevi kültür ögeleridir."}, {"text": "Üretimde kullanılan araç-gereçler", "isCorrect": false, "rationale": "Araç ve gereçler somut nesneler olduğu için maddi kültür alanına girer."}], "hint": "Zihinsel, soyut ve toplumsal değer yargıları içeren unsurları göz önünde bulundurun.", "type": "multiple_choice"}, {"question": "\"Dil; ses, biçim, söz dizimi ve anlam gibi birbiriyle bağlantılı alt sistemlerin oluşturduğu bütüncül bir yapıdır.\" Bu tanım dilin hangi temel özelliğini vurgulamaktadır?", "answerOptions": [{"text": "Dilin tamamen bireysel bir edim olduğunu", "isCorrect": false, "rationale": "Dil bireysel değil, toplumsal uzlaşıya dayanan kuralcı bir sistemdir."}, {"text": "Dilin bir sistem olduğunu", "isCorrect": true, "rationale": "Birbiriyle uyumlu çalışarak iletişimi mümkün kılan alt birimlerin oluşturduğu bütünlük, dilin sistemik yapısını açıklar."}, {"text": "Dilin coğrafyalara göre değiştiğini", "isCorrect": false, "rationale": "Coğrafi değişim diyalekt ve ağız farklılıklarını açıklar, alt sistemlerin bütünlüğünü vurgulamaz."}, {"text": "Dilde nedensizlik ilkesinin geçerli olduğunu", "isCorrect": false, "rationale": "Nedensizlik ilkesi nesneler ile onları karşılayan kelimeler arasındaki nedensiz bağ ilişkisini ifade eder."}], "hint": "Ögelerin düzenli bir bütün oluşturması ve belirli kurallara göre işlemesi durumuna ne ad verildiğini düşünün.", "type": "multiple_choice"}, {"question": "Bir dilin coğrafi, toplumsal ve tarihî süreçlerde ağız, şive ve lehçe gibi farklı \"değişke\"lere ayrılmasının temel nedeni aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dilin zamana, coğrafyaya ve toplumsal katmanlara bağlı olarak sürekli değişmesi", "isCorrect": true, "rationale": "Dil durağan olmayıp zamanla, farklı coğrafyalarla ve toplumsal gruplarla etkileşime girerek çeşitlenir ve değişkelere ayrılır."}, {"text": "Yazı dilinin konuşma dilinden daha sonra keşfedilmiş olması", "isCorrect": false, "rationale": "Yazının keşif zamanı, dilde coğrafi veya toplumsal varyasyonların oluşmasının doğrudan nedeni değildir."}, {"text": "Dilde ilkeller ve gelişmişler ayrımının bulunması", "isCorrect": false, "rationale": "Dil biliminde ilkel dil-gelişmiş dil ayrımı yoktur, dolayısıyla değişke sebebi olamaz."}, {"text": "Dillerin yalnızca resmî yazışmalarda kullanılması", "isCorrect": false, "rationale": "Dilin günlük yaşamda ve her kesimce kullanılması değişkeleșmeyi artırır; sadece resmî kullanım çeşitliliği azaltırdı."}], "hint": "Dilin durağan olmayıp toplumla ve mekanla birlikte dönüşme karakterini göz önüne alın.", "type": "multiple_choice"}, {"question": "\"Dil hem düşünceyi aktaran bir araç, hem edebî ve fikrî ürünlerin hammaddesi olan malzeme, hem de bu sistemi işleten bir düzendir.\" ifadesi dilin hangi yönünü öne çıkarmaktadır?", "answerOptions": [{"text": "Araç-amaç ikiliği ve çok yönlülüğü", "isCorrect": true, "rationale": "Dilin hem duygu/düşünce aktarımında vasıta olması hem de kendisinin inceleme ve sanat nesnesi yapılması çok yönlü yapısını gösterir."}, {"text": "Yalnızca yazılı kurallara dayanmasını", "isCorrect": false, "rationale": "Bu ifade dilin tek yönlü yazılı kuralcılığını değil, işlevsel çeşitliliğini ve esnekliğini anlatır."}, {"text": "Yalnızca tek bir toplumsal sınıfa ait olmasını", "isCorrect": false, "rationale": "Dil tüm topluma ait ortak bir kurumdur, tek bir sınıfla sınırlandırılamaz."}, {"text": "Sözcüklerin nedensiz bağlarla oluşmasını", "isCorrect": false, "rationale": "Nedensizlik kavramı kelimelerin anlamlandırılmasıyla ilgilidir, dilin işlevsel çift yönlülüğünü kapsamaz."}], "hint": "Dilin hem iletişimi sağlayan bir vasıta hem de incelenen nesnenin kendisi olması durumunu değerlendirin.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi Birleşmiş Milletler (BM) örgütünün resmî dillerinden biridir?", "answerOptions": [{"text": "Portekizce", "isCorrect": false, "rationale": "Portekizce küresel düzeyde geniş bir coğrafyada konuşulmasına rağmen BM resmî diller listesinde yoktur."}, {"text": "Çince", "isCorrect": true, "rationale": "Çince, Birleşmiş Milletler'in İngilizce, Fransızca, Rusça, İspanyolca ve Arapça ile birlikte kabul ettiği altı resmî dilden biridir."}, {"text": "Korece", "isCorrect": false, "rationale": "Korece Doğu Asya'da önemli bir dil olmasına karşın BM resmî dili statüsünde değildir."}, {"text": "Almanca", "isCorrect": false, "rationale": "Almanca Avrupa'da yaygın konuşulsa da Birleşmiş Milletler'in resmî dilleri arasında yer almaz."}], "hint": "Dünyada en çok konuşuru bulunan ve BM'nin altı resmî dilinden biri olan Doğu Asya dilini düşünün.", "type": "multiple_choice"}]}, "2": {"unit": 2, "unitTitle": "Türk Dilinin Gelişimi ve Tarihsel Dönemleri", "title": "Türk Dili Testi", "questions": [{"question": "Türkçenin metinlerle takip edilebilen tarihi boyunca kullandığı, kendine özgü ilk düzenli ve kuralları yerleşmiş yerli yazı sistemi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Soğd alfabesi", "isCorrect": false, "rationale": "İran kökenli bir alfabe olup Uygur yazısının oluşumuna temel sağlamıştır ancak Türklerin özgün ilk alfabesi değildir."}, {"text": "Uygur alfabesi", "isCorrect": false, "rationale": "Soğd alfabesinden türetilen ve Köktürk alfabesinden sonra geniş kabul gören bir yazı sistemidir."}, {"text": "Mani alfabesi", "isCorrect": false, "rationale": "Maniheizm dininin kabulüyle beraber dar bir çevrede tercih edilen alfabelerden biridir."}, {"text": "Köktürk alfabesi", "isCorrect": true, "rationale": "Türklerin bilinen ilk millî alfabesi olup Orhun Yazıtları bu gelişmiş ve kuralları oturmuş yazı sistemiyle taşa kazınmıştır."}], "hint": "Batılı bilginlerce 'Runik' olarak adlandırılan ve Orhun Yazıtları'nın yazımında kullanılan alfabeyi düşününüz.", "type": "multiple_choice"}, {"question": "Türk dilinin yazıyla izlenebilen ilk dönemi olan ve MS 5.-10. yüzyıllar arasında Göktürk ile Uygur metinlerini kapsayan tarihî dönem aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Çağatay Türkçesi Dönemi", "isCorrect": false, "rationale": "Doğu Türkçesi kolunda Müşterek Türkistan Türkçesi olarak gelişen daha geç bir dönemi ifade eder."}, {"text": "Orta Türkçe Dönemi", "isCorrect": false, "rationale": "İslamiyet'in kabulünden sonra Karahanlı, Harezm ve Çağatay sahalarını kapsayan sonraki evredir."}, {"text": "Yeni Türkçe Dönemi", "isCorrect": false, "rationale": "20. yüzyıl sonrasını ve modern yazı dillerinin oluştuğu evreyi kapsar."}, {"text": "Eski Türkçe Dönemi", "isCorrect": true, "rationale": "Türkçenin bilinen ilk hacimli yazılı belgelerinin verildiği ve Köktürk ile Uygur evrelerini kapsayan ilk tarihî dönemdir."}], "hint": "MS 5. ile 10. yüzyıllar arasında varlık gösteren ve Türkçenin bilinen en eski yazılı örneklerini barındıran ilk dönemi hatırlayınız.", "type": "multiple_choice"}, {"question": "Soğd yazı sisteminin dönüştürülmesiyle oluşturulan ve Moğol ile Mançu gibi toplulukların alfabelerine de kaynaklık eden tarihî alfabe aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Uygur alfabesi", "isCorrect": true, "rationale": "Soğd alfabesinden uyarlanarak geliştirilmiş ve çevre halkların alfabe yapılarına da modellik etmiştir."}, {"text": "Süryani alfabesi", "isCorrect": false, "rationale": "Yakın Doğu kökenli bir alfabe olup Türkçenin yazımında kısıtlı dinî metinlerde tercih edilmiştir."}, {"text": "Brahmi alfabesi", "isCorrect": false, "rationale": "Hindistan kaynaklı olup Budist metinlerin tercümesinde kısıtlı biçimde kullanılmıştır."}, {"text": "Köktürk alfabesi", "isCorrect": false, "rationale": "Yerli ve özgün damgalardan gelişmiş olup dış kaynaklı Soğd alfabesine dayanmaz."}], "hint": "Yerleşik hayata geçen Türk topluluklarının uzun yıllar zengin bir edebiyat külliyatı oluştururken yararlandığı alfabeyi göz önüne getiriniz.", "type": "multiple_choice"}, {"question": "Karahanlı ve Harezm Türkçesi metinlerini kapsayan, Türklerin İslam kültür çevresine girmesiyle şekillenen tarihî evre aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Yeni Türkçe Dönemi", "isCorrect": false, "rationale": "Modern Çağ'daki çağdaş Türk şivelerini ve yazı dillerini kapsayan evredir."}, {"text": "Hun Dönemi", "isCorrect": false, "rationale": "Türkçenin henüz yazılı belgelerle geniş biçimde takip edilemediği çok daha eski döneme aittir."}, {"text": "Orta Türkçe Dönemi", "isCorrect": true, "rationale": "Karahanlı ve Harezm sahası eserleriyle İslam etkisindeki ilk yazılı ürünlerin ortaya konduğu dönemi ifade eder."}, {"text": "Eski Türkçe Dönemi", "isCorrect": false, "rationale": "İslam öncesi Göktürk ve Uygur metinlerinin üretildiği ilk dönemi kapsar."}], "hint": "Divânü Lügati't-Türk ve Kutadgu Bilig gibi geçiş dönemi eserlerinin kaleme alındığı yüzyılları kapsayan dönemi değerlendiriniz.", "type": "multiple_choice"}, {"question": "Müşterek Türkistan Türkçesi adıyla da anılan ve Ali Şîr Nevâî'nin Muhakemetü'l-Lügateyn adlı eseriyle zirveye ulaşan edebî dil dönemi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Oğuz Türkçesi", "isCorrect": false, "rationale": "Türkiye Türkçesi ve Azerbaycan Türkçesinin temelini oluşturan Batı Türkçesi koludur."}, {"text": "Kıpçak Türkçesi", "isCorrect": false, "rationale": "Kuzey Türkçesi alanında Altınordu ve Karadeniz'in kuzeyinde gelişen yazı dilidir."}, {"text": "Çağatay Türkçesi", "isCorrect": true, "rationale": "Doğu Türkçesi sahasında gelişen ve Orta Asya Türk dünyasının ortak edebî dili olarak işlev gören tarihî yazı dilidir."}, {"text": "Uygur Türkçesi", "isCorrect": false, "rationale": "Eski Türkçe dönemi içinde yer alan ve Budist-Maniheist metinlerle tanınan evredir."}], "hint": "Doğu Türkçesi kolunun en önemli edebî gelişim safhasını dikkate alınız.", "type": "multiple_choice"}, {"question": "MS 687-692 yıllarına tarihlenen ve Türk dilinin tarihi bilinen ilk yazılı belgesi kabul edilen yazıt aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Yenisey Yazıtları", "isCorrect": false, "rationale": "Tarihlenmesi tam olarak kesinleşmemiş, daha kısa nitelikli mezar taşlarıdır."}, {"text": "Çoyr Yazıtı", "isCorrect": true, "rationale": "Tarihi kesin olarak belirlenebilen en eski Türk yazılı belgesi olma niteliğini taşır."}, {"text": "Kül Tigin Yazıtı", "isCorrect": false, "rationale": "732 yılında dikilen ve Köktürk alfabesiyle yazılan görkemli bir anıttır."}, {"text": "Bilge Kağan Yazıtı", "isCorrect": false, "rationale": "8. yüzyılda (735 civarı) dikilmiş ana Orhun abidelerinden biridir."}], "hint": "MS 7. yüzyılın sonlarına tarihlenen ve bilinen en eski yazılı Türk anıtı olma özelliğini taşıyan metni düşününüz.", "type": "multiple_choice"}, {"question": "Kuzey Türkçesi (Kıpçak Türkçesi) sahasında kaleme alınan, Kıpçak Türkçesinin söz varlığı ve dil bilgisi bakımından en önemli kaynağı sayılan eser aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Atebetü'l-Hakâyık", "isCorrect": false, "rationale": "Edip Ahmet Yüknekî tarafından Karahanlı Türkçesiyle yazılmış ahlaki bir öğüt kitabıdır."}, {"text": "Kutadgu Bilig", "isCorrect": false, "rationale": "Karahanlı Türkçesi dönemiyle yazılmış siyasetname niteliğinde ilk İslami eserdir."}, {"text": "Muhakemetü'l-Lügateyn", "isCorrect": false, "rationale": "Ali Şîr Nevâî tarafından Çağatay Türkçesi ile Farsça karşılaştırmalı olarak yazılmıştır."}, {"text": "Codex Cumanicus", "isCorrect": true, "rationale": "Karadeniz'in kuzeyindeki Kıpçak Türklerinin dilini yansıtan ve Hristiyan misyonerlerce derlenen temel kaynaktır."}], "hint": "Karadeniz'in kuzeyindeki Kıpçaklar ile Avrupalılar arasındaki ticari ve dinî ilişkiler sonucu derlenen derleme eseri hatırlayınız.", "type": "multiple_choice"}, {"question": "Çağdaş Türkiye Türkçesi aşağıdaki tarihî Türk dili kollarından hangisinin doğrudan devamı kabul edilmektedir?", "answerOptions": [{"text": "Oğuz Türkçesi", "isCorrect": true, "rationale": "Selçuklu ve Osmanlı üzerinden günümüz Türkiye Türkçesine ulaşan Batı Türkçesi kolunu oluşturur."}, {"text": "Çağatay Türkçesi", "isCorrect": false, "rationale": "Özbek ve Doğu Türkistan alanındaki çağdaş lehçelerin tarihî temelidir."}, {"text": "Kıpçak Türkçesi", "isCorrect": false, "rationale": "Tatar, Başkurt ve Kazak Türkçesi gibi Kuzey grubu lehçelerinin kaynağını oluşturur."}, {"text": "Karluk Türkçesi", "isCorrect": false, "rationale": "Doğu grubunun oluşumunda rol oynayan ve Karahanlı Türkçesine zemin oluşturan koldur."}], "hint": "Yunus Emre ve Âşık Paşa gibi isimlerin ilk örneklerini verdiği Batı Türkçesi ana kolunu dikkate alınız.", "type": "multiple_choice"}, {"question": "1926 yılında toplanan ve Çuvaşlar haricindeki tüm Türk topluluklarının Latin alfabesine geçmesi yönünde tarihi bir karar alan kongre aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kazan Türkoloji Toplantısı", "isCorrect": false, "rationale": "Tatar dili üzerine odaklanan, tüm Türk dünyasını bağlayan genel kararın çıkmadığı bir etkinliktir."}, {"text": "Bakü Türkoloji Kongresi", "isCorrect": true, "rationale": "Türk dünyasının ortak alfabe kullanımı ve dil meselelerinin karara bağlandığı simge toplantıdır."}, {"text": "Almatı Kültür Kongresi", "isCorrect": false, "rationale": "Kazakistan sahasındaki dil çalışmalarıyla sınırlı yerel bir buluşmadır."}, {"text": "Taşkent Dil Kurultayı", "isCorrect": false, "rationale": "Orta Asya'da bölgesel alfabe düzenlemeleri yapılan ancak bu kararın alındığı ana kongre olmayan bir toplantıdır."}], "hint": "1920'li yıllarda Azerbaycan'ın başkentinde düzenlenen geniş katılımlı Türkoloji kongresini hatırlayınız.", "type": "multiple_choice"}, {"question": "Türkçenin metinlerle takip edilemeyen, teorik karşılaştırmalarla (rekonstrüksiyon) kurgulanan en eski karanlık dönemi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Karahanlı Dönemi", "isCorrect": false, "rationale": "İslami dönemin ilk yazılı eserlerinin verildiği takipli evredir."}, {"text": "Altay Dönemi", "isCorrect": true, "rationale": "Türkçenin henüz ayrı bir dil olarak şekillenmediği, Altay dil birliği içinde değerlendirildiği yazısız evredir."}, {"text": "Harezm Dönemi", "isCorrect": false, "rationale": "14. yüzyılda Altınordu ve Orta Asya sahasında zengin yazılı metinler sunan dönemdir."}, {"text": "Uygur Dönemi", "isCorrect": false, "rationale": "Yüzlerce yazılı belgenin günümüze ulaştığı metinlerle izlenebilir bir dönemdir."}], "hint": "Türkçenin henüz Moğolca, Mançu-Tunguzca gibi akraba dillerle bir arada bulunduğu düşünülen en eski evreyi değerlendiriniz.", "type": "multiple_choice"}, {"question": "Batı Türkçesinin ilk evresi olan Eski Oğuz Türkçesi dönemi dil özelliklerini yansıtan ve destansı anlatılar barındıran eser aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dede Korkut Kitabı", "isCorrect": true, "rationale": "Oğuz Türklerinin toplumsal hayatını ve dil yapısını Eski Anadolu Türkçesi dönemi özellikleriyle günümüze taşıyan destansı metindir."}, {"text": "Mukaddimetü'l-Edeb", "isCorrect": false, "rationale": "Zemahşerî tarafından Harezm Türkçesi sahasında hazırlanan Arapça öğretim sözlüğüdür."}, {"text": "Divânü Lügati't-Türk", "isCorrect": false, "rationale": "11. yüzyılda Kâşgarlı Mahmud tarafından Karahanlı sahasında yazılmış Arapça-Türkçe sözlüktür."}, {"text": "Nehcü'l-Ferâdis", "isCorrect": false, "rationale": "Harezm Türkçesi döneminde dinsel ve ahlaki konularda kaleme alınan bir yapıttır."}], "hint": "Salur Kazan, Bamsı Beyrek gibi kahramanların yer aldığı ve Batı Türkçesinin ilk evresini yansıtan eseri hatırlayınız.", "type": "multiple_choice"}, {"question": "Tarih boyunca Türklerin dillerini kaydetmek için kullandığı 13 farklı alfabe arasında aşağıdakilerden hangisi yer almaz?", "answerOptions": [{"text": "İbrani alfabesi", "isCorrect": false, "rationale": "Musevi dinine mensup Hazar Türkleri ve Karaylar tarafından kullanılan yazılardandır."}, {"text": "Süryani alfabesi", "isCorrect": false, "rationale": "Hristiyan Türk topluluklarının dinî metinleri yazarken tercih ettiği alfabelerdendir."}, {"text": "Mani alfabesi", "isCorrect": false, "rationale": "Uygur döneminde Maniheizm inancının benimsenmesiyle kullanılan yazı sistemlerinden biridir."}, {"text": "Japon alfabesi", "isCorrect": true, "rationale": "Türklerin tarihsel süreçte coğrafi ve kültürel temaslar sonucunda kullandığı 13 yazı sistemi arasında bulunmamaktadır."}], "hint": "Türkçenin yazımında kullanılan 13 tarihî ve çağdaş alfabeden biri olmayan Doğu Asya kökenli yazı sistemini arayınız.", "type": "multiple_choice"}]}, "3": {"unit": 3, "unitTitle": "Ses Bilgisi", "title": "Ses Bilgisi Testi", "questions": [{"question": "Konuşurların sesleri nasıl ürettiğini, ciğerlerden gelen havanın ses organlarında uğradığı değişiklikleri ve oluşum noktalarını inceleyen ses bilgisi alt dalı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Akustik ses bilgisi", "isCorrect": false, "rationale": "Bu alan seslerin fiziksel olarak havada nasıl yol aldığını ve ses dalgalarının özelliklerini inceler."}, {"text": "İşitsel ses bilgisi", "isCorrect": false, "rationale": "Bu alt dal seslerin dinleyen kişinin kulağı ve beyni tarafından nasıl algılandığını konu edinir."}, {"text": "Tarihî ses bilgisi", "isCorrect": false, "rationale": "Bu alan dilin ses yapısının tarihsel süreç içerisindeki evrimini ve değişimlerini inceler."}, {"text": "Söyleyiş ses bilgisi", "isCorrect": true, "rationale": "Konuşanın ses organlarını kullanarak sesleri üretme ve boğumlama sürecini doğrudan inceleyen alan söyleyiş ses bilgisidir."}], "hint": "Seslerin konuşmacı tarafından fizyolojik olarak organlar vasıtasıyla çıkarılması sürecine odaklanmalısınız.", "type": "multiple_choice"}, {"question": "Türkçedeki 'e' ünlüsünün boğumlanma özelliklerine göre sınıflandırılması aşağıdakilerin hangisinde doğru ve eksiksiz olarak verilmiştir?", "answerOptions": [{"text": "Ön, düz, geniş", "isCorrect": true, "rationale": "/e/ sesi dilin ön tarafının yükselmesiyle oluşur, dudaklar düzdür ve çene açıklığı geniş konumdadır."}, {"text": "Ön, düz, dar", "isCorrect": false, "rationale": "Ağız açıklığının dar olması durumunda ön-düz konumda /i/ ünlüsü ortaya çıkar."}, {"text": "Art, düz, dar", "isCorrect": false, "rationale": "Bu özellikler dilin arka tarafında oluşan /ı/ ünlüsüne aittir."}, {"text": "Ön, yuvarlak, geniş", "isCorrect": false, "rationale": "Dudakların yuvarlaklaşması durumunda ön-geniş konumda /ö/ ünlüsü oluşur."}], "hint": "Ünlünün dil pozisyonu (ön/art), dudak biçimi (düz/yuvarlak) ve çene açıklığı (geniş/dar) ölçütlerini değerlendirin.", "type": "multiple_choice"}, {"question": "Eski Türkçe dönemindeki 'öpke > öfke' veya 'beg > bey' örneklerinde görülen ses olayı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ünsüz tekleşmesi", "isCorrect": false, "rationale": "İkizleşmiş veya çift yazılan bir ünsüzün teke düşmesidir."}, {"text": "Göçüşme", "isCorrect": false, "rationale": "Sözcük içindeki iki ünsüzün birbiriyle yer değiştirmesidir."}, {"text": "Ötümlüleşme", "isCorrect": false, "rationale": "Ötümsüz bir sesin ses tellerinin titreşimiyle ötümlü hâle gelmesidir."}, {"text": "Süreklileşme", "isCorrect": true, "rationale": "Patlamalı/süreksiz bir ünsüzün (/p/, /g/), sızıcı/sürekli bir ünsüze (/f/, /y/) dönüşmesi süreklileşme olarak adlandırılır."}], "hint": "Hava akımını aniden kesen patlamalı bir sesin, havayı sızdıran sürekli bir sese dönüşmesini düşünün.", "type": "multiple_choice"}, {"question": "Arapçadan dilimize geçen 'hamir' sözcüğünün Türkçede 'hamur' şekline dönüşmesinde görülen ses olayı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ünlü daralması", "isCorrect": false, "rationale": "Geniş bir ünlünün dar bir ünlüye dönüşmesidir."}, {"text": "Ünsüz benzeşmesi", "isCorrect": false, "rationale": "Ünsüz seslerin nitelikçe birbirine yaklaşması veya aynı olmasıdır."}, {"text": "Ön damaksıllaşma", "isCorrect": false, "rationale": "Art ünlünün ön ünlüye dönüşmesi olayıdır (bıç- > biç- gibi)."}, {"text": "Ünlü yuvarlaklaşması", "isCorrect": true, "rationale": "İkinci hecedeki düz-dar /i/ ünlüsü, birinci hecedeki dudak ünsüzü veya çevre etkisiyle yuvarlak-dar /u/ sesine dönüşmüştür."}], "hint": "İkinci hecedeki düz sesin dudakların büzülmesiyle aldığı yeni biçimi göz önüne getirin.", "type": "multiple_choice"}, {"question": "Türkçe kökenli sözcüklerin ses özellikleri dikkate alındığında, aşağıdakilerden hangisi doğrudan yabancı kökenli bir sözcüktür?", "answerOptions": [{"text": "Neşe", "isCorrect": true, "rationale": "Türkçe kökenli sözcüklerin başında istisnalar dışında /n/ ünsüzü bulunmaz ve 'neşe' bu istisnai Türkçe köklerden biri değildir."}, {"text": "Pek", "isCorrect": false, "rationale": "Başta /p/ ünsüzü barındırmasına karşın Türkçe kökenli kabul edilen istisnai kelimelerdendir."}, {"text": "Şimdi", "isCorrect": false, "rationale": "Söz başında /ş/ bulunmasına rağmen Eski Türkçedeki biçimden gelişmiş Türkçe kökenli bir istisnadır."}, {"text": "Pınar", "isCorrect": false, "rationale": "Söz başında /p/ bulunmasına rağmen Türkçe kökenli istisnai sözcükler arasında yer alır."}], "hint": "Türkçe sözcüklerin başında bulunmayan ünsüzleri ve bu kuralın Türkçe kökenli bilinen istisnalarını dikkate alın.", "type": "multiple_choice"}, {"question": "'kirpik > kiprik' ve 'ekşi > eşki' örneklerinde görülen, sözcük içindeki ünsüzlerin birbiriyle yer değiştirmesi olayına ne ad verilir?", "answerOptions": [{"text": "Göçüşme", "isCorrect": true, "rationale": "Komşu hecelerdeki veya yan yana duran ünsüzlerin yer değiştirmesi göçüşme (metatez) olarak tanımlanır."}, {"text": "Ünsüz aykırılaşması", "isCorrect": false, "rationale": "Birbiriyle aynı veya benzer olan iki sesin farklılaşmasıdır."}, {"text": "Ötümsüzleşme", "isCorrect": false, "rationale": "Ötümlü bir sesin sertleşerek ötümsüz hâle gelmesidir."}, {"text": "Ünsüz ikizleşmesi", "isCorrect": false, "rationale": "Sözcük içindeki tek bir ünsüzün iki defa telaffuz edilmesidir."}], "hint": "Seslerin sözcük içinde karşılıklı olarak yer değiştirmesi terimini hatırlayın.", "type": "multiple_choice"}, {"question": "Aşağıdaki cümlelerin hangisinde yer alan altı çizili sözcükte ünlü daralması gerçekleşmiştir?", "answerOptions": [{"text": "Akşamüstü kütüphanede ders çalışıyordu.", "isCorrect": false, "rationale": "'çalış-' fiili dar ünlülü bittiği için araya bağlama ünlüsü girmiştir, kökte geniş ünlü daralması yoktur."}, {"text": "Yeni aldığı kitabı büyük bir keyifle okuyordu.", "isCorrect": false, "rationale": "'oku-' fiil kökü zaten dar ünlü ile bittiğinden bir daralma gerçekleşmemiştir."}, {"text": "Çocuk neden sürekli ağlıyorsun diye sordu.", "isCorrect": true, "rationale": "'ağla-' fiil kökündeki geniş /a/ ünlüsü, şimdiki zaman ekinin etkisiyle daralarak /ı/ sesine dönüşmüştür."}, {"text": "Olayın ardından polisler şüpheliyi götürüyordu.", "isCorrect": false, "rationale": "'götür-' fiili dar ünlü barındırdığı için geniş ünlünün daralması durumu söz konusu değildir."}], "hint": "Fiil kök veya gövdesindeki geniş ünlünün (a, e) /-yor/ ekinin etkisiyle daralıp daralmadığını kontrol edin.", "type": "multiple_choice"}, {"question": "Türkçede 'kardeş' sözcüğüne 'benim' iyelik eki getirildiğinde sözcüğün 'kardeşim' biçimini almasında araya giren '-i-' sesinin temel işlevi nedir?", "answerOptions": [{"text": "Ünlü birleşmesi", "isCorrect": false, "rationale": "Aşınma yoluyla iki ünlünün tek bir ünlüde toplanması olayıdır."}, {"text": "Bağlama ünsüzü", "isCorrect": false, "rationale": "İki ünlü yan yana geldiğinde ikiz ünlü oluşumunu önlemek için araya giren ünsüz yardımcı sestir."}, {"text": "Bağlama ünlüsü", "isCorrect": true, "rationale": "Ünsüzle biten bir sözcüğe ünsüzle başlayan ek getirildiğinde hece yapısını korumak üzere araya giren yardımcı ses bağlama ünlüsüdür."}, {"text": "Ünlü türemesi", "isCorrect": false, "rationale": "Kök veya gövdede pekiştirme veya küçültme gibi süreçlerde ortaya çıkan yapım işlevli ünlü belirmesidir."}], "hint": "Ünsüzle biten kelime ile ünsüzle başlayan ek arasında heceleme olanağı sağlayan yardımcı sesi düşünün.", "type": "multiple_choice"}, {"question": "Konuşma sırasında cümlenin veya sözcüklerin anlamını değiştiren; vurgu, tonlama ve durak gibi doğrudan harflerle gösterilmeyen unsurlara ne ad verilir?", "answerOptions": [{"text": "Parçalar üstü ses birimleri", "isCorrect": true, "rationale": "Vurgu, tonlama ve durak gibi söyleyişin ezgisini ve anlamını belirleyen nitelikler parçalar üstü ses birimleridir."}, {"text": "İkincil ünsüzler", "isCorrect": false, "rationale": "Tarihsel süreçte sonradan ortaya çıkmış olan ünsüz seslerdir."}, {"text": "Bağlama sesleri", "isCorrect": false, "rationale": "Ek birleşmelerinde hece uyumu sağlayan yardımcı ünlü ve ünsüzlerdir."}, {"text": "Parçasal ses birimleri", "isCorrect": false, "rationale": "Doğrudan harflerle temsil edilen ünlü ve ünsüz seslerin kendisidir."}], "hint": "Ses birimlerinin ötesinde söyleyiş ezgisi ve duraklamalarla sağlanan anlam katmanını arayın.", "type": "multiple_choice"}, {"question": "Eski Türkçe döneminden beri var olan 'penbe > pembe' sözcüğünde görülen ses olayı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ünsüz benzeşmesi", "isCorrect": true, "rationale": "Dudak ünsüzü olan /b/, kendinden önceki diş-damak ünsüzü /n/ sesini etkileyerek dudak ünsüzü /m/ hâline getirmiştir (dudak benzeşmesi)."}, {"text": "Ünsüz tekleşmesi", "isCorrect": false, "rationale": "Çift ünsüzün teke düşmesidir."}, {"text": "Ötümlüleşme", "isCorrect": false, "rationale": "Ötümsüz bir sesin ötümlü hâle dönüşmesidir."}, {"text": "Süreklileşme", "isCorrect": false, "rationale": "Patlamalı bir ünsüzün sızıcı ünsüze dönüşmesidir."}], "hint": "Bir ünsüzün diğer ünsüzü kendisine benzeterek boğumlanma noktasını değiştirmesini göz önüne alın.", "type": "multiple_choice"}, {"question": "'kavuşak > kavşak' veya 'devirim > devrim' örneklerinde görülen ses olayı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ünlü düşmesi", "isCorrect": true, "rationale": "Sözcük türetilirken veya ek alırken vurgusuz orta hecedeki dar ünlünün kaybolması olayıdır."}, {"text": "Ünlü türemesi", "isCorrect": false, "rationale": "Sözcükte daha önce bulunmayan bir ünlünün ortaya çıkmasıdır."}, {"text": "Hece düşmesi", "isCorrect": false, "rationale": "Ünlü ve ünsüzden oluşan bütün bir hecenin kaybolmasıdır (ilerilemek > ilerlemek)."}, {"text": "Ünlü daralması", "isCorrect": false, "rationale": "Geniş ünlünün dar ünlüye dönüşmesidir."}], "hint": "İki ünsüz arasında yer alan vurgusuz dar ünlünün kaybolması durumunu düşünün.", "type": "multiple_choice"}, {"question": "Eski Türkçe 'ana' ve 'elig' sözcüklerinin Türkiye Türkçesinde 'anne' ve 'elli' biçimlerini alması hangi ses olayının sonucudur?", "answerOptions": [{"text": "Ünsüz ikizleşmesi", "isCorrect": true, "rationale": "Kök veya gövde içindeki tek bir ünsüzün vurgu ve seslik nedenlerle çiftleşerek söylenmesidir."}, {"text": "Ünsüz benzeşmesi", "isCorrect": false, "rationale": "Farklı ünsüzlerin birbirini etkileyerek benzer hâle gelmesidir."}, {"text": "Ünsüz tekleşmesi", "isCorrect": false, "rationale": "Çift ünsüzlü yabancı kelimelerin Türkçede tek ünsüzle söylenmesidir."}, {"text": "Ünsüz türemesi", "isCorrect": false, "rationale": "Sözcük başında veya içinde önceden var olmayan yeni bir ünsüz belirmesidir."}], "hint": "Sözcük kökündeki tek ünsüzün iki kez telaffuz edilmeye başlanmasını değerlendirin.", "type": "multiple_choice"}, {"question": "Türkçenin düzlük-yuvarlaklık (dudak) uyumu kuralına göre, ilk hecesinde yuvarlak ünlü (o, ö, u, ü) bulunan bir sözcüğün sonraki hecelerinde hangi ünlüler yer alabilir?", "answerOptions": [{"text": "Yalnızca yuvarlak-geniş (o, ö) ünlüler", "isCorrect": false, "rationale": "Türkçe kökenli sözcüklerde ikinci ve sonraki hecelerde yuvarlak-geniş (o, ö) ünlüler bulunmaz."}, {"text": "Dar-yuvarlak (u, ü) veya düz-geniş (a, e)", "isCorrect": true, "rationale": "Dudak uyumu kuralına göre yuvarlak ünlüleri ancak dar-yuvarlak (u, ü) veya düz-geniş (a, e) ünlüler takip edebilir (ör. bora, kuru, bölüm)."}, {"text": "Yalnızca düz-dar (ı, i) ünlüler", "isCorrect": false, "rationale": "Düz ünlülerden sonra düz ünlüler gelebilir kuralı ile karıştırılmamalıdır."}, {"text": "Yalnızca art-düz (a, ı) ünlüler", "isCorrect": false, "rationale": "Bu durum kalınlık-incelik (önlük-artlık) uyumu kuralıyla ilgilidir."}], "hint": "Dudak uyumunda yuvarlak ünlüden sonra gelebilecek iki ünlü grubunu hatırlayın.", "type": "multiple_choice"}, {"question": "Türkçe kökenli sözcüklerde asli olarak bulunmayıp zamanla ses değişimleri ve sızıcılaşma ile ortaya çıkan 'c, f, ğ, h, v' ünsüzlerine ne ad verilir?", "answerOptions": [{"text": "İkincil ünsüzler", "isCorrect": true, "rationale": "Eski Türkçedeki ana seslerin (yupka > yufka, eb > ev) değişimiyle sonradan oluşan bu sesler ikincil ünsüzler olarak adlandırılır."}, {"text": "Asli ünsüzler", "isCorrect": false, "rationale": "Dilin en eski dönemlerinden beri köklerde yer alan temel ünsüzlerdir."}, {"text": "Titreşimsiz ünsüzler", "isCorrect": false, "rationale": "Ses tellerinin titreşmemesiyle oluşan ötümsüz/tonsuz ünsüzlerdir."}, {"text": "Süreksiz ünsüzler", "isCorrect": false, "rationale": "Hava akımının çıkakta engellenip patlamayla çıktığı ünsüzlerdir."}], "hint": "Tarihsel süreçte sonradan türeyen veya dönüşen ünsüz türünü düşünün.", "type": "multiple_choice"}]}, "4": {"unit": 4, "unitTitle": "Biçim Bilgisi", "title": "Biçim Bilgisi Testi", "questions": [{"question": "Biri bağımsız biçim birim olmak üzere, en az iki biçim birimden oluşan ve bir veya daha fazla ek alan kök biçim birimlere 'gövde' adı verilir. Buna göre aşağıdaki sözcüklerden hangisi gövde durumundadır?", "answerOptions": [{"text": "Dinozor", "isCorrect": false, "rationale": "Daha küçük anlamlı birimlere bölünemeyen tek başına bir kök biçim birimdir."}, {"text": "Bahçe", "isCorrect": false, "rationale": "Herhangi bir ek almamış, daha küçük anlamlı parçalara ayrılamayan yalın bir köktür."}, {"text": "Gelişmişlik", "isCorrect": true, "rationale": "Kök üzerine eklenen türetme ekleriyle birden fazla biçim birimden oluşan türemiş bir yapıdır."}, {"text": "Kelebek", "isCorrect": false, "rationale": "Sözlüksel anlam taşıyan ve ek almamış kök durumunda tek bir biçim birimdir."}], "hint": "Sözcüğün kök durumundan çıkıp en az bir türetme eki alarak genişleyip genişlemediğine dikkat ediniz.", "type": "multiple_choice"}, {"question": "Yabancı dildeki bir sözcüğün yapısına veya ses yapısına benzetilerek Türkçe kök ve eklerle yeni sözcük türetilmesi yoluna 'örnekseme' denir. Aşağıdaki sözcüklerden hangisi örnekseme yoluyla üretilmiş bir sözcük değildir?", "answerOptions": [{"text": "Okul", "isCorrect": false, "rationale": "Fransızcadaki 'école' sözcüğünün ses ve yapı özellikleri örnek alınarak üretilmiştir."}, {"text": "Genel", "isCorrect": false, "rationale": "Fransızcadaki 'général' kelimesinin yapısına benzetilerek türetilmiş bir sözcüktür."}, {"text": "Arge", "isCorrect": true, "rationale": "İki ayrı sözcüğün hece veya parçalarının bir araya getirilmesiyle oluşturulmuş karma bir yapı örneğidir."}, {"text": "İmge", "isCorrect": false, "rationale": "Fransızca 'image' sözcüğünün biçimsel yapısı esas alınarak Türkçeye kazandırılmıştır."}], "hint": "Sözcüklerden hangisinin iki farklı ifadenin kısaltılarak birleştirilmesiyle oluştuğuna odaklanınız.", "type": "multiple_choice"}, {"question": "'Bayılmak' eyleminden 'bay-', 'ayılmak' eyleminden 'ay-' eylemlerinin türetilmesinde olduğu gibi, var olan bir eylemden ek yapısının eksiltilmesiyle yeni bir eylem oluşturulması yöntemi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Derleme", "isCorrect": false, "rationale": "Halk ağızlarında yaşayan sözlerin taranıp yazı diline aktarılması sürecidir."}, {"text": "Kırpma", "isCorrect": false, "rationale": "Uzun kelimelerin hecelerinin günlük dilde kısaltılarak kullanılması esasına dayanır."}, {"text": "Kasıtlı yaratma", "isCorrect": false, "rationale": "Herhangi bir var olan kök veya ek bulunmaksızın dilcilerce sıfırdan sözcük oluşturulmasıdır."}, {"text": "Ters türetme", "isCorrect": true, "rationale": "Var olan ekli bir biçim birimden ek yapısı eksiltilerek geriye doğru yeni bir kök/eylem elde edilmesidir."}], "hint": "Var olan türemiş bir eylemin ek kısmının mantıksal olarak eksiltilip geriye dönük türetilmesini düşününüz.", "type": "multiple_choice"}, {"question": "Çekim eklerinin ya da sözcük öbeklerinin kendi gramatikal işlevlerinin dışında yeni bir kavramı karşılayacak biçimde adlaşması durumuna 'kalıplaşma' adı verilir. Aşağıdaki sözcüklerden hangisi kalıplaşma yoluyla türetilmiştir?", "answerOptions": [{"text": "İmambayıldı", "isCorrect": true, "rationale": "Cümle yapısındaki bir öbeğin zamanla bir yemek adı olarak sabitlenip kalıcı ad durumuna gelmesidir."}, {"text": "Kilo", "isCorrect": false, "rationale": "'Kilogram' sözcüğünün hece atımıyla elde edilen kırpma yöntemine örnektir."}, {"text": "Selpak", "isCorrect": false, "rationale": "Özel bir marka adının ürünün tümü yerine geçmesiyle oluşan genelleşme örneğidir."}, {"text": "Uygar", "isCorrect": false, "rationale": "Belirli bir kavramı karşılamak üzere dil uzmanlarınca üretilmiş kasıtlı yaratma örneğidir."}], "hint": "Bir eylem cümlesinin zamanla bir yemek adı olarak sabitleşip kalıcı ad haline gelmesini göz önüne getiriniz.", "type": "multiple_choice"}, {"question": "Aşağıdaki seçeneklerin hangisinde yer alan sözcüklerin tamamı 'eylemden ad yapma eki' almıştır?", "answerOptions": [{"text": "İlçe, odun, yüzey", "isCorrect": false, "rationale": "Kökü ad olan veya farklı türde ek birleşimleri içeren yapılardan oluşmaktadır."}, {"text": "Yolsuz, cızırtı, toptan", "isCorrect": false, "rationale": "İçlerinde addan ad yapma eki barındıran veya yansıma ad köklü sözcükler yer almaktadır."}, {"text": "Azımsa, yüksün, kısal", "isCorrect": false, "rationale": "Seçenekteki ekler ad soyundan köklere gelerek eylem türeten ek işlevindedir."}, {"text": "Çekingen, akın, saplantı", "isCorrect": true, "rationale": "Sözcüklerin tamamı eylem köklerine gelen yapım ekleriyle ad soyundan sözcüklere dönüştürülmüştür."}], "hint": "Sözcüklerin türetildiği ilk durumlarının eylem (fiil) olup olmadığına dikkat ediniz.", "type": "multiple_choice"}, {"question": "Uzun bir sözcüğün bazı hece veya seslerinin düşürülerek günlük dilde daha kısa bir biçimde kullanılması işlemine 'kırpma' denir. Aşağıdakilerden hangisi kırpma yoluyla oluşturulmuş bir sözcüktür?", "answerOptions": [{"text": "Tümce", "isCorrect": false, "rationale": "Örnekseme veya türetme yollarıyla Türkçe eklerle oluşturulmuş bir sözcüktür."}, {"text": "Okul", "isCorrect": false, "rationale": "Yabancı bir sözcüğün yapısının Türkçeye örneksenmesiyle türetilmiştir."}, {"text": "İmge", "isCorrect": false, "rationale": "Başka bir dildeki kelimenin ses yapısına benzetilerek türetilmiştir."}, {"text": "Kilo", "isCorrect": true, "rationale": "'Kilogram' sözcüğünün hecelerinin kısaltılarak günlük dile aktarılmış biçimidir."}], "hint": "'Kilogram' veya 'santimetre' gibi uzun ölçü birimlerinin günlük konuşmada kısaltılarak kullanılmasını hatırlayınız.", "type": "multiple_choice"}, {"question": "Biçim bilgisinde, eklerin (bağımlı biçim birimlerin) üzerine eklendiği yalın veya türemiş biçim birim yapısına ne ad verilir?", "answerOptions": [{"text": "Gövde", "isCorrect": false, "rationale": "Kökün en az bir yapım eki almış durumunu ifade eden türemiş yapıdır."}, {"text": "Karma", "isCorrect": false, "rationale": "Farklı sözcük parçalarının birleştirilmesiyle yapılan sözcük oluşturma yöntemidir."}, {"text": "Kök", "isCorrect": false, "rationale": "Sözcüğün parçalanamayan en küçük anlamlı yapı birimidir."}, {"text": "Taban", "isCorrect": true, "rationale": "Ekin doğrudan eklendiği temel birimi veya gövdeleşmiş aşamayı ifade eden kavramdır."}], "hint": "Örneğin 'gözlük' türemiş sözcüğünün üzerine getirilen yeni bir ek için 'gözlük' kelimesinin üstlendiği birimi düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdaki sözcüklerin hangisinde hem birden çok yapım eki hem de birden çok çekim eki yer almaktadır?", "answerOptions": [{"text": "Yaşanmışlıklarımız", "isCorrect": true, "rationale": "Sözcük yapısında birden fazla yapım eki ile çoğul ve iyelik ekleri gibi birden fazla çekim eki bir arada kullanılmıştır."}, {"text": "Beklemek", "isCorrect": false, "rationale": "Yalnızca bir yapım eki ile isim-fiil eki içeren sınırlı bir ek dizilimine sahiptir."}, {"text": "Eleştirmenin", "isCorrect": false, "rationale": "İçeriğinde birden fazla çekim eki çeşidi barındırmayan daha dar bir ek dizilimidir."}, {"text": "Gitmişlerse", "isCorrect": false, "rationale": "Yapım eki içermeyip yalnızca birleşik zaman ve çoğul gibi çekim ekleri almıştır."}], "hint": "Sözcükteki türetme ekleri ile çekim eklerinin (çoğul, iyelik vb.) sayısını ayrı ayrı analiz ediniz.", "type": "multiple_choice"}, {"question": "Dil uzmanları veya yetkili kurumlarca belirli bir kavramı karşılamak üzere doğrudan doğruya oluşturulan sözcük yapım yoluna 'kasıtlı yaratma' denir. Aşağıdakilerden hangisi bu yolla üretilmiş sözcüklerden biridir?", "answerOptions": [{"text": "Uygar", "isCorrect": true, "rationale": "Yeni bir kavramı karşılamak amacıyla dil planlamacıları tarafından doğrudan oluşturulmuş bir sözcüktür."}, {"text": "Jilet", "isCorrect": false, "rationale": "Bir marka adının ürün türünün genel adı haline dönüşmesiyle oluşan genelleşmedir."}, {"text": "Deprenmek", "isCorrect": false, "rationale": "Halk ağızlarından taranıp yazı diline aktarılan derleme kökenli bir sözcüktür."}, {"text": "Futbol", "isCorrect": false, "rationale": "Başka bir dilden doğrudan alınan kopyalama bir sözcüktür."}], "hint": "'Bayan', 'koşul' veya 'uygar' gibi kavramların dil kurulları tarafından türetilme amacını düşününüz.", "type": "multiple_choice"}, {"question": "'Araştırmacılık' sözcüğü biçim birimlerine ayrıldığında, anlam ilişkisi kopmaksızın ulaşılabilen en küçük anlamlı kök aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Araştırma", "isCorrect": false, "rationale": "Eylemden ad türetilmiş bir alt gövde veya taban durumudur."}, {"text": "Ar", "isCorrect": false, "rationale": "Kelimenin genel anlam bağlamıyla ilişkisi bulunmayan bağımsız bir köktür."}, {"text": "Araştır", "isCorrect": false, "rationale": "Kök üzerine gelen ekle oluşmuş eylem gövdesi aşamasıdır."}, {"text": "Ara", "isCorrect": true, "rationale": "Sözcüğün türetilme sürecindeki ilk ve anlamca ilişkili en temel bağımsız biçim birimidir."}], "hint": "'Aramak' eylemi ile 'araştırmak' arasındaki ilk anlam bağına odaklanınız.", "type": "multiple_choice"}, {"question": "Ticari bir marka adının zaman içerisinde o türdeki ürünlerin tümünü karşılar hale gelmesine 'genelleşme' denir. Aşağıdaki sözcüklerden hangisi bu yolla dili zenginleştiren sözcüklerden biridir?", "answerOptions": [{"text": "Başkan", "isCorrect": false, "rationale": "Tarihsel metinlerden taranarak yazı diline kazandırılmış bir sözcüktür."}, {"text": "Selpak", "isCorrect": true, "rationale": "Marka adının zamanla kağıt mendil ürünlerinin tümünü ifade edecek şekilde genelleşmesidir."}, {"text": "Yozlaşmak", "isCorrect": false, "rationale": "Halk dili kaynaklı derleme sürecine ait bir sözcüktür."}, {"text": "Aşçı", "isCorrect": false, "rationale": "Standart addan ad yapma ekiyle türetilmiş bir sözcüktür."}], "hint": "Bir marka adının mendil türündeki tüm ürünler için genel isim olarak kullanılması örneğini hatırlayınız.", "type": "multiple_choice"}, {"question": "İki ayrı sözcüğün hecelerinin veya parçalarının bir araya getirilerek yeni ve tek bir kavramı karşılayacak biçimde birleştirilmesiyle yapılan sözcük oluşturma yöntemine 'karma' adı verilir. Aşağıdakilerden hangisi bu yöntemle oluşturulmuştur?", "answerOptions": [{"text": "Açık öğretim", "isCorrect": false, "rationale": "Sözcüklerin eksiltilmeden yan yana gelmesiyle kurulan birleşik ad yapısıdır."}, {"text": "Şükretmek", "isCorrect": false, "rationale": "Bir ad ile yardımcı eylemin birleşmesinden oluşan birleşik eylemdir."}, {"text": "Ordonat", "isCorrect": true, "rationale": "'Ordu' ve 'donatım' sözcüklerinin hece parçalarının birleştirilmesiyle türetilmiş karma bir sözcüktür."}, {"text": "Karatavuk", "isCorrect": false, "rationale": "İki ayrı sözcüğün eksiltilmeden bir araya getirildiği geleneksel birleştirme örneğidir."}], "hint": "'Ordu donatım' veya 'araştırma geliştirme' gibi tamlamaların hece birleştirilmesiyle tek kelime haline getirilmesini düşününüz.", "type": "multiple_choice"}]}, "5": {"unit": 5, "unitTitle": "Cümle Bilgisi", "title": "Türkçe Testi", "questions": [{"question": "Cümle türleri yapısına göre incelendiğinde aşağıdakilerden hangisi 'Basit Cümle' türüne örnektir?", "answerOptions": [{"text": "Benim gecem yeni bir umutla başladı.", "isCorrect": true, "rationale": "Tek bir eylem ve tek bir yargı bildiren, içinde fiilimsi veya başka tümce barındırmayan yapılar basit cümle oluşturur."}, {"text": "Onu seviyorsan bunu ona açıkça söylemelisin.", "isCorrect": false, "rationale": "İçinde şart ekiyle kurulmuş yan yargı barındıran cümleler birleşik cümle yapısındadır."}, {"text": "Belki onlar seviyorlar da ben farkına varmıyorum.", "isCorrect": false, "rationale": "Ayrı yargıların bağlaçla birbirine bağlandığı yapılar bağlı cümle sınıfına girer."}, {"text": "Bir öğrenci geldi sınıfa, etrafa bakıp arka sıraya geçti.", "isCorrect": false, "rationale": "Virgülle birbirinden ayrılmış birden fazla bağımsız yüklem barındıran yapılar sıralı cümle örneğidir."}], "hint": "İçinde yan yargı, fiilimsi veya ek bir bağlaç bulunmayan tek yargılı yapıyı arayın.", "type": "multiple_choice"}, {"question": "Cümlenin ögeleri değerlendirildiğinde, öznenin yaptığı işten doğrudan etkilenen ve geçişli eylemleri tamlayan öge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Nesne", "isCorrect": true, "rationale": "Geçişli fiillerin doğrudan etkilediği ve yükleme sorulan 'ne, neyi, kimi' sorularına yanıt veren öge nesnedir."}, {"text": "Zarf tümleci", "isCorrect": false, "rationale": "Eylemin zaman, tarz, miktar veya sebep yönünden sınırlarını belirleyen tümleç türüdür."}, {"text": "Dolaylı tümleç", "isCorrect": false, "rationale": "Yüklemin bildirdiği hareketin gerçekleştiği yeri veya yönü yaklaşma, bulunma ve uzaklaşma ekleriyle bildiren ögedir."}, {"text": "Yüklem", "isCorrect": false, "rationale": "Cümledeki işi, hareketi, yargıyı veya durumu üstlenen temel ögedir."}], "hint": "Geçişli fiillere sorulan 'neyi' veya 'kimi' sorularının yanıtı olan ögeyi düşünün.", "type": "multiple_choice"}, {"question": "'Sıcak güneş' ve 'mavi deniz' kelime öbekleri tamlama ilişkisi bakımından aşağıdakilerden hangisine örnektir?", "answerOptions": [{"text": "Takısız ad tamlaması", "isCorrect": false, "rationale": "Bir şeyin neyden yapıldığını veya neye benzediğini ek almadan belirten ad tamlaması türüdür."}, {"text": "Sıfat tamlaması", "isCorrect": true, "rationale": "Bir ismin rengini, durumunu veya niteliğini gösteren niteleme sözcükleriyle oluşturulan öbeklerdir."}, {"text": "Belirtili ad tamlaması", "isCorrect": false, "rationale": "Hem tamlayanın ilgi eki hem de tamlananın iyelik eki aldığı tamlama yapısıdır."}, {"text": "Edat öbeği", "isCorrect": false, "rationale": "İsim ya da isim soylu sözcüklerin edatlar aracılığıyla oluşturduğu öbek yapısıdır."}], "hint": "İsme sorulan 'Nasıl?' sorusuna yanıt veren nitelik belirten yapıyı göz önüne getirin.", "type": "multiple_choice"}, {"question": "Cümlede yüklemin bildirdiği hareket, iş veya oluşun yerini ve yönünü belirten; yaklaşma, bulunma ya da uzaklaşma durumu eklerini alan öge hangisidir?", "answerOptions": [{"text": "Zarf Tümleci", "isCorrect": false, "rationale": "Durum, zaman, tarz ve miktar bildirerek yüklemi tamamlayan ögedir."}, {"text": "Özne", "isCorrect": false, "rationale": "Yüklemin bildirdiği işi yapan veya durumu üstlenen temel unsur olup hâl ekleri ile yer bildirmez."}, {"text": "Nesne", "isCorrect": false, "rationale": "Eylemden etkilenen öge olup yaklaşma veya uzaklaşma durumu ekleriyle yer göstermez."}, {"text": "Dolaylı Tümleç (Yer Tamlayıcısı)", "isCorrect": true, "rationale": "İsmin -e, -de ve -den hâl eklerini alarak yüklemin yöneldiği, bulunduğu veya ayrıldığı yeri belirten ögedir."}], "hint": "İsmin durum eklerinden (-e, -de, -den) yararlanarak mekan belirten ögeyi arayın.", "type": "multiple_choice"}, {"question": "'On yedi' ve 'beş bin iki yüz otuz' ifadeleri tamlama ilişkisi bulunmayan sözcük öbeklerinden hangisine örnektir?", "answerOptions": [{"text": "Kısaltma öbeği", "isCorrect": false, "rationale": "Eklerin düşmesi veya kalıplaşmasıyla oluşan basitleşmiş söz öbekleridir."}, {"text": "Tekrar öbeği", "isCorrect": false, "rationale": "Aynı veya yakın anlamlı sözcüklerin yinelenmesiyle oluşan ikileme yapılarıdır."}, {"text": "Sayı öbeği", "isCorrect": true, "rationale": "Basamak isimlerinin ve sayıların yan yana gelmesiyle oluşan karmaşık sayı ifadeleridir."}, {"text": "Unvan öbeği", "isCorrect": false, "rationale": "Kişi adlarına getirilen makam, meslek veya saygı sözcüklerinin oluşturduğu öbeklerdir."}], "hint": "Birden fazla sözcükten oluşan matematiksel nicelik bildiren öbek türünü düşünün.", "type": "multiple_choice"}, {"question": "'Onun gibi benimsenmiş bir lider yoktur bu coğrafyada.' cümlesi yüklemin türüne göre hangi cümle grubunda yer alır?", "answerOptions": [{"text": "Bağlı cümle", "isCorrect": false, "rationale": "Cümlenin yüklem türünü değil, yapısını belirten bir tanımdır."}, {"text": "Ad cümlesi", "isCorrect": true, "rationale": "Yüklemi isim köklü bir sözcük ('yok') olan ve ek eylem alarak yüklemleşen cümleler ad cümlesidir."}, {"text": "Devrik cümle", "isCorrect": false, "rationale": "Yüklemin türünü değil, yüklemin cümle içerisindeki yerini ifade eden bir sınıflandırmadır."}, {"text": "Eylem cümlesi", "isCorrect": false, "rationale": "Yüklemi çekimlenmiş bir fiilden oluşan cümle türüdür."}], "hint": "Cümlenin yükleminin fiil kökenli mi yoksa isim kökenli mi olduğuna dikkat edin.", "type": "multiple_choice"}, {"question": "Yüklemin anlamını zaman, sebep, tarz, yön, ölçü veya şart gibi yönlerden tamamlayan ve sınırlayan cümlenin ögesi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Zarf tümleci (Belirteç tümleci)", "isCorrect": true, "rationale": "Eylemin nasıl, ne zaman, ne kadar ve ne sebeple yapıldığını belirten ögedir."}, {"text": "Nesne", "isCorrect": false, "rationale": "Eylemden etkilenen ögedir ve eylemin tarzını veya zamanını bildirmez."}, {"text": "Dolaylı tümleç", "isCorrect": false, "rationale": "Yüklemi yer ve mekân ilişkisi yönünden tamamlayan ögedir."}, {"text": "Özne", "isCorrect": false, "rationale": "Eylemi gerçekleştiren veya durumu taşıyan ana ögedir."}], "hint": "Yükleme sorulan 'Nasıl?', 'Ne zaman?' ve 'Ne kadar?' sorularına yanıt veren ögeyi hatırlayın.", "type": "multiple_choice"}, {"question": "'Ertuğrul Gazi' ve 'Selin Hanım' ifadeleri sözcük öbekleri bakımından aşağıdakilerden hangisine örnektir?", "answerOptions": [{"text": "Aitlik öbeği", "isCorrect": false, "rationale": "Aitlik eki (-ki) kullanılarak kurulan söz öbeğidir."}, {"text": "Ünlem öbeği", "isCorrect": false, "rationale": "Seslenme ve duygu belirten ünlemlerin isimlerle oluşturduğu yapıdır."}, {"text": "Bağlama öbeği", "isCorrect": false, "rationale": "Bağlaçlar aracılığıyla birbirine tutturulmuş kelime grubudur."}, {"text": "Unvan öbeği", "isCorrect": true, "rationale": "Özel adlara eklenen saygı, derece, san veya meslek adlarının oluşturduğu öbektir."}], "hint": "Kişi isimlerine eşlik eden saygı ve makam sözcüklerinin oluşturduğu grubu değerlendirin.", "type": "multiple_choice"}, {"question": "Yüklemi sonda bulunan cümleler, ögelerin dizilişine (yüklemin yerine) göre nasıl adlandırılır?", "answerOptions": [{"text": "Kurallı (Düz) Cümle", "isCorrect": true, "rationale": "Türkçenin standart söz dizimine uygun olarak yüklemi sonda yer alan yapılar kurallı cümledir."}, {"text": "Devrik Cümle", "isCorrect": false, "rationale": "Yüklemi sonda olmayan, başında veya ortasında yer alan cümle türüdür."}, {"text": "Sıralı Cümle", "isCorrect": false, "rationale": "Birden çok yüklemin noktalama işaretleriyle dizilmesini ifade eder."}, {"text": "Basit Cümle", "isCorrect": false, "rationale": "Yüklemin konumunu değil, cümlenin yargı sayısını ve yapısını belirten kavramdır."}], "hint": "Türkçe dil bilgisinde yüklemin standart ve doğal yerinde olduğu cümle türünü düşünün.", "type": "multiple_choice"}, {"question": "'Hazırlanan öğrenci', 'yaşanacak günler' ve 'gördüğü güzellik' örnekleri tamlama ilişkisi bulunmayan öbeklerden hangisidir?", "answerOptions": [{"text": "Zarf-fiil öbeği", "isCorrect": false, "rationale": "Fiillere eklenen -erek, -ip, -meden gibi eklerle yapılan zarf yapısındaki öbektir."}, {"text": "İsim-fiil öbeği", "isCorrect": false, "rationale": "Fiillere getirilen -me, -mak, -ış gibi eklerle oluşturulan eylemsi öbeğidir."}, {"text": "Birleşik eylem öbeği", "isCorrect": false, "rationale": "Yardımcı eylem veya deyimleşme yoluyla oluşan eylem gruplarıdır."}, {"text": "Sıfat-fiil öbeği", "isCorrect": true, "rationale": "Fiil tabanlarına getirilen -an, -acak, -dık gibi sıfat-fiil ekleriyle kurulan söz öbekleridir."}], "hint": "Fiillere getirilen eklerle isimleri niteleme görevi üstlenen eylemsi grubunu arayın.", "type": "multiple_choice"}, {"question": "Birden fazla yüklemi bulunan ve bu yüklemleri 've, fakat, ama, de' gibi ögelerle bağlanan cümle türü aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sıralı Cümle", "isCorrect": false, "rationale": "Yargıların bağlaç yerine virgül veya noktalı virgülle sıralandığı yapıdır."}, {"text": "Birleşik Cümle", "isCorrect": false, "rationale": "Tek bir temel yüklem ve ona bağlı yan cümleciklerden oluşan yapıdır."}, {"text": "Basit Cümle", "isCorrect": false, "rationale": "İçinde yalnızca tek bir yargı ve yüklem barındıran yapıdır."}, {"text": "Bağlı Cümle", "isCorrect": true, "rationale": "Ayrı cümlelerin veya yargıların bağlaçlar vasıtasıyla bir araya getirildiği yapıdır."}], "hint": "Yargıları birbirine kavuşturan dil bilgisi bağlama ögelerine odaklanın.", "type": "multiple_choice"}, {"question": "'Vişne reçeli' ve 'gül kokusu' örnekleri tamlama ilişkisi bulunan öbeklerden hangisine girmektedir?", "answerOptions": [{"text": "Belirtili ad tamlaması", "isCorrect": false, "rationale": "Tamlayanın da ilgi eki (-ın/-in) aldığı tamlama türüdür."}, {"text": "Takısız ad tamlaması", "isCorrect": false, "rationale": "Hem tamlayanın hem tamlananın ek almadığı ad tamlaması yapısıdır."}, {"text": "Belirtisiz ad tamlaması", "isCorrect": true, "rationale": "Tamlayanın ilgi eki almadığı, yalnızca tamlananın iyelik eki aldığı ad tamlaması türüdür."}, {"text": "Sıfat tamlaması", "isCorrect": false, "rationale": "Bir ismin sıfat tarafından nitelendiği ve iyelik eki içermeyen yapıdır."}], "hint": "Tamlayan ögenin yalın kaldığı, tamlanan ögenin ise iyelik eki aldığı tamlama yapısını düşünün.", "type": "multiple_choice"}]}, "6": {"unit": 6, "unitTitle": "Türkçenin Söz Varlığı", "title": "Söz Varlığı Testi", "questions": [{"question": "Türk dilinin söz varlığı içinde yer alan; toplumsal yaşamda dilek, temenni, dua veya beddua bildirmek amacıyla kullanılan kalıplaşmış söz öbekleri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ağız ögeleri", "isCorrect": false, "rationale": "Bölgesel veya yöresel konuşma farklılıklarından doğan sözcükleri ifade eder."}, {"text": "Alkış ve kargış", "isCorrect": true, "rationale": "Alkış dua ve iyi dilekleri, kargış ise beddua ve kötü dilekleri ifade eden geleneksel söz varlığı ögesidir."}, {"text": "İlişki sözleri", "isCorrect": false, "rationale": "Selamlaşma ve hatır sorma gibi gündelik toplumsal iletişim kalıplarını kapsar."}, {"text": "Argo", "isCorrect": false, "rationale": "Belirli grup veya toplumsal katmanların kullandığı özel söz dağarcığına dayanır."}], "hint": "Halk kültüründe iyilik dileme veya kınama amacıyla kullanılan ikili kavram çiftini düşünün.", "type": "multiple_choice"}, {"question": "Özel bir nesne veya marka adının zamanla o türdeki tüm ürünleri kapsayacak şekilde kullanılmasına 'genelleşme' denir. Aşağıdakilerden hangisi bu yolla söz varlığına katılmış bir kelimedir?", "answerOptions": [{"text": "Başkan", "isCorrect": false, "rationale": "Tarihî metinlerden veya ağızlardan taranarak yazı diline kazandırılmış bir sözcüktür."}, {"text": "Jilet", "isCorrect": true, "rationale": "Marka adının zamanla tıraş bıçağının genel adı haline gelmesi genelleşme örneğidir."}, {"text": "Uydu", "isCorrect": false, "rationale": "Yabancı sözcük yapısına uygun şekilde türetilmiş bir örnekseme örneğidir."}, {"text": "Arge", "isCorrect": false, "rationale": "İki farklı sözcüğün hece birleşimiyle oluşturulmuş karma bir sözcüktür."}], "hint": "Belli bir markanın bütün tıraş bıçakları için ortak ad haline gelmesini hatırlayın.", "type": "multiple_choice"}, {"question": "Yabancı bir dildeki sözcüğün biçimsel yapısı örnek alınarak Türkçe kök ve eklerle yeni bir kelime oluşturulması işlemine 'örnekseme' denir. Aşağıdakilerden hangisi bu yönteme örnektir?", "answerOptions": [{"text": "Santim", "isCorrect": false, "rationale": "Sözcüğün hece eksiltilmesiyle kısaltılması sonucunda ortaya çıkan kırpma örneğidir."}, {"text": "Patates", "isCorrect": false, "rationale": "Başka bir dilden Türkçeye doğrudan geçmiş bir kopyalama (alıntı) örneğidir."}, {"text": "Yozlaşmak", "isCorrect": false, "rationale": "Halk ağızlarından derlenerek yazı diline aktarılmış bir derleme örneğidir."}, {"text": "Okul", "isCorrect": true, "rationale": "Fransızca 'école' sözcüğünün ses ve yapı bakımından Türkçeye uyarlanıp türetilmesiyle oluşturulmuştur."}], "hint": "Fransızca 'école' kelimesinin sesletim ve yapısına benzetilerek türetilen sözcüğü arayın.", "type": "multiple_choice"}, {"question": "Tarihî Türk dili metinlerinde geçen ancak unutulmuş olan sözcüklerin taranarak günümüz yazı diline yeniden kazandırılmasına 'tarama' denir. Aşağıdakilerden hangisi tarama yoluyla söz varlığına katılmıştır?", "answerOptions": [{"text": "Futbol", "isCorrect": false, "rationale": "Yabancı dilden doğrudan alınan bir kopyalama örneğidir."}, {"text": "Selpak", "isCorrect": false, "rationale": "Bir markanın nesne adının yerine geçmesiyle oluşan genelleşme örneğidir."}, {"text": "Kilo", "isCorrect": false, "rationale": "Kilogram sözcüğünün sonundaki hecelerin atılmasıyla oluşmuş bir kırpma örneğidir."}, {"text": "Başkan", "isCorrect": true, "rationale": "Eski metinlerin taranması sonucu ortaya çıkarılıp modern Türkçe söz varlığına kazandırılmıştır."}], "hint": "Eski yazılı metinlerin incelenmesi sonucu günümüz diline kazandırılan yönetsel unvanı düşünün.", "type": "multiple_choice"}, {"question": "Ölçünlü dilde bulunmayan ancak yörelere ait halk ağızlarında yaşayan sözcüklerin toplanıp yazı diline kazandırılmasına 'derleme' adı verilir. Aşağıdakilerden hangisi bu yolla dilimize kazandırılmıştır?", "answerOptions": [{"text": "Bayan", "isCorrect": false, "rationale": "Dil devrimi döneminde bilinçli ve amaçlı bir şekilde türetilen kasıtlı yaratma örneğidir."}, {"text": "Ordonat", "isCorrect": false, "rationale": "Ordu ve donatım kelimelerinin birleştirilmesiyle yapılan karma sözcük örneğidir."}, {"text": "ASELSAN", "isCorrect": false, "rationale": "Kurum adının baş harflerinden veya ilk hecelerinden oluşan bir kısaltma örneğidir."}, {"text": "Alan", "isCorrect": true, "rationale": "Ağız araştırmaları ve halk dilinden toplanıp ölçünlü Türkçeye kazandırılmış bir derleme sözcüğüdür."}], "hint": "Ağızlardan toplanarak 'saha/meydan' anlamında kullanılan Türkçe sözcüğü hatırlayın.", "type": "multiple_choice"}, {"question": "İki farklı sözcüğün ilk veya son hecelerinin bir araya getirilmesiyle yeni bir kavramın türetilmesi işlemine 'karma' adı verilir. Aşağıdakilerden hangisi karma yöntemiyle oluşturulmuştur?", "answerOptions": [{"text": "Ordonat", "isCorrect": true, "rationale": "'Ordu' ve 'donatım' sözcüklerinin hece birleşimiyle oluşan karma bir sözcüktür."}, {"text": "Yöre", "isCorrect": false, "rationale": "Tarihî kaynaklardan taranarak dile kazandırılan tarama örneğidir."}, {"text": "Köken", "isCorrect": false, "rationale": "Eski metin araştırmalarıyla günümüz diline aktarılan tarama sözcüğüdür."}, {"text": "Deprenmek", "isCorrect": false, "rationale": "Halk ağızlarından toplanarak dilde kullanılan derleme örneğidir."}], "hint": "'Ordu' ve 'donatım' sözcüklerinin bir araya getirilerek kısaltılmış yeni bir yapı kazanmasını düşünün.", "type": "multiple_choice"}, {"question": "Başka dillerden biçim veya anlam olarak Türkçeye geçen ve söz varlığında yer alan alıntı kelimelere 'kopyalama' denir. Aşağıdakilerden hangisi kopyalama yoluyla Türkçeye girmiştir?", "answerOptions": [{"text": "Geliştir", "isCorrect": false, "rationale": "Türkçe kök üzerine türetme eki getirilmesiyle yapılan türetme örneğidir."}, {"text": "Çıktı", "isCorrect": false, "rationale": "Eylem türevinin kalıcı isim haline gelmesiyle oluşan kalıplaşma örneğidir."}, {"text": "Patates", "isCorrect": true, "rationale": "Yabancı bir dilden Türkçeye doğrudan geçen bir kopyalama örneğidir."}, {"text": "Yüzde", "isCorrect": false, "rationale": "Sözcük çekim kalıplarının zamanla sabitleşmesiyle oluşan kalıplaşma örneğidir."}], "hint": "Sebze adı olan ve yabancı dilden dilimize kopyalanarak geçen sözcüğü dikkate alın.", "type": "multiple_choice"}, {"question": "Sözcüğün sonundaki veya içindeki ses ve hecelerin atılarak daha kısa bir biçimde kullanılmasına 'kırpma' denir. Aşağıdakilerden hangisi kırpma örneğidir?", "answerOptions": [{"text": "Uygar", "isCorrect": false, "rationale": "Kavram ihtiyacını karşılamak üzere bilinçli üretilen kasıtlı yaratma örneğidir."}, {"text": "Pop", "isCorrect": true, "rationale": "'Popüler' sözcüğünün hece eksiltilmesi sonucu oluşan kırpılmış biçimidir."}, {"text": "Yazar", "isCorrect": false, "rationale": "Geniş zaman ekinin kalıcı ad yapmasıyla oluşan kalıplaşma örneğidir."}, {"text": "Genel", "isCorrect": false, "rationale": "Fransızca 'général' sözcüğünden hareketle türetilen örnekseme örneğidir."}], "hint": "'Popüler' müzik türünün dil içinde kısalmış biçimini hatırlayın.", "type": "multiple_choice"}, {"question": "Toplumda belirli kavramları karşılamak amacıyla doğrudan dil bilinciyle ve bilinçli bir planlamayla yeni sözcükler üretilmesine 'kasıtlı yaratma' denir. Aşağıdakilerden hangisi bu yolla türetilmiştir?", "answerOptions": [{"text": "Sanayağı", "isCorrect": false, "rationale": "Belirli bir margarin markasının nesneye ad olmasıyla gelişen genelleşme örneğidir."}, {"text": "Koşul", "isCorrect": true, "rationale": "Şart kavramını karşılamak üzere bilinçli ve kasıtlı biçimde yaratılmış bir sözcüktür."}, {"text": "Toptan", "isCorrect": false, "rationale": "Ek ve kök birleşimiyle kalıplaşmış bir sözcük örneğidir."}, {"text": "Belleten", "isCorrect": false, "rationale": "Yabancı sözcük yapısına benzetilerek türetilen örnekseme örneğidir."}], "hint": "Arapça 'şart' kelimesine karşılık olarak dil devrimi sürecinde bilinçli oluşturulan kelimeyi düşünün.", "type": "multiple_choice"}, {"question": "Yabancı veya kökeni bilinmeyen kelimelerin halk tarafından bilinen Türkçe ögelere benzetilerek yeniden anlamlandırılmasına 'yerlileştirme' (halk etimolojisi) denir. Kaynakta verilen bilgilere göre aşağıdakilerden hangisi yerlileştirme örneğidir?", "answerOptions": [{"text": "Kremlin", "isCorrect": false, "rationale": "Başka bir kurumun yerine kullanılan bir aktarma örneğidir."}, {"text": "İstanbul", "isCorrect": true, "rationale": "Halk tarafından 'İslam+bol' biçiminde anlamlandırılarak yerlileştirilmiş bir şehir adıdır."}, {"text": "Kol saati", "isCorrect": false, "rationale": "Somut bir varlığı doğrudan adlandıran somut anlam örneğidir."}, {"text": "Führer", "isCorrect": false, "rationale": "Hitler'i zihinde canlandıran bir çağrıştırma anlamı örneğidir."}], "hint": "Halk arasında 'İslam+bol' yakıştırmasıyla açıklanan şehir adını hatırlayın.", "type": "multiple_choice"}, {"question": "Çekimli eylemlerin veya ek almış biçimlerin zamanla ek fonksiyonunu yitirip kalıcı isim haline gelmesine 'kalıplaşma' adı verilir. Aşağıdakilerden hangisi kalıplaşma yoluyla türetilmiştir?", "answerOptions": [{"text": "Derya", "isCorrect": false, "rationale": "Farsçadan Türkçeye geçmiş bir kopyalama örneğidir."}, {"text": "Sanayağı", "isCorrect": false, "rationale": "Ticari bir markanın ürüne ad olmasıyla oluşan genelleşme örneğidir."}, {"text": "İmge", "isCorrect": false, "rationale": "Fransızca 'image' sözcüğünden örneksenerek oluşturulmuştur."}, {"text": "Yazar", "isCorrect": true, "rationale": "-ar geniş zaman ekinin zamanla kalıcı ad yapmasıyla oluşan kalıplaşma örneğidir."}], "hint": "Fiil geniş zaman eki alarak zamanla kalıcı meslek/faaliyet adı haline gelmiş sözcüğü düşünün.", "type": "multiple_choice"}, {"question": "Çeşitli bilim, sanat, spor veya meslek alanlarında özel anlamlarıyla kullanılan sözcüklere ne ad verilir?", "answerOptions": [{"text": "Ağız", "isCorrect": false, "rationale": "Bir dilin aynı ülke sınırları içindeki bölgesel söyleyiş farklarıdır."}, {"text": "İkileme", "isCorrect": false, "rationale": "Anlamı güçlendirmek için sözcüklerin yinelemesiyle kurulan öbektir."}, {"text": "Argo", "isCorrect": false, "rationale": "Belirli sosyal grupların ortak dilden ayrı kullandığı özel söz varlığıdır."}, {"text": "Terim", "isCorrect": true, "rationale": "Belirli bir meslek veya bilim dalına özgü kavramları karşılayan özel anlamlı sözcüklerdir."}], "hint": "Matematik, tıp veya dil bilgisi gibi uzmanlık alanlarına özgü kavram adlarını hatırlayın.", "type": "multiple_choice"}]}, "7": {"unit": 7, "unitTitle": "Diller Arası Etkileşim ve Türkçe", "title": "Türk Dili Quiz", "questions": [{"question": "Aşağıdakilerden hangisi 'Türkçenin Gücü ve İç Zenginliği' başlığı altında incelenen konulardan biri değildir?", "answerOptions": [{"text": "Atasözleri ve Anlatım Gücü", "isCorrect": false, "rationale": "Türk dilinin tarihsel süreçte biriktirdiği derin mecaz ve anlatım gücünü temsil eder."}, {"text": "Akrabalık Adlarında Çeşitlilik", "isCorrect": false, "rationale": "Türkçenin aile ve akrabalık bağlarını ifade eden zengin kavram dünyasını gösteren ana başlıklardan biridir."}, {"text": "İlişki ve Nezaket Sözleri", "isCorrect": false, "rationale": "Toplumsal yaşamda kullanılan zengin nezaket ve selamlaşma kaliplarını kapsar."}, {"text": "Eğitim ve Öğretim Dilinin Yabancılaştırılması", "isCorrect": true, "rationale": "Bu konu Türkçenin gücü ve iç zenginliği başlığında değil, dilin karşı karşıya olduğu güncel sorunlar arasında değerlendirilir."}], "hint": "Dilin olumlu nitelikleri ve derinlikleri yerine dilde yaşanan olumsuz bir gelişmeye odaklanan seçeneği arayın.", "type": "multiple_choice"}, {"question": "Türk dilinin yayılma alanları dikkate alındığında, hem Halaçça hem de Horasan Türkçesinin konuşulduğu ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İran", "isCorrect": true, "rationale": "Her iki Türk yazı dili ve değişkesi de İran sınırları içerisinde varlığını sürdürmektedir."}, {"text": "Rusya Federasyonu", "isCorrect": false, "rationale": "Tatar, Başkurt ve Hakas gibi pek çok grubun yaşadığı ülke olmasına rağmen Halaçça burada yer almaz."}, {"text": "Afganistan", "isCorrect": false, "rationale": "Afganistan'da Özbekçe ve Türkmence gibi diller konuşulsa da Halaçça ve Horasan Türkçesinin ana coğrafyası değildir."}, {"text": "Özbekistan", "isCorrect": false, "rationale": "Özbek ve Karakalpak Türklerinin yoğun yaşadığı temel ülkedir."}], "hint": "Orta Doğu'da Afşar ve Kaşgay Türkçelerinin de yoğun olarak görüldüğü ülkeyi düşünün.", "type": "multiple_choice"}, {"question": "Türk dilinin coğrafi yayılma alanları incelendiğinde, Salar Türkçesi ve Sarı Uygur Türkçesinin ortak yayılma alanı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Rusya Federasyonu", "isCorrect": false, "rationale": "Sibirya ve Volga bölgesindeki birçok Türk boyunun yaşadığı ancak Salar ve Sarı Uygurların bulunmadığı ülkedir."}, {"text": "Moğolistan", "isCorrect": false, "rationale": "Tuva ve Kazak Türkçesi konuşurlarına ev sahipliği yapsa da bu iki dilin ana vatanı değildir."}, {"text": "Kazakistan", "isCorrect": false, "rationale": "Kazak, Ahıska, Uygur ve Karakalpak topluluklarının bulunduğu Orta Asya ülkesidir."}, {"text": "Çin", "isCorrect": true, "rationale": "Hem Salar hem de Sarı Uygur Türkçesi Çin sınırları içerisinde varlığını sürdüren Türk yazı dillerindendir."}], "hint": "Doğu Asya'da Uygur Türkçesinin de konuşulduğu geniş coğrafyayı anımsayın.", "type": "multiple_choice"}, {"question": "Gagavuz Türkçesinin özerk bir bölge olarak resmîleştiği ve yoğun biçimde konuşulduğu ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Romanya", "isCorrect": false, "rationale": "Balkanlar'da Gagavuz Türklerinin yerleştiği ancak özerk idarenin kurulmadığı bir ülkedir."}, {"text": "Bulgaristan", "isCorrect": false, "rationale": "Gagavuz konuşurlarının bulunduğu bir diğer Balkan ülkesidir."}, {"text": "Moldova", "isCorrect": true, "rationale": "Gagavuz Yeri Özerk Bölgesi Moldova sınırları içerisinde hukuki statüye sahiptir."}, {"text": "Ukrayna", "isCorrect": false, "rationale": "Gagavuz nüfusun yaşadığı ülkelerden biri olmakla birlikte özerk bölgenin bulunduğu yer değildir."}], "hint": "Gagavuz Yeri Özerk Bölgesi'ne ev sahipliği yapan Doğu Avrupa ülkesini hatırlayın.", "type": "multiple_choice"}, {"question": "Yakutça (Saha Türkçesi) Türk dilinin yayılma alanları içinde temelde hangi özerk cumhuriyet ve ülke sınırlarında konuşulmaktadır?", "answerOptions": [{"text": "Rusya Federasyonu (Yakutistan Cumhuriyeti)", "isCorrect": true, "rationale": "Yakutça, Rusya Federasyonu'na bağlı Yakutistan Özerk Cumhuriyeti'nde konuşulmaktadır."}, {"text": "Çin Halk Cumhuriyeti", "isCorrect": false, "rationale": "Uygur, Salar ve Kazakh topluluklarının yaşadığı Doğu Asya coğrafyasıdır."}, {"text": "Kırgızistan", "isCorrect": false, "rationale": "Kırgız Türkçesinin ana yayılma merkezidir."}, {"text": "Özbekistan", "isCorrect": false, "rationale": "Özbekçe ve Karakalpakçanın yaygın olduğu bağımsız Orta Asya devletidir."}], "hint": "Sibirya'nın kuzeydoğusunda yer alan ve Rusya'ya bağlı olan özerk bölgeyi göz önüne getirin.", "type": "multiple_choice"}, {"question": "Karayim Türkçesinin konuşulduğu Doğu Avrupa ülkeleri arasında aşağıdakilerden hangisi yer alır?", "answerOptions": [{"text": "Gürcistan", "isCorrect": false, "rationale": "Ahıska ve Azerbaycan Türkçesinin görüldüğü Kafkasya ülkesidir."}, {"text": "Litvanya", "isCorrect": true, "rationale": "Karayim Türkçesi Litvanya, Polonya ve Rusya Federasyonu'nda konuşulan Türk dillerindendir."}, {"text": "Çin", "isCorrect": false, "rationale": "Salar ve Sarı Uygur gibi Türk topluluklarının yer aldığı Asya ülkesidir."}, {"text": "İran", "isCorrect": false, "rationale": "Afşar, Halaç, Kaşgay ve Horasan Türkçesinin konuşulduğu coğrafyadır."}], "hint": "Baltık bölgesinde yer alan ve Polonya ile komşu olan ülkeyi düşünün.", "type": "multiple_choice"}, {"question": "İlgili ders materyalindeki 'Türkçedeki Alıntı Sözcüklerin Kaynağı Diller' listesinde yer alan Doğu Asya dili aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İsveççe", "isCorrect": false, "rationale": "Ders dokümanındaki alıntı diller şemasında yer almayan bir İskandinav dilidir."}, {"text": "Portekizce", "isCorrect": false, "rationale": "Listelenen alıntı sözcük kaynakları arasında bu dil bulunmamaktadır."}, {"text": "Norveççe", "isCorrect": false, "rationale": "Alıntı sözcük kaynakları tablosuna dahil edilmemiştir."}, {"text": "Japonca", "isCorrect": true, "rationale": "Türkçe söz varlığına etki eden diller şemasında Japonca açıkça belirtilmiştir."}], "hint": "Uzak Doğu kültüründen Türkçeye giren sözcüklerin kaynağı olan ada ülkesi dilini anımsayın.", "type": "multiple_choice"}, {"question": "Ders materyalinde yer alan 'Türkçedeki Alıntı Sözcüklerin Kaynağı Diller' listesine göre aşağıdaki dillerden hangisi Türkçeye sözcük veren Slav dillerindendir?", "answerOptions": [{"text": "Makedonca", "isCorrect": false, "rationale": "İlgili ünitedeki alıntı diller tablosunda yer almaz."}, {"text": "Çekçe", "isCorrect": false, "rationale": "Kaynak diller tablosuna girmeyen bir Batı Slav dilidir."}, {"text": "Sırpça", "isCorrect": false, "rationale": "Listede Türkçeye sözcük aktaran diller arasında sayılmamıştır."}, {"text": "Bulgarca", "isCorrect": true, "rationale": "Türkçenin alıntı sözcük aldığı kaynak diller şemasında Bulgarca yer almaktadır."}], "hint": "Türkiye'nin batı komşularından biri olan ve Slav dil ailesine mensup dili düşünün.", "type": "multiple_choice"}, {"question": "Karakalpak Türkçesinin özerk cumhuriyet olarak bünyesinde bulunduğu ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tacikistan", "isCorrect": false, "rationale": "Orta Asya'da Karakalpak azınlığın yer aldığı fakat özerk yapının bulunmadığı devlettir."}, {"text": "Türkmenistan", "isCorrect": false, "rationale": "Karakalpakların yaşadığı ancak özerk bölge statüsünün bulunmadığı komşu ülkedir."}, {"text": "Özbekistan", "isCorrect": true, "rationale": "Karakalpakistan Özerk Cumhuriyeti Özbekistan sınırları içinde idari yapıya sahiptir."}, {"text": "Kazakistan", "isCorrect": false, "rationale": "Karakalpak nüfusu barındırmakla birlikte özerk cumhuriyet idaresini içermez."}], "hint": "Aril Gölü yakınlarında kurulan Karakalpakistan Özerk Cumhuriyeti'ni barındıran Orta Asya ülkesini anımsayın.", "type": "multiple_choice"}, {"question": "Türk dillerinin yayılma alanları dikkate alındığında hem Afşar hem de Kaşgay Türkçesinin konuşulduğu ortak ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Çin", "isCorrect": false, "rationale": "Salar, Uygur ve Sarı Uygur Türkçesinin konuşulduğu bölgedir."}, {"text": "Ukrayna", "isCorrect": false, "rationale": "Gagavuz, Kırım Tatarı ve Karaçay gruplarının yaşadığı Doğu Avrupa ülkesidir."}, {"text": "İran", "isCorrect": true, "rationale": "Afşar, Kaşgay, Halaç ve Horasan Türkçeleri İran coğrafyasında konuşulmaktadır."}, {"text": "Rusya Federasyonu", "isCorrect": false, "rationale": "Altay, Hakas, Başkurt ve Tuva gibi dillerin yaygın olduğu coğrafyadır."}], "hint": "Güneybatı Oğuz grubuna ait birçok topluluğun yaşadığı komşu Orta Doğu ülkesini düşünün.", "type": "multiple_choice"}, {"question": "Türkçenin iç zenginliği açıklanırken akrabalık adlarındaki çeşitlilik önemli bir örnek olarak gösterilir. Aşağıdakilerden hangisi bu zenginliği doğrudan kanıtlar?", "answerOptions": [{"text": "Anne ve baba tarafındaki akrabalar için ayrı kavramların bulunması", "isCorrect": true, "rationale": "Amca, dayı, hala, teyze gibi kavramların her biri için ayrı sözcüklerin kullanılması akrabalık adlarındaki anlam derinliğini ve çeşitliliği gösterir."}, {"text": "Akrabalık isimlerinin yabancı dillerden kopyalanması", "isCorrect": false, "rationale": "Dış etkileşimi gösterir, dilin kendi iç zenginliğini temsil etmez."}, {"text": "Sadece çekirdek aile üyelerine isim verilmiş olması", "isCorrect": false, "rationale": "Sınırlı bir söz varlığına işaret eder."}, {"text": "Tüm akrabalar için tek bir genel sözcüğün tercih edilmesi", "isCorrect": false, "rationale": "Genel sözcük kullanımı dildeki kavramsal çeşitliliği değil, genellemeyi ifade eder."}], "hint": "Ebeveynlerin kardeşlerini tanımlarken kullanılan farklı kelimeleri göz önüne getirin.", "type": "multiple_choice"}, {"question": "'Türkçedeki Alıntı Sözcüklerin Kaynağı Diller' şemasında yer alan ve Ural dil ailesine mensup olan Avrupa dili aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Fransızca", "isCorrect": false, "rationale": "Hint-Avrupa dil ailesine bağlı bir Roman dilidir."}, {"text": "Fince", "isCorrect": true, "rationale": "Fince, Türkçe söz varlığını besleyen Ural dil ailesine ait dillerden biri olarak şemada gösterilmiştir."}, {"text": "Almanca", "isCorrect": false, "rationale": "Hint-Avrupa dil ailesinin Cermen koluna aittir."}, {"text": "İspanyolca", "isCorrect": false, "rationale": "Hint-Avrupa dil ailesinin Roman koluna mensuptur."}], "hint": "Kuzey Avrupa'da (İskandinavya bölgesinde) konuşulan Ural kökenli dili anımsayın.", "type": "multiple_choice"}, {"question": "Şor Türkçesi, Türk dilinin coğrafi yayılma alanları çerçevesinde Rusya Federasyonu'nun hangi idari bölgesinde konuşulmaktadır?", "answerOptions": [{"text": "Dağıstan Cumhuriyeti", "isCorrect": false, "rationale": "Kumuk ve Nogay Türkçesinin yaygın olduğu özerk cumhuriyettir."}, {"text": "Kabartay-Balkar Cumhuriyeti", "isCorrect": false, "rationale": "Balkar Türkçesinin ana merkezidir."}, {"text": "Gagavuz Yeri", "isCorrect": false, "rationale": "Moldova sınırlarında yer alan Gagavuz bölgesidir."}, {"text": "Kemerovo bölgesi", "isCorrect": true, "rationale": "Şor ve Teleüt Türkçesi Rusya Federasyonu'nun Kemerovo bölgesinde konuşulmaktadır."}], "hint": "Sibirya bölgesinde Teleüt Türkçesiyle aynı coğrafi alanda yer alan bölgeyi düşünün.", "type": "multiple_choice"}]}, "8": {"unit": 8, "unitTitle": "Türkçenin Güncel Sorunları", "title": "Türkçe Bilgi Sınavı", "questions": [{"question": "Türkçenin 'yazıldığı gibi okunan ve okunduğu gibi yazılan bir dil' olduğu yönündeki yaygın inanışın doğru olmadığını gösteren durum aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Yabancı kökenli terimlerin dilimize ses uyumlarına aykırı biçimde girmesi.", "isCorrect": false, "rationale": "Kelime kökenindeki farklılıklar ve ses uyumu aykırılıkları söyleyiş-yazım arasındaki doğrudan sesletim ilkesinden ziyade söz varlığıyla ilgilidir."}, {"text": "Günlük hayatta kullanılan kelime sayısının sözlükteki toplam söz varlığından az olması.", "isCorrect": false, "rationale": "Bu durum konuşma ve yazıda kelime hazinesinin kısıtlılığına işaret eder, ses ile harf arasındaki karşılığa ilişkin bir kanıt sunmaz."}, {"text": "Sosyal medyada sesli harflerin kullanılmadan yazışılması.", "isCorrect": false, "rationale": "Bu durum yazımdaki bir özensizlik veya iletişim alışkanlığı olup kelimenin doğal ve ölçünlü sesletim kurallarıyla doğrudan ilgili değildir."}, {"text": "'Söyleyeyim' sözcüğünün ölçünlü konuşma dilinde 'söyliyim' biçiminde telaffuz edilmesi.", "isCorrect": true, "rationale": "Ölçünlü Türkçe söyleyişinde yazım kuralları ile seslendirme arasında belirgin farklar bulunabilmekte, bazı sözcükler yazıldığından farklı telaffuz edilmektedir."}], "hint": "Yazı dili ile ölçünlü konuşma dili arasındaki telaffuz farklarını düşününüz.", "type": "multiple_choice"}, {"question": "Türkçenin öğretim ve bilim dili olarak gelişmesini olumsuz etkileyen durumlardan biri olan yabancı dil eğitimiyle ilgili temel yanlışlık aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Öğrencilerin sadece tek bir yabancı dili öğrenmeye yönlendirilip ikinci dili seçememesi.", "isCorrect": false, "rationale": "Birden fazla dil öğrenimi bireysel bir imkân olup Türkçenin eğitim dili olmaktan çıkarılması sorununu doğrudan temsil etmez."}, {"text": "Yabancı dildeki dil bilgisi kurallarının ezbere dayalı biçimde öğretilmesi.", "isCorrect": false, "rationale": "Metodolojik bir eksiklik olan bu yaklaşım, Türkçenin bilim ve öğretim dili olmaktan uzaklaştırılması sonucunu doğurmaz."}, {"text": "Yabancı dil eğitimine erken yaşlarda değil yalnızca yükseköğretim düzeyinde başlanması.", "isCorrect": false, "rationale": "Eğitim kademesiyle ilgili bu durum dilin öğretim dili haline getirilmesinin yarattığı yapısal engeli açıklamaz."}, {"text": "Yabancı dili bir ders olarak öğretmek yerine, derslerin yabancı bir dille (örneğin İngilizce) okutulması.", "isCorrect": true, "rationale": "Eğitim ve öğretim dilinin yabancılaştırılması, kavramların Türkçe ile işlenmesini önleyerek dilin bilim dili olarak gelişimine engel oluşturur."}], "hint": "Yabancı dilin bir öğretim konusu olması ile öğretim vasıtası yapılması arasındaki farkı dikkate alınız.", "type": "multiple_choice"}, {"question": "İş yerlerinde 'Rainbow Kasabı' veya 'Börek Center' gibi adların tercih edilmesi ve ürün kullanım kılavuzlarında Türkçeye yer verilmemesi hangi soruna işaret eder?", "answerOptions": [{"text": "İş yaşamında Türkçenin göz ardı edilmesi ve yabancılaşma eğiliminin artması.", "isCorrect": true, "rationale": "Ticari alandaki yabancı ad ve tabela kullanımı, dildeki yabancılaşmanın iş hayatına ve günlük kültüre yansımasını gösterir."}, {"text": "Konuşma ve yazı dilindeki söyleyiş farklılıklarının derinleşmesi.", "isCorrect": false, "rationale": "Bu durum kelimelerin telaffuz özellikleriyle değil, iş yeri ve ticari isimlerdeki dil tercihiyle ilgilidir."}, {"text": "Dilin köken bakımından farklı dil aileleriyle etkileşime girmesi.", "isCorrect": false, "rationale": "Tarihsel dil etkileşimleri doğal bir süreçken, ticari mekân adlarındaki bilinçli yabancılaşma güncel bir kullanım sorunudur."}, {"text": "Türkçedeki eklerin yeni kavramları karşılamada yetersiz kalması.", "isCorrect": false, "rationale": "Bu tutum Türkçe eklerin yetersizliğinden ziyade toplumsal prestij ve özentiden kaynaklanmaktadır."}], "hint": "Tabela ve ticari işletme isimlerindeki dille ilgili tercihler üzerine odaklanınız.", "type": "multiple_choice"}, {"question": "Büyük Türkçe Sözlük'te yüz binlerce söz varlığı bulunmasına karşın, gündelik hayatta kısıtlı sayıda sözcükle iletişim kurulmasının doğurduğu temel sonuç aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dildeki nedensizlik ilkesinin ve ses kurallarının geçersiz kılınması.", "isCorrect": false, "rationale": "Nedensizlik ilkesi dilin temel yapısal bir özelliği olup kullanılan kelime miktarının azlığıyla değişmez."}, {"text": "Standart (ölçünlü) dil ile bölgesel ağızlar arasındaki sınırların ortadan kalkması.", "isCorrect": false, "rationale": "Ağız çeşitliliği coğrafi ve toplumsal etkenlere bağlıdır; genel kelime kısırlığı ağızları ortadan kaldırmaz."}, {"text": "Duygu ve düşüncelerin tam aktarılamaması neticesinde yanlış anlamalar ve iletişimsizlik yaşanması.", "isCorrect": true, "rationale": "Kelime hazinesinin daralması, bireylerin karmaşık düşünce ve duyguları ifade etme yeteneğini sınırlandırarak iletişim kopukluklarına yol açar."}, {"text": "Dilin yapısal olarak bitişkenlik özelliğini kaybedip bükümlü hale gelmesi.", "isCorrect": false, "rationale": "Söz varlığının daralması dilin tipolojik ve gramer yapısında bir değişikliğe sebep olmaz."}], "hint": "Kelime hazinesinin yetersizliğinin bireyler arası duygu ve düşünce aktarımına etkisini değerlendiriniz.", "type": "multiple_choice"}, {"question": "İnsan dillerinin doğuşunu, insanların doğadaki sesleri taklit etmesi esasına dayandıran dil doğuş kuramı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Güneş dil kuramı", "isCorrect": false, "rationale": "Türkçenin dünya dillerinin kökeninde yer aldığını ileri sürer, genel bir doğa sesi taklidi tezi değildir."}, {"text": "Yansıma kuramı", "isCorrect": true, "rationale": "Bu kuram, ilk kelimelerin doğadaki nesne, hayvan ve doğa seslerinin benzetilmesi ve taklit edilmesiyle ortaya çıktığını savunur."}, {"text": "Ünlem kuramı", "isCorrect": false, "rationale": "Bu kuram dillerin kaynağını doğa seslerinin taklidine değil, insanların korku, sevinç gibi duygularla çıkardığı seslere bağlar."}, {"text": "Ding dong kuramı", "isCorrect": false, "rationale": "Bu yaklaşım nesnelerin insan zihninde uyandırdığı doğal titreşim ve izlenimlerden hareket eder."}], "hint": "Doğadaki seslerin taklit edilmesiyle türeyen sözcük gruplarını hatırlayınız.", "type": "multiple_choice"}, {"question": "VIII-XVII. yüzyıllar arasında Doğu Türkistan'dan İstanbul'a kadar geniş bir coğrafyada kullanılan ve Soğut alfabesinden geliştirilmiş olan alfabe aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Arap alfabesi", "isCorrect": false, "rationale": "Samî dil ailesine ait bir alfabe olup Türklerin İslamiyet'i kabulüyle yaygınlaşan bir sistemdir."}, {"text": "Uygur alfabesi", "isCorrect": true, "rationale": "Soğut alfabesinden türetilen ve 18 harften oluşan bu alfabe, uzun süre geniş bir kültür çevresinde kullanılmıştır."}, {"text": "Brahmi alfabesi", "isCorrect": false, "rationale": "Hint kökenli bir alfabe olup Türkler tarafından sınırlı alanlarda ve Budist metinlerde kullanılmıştır."}, {"text": "Köktürk alfabesi", "isCorrect": false, "rationale": "Türklerin bilinen ilk düzenli alfabesi olup Soğut kaynaklı değil, yerli ve orijinal işaret sistemine dayanır."}], "hint": "Soğut yazısından geliştirilen ve Göç Destanı gibi eserlerin aktarımında kullanılan alfabeyi düşününüz.", "type": "multiple_choice"}, {"question": "Genç Kalemler dergisinde başlatılan Yeni Lisan hareketinin dille ilgili benimsediği ilkeler göz önüne alındığında, aşağıdakilerden hangisi bu hareketin prensiplerinden biri değildir?", "answerOptions": [{"text": "Arapça ve Farsça dil bilgisi kurallarını ve tamlamaları terk etmek.", "isCorrect": false, "rationale": "Dildeki yabancı dil bilgisi kaidelerinin çıkarılması sadeleşme programının ana maddelerinden biridir."}, {"text": "Dildeki eksiklikleri kapatmak amacıyla diğer Türk lehçelerinden kelimeler aktarmak.", "isCorrect": true, "rationale": "Yeni Lisan hareketi, zorunlu olmadıkça diğer Türk lehçelerinden sözcük taşınmasını ilke olarak reddetmiştir."}, {"text": "Yazı dilini konuşma diline yaklaştırıp İstanbul halkının konuştuğu dili esas almak.", "isCorrect": false, "rationale": "Hareketin temel hedeflerinden biri konuşma dili ile yazı dili arasındaki uçurumu kapatarak İstanbul Türkçesini esas almaktır."}, {"text": "Dilimize yerleşmiş yabancı kelimeleri Türkçedeki söylenişlerine göre yazmak.", "isCorrect": false, "rationale": "Yaygınlaşmış ve Türkçeleşmiş yabancı sözcüklerin imlasında halkın telaffuzunun esas alınması ilkesi benimsenmiştir."}], "hint": "Ömer Seyfettin ve arkadaşlarının başka Türk lehçelerinden kelime alma konusundaki tutumunu anımsayınız.", "type": "multiple_choice"}, {"question": "Süreksiz bir ünsüzün sürekli bir ünsüze dönüşmesi olayına 'süreklileşme' denir. Buna göre 'öpke > öfke' sözcük değişiminde görülen ses olayı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ünsüz tekleşmesi", "isCorrect": false, "rationale": "Çift ünsüzlerin teke düşmesini ifade eden bu olay, /p/ sesinin /f/ sesine dönüşümüyle örtüşmez."}, {"text": "Ön damaksıllaşma", "isCorrect": false, "rationale": "Ön damaksıllaşma art damak seslerinin ön damak bölgesine kaymasıyla ilgilidir, ünsüzün sürekli hale gelmesiyle açıklanamaz."}, {"text": "Ötümlüleşme", "isCorrect": false, "rationale": "Ötümlüleşme, tonlu/ötümlü olmayan bir ünsüzün ötümlü hale gelmesidir; buradaki temel değişim sızıcılaşmadır."}, {"text": "Süreklileşme", "isCorrect": true, "rationale": "Patlamalı ve süreksiz bir ünsüz olan /p/ sesinin sızıcı ve sürekli bir ünsüz olan /f/ sesine dönüşmesi süreklileşme örneğidir."}], "hint": "Patlamalı (süreksiz) bir sesin sızıcı (sürekli) bir sese dönüşme durumunu dikkate alınız.", "type": "multiple_choice"}, {"question": "Osmanlı Dönemi'nin sonlarında Şemsettin Sami tarafından hazırlanan ve Türkçenin en yetkin sözlüklerinden biri kabul edilen eser aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Muhakemetü'l-Lügateyn", "isCorrect": false, "rationale": "Ali Şir Nevayi tarafından Türkçe ile Farsçayı karşılaştırmak amacıyla yazılmış bir eserdir."}, {"text": "Kamus-ı Türkî", "isCorrect": true, "rationale": "Şemsettin Sami'nin kaleme aldığı Kamus-ı Türkî, Türkçe sözlükçülük tarihinin en önemli köşe taşlarından biridir."}, {"text": "Divanu Lugati't-Türk", "isCorrect": false, "rationale": "Kaşgarlı Mahmut tarafından XI. yüzyılda Arapça olarak kaleme alınmış ilk Türkçe sözlüktür."}, {"text": "Kavaid-i Osmaniyye", "isCorrect": false, "rationale": "Ahmet Cevdet Paşa ve Fuat Paşa tarafından kaleme alınmış bir dil bilgisi (gramer) kitabıdır."}], "hint": "19. yüzyıl sonlarında Türkçe kelimelere geniş yer vererek hazırlanan başyapıtı düşününüz.", "type": "multiple_choice"}, {"question": "Dünya dilleri yapı bakımından incelendiğinde, kök değişmeden kelime türetme ve çekim eklerinin kökün sonuna eklenmesi esasına dayanan Türkçe hangi dil grubunda yer alır?", "answerOptions": [{"text": "Yalınlayan diller", "isCorrect": false, "rationale": "Çince gibi yalınlayan dillerde ek bulunmaz, kelimeler biçim değiştirmeden cümledeki sırasına göre anlam kazanır."}, {"text": "Çekimli (bükümlü) diller", "isCorrect": false, "rationale": "Arapça ve Hint-Avrupa dilleri gibi bükümlü dillerde türetme sırasında kök içi ses değişimleri yaşanır."}, {"text": "İzole diller", "isCorrect": false, "rationale": "İzole diller bilinen hiçbir dil ailesiyle akrabalığı kanıtlanamamış dillerdir, yapı sınıflandırması terimi değildir."}, {"text": "Bitişken (eklemeli) diller", "isCorrect": true, "rationale": "Bitişken dillerde kelime kökleri sabit kalır ve gramer işlevleri köke eklenen yapım ve çekim ekleriyle sağlanır."}], "hint": "Kökün değişmeyip eklerin sıralanması esasına dayalı tipolojik grubu hatırlayınız.", "type": "multiple_choice"}, {"question": "Cumhuriyet Dönemi'nde Türk dilinin özleştirilmesi ve bilimsel yöntemlerle incelenip geliştirilmesi amacıyla kurulan Türk Dil Kurumu hangi tarihte faaliyete geçmiştir?", "answerOptions": [{"text": "10 Mart 1933", "isCorrect": false, "rationale": "TDK'nin kuruluş tarihi olmayıp Cumhuriyet dönemi kültür çalışmalarının yürütüldüğü takvimdeki farklı bir tarihtir."}, {"text": "12 Temmuz 1932", "isCorrect": true, "rationale": "Türk Dil Kurumu, Atatürk'ün direktifleriyle 12 Temmuz 1932 tarihinde kurulmuştur."}, {"text": "1926 Bakü Türkoloji Kongresi", "isCorrect": false, "rationale": "Azerbaycan'da toplanan ve Türk halklarının ortak alfabe kullanımı kararlarının tartışıldığı kongredir."}, {"text": "1 Kasım 1928", "isCorrect": false, "rationale": "Bu tarih Harf Devrimi'nin gerçekleştiği ve Yeni Türk Harflerinin Kabulü Kanunu'nun çıkarıldığı tarihtir."}], "hint": "1932 yılında Atatürk öncülüğünde kurulan cemiyetin kuruluş gün ve ayını hatırlayınız.", "type": "multiple_choice"}, {"question": "Günümüz teknolojisinde 'bilgisayar' ve 'gerilim' gibi başarılı Türkçe terim türetmelerine karşın, bilimsel çalışmalarda yabancı terimlerin olduğu gibi kullanılması dil açısından hangi olumsuz sonucu doğurur?", "answerOptions": [{"text": "Türkçenin bilim dili olarak gelişmesini ve yetkinleşmesini engeller.", "isCorrect": true, "rationale": "Bilimsel kavramların Türkçe terimlerle karşılanmaması dilin işlenme kapasitesini sınırlar ve terim yabancılaşmasına yol açar."}, {"text": "Ağızlar ile ölçünlü dil arasındaki ses farklarının silinmesine yol açar.", "isCorrect": false, "rationale": "Terim düzeyindeki yabancılaşma coğrafi söyleyiş ve ağız farklarıyla doğrudan ilgili değildir."}, {"text": "Sözcüklerin köken yapısını tamamen değiştireceğinden dilin ailesini değiştirir.", "isCorrect": false, "rationale": "Terim alıntıları dilin ait olduğu dil ailesini veya genetik kökenini değiştiremez."}, {"text": "Dildeki eklerin türetme gücünün tamamen ortadan kalkmasına neden olur.", "isCorrect": false, "rationale": "Yabancı terim kullanımı dilin ek yapısını yok etmez, ancak Türkçe türetme potansiyelinin hayata geçirilmesini kısıtlar."}], "hint": "Yabancı terim egemenliğinin dilin yüksek öğretim ve araştırma alanlarındaki imkânlarına etkisini düşününüz.", "type": "multiple_choice"}]}}, "ataturk-ilkeleri-1": {"1": {"unit": 1, "unitTitle": "Türk İnkılabını Hazırlayan Sebepler", "title": "Osmanlı Tarihi Testi", "questions": [{"question": "XVII. yüzyıl Osmanlı ıslahatçı düşünürlerinden Kâtip Çelebi'nin, devlet mekanizmasındaki bozulmaları ve yönetimdeki aksaklıkları eleştirerek çözüm yolları sunduğu ünlü eseri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Keşfü'z-Zünûn", "isCorrect": false, "rationale": "Kâtip Çelebi'ye ait olmakla birlikte bu çalışma devlet ıslahatından ziyade geniş kapsamlı bir bibliyografya eseridir."}, {"text": "Cihannüma", "isCorrect": false, "rationale": "Bu çalışma coğrafya alanında hazırlanmış bir eser olup idari reform tavsiyeleri içermemektedir."}, {"text": "Asafnâme", "isCorrect": false, "rationale": "Bu eser XVI. yüzyılda Kanuni Sultan Süleyman'ın sadrazamı Lütfi Paşa tarafından devlet yönetimine dair kaleme alınmıştır."}, {"text": "Düstûrü'l-Amel li Islahı'l-Halel", "isCorrect": true, "rationale": "Kâtip Çelebi bu eserinde devlet organlarındaki bozulmaları cesurca teşhis etmiş ve ıslahe yönelik somut öneriler sunmuştur."}], "hint": "Yazarın devlet dairesindeki aksaklıkların giderilmesi ve bozulmaların düzeltilmesi için reçete sunduğu risalesini düşününüz.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti'nde III. Selim döneminde gerçekleştirilen Nizam-ı Cedit ıslahatları kapsamında yer almayan gelişme aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Humbaracı ve topçu ocaklarının ıslah edilmesi", "isCorrect": false, "rationale": "III. Selim dönemi askerî yenilikleri kapsamında teknik sınıflar ve topçu ocakları yeniden yapılandırılmıştır."}, {"text": "Evkaf Vekâletinin kurulması", "isCorrect": true, "rationale": "Vakıf idaresini tek bir çatı altında toplayan Evkaf Vekâleti III. Selim döneminde değil, II. Mahmud döneminde tesis edilmiştir."}, {"text": "Mühendishane-i Bahri-i Hümayunun yeniden düzenlenmesi", "isCorrect": false, "rationale": "Deniz mühendishanesi bu dönemde modernize edilerek ıslah edilen kurumlar arasındadır."}, {"text": "Mühendishane-i Berr-i Hümayun matbaasının açılması", "isCorrect": false, "rationale": "III. Selim döneminde askerî okul bünyesinde telif ve tercüme eserleri basmak amacıyla bu matbaa kurulmuştur."}], "hint": "Cevap seçeneği, vakıf mallarının idaresini merkezîleştirmek amacıyla II. Mahmud döneminde oluşturulan bakanlıktır.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti'nde idari ve hukuki yapıyı yeniden şekillendiren, 23 Aralık 1876 tarihinde ilan edilerek Türk tarihinin ilk anayasası olma özelliğini taşıyan belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Islahat Fermanı", "isCorrect": false, "rationale": "1856 yılında gayrimüslimlere verilen hakları genişleten mülki ıslahat fermanıdır."}, {"text": "Kanun-i Esasi", "isCorrect": true, "rationale": "Tersane Konferansı sırasında ilan edilen Kanun-i Esasi, Osmanlı Devleti'nin ilk yazılı anayasasıdır."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında Padişah ile âyânlar arasında imzalanan ve padişah yetkilerini kısıtlayan bir sözleşmedir."}, {"text": "Tanzimat Fermanı", "isCorrect": false, "rationale": "1839 yılında ilan edilen bu ferman anayasal düzene geçişin ilk adımı olmakla birlikte bir anayasa metni değildir."}], "hint": "I. Meşrutiyet'in ilanı ile yürürlüğe giren ve meclisli yönetimin temelini oluşturan metni hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı modernleşme sürecinde dış dünyaya merak duyan, 'kadim' anlayış yerine 'yeni' yaklaşımları öne çıkaran kâtip sınıfı kuşağını tanımlamak için kullanılan kavram aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Münevverler Çağı", "isCorrect": false, "rationale": "Bu terim daha çok XIX. yüzyıl sonu ve XX. yüzyıl başındaki Jön Türk ve aydın grubunu ifade etmek için kullanılır."}, {"text": "Kahramanlar Çağı", "isCorrect": false, "rationale": "Bu kavram erken dönem Osmanlı kuruluş veya askerî fetih dönemlerini tanımlamakta kullanılır."}, {"text": "Çelebiler Çağı", "isCorrect": true, "rationale": "Bu kavram, Batı'daki ve Osmanlı dışındaki gelişmeleri kavramaya çalışan bürokrat ve kâtip kuşağını ifade eder."}, {"text": "Sefirler Çağı", "isCorrect": false, "rationale": "Bu niteleme diplomasi ve elçilik faaliyetlerinin yoğunlaştığı Lale Devri ve sonrasını tanımlamada kullanılır ancak bürokratik kuşak adı değildir."}], "hint": "Osmanlı eğitimli bürokrat sınıfının 'çelebi' unvanıyla anıldığı tarihsel dönemi düşününüz.", "type": "multiple_choice"}, {"question": "Kanuni Sultan Süleyman'ın sadrazamlarından Lütfi Paşa tarafından kaleme alınan ve Osmanlı devlet teşkilatındaki aksaklıkları inceleyen siyasetname türündeki eser aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Künhü'l-Ahbar", "isCorrect": false, "rationale": "Gelibolulu Mustafa Âlî tarafından yazılmış genel bir tarih eseridir."}, {"text": "Usulü'l-Hikem", "isCorrect": false, "rationale": "Bu eser XVIII. yüzyıl düşünürlerinden İbrahim Müteferrika tarafından kaleme alınmıştır."}, {"text": "Asafnâme", "isCorrect": true, "rationale": "Lütfi Paşa'nın devlet yönetimi, hazine idaresi ve askerî düzen konularında tavsiyelerde bulunduğu eseridir."}, {"text": "Vakayi'u'l-Fuzala", "isCorrect": false, "rationale": "Şeyhi Mehmed Efendi tarafından yazılan ilmiye biyografisi eseridir."}], "hint": "Hz. Süleyman'ın veziri Asaf'a atıfla adlandırılan yönetim risalesini hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti'nde milliyetçilik akımlarının ve dağılma tehlikesinin önüne geçmek amacıyla ortaya atılan ilk siyasi ideoloji aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Adem-i Merkeziyetçilik", "isCorrect": false, "rationale": "Prens Sabahaddin tarafından savunulan yerel yönetim ağırlıklı bir idari model önerisidir."}, {"text": "İslamcılık", "isCorrect": false, "rationale": "II. Abdülhamid döneminde öne çıkan ve Müslüman unsurların birliğini savunan daha sonraki ideolojik yaklaşımdır."}, {"text": "Osmanlıcılık", "isCorrect": true, "rationale": "Din ve ırk farkı gözetmeksizin tüm tebaayı eşit yurttaşlar olarak bir arada tutmayı hedefleyen ilk kapsayıcı ideolojidir."}, {"text": "Türkçülük", "isCorrect": false, "rationale": "Balkan Savaşları sonrasında ve İttihat ve Terakki döneminde etkisini artıran akımdır."}], "hint": "Tanzimat dönemiyle birlikte tüm Osmanlı tebaasını tek bir kimlik altında birleştirmeyi amaçlayan akımı düşününüz.", "type": "multiple_choice"}, {"question": "1 Kasım 1831 tarihinde yayın hayatına başlayan ve Osmanlı Devleti'nin Türkçe olarak yayımlanan ilk resmî gazetesi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Takvim-i Vekayi", "isCorrect": true, "rationale": "II. Mahmud döneminde devlet icraatlarını ve mevzuatı duyurmak amacıyla çıkarılan ilk resmî gazetedir."}, {"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Şinasi tarafından çıkarılan fikrî ve siyasi içerikli özel gazetedir."}, {"text": "Tercüman-ı Ahvâl", "isCorrect": false, "rationale": "1860 yılında Şinasi ve Agâh Efendi tarafından çıkarılan ilk özel Türkçe gazetedir."}, {"text": "Ceride-i Havadis", "isCorrect": false, "rationale": "1840 yılında bir İngiliz girişimci tarafından çıkarılan ilk yarı resmî gazetedir."}], "hint": "Devlet olaylarının ve resmî duyuruların takvim sırasına göre aktarıldığı yayını hatırlayınız.", "type": "multiple_choice"}, {"question": "13 Nisan 1909 (31 Mart 1325) tarihinde gerçekleşen 31 Mart Vakası ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "answerOptions": [{"text": "Aşırı dinî söylemler ve şeriat talepleri isyanın propaganda unsurları arasında yer almıştır.", "isCorrect": false, "rationale": "İsyancılar şeriat hükümlerinin tam uygulanması talebini öne sürmüşlerdir."}, {"text": "II. Meşrutiyet yönetimine ve İttihat ve Terakki Cemiyetine karşı bir tepki niteliğindedir.", "isCorrect": false, "rationale": "31 Mart Ayaklanması meşrutiyet rejimine ve İttihatçıların yönetimine karşı muhafazakâr ve tepkisel bir harekettir."}, {"text": "İsyancılar İttihatçı subayların görevlerine derhal iade edilmesini talep etmişlerdir.", "isCorrect": true, "rationale": "İsyan doğrudan İttihat ve Terakki Cemiyetine ve onun subay kadrosuna bir tepki olarak çıktığı için bu subayların iadesi değil, uzaklaştırılması istenmiştir."}, {"text": "Ayaklanma sonucunda Hüseyin Hilmi Paşa Hükûmeti istifa etmek zorunda kalmıştır.", "isCorrect": false, "rationale": "İsyancıların baskısı ve gösterileri üzerine mevcut hükûmet istifasını sunmuştur."}], "hint": "İsyancıların İttihat ve Terakki politikalarına tamamen karşıt bir duruş sergilediğini göz önünde bulundurunuz.", "type": "multiple_choice"}, {"question": "1889 yılında İttihad-ı Osmanî Cemiyetini kurarak daha sonra İttihat ve Terakki Cemiyetine dönüşecek olan harekete öncülük eden isim aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ahmet Rıza Bey", "isCorrect": false, "rationale": "Cemiyetin Paris grubunun liderliğini üstlenmiş ancak İstanbul'daki ilk gizli teşkilatlanmayı başlatan isim olmamıştır."}, {"text": "Ziya Gökalp", "isCorrect": false, "rationale": "İttihat ve Terakki'nin ideoloğu olmakla birlikte cemiyetin ilk kurucu çekirdeğinde yer almamıştır."}, {"text": "Namık Kemal", "isCorrect": false, "rationale": "Genç Osmanlılar hareketinin önde gelen fikir adamlarından biridir."}, {"text": "İbrahim Temo", "isCorrect": true, "rationale": "Askeri Tıbbiye öğrencileriyle birlikte İttihad-ı Osmanî Cemiyetinin kurucuları arasında yer alan öncü isimdir."}], "hint": "Askerî Tıbbiye'de gizli cemiyetleşmeyi başlatan Arnavut kökenli Osmanlı aydınını düşününüz.", "type": "multiple_choice"}, {"question": "Sultan Abdülmecit döneminde ilan edilen ve gayrimüslim tebaaya eşit haklar tanıyarak geleneksel yapıda köklü değişimler öngören mülki ıslahat belgesi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Nizam-ı Cedit", "isCorrect": false, "rationale": "III. Selim dönemi askerî ve idari yenilik programına verilen isimdir."}, {"text": "Islahat Fermanı", "isCorrect": true, "rationale": "1856 yılında ilan edilen bu ferman özellikle azınlık haklarını düzenleyen ve dış baskıların da etkisiyle hazırlanan mülki yenilik programıdır."}, {"text": "Halepa Fermanı", "isCorrect": false, "rationale": "Girit'teki Rum nüfusa özerklik imtiyazları veren özel bir düzenlemedir."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "II. Mahmud döneminde merkezî otorite ile âyânlar arasında yapılan belgedir."}], "hint": "Kırım Savaşı sonrasında Paris Antlaşması öncesinde ilan edilen reform belgesini hatırlayınız.", "type": "multiple_choice"}, {"question": "31 Mart Ayaklanması'nın çıkmasında ve ordu içerisinde huzursuzluk yaşanmasında etkili olan temel askerî idari sorun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kapıkulu askerlerinin ulufe alamaması", "isCorrect": false, "rationale": "Ulufe sistemi klasik dönem Osmanlı askerî yapısına aittir."}, {"text": "Tımar sisteminin bozulması", "isCorrect": false, "rationale": "Tımar sistemi eyalet ordusuyla ilgili olup XX. yüzyıl başındaki profesyonel ordu içi çatışmayı açıklamaz."}, {"text": "Yeniçeri Ocağı'nın kaldırılması kararı", "isCorrect": false, "rationale": "Yeniçeri Ocağı 1826'da (Vaka-i Hayriye) kaldırılmış olup 1909 olayları ile ilgisi yoktur."}, {"text": "Alaylı-mektepli çatışması ve alaylı subayların tasfiye edilmesi", "isCorrect": true, "rationale": "Mektepli subayların öne çıkarılması ve geleneksel alaylı subay kadrosunun tasfiyesi subaylar arasında ciddi tepki oluşturmuştur."}], "hint": "Mektep mezunu eğitimli subaylar ile çekirdekten yetişme subaylar arasındaki gerilimi düşününüz.", "type": "multiple_choice"}, {"question": "Mustafa Kemal Paşa'nın 19 Gemici/Mayıs 1919'da Samsun'a çıkarken resmi görevi olan 9. Ordu Müfettişliğine atanmasının asıl gerekçesi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Güney cephesinde Fransızlara karşı direnişi başlatmak", "isCorrect": false, "rationale": "Güney cephesi 9. Ordu Müfettişliği görev sahası dışındadır."}, {"text": "Anadolu'da yeni bir hükûmet kurmak", "isCorrect": false, "rationale": "İstanbul Hükûmeti tarafından verilen resmi talimatta yeni bir hükûmet kurma yetkisi yer almamaktadır."}, {"text": "Sivas Kongresi'ni hemen organize etmek", "isCorrect": false, "rationale": "Kongre kararları Mustafa Kemal Paşa'nın resmi görevinin bir parçası olmayıp Millî Mücadele sürecinde kendi kararıyla uygulanmıştır."}, {"text": "Bölgedeki Türkler ile Rumlar arasındaki çatışmaları sona erdirmek ve asayişi sağlamak", "isCorrect": true, "rationale": "İstanbul Hükûmeti ve İtilaf Devletleri'nin talebi doğrultusunda Mondros mütarekesi hükümlerine uyulmasını sağlamak ve çatışmaları durdurmak amacıyla görevlendirilmiştir."}], "hint": "Karadeniz bölgesindeki Mondros Mütarekesi ihlallerini ve İtilaf Devletleri'nin müdahale tehditlerini önleme amacını düşününüz.", "type": "multiple_choice"}]}, "2": {"unit": 2, "unitTitle": "Yeni Bir İktidar, Yıkıcı ve Yıpratıcı Savaşlar Dönemi", "title": "Tarih Testi", "questions": [{"question": "Osmanlı Devleti'nde bürokrasiyi yönlendiren kâtip sınıfının gelişim süreçlerinde, dış dünyayı kavramaya çalışan ve 'kadim' olanın karşısına 'yeni' yaklaşımını koyan evre aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Çelebiler Çağı", "isCorrect": true, "rationale": "Bu dönem, kâtip sınıfının Osmanlı dışındaki gelişmeleri merak ederek geleneksel kalıpların ötesinde yeni fikirleri kavramaya başladığı dönemi temsil eder."}, {"text": "Kahramanlar Çağı", "isCorrect": false, "rationale": "Bu adlandırma, devletin kuruluş ve yükselme dönemindeki askeri liderlik ve fetih sürecini tanımlamada kullanılır."}, {"text": "Sefirler ve Reîsülküttâplar Çağı", "isCorrect": false, "rationale": "Bu evre, diplomasinin ön plana çıktığı ve hariciye sınıfının belirleyici olduğu farklı bir dönemi tanımlar."}, {"text": "Münevverler Çağı", "isCorrect": false, "rationale": "Bu kavram daha çok 19. yüzyıldaki Batılılaşma etkisindeki aydın bürokrat kuşağını ifade etmektedir."}], "hint": "Bu dönemin adı, terbiye, görgü ve entelektüel merakı temsil eden geleneksel unvandan türetilmiştir.", "type": "multiple_choice"}, {"question": "23 Temmuz 1908'de II. Meşrutiyet'in ilan edilmesinden sonra İttihat ve Terakki Cemiyeti'nin yönetimine ve uygulamalarına tepki olarak başlayan siyasi olay aşağıdakilerden hangisidir?", "answerOptions": [{"text": "31 Mart Vakası", "isCorrect": true, "rationale": "Rumi takvime göre 31 Mart 1325'te patlak veren bu isyan, meşrutiyet rejimine ve İttihatçıların iktidar nüfuzuna karşı gelişen en belirgin tepkidir."}, {"text": "Vaka-i Hayriye", "isCorrect": false, "rationale": "Bu gelişme II. Mahmud döneminde Yeniçeri Ocağı'nın kaldırılmasını ifade eden devlet hamlesidir."}, {"text": "Kabakçı Mustafa İsyanı", "isCorrect": false, "rationale": "Bu olay III. Selim dönemi ıslahatlarına ve Nizam-ı Cedit ordusuna karşı gerçekleştirilmiş bir başkaldırıdır."}, {"text": "Patrona Halil İsyanı", "isCorrect": false, "rationale": "Bu ayaklanma 18. yüzyılda Lale Devri'ni sona erdiren toplumsal ve askeri bir huzursuzluktur."}], "hint": "Olay, Rumi takvimdeki meydana geliş tarihine atıfla anılmaktadır.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sonunda Almanya'nın sömürgelerini kaybetmesine, askeri sınırlamalara tabi tutulmasına ve ağır finansal yükümlülükler üstlenmesine yol açan antlaşma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "St. Germain Barış Antlaşması", "isCorrect": false, "rationale": "Bu düzenleme Avusturya İmparatorluğu'nun savaştan sonraki statüsünü tayin etmek üzere imzalanmıştır."}, {"text": "Neuilly Antlaşması", "isCorrect": false, "rationale": "Bu antlaşma I. Dünya Savaşı sonrasında Bulgaristan ile imzalanmıştır."}, {"text": "Trianon Antlaşması", "isCorrect": false, "rationale": "Bu metin I. Dünya Savaşı'nın ardından Macaristan sınırlarını ve yükümlülüklerini belirlemiştir."}, {"text": "Versay Barış Antlaşması", "isCorrect": true, "rationale": "Savaş sonrasında Müttefik Devletler ile Almanya arasında imzalanan bu antlaşma, Almanya'ya dönük son derece ağır yaptırımlar içermektedir."}], "hint": "Fransa'da tarihi bir sarayda imzalanan ve II. Dünya Savaşı'na giden süreci tetikleyen barış metnini düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi Çanakkale Zaferi'nin küresel düzeyde yarattığı siyasi ve ekonomik neticelerden biri değildir?", "answerOptions": [{"text": "Osmanlı Boğazları yönetimi için uluslararası bir komisyonun kurulması", "isCorrect": true, "rationale": "Boğazlar Komisyonu'nun kurulması Çanakkale Zaferi'nin değil, savaştan sonra imzalanan mütareke ve barış taslaklarının bir sonucudur."}, {"text": "Rusya'ya yardım ulaştırılamaması sebebiyle Çarlık rejiminin çöküş sürecinin hızlanması", "isCorrect": false, "rationale": "Müttefiklerin Boğazları geçememesi Rusya'daki ekonomik ve askeri krizi derinleştirerek Bolşevik İhtilali'ne zemin hazırlamıştır."}, {"text": "İngiltere ve Fransa'nın sömürgeleri üzerindeki sarsılmaz askeri itibarının darbe alması", "isCorrect": false, "rationale": "Çanakkale'de alınan yenilgi, Batılı güçlerin yenilmezliği algısını kırarak sömürgelerde bağımsızlık düşüncesini cesaretlendirmiştir."}, {"text": "İngiltere'de savaş harcamalarının getirdiği baskıyla hükümet krizinin yaşanması", "isCorrect": false, "rationale": "Uzayan savaş ve ağır maliyetler İngiliz iç siyasetinde hükümet değişikliklerine yol açmıştır."}], "hint": "Çanakkale Savaşı Osmanlı Devleti'nin zaferiyle sonuçlandığından, Boğazlar üzerindeki kontrol derhal Müttefiklerin eline geçmemiştir.", "type": "multiple_choice"}, {"question": "XVII. yüzyıl Osmanlı düşünürü Katip Çelebi'nin, devlet mekanizmasındaki aksaklıkları ve bürokratların basiretsizliğini cesur bir dille eleştirerek çözüm yolları sunduğu eseri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Düstûrü'l-Amel li Islahı'l-Halel", "isCorrect": true, "rationale": "Katip Çelebi bu risalesinde devlet yapısındaki bozulmaları bir tıp benzetmesiyle ele almış ve ıslahat önerileri sunmuştur."}, {"text": "Asafnâme", "isCorrect": false, "rationale": "Sadrazam Lütfi Paşa'ya ait olan bu eser devlet yönetimi ilkelerini ele alır."}, {"text": "Keşfü'z-Zünûn", "isCorrect": false, "rationale": "Bu eser binlerce yazma eseri ve yazarlarını içeren geniş bir bibliyografya çalışmasıdır."}, {"text": "Künhü’l-Ahbar", "isCorrect": false, "rationale": "Bu çalışma Gelibolulu Mustafa Âlî tarafından kaleme alınmış genel bir tarih eseridir."}], "hint": "Eserin adı Türkçe karşılık olarak 'Bozuklukların Düzeltilmesinde Uygulanacak Düsturlar' anlamına gelmektedir.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti ile İtalya arasında gerçekleşen Trablusgarp Savaşı'nı resmi olarak sona erdiren diplomatik antlaşma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Atina Antlaşması", "isCorrect": false, "rationale": "Balkan Savaşları sonrasında Osmanlı Devleti ile Yunanistan arasında imzalanan ikili antlaşmadır."}, {"text": "Uşi Antlaşması", "isCorrect": true, "rationale": "1912 yılında imzalanan bu antlaşma ile Osmanlı Devleti Kuzey Afrika'daki son toprak parçası olan Trablusgarp ve Bingazi'yi İtalya'ya bırakmıştır."}, {"text": "Londra Antlaşması", "isCorrect": false, "rationale": "I. Balkan Savaşı'nı sona erdiren ve Midye-Enez hattını sınır kabul eden düzenlemedir."}, {"text": "Bükreş Antlaşması", "isCorrect": false, "rationale": "Bu antlaşma Balkan Savaşları sonrasında Balkan devletlerinin kendi aralarında yaptığı paylaşımı kapsar."}], "hint": "İsviçre'de imzalanan ve Osmanlı Devleti'nin Kuzey Afrika varlığını sona erdiren antlaşmayı hatırlayınız.", "type": "multiple_choice"}, {"question": "I. TBMM Hükûmeti'nin açılışından sonra Anadolu'da hızla yayılan iç ayaklanmaları bastırmak ve kamu düzenini tesis etmek amacıyla 29 Nisan 1920'de kabul edilen kanun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "TBMM'nin çalışma esaslarını ve toplantı yeter sayısını düzenleyen iç tüzük niteliğinde bir kanundur."}, {"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "Meclisin meşruiyetine karşı çıkan her türlü ayaklanma ve direnci yasaklayan ve ağır cezai yaptırımlar getiren temel yasal düzenlemedir."}, {"text": "Takrir-i Sükûn Kanunu", "isCorrect": false, "rationale": "Bu kanun 1925 yılında Şeyh Sait İsyanı sonrasında devlet otoritesini yeniden kurmak amacıyla çıkarılmıştır."}, {"text": "Men-i Müskirat Kanunu", "isCorrect": false, "rationale": "Savaş dönemi tasarruf tedbirleri kapsamında alkollü içeceklerin üretim ve tüketimini engellemeye yönelik yasadır."}], "hint": "Vatana ihanet edenlerin cezalandırılmasını öngören yasayı düşününüz.", "type": "multiple_choice"}, {"question": "Milli Mücadele Dönemi'nde işgalci Batılı devletlerin kendi güvenliğine tehdit oluşturması ve kendi bünyesindeki Türk-Müslüman unsurlara sempatik görünme arzusuyla Ankara Hükûmeti'ne finansal ve askeri destek sağlayan ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Bulgaristan", "isCorrect": false, "rationale": "Bulgaristan savaştan yenik çıkmış ve kendi toprak kayıplarıyla mücadele etmek durumunda kalmıştır."}, {"text": "Almanya", "isCorrect": false, "rationale": "Almanya, I. Dünya Savaşı'ndan yenik ayrıldığı için Mondros sonrası süreçte destek verecek durumda değildi."}, {"text": "Arnavutluk", "isCorrect": false, "rationale": "Arnavutluk o dönemde kendi bağımsızlığını ve sınırlarını korumaya çalışan küçük bir Balkan devletidir."}, {"text": "Sovyet Rusya", "isCorrect": true, "rationale": "Bolşevik yönetimi, ortak düşman olarak gördüğü Müttefik Devletler'e karşı Milli Mücadele'ye parasal ve cephane yardımı yapmıştır."}], "hint": "Çarlık rejiminin yıkılmasından sonra kurulan ve Batılı devletlerle rekabet halinde olan komşu devleti hatırlayınız.", "type": "multiple_choice"}, {"question": "Milli Mücadele Dönemi'nde Ankara'da yayımlanan, TBMM Hükûmeti'nin yarı resmî yayın organı kabul edilen ve 1934 yılında adını 'Ulus' olarak değiştiren gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Mustafa Kemal Paşa'nın Ankara'ya gelişinden sonra çıkarılan bu gazete, Anadolu hareketinin temel yayın organı olmuştur."}, {"text": "Minber", "isCorrect": false, "rationale": "Mondros sonrasında İstanbul'da Ali Fethi (Okyar) ve Mustafa Kemal tarafından çıkarılan gazetedir."}, {"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi kararlarını duyurmak amacıyla Sivas'ta çıkarılan ilk gazeteydi."}, {"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Şinasi tarafından Tanzimat Dönemi'nde İstanbul'da kurulmuş tarihi bir basın organıdır."}], "hint": "İsmi 'Millet Egemenliği' anlamına gelen bu yayın organı Ankara merkezli mücadeleyi seslendirmiştir.", "type": "multiple_choice"}, {"question": "28 Ocak 1920'de Son Osmanlı Mebusan Meclisi tarafından kabul edilen, Türk vatanının sınırlarını çizen ve siyasi-ekonomik bağımsızlığın asgari şartlarını belirleyen tarihi bildiri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kanun-ı Esasi", "isCorrect": false, "rationale": "1876 yılında ilan edilen Osmanlı Devleti'nin ilk yazılı anayasasıdır."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında II. Mahmud ile ayanlar arasında yapılan yetki paylaşımı sözleşmesidir."}, {"text": "Amasya Tamimi", "isCorrect": false, "rationale": "Milli Mücadele'nin gerekçe, amaç ve yöntemini ilk kez belirten ihtilal beyannamesidir."}, {"text": "Misak-ı Milli", "isCorrect": true, "rationale": "'Milli And' olarak da bilinen bu kararlar metni, Türkiye Cumhuriyeti'nin temel sınırlarını ve bağımsızlık koşullarını ilke edinmiştir."}], "hint": "Ahd-ı Milli veya Milli Yemin adlarıyla da bilinen belgeyi düşününüz.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sırasında Osmanlı ordusunun Irak Cephesi'nde İngiliz kuvvetlerini kuşatarak General Townshend dâhil çok sayıda askeri esir aldığı zafer aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kutü'l-Amâre Muharebesi", "isCorrect": true, "rationale": "Halil (Kut) Paşa komutasındaki Osmanlı birliklerinin İngiliz ordusunu kuşatarak büyük bir zafer elde ettiği muharebedir."}, {"text": "Kirte Muharebeleri", "isCorrect": false, "rationale": "Çanakkale Kara Savaşları sırasında Gelibolu Yarımadası'nda gerçekleşen savunma muharebeleridir."}, {"text": "Zığındere Muharebesi", "isCorrect": false, "rationale": "Çanakkale Savaşları bünyesinde kanlı çarpışmalara sahne olan bir diğer muharebedir."}, {"text": "83 Rakımlı Tepe Muharebesi", "isCorrect": false, "rationale": "Çanakkale Cephesi'ndeki yerel çatışma alanlarından biridir."}], "hint": "Irak Cephesi'nde İngiliz tümeninin tamamının teslim alındığı tarihi muharebeyi hatırlayınız.", "type": "multiple_choice"}, {"question": "İzmir'in Yunanistan tarafından işgal edilmesini ve ilhakını kabul etmeyerek bölgede protestolar düzenleyen ve işgale karşı direnişi örgütleyen cemiyet aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Trakya Paşaeli Cemiyeti", "isCorrect": false, "rationale": "Doğu Trakya'nın Yunanistan'a ilhakını önlemek amacıyla Edirne merkezli faaliyet gösteren cemiyettir."}, {"text": "Redd-i İlhak Cemiyeti", "isCorrect": true, "rationale": "İzmir'in Yunanlılara verilmesini engellemek ve Ege'deki Türk varlığını savunmak amacıyla kurulan teşkilattır."}, {"text": "Kilikyalılar Cemiyeti", "isCorrect": false, "rationale": "Çukurova ve Adana bölgesindeki Fransız ve Ermeni işgallerine karşı kurulmuş bir cemiyettir."}, {"text": "Mavri Mira Cemiyeti", "isCorrect": false, "rationale": "Fener Rum Patrikhanesi bünyesinde Büyük Yunanistan fikrini gerçekleştirmek için çalışan zararlı cemiyettir."}], "hint": "Cemiyetin adı 'Toprakların Başka Bir Devlete Bağlanmasını Reddetme' ilkesine dayanmaktadır.", "type": "multiple_choice"}]}, "3": {"unit": 3, "unitTitle": "Millî Mücadele Başlıyor", "title": "İnkılap Tarihi Testi", "questions": [{"question": "Millî Mücadele Dönemi'nde Sivas Kongresi kararlarını halka duyurmak ve millî birliği sağlamak amacıyla çıkarılan ilk resmî yayın organı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hâkimiyet-i Milliye", "isCorrect": false, "rationale": "Bu gazete, TBMM'nin açılmasından sonra Ankara'da yayımlanmaya başlayan yarı resmî yayın organıdır."}, {"text": "Albayrak", "isCorrect": false, "rationale": "Erzurum'da Doğu Anadolu Müdafaa-i Hukuk Cemiyeti'nin görüşlerini savunmak üzere yayımlanmıştır."}, {"text": "İrade-i Milliye", "isCorrect": true, "rationale": "Sivas Kongresi sonrasında alınan kararları halka aktarmak ve ulusal hareketi desteklemek amacıyla Sivas'ta çıkarılan ilk resmî gazetedir."}, {"text": "Minber", "isCorrect": false, "rationale": "Mütareke Dönemi'nde İstanbul'da Mustafa Kemal Paşa ve Ali Fethi Bey tarafından çıkarılan gazetedir."}], "hint": "Sivas Kongresi kararlarının kamuoyuna duyurulması için kurulmuş olan gazeteyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Mustafa Kemal Paşa'nın yaveri Cevat Abbas Bey'e yazdırılan ve Millî Mücadele'nin gerekçe, amaç ve yöntemini ilk kez belirten tarihî belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Erzurum Kongresi Kararları", "isCorrect": false, "rationale": "Doğu illerinin durumunu değerlendirmek ve manda fikrini reddetmek amacıyla toplanan bölgesel kongre kararlarıdır."}, {"text": "Sivas Kongresi Beyannamesi", "isCorrect": false, "rationale": "Tüm millî cemiyetlerin birleştirilmesinden sonra kamuoyuna yayımlanan genel beyannamedir."}, {"text": "Misak-ı Millî", "isCorrect": false, "rationale": "Son Osmanlı Mebusan Meclisinde kabul edilen ve ulusal sınırları belirleyen bağımsızlık bildirimidir."}, {"text": "Amasya Genelgesi", "isCorrect": true, "rationale": "Amasya Genelgesi, Kurtuluş Savaşı'nın gerekçe, amaç ve yöntemini beyan eden ilk resmî ihtilal beyannamesidir."}], "hint": "21-22 Haziran 1919 tarihlerinde yayımlanan ve Sivas'ta ulusal bir kongre toplanması çağrısı yapan belgeyi düşününüz.", "type": "multiple_choice"}, {"question": "Millî Mücadele sürecinde bölgesel nitelikteki tüm müdafaa-i hukuk cemiyetlerinin 'Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti' çatısı altında birleştirildiği gelişme aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Balıkesir Kongresi", "isCorrect": false, "rationale": "Batı Anadolu'da Yunan işgaline karşı düzenlenen yerel direniş kongrelerinden biridir."}, {"text": "Amasya Görüşmeleri", "isCorrect": false, "rationale": "Temsil Heyeti ile İstanbul Hükûmeti arasında yapılan ve Heyet-i Temsiliye'nin hukuki varlığını tanıtan görüşmelerdir."}, {"text": "Sivas Kongresi", "isCorrect": true, "rationale": "Sivas Kongresi'nde bölgesel tüm direniş cemiyetleri tek bir çatı altında toplanarak Millî Mücadele'nin yönetimi merkezîleştirilmiştir."}, {"text": "Erzurum Kongresi", "isCorrect": false, "rationale": "Sadece Doğu Anadolu ve Karadeniz bölgesindeki cemiyetlerin birleştirildiği bölgesel bir kongredir."}], "hint": "Manda ve himayenin kesin olarak reddedildiği ve tüm ulusal güçlerin tek çatı altında toplandığı kongreyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Mebusan Meclisinde 28 Ocak 1920'de kabul edilen, millî sınırları çizen ve vatanın bölünmezliğini ilan eden metin aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kanun-ı Esasi", "isCorrect": false, "rationale": "1876 yılında ilan edilen Osmanlı Devleti'nin ilk anayasasıdır."}, {"text": "Sevr Antlaşması", "isCorrect": false, "rationale": "İtilaf Devletleri tarafından hazırlanan ve Osmanlı Devleti'ni fiilen paylaşmayı hedefleyen tasarıdır."}, {"text": "Mondros Mütarekesi", "isCorrect": false, "rationale": "I. Dünya Savaşı sonrasında işgallere zemin hazırlayan ateşkes antlaşmasıdır."}, {"text": "Misak-ı Millî", "isCorrect": true, "rationale": "Misak-ı Millî, Türk vatanının sınırlarını netleştiren ve kapitülasyonları reddeden temel bağımsızlık bildirgesidir."}], "hint": "'Ahd-ı Millî' veya 'Millî And' olarak da bilinen kararlar bütününü düşününüz.", "type": "multiple_choice"}, {"question": "TBMM Hükûmetinin açılmasından hemen sonra artan iç ayaklanmalara karşı otoriteyi sağlamak amacıyla 29 Nisan 1920'de çıkarılan kanun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "Meclisin çalışma usul ve esaslarını belirleyen iç tüzük niteliğindeki kanundur."}, {"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "TBMM'nin varlığına ve meşruiyetine karşı çıkan isyanları bastırmak ve iç huzuru sağlamak amacıyla çıkarılan kanundur."}, {"text": "Teşkilat-ı Esasiye Kanunu", "isCorrect": false, "rationale": "1921 yılında kabul edilen TBMM'nin ilk kurucu anayasasıdır."}, {"text": "Takrir-i Sükûn Kanunu", "isCorrect": false, "rationale": "1925 yılında Şeyh Sait İsyanı sürecinde asayişi sağlamak amacıyla yürürlüğe konulmuştur."}], "hint": "Vatan hainliği suçlamalarını önlemek ve Meclis otoritesini tesis etmek amacıyla ilk çıkarılan yasalardan birini hatırlayınız.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde hem işgalci devletlerin ortak düşman olması hem de kendi ülkesindeki Müslüman azınlığa sempatik görünme amacı taşıyarak Ankara Hükûmetine mali yardım sağlayan devlet aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sovyet Rusya", "isCorrect": true, "rationale": "Ortak düşman İtilaf Devletleri'ne karşı cephe almak ve iç siyasetteki azınlıklara olumlu mesaj vermek amacıyla Ankara Hükûmetine maddi ve askeri destek sağlamıştır."}, {"text": "Almanya", "isCorrect": false, "rationale": "I. Dünya Savaşı'ndan yenik çıkmış ve Versay Antlaşması kısıtlamaları altında ezilmiş bir devlettir."}, {"text": "Arnavutluk", "isCorrect": false, "rationale": "Balkan Savaşları sürecinde bağımsızlığını kazanmış ve dış yardım yapabilecek ekonomik güce sahip olmayan bir ülkedir."}, {"text": "Bulgaristan", "isCorrect": false, "rationale": "I. Dünya Savaşı sonrası Neuilly Antlaşması ile ağır yükümlülükler üstlenmiş ve tarafsız kalmaya çalışmıştır."}], "hint": "Kurtuluş Savaşı sürecinde Ankara Hükûmeti ile Moskova Antlaşması'nı imzalayan kuzey komşumuzu düşününüz.", "type": "multiple_choice"}, {"question": "Mustafa Kemal Paşa, İstanbul'un işgalinden sonra Ankara'da toplanacak yeni meclis için hazırladığı ilk taslaklarda hangi tabiri kullanmış, ancak gelen tepkiler üzerine bu tanımı değiştirmek durumunda kalmıştır?", "answerOptions": [{"text": "Meclis-i Mebusan", "isCorrect": false, "rationale": "Osmanlı Devleti'nin İstanbul'da bulunan anayasal parlamentosuna verilen addır."}, {"text": "Meclis-i Müessesan", "isCorrect": true, "rationale": "'Kurucu Meclis' anlamına gelen bu terim, rejimin değişeceği kaygısını taşıyan çevrelerin tepkisi üzerine 'olağanüstü yetkilere sahip meclis' şeklinde değiştirilmiştir."}, {"text": "Meclis-i Kebir", "isCorrect": false, "rationale": "Osmanlı yönetim geleneklerinde üst düzey kararların görüşüldüğü danışma kuruludur."}, {"text": "Millet Meclisi", "isCorrect": false, "rationale": "Tepkiler sonrasında ve Meclis açıldıktan sonra kullanılan genel kavrama yakın bir tanımdır."}], "hint": "Fransızca kökenli olan ve 'Kurucu Meclis' anlamına gelen kavaramı hatırlayınız.", "type": "multiple_choice"}, {"question": "Millî Mücadele'nin masraflarını karşılamak ve ordunun ihtiyaçlarına kaynak yaratmak amacıyla şehirlere dışarıdan getirilen mallardan alınan giriş vergisi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Derbent vergisi", "isCorrect": false, "rationale": "Geçit ve yolların güvenliğini sağlayan birimlerin masrafları için toplanan vergidir."}, {"text": "Oktura vergisi", "isCorrect": true, "rationale": "Oktura vergisi, Millî Mücadele döneminde şehirlere giren ticari mallara uygulanan ek bir giriş vergisidir."}, {"text": "Ağnam vergisi", "isCorrect": false, "rationale": "Küçükbaş hayvan yetiştiricilerinden alınan doğrudan bir hayvancılık vergisidir."}, {"text": "Aşar vergisi", "isCorrect": false, "rationale": "Tarımsal rekolte üzerinden alınan geleneksel Osmanlı ürün vergisidir."}], "hint": "Ticaret amacıyla şehir merkezlerine sokulan mallara uygulanan kapı ve giriş vergisini düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi düzenli ordunun kurulma kararı sonrasında disiplin altına girmeyi reddederek I. TBMM'ye karşı ayaklanan Kuva-yı Milliye liderlerinden biridir?", "answerOptions": [{"text": "Çopur Musa", "isCorrect": false, "rationale": "Afyon bölgesinde dini duyguları kışkırtarak TBMM otoritesine başkaldıran yerel bir isyancıdır."}, {"text": "Anzavur Ahmet", "isCorrect": false, "rationale": "Doğrudan İstanbul Hükûmeti desteğiyle Kuva-yı Milliye'yi engellemek üzere isyan başlatan eski bir subaydır."}, {"text": "Demirci Mehmet Efe", "isCorrect": true, "rationale": "Batı Anadolu'da işgale karşı yararlılıklar göstermiş fakat düzenli ordu emir ve komutasına girmeyi kabul etmeyerek TBMM'ye karşı isyan etmiştir."}, {"text": "Delibaş Mehmet", "isCorrect": false, "rationale": "Konya ve çevresinde hilafet yanlısı söylemlerle TBMM'ye karşı ayaklanma çıkaran kişidir."}], "hint": "Batı Cephesi'nde Kuva-yı Milliye komutanlığı yapmış ancak düzenli orduya katılması istenince isyan etmiş ünlü efe liderini hatırlayınız.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde Ankara'da yayımlanan, TBMM Hükûmetinin yarı resmî yayın organı kabul edilen ve 1934 yılında 'Ulus' adını alan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Tanzimat Dönemi'nden itibaren İstanbul'da yayımlanan köklü basın organlarından biridir."}, {"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi kararlarını duyurmak üzere Sivas'ta çıkarılan ilk gazetedir."}, {"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "10 Ocak 1920'de Ankara'da yayımlanmaya başlayan gazete, TBMM'nin yarı resmî organı olmuş ve 1934'te Ulus adını almıştır."}, {"text": "Yenigün", "isCorrect": false, "rationale": "Yunus Nadi liderliğinde yayımlanan ve Millî Mücadele'yi destekleyen özel bir gazetedir."}], "hint": "Ankara'da Meclis'in sesini duyuran ve halk egemenliği vurgusu taşıyan ismi düşününüz.", "type": "multiple_choice"}, {"question": "Mustafa Kemal Paşa ve Ali Fethi Bey tarafından Mütareke döneminde İstanbul'da kamuoyunu bilgilendirmek amacıyla çıkarılan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Peyam-ı Sabah", "isCorrect": false, "rationale": "Ali Kemal'in başyazarlığını yaptığı ve Millî Mücadele karşıtı sert tutumuyla bilinen gazetedir."}, {"text": "Minber", "isCorrect": true, "rationale": "Mustafa Kemal Paşa ve Fethi (Okyar) Bey'in Mondros sonrasında İstanbul'da görüşlerini açıklamak için ortaklaşa çıkardıkları haftalık gazetedir."}, {"text": "Sabah", "isCorrect": false, "rationale": "Mütareke devrinde İstanbul'da yayımlanan dönemin mütareke gazetelerinden biridir."}, {"text": "Vakit", "isCorrect": false, "rationale": "Ahmet Emin Yalman ve Asım Us tarafından çıkarılan bağımsız bir gazetedir."}], "hint": "Mütareke günlerinde Fethi Bey ile Mustafa Kemal Paşa'nın görüşlerini kamuoyuna duyurmak için çıkardıkları gazeteyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Erzurum Kongresi'nde oluşturulan, Sivas Kongresi'nde yetkileri tüm vatanı kapsayacak şekilde genişletilen ve yürütme gücünü temsil eden kurul aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İcra Vekilleri Heyeti", "isCorrect": false, "rationale": "TBMM açıldıktan sonra Meclis içerisinden seçilen Bakanlar Kurulu kabinesine verilen isimdir."}, {"text": "Felah-ı Vatan Grubu", "isCorrect": false, "rationale": "Son Osmanlı Mebusan Meclisinde Misak-ı Millî kararlarının kabulünü sağlayan milletvekili grubudur."}, {"text": "Meclis-i Mebusan", "isCorrect": false, "rationale": "Osmanlı Anayasası gereğince İstanbul'da toplanan yasama meclisidir."}, {"text": "Heyet-i Temsiliye", "isCorrect": true, "rationale": "Heyet-i Temsiliye (Temsil Kurulu), TBMM açılıncaya kadar Millî Mücadele'nin siyasi ve yürütme organı olarak görev yapmıştır."}], "hint": "Başkanlığını Mustafa Kemal Paşa'nın yaptığı ve TBMM açılana dek geçici hükûmet gibi çalışan kurulu düşününüz.", "type": "multiple_choice"}]}, "4": {"unit": 4, "unitTitle": "Yeni Türk Devleti'nin Kuruluşu", "title": "İnkılap Tarihi Testi", "questions": [{"question": "TBMM Hükûmetinin Millî Mücadele Dönemi'nde kamuoyunu bilgilendirmek ve kamuoyu desteğini sağlamak amacıyla Ankara'da çıkardığı, sonradan 'Ulus' adını alan yarı resmî gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Ankara'da kurularak Millî Mücadele'nin sözcülüğünü üstlenmiş ve Cumhuriyet döneminde Ulus adıyla yayınına devam etmiştir."}, {"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi'nin ardından Sivas'ta çıkarılmaya başlanan ilk Millî Mücadele gazetesidir."}, {"text": "Minber", "isCorrect": false, "rationale": "İstanbul'da Mustafa Kemal Paşa ile Ali Fethi Bey tarafından yayımlanan mütareke dönemi gazetesidir."}, {"text": "Yenigün", "isCorrect": false, "rationale": "Yunus Nadi tarafından önce İstanbul'da, ardından Ankara'da yayımlanan bağımsız bir gazetedir."}], "hint": "Ankara'da TBMM'nin yayın organı haline gelen ve adını millet egemenliği kavramından alan gazeteyi düşününüz.", "type": "multiple_choice"}, {"question": "TBMM'nin açılmasının ardından otoriteyi sağlamak ve iç ayaklanmaları bastırmak amacıyla 29 Nisan 1920 tarihinde kabul edilen yasal düzenleme aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "Millî Mücadele'ye ve TBMM'nin meşruiyetine karşı çıkan isyanları bastırmak ve iç güvenliği sağlamak amacıyla çıkarılmıştır."}, {"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "TBMM'nin çalışma esaslarını ve toplantı yeter sayısını düzenleyen ilk içtüzük niteliğindeki kanundur."}, {"text": "Takrir-i Sükûn Kanunu", "isCorrect": false, "rationale": "1925 yılında Şeyh Sait İsyanı'nın ardından huzur ve güvenliği sağlamak amacıyla yürürlüğe girmiştir."}, {"text": "Teşkilat-ı Esasiye Kanunu", "isCorrect": false, "rationale": "1921 yılında kabul edilen yeni Türk devletinin ilk anayasasıdır."}], "hint": "Meclisin açılışından hemen sonra vatan hainliği ve isyan hareketlerini önlemek için çıkarılan kanunu hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Mebusan Meclisi tarafından 28 Ocak 1920'de kabul edilen ve Türk vatanının sınırları ile tam bağımsızlık ilkelerini belirleyen tarihi belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında Sultan II. Mahmut ile ayanlar arasında imzalanan sözleşmedir."}, {"text": "Amasya Genelgesi", "isCorrect": false, "rationale": "Millî Mücadele'nin amaç, gerekçe ve yöntemini belirten ihtilal beyannamesi niteliğindeki belgedir."}, {"text": "Kanun-i Esasi", "isCorrect": false, "rationale": "1876 yılında ilan edilen Osmanlı Devleti'nin ilk yazılı anayasasıdır."}, {"text": "Misak-ı Millî", "isCorrect": true, "rationale": "Osmanlı Mebusan Meclisinin son oturumlarında kabul edilen ve asgari barış şartlarını belirleyen Ulusal Ant'tır."}], "hint": "'Milli And' olarak da bilinen ve Mebusan Meclisinde oy birliğiyle kabul edilen bildiriyi düşününüz.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde işgalci devletlerle mücadele ederken aynı zamanda Anadolu'daki Türk-Müslüman nüfusa sempatik görünmek ve ortak düşmanlarına karşı Türk direnişini desteklemek amacıyla TBMM'ye mali ve askeri yardım sağlayan devlet aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sovyet Rusya", "isCorrect": true, "rationale": "Hem İtilaf Devletleri'nin güneyden kendisini kuşatmasını engellemek hem de ortak düşmana karşı savaşmak amacıyla TBMM'ye altın ve silah desteği sağlamıştır."}, {"text": "Fransa", "isCorrect": false, "rationale": "Millî Mücadele döneminde Çukurova ve çevresini işgal eden İtilaf devletlerinden biridir."}, {"text": "Almanya", "isCorrect": false, "rationale": "I. Dünya Savaşı'nda Osmanlı Devleti'nin müttefiki olup savaş sonrasında ağır şartlar içeren Versay Antlaşması'nı imzalamıştır."}, {"text": "İngiltere", "isCorrect": false, "rationale": "İşgalci güçlerin başında yer alan ve TBMM'ye karşı tutum sergileyen ana devlettir."}], "hint": "Çarlık rejiminin yıkılmasından sonra İtilaf Devletleri'ne karşı Ankara Hükûmeti ile yakınlaşan kuzey komşumuzu hatırlayınız.", "type": "multiple_choice"}, {"question": "Mustafa Kemal Paşa ve Ali Fethi (Okyar) Bey tarafından Mütareke döneminde İstanbul'da fikirlerini yaymak ve kamuoyu oluşturmak amacıyla çıkarılan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi kararlarını duyurmak üzere Sivas'ta çıkarılan gazetedir."}, {"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Şinasi tarafından Tanzimat döneminde çıkarılmaya başlanan köklü bir Osmanlı gazetesidir."}, {"text": "Albayrak", "isCorrect": false, "rationale": "Doğu Anadolu Müdafaa-i Hukuk Cemiyeti bünyesinde Erzurum'da yayımlanan gazetedir."}, {"text": "Minber", "isCorrect": true, "rationale": "Mustafa Kemal Paşa'nın Mondros sonrasında İstanbul'da siyasi düşüncelerini aktarmak için Ali Fethi Bey ile ortaklaşa çıkardığı gazetedir."}], "hint": "Mondros Ateşkesi'nden sonra İstanbul'daki mütareke günlerinde yayın hayatına giren gazeteyi düşününüz.", "type": "multiple_choice"}, {"question": "4-11 Eylül 1919 tarihleri arasında toplanan ve Anadolu'daki tüm cemiyetleri 'Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti' adı altında birleştiren kongre aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Erzurum Kongresi", "isCorrect": false, "rationale": "Doğu vilayetlerinin durumunu görüşmek üzere toplanan ancak kararları bakımından ulusal nitelik taşıyan bölgesel bir kongredir."}, {"text": "Amasya Görüşmeleri", "isCorrect": false, "rationale": "Temsil Heyeti ile İstanbul Hükûmeti arasında hukuki tanınmayı sağlayan görüşmelerdir."}, {"text": "Alaşehir Kongresi", "isCorrect": false, "rationale": "Batı Anadolu'daki Yunan işgaline karşı bölgesel direnişi örgütlemek amacıyla toplanmıştır."}, {"text": "Sivas Kongresi", "isCorrect": true, "rationale": "Bölgesel direniş cemiyetlerini tek bir çatı altında toplayarak Millî Mücadele'yi ulusal çapta tek merkezden yönetilebilir hale getirmiştir."}], "hint": "Manda ve himayenin kesin olarak reddedildiği ve tüm cemiyetlerin tek çatı altında birleştirildiği kongreyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti'nde Divan-ı Hümayun'un kaldırılarak yerine Avrupa tarzı nezaretlerin (bakanlıkların) kurulması ve ilk nüfus sayımının yapılması hangi padişah döneminde gerçekleşmiştir?", "answerOptions": [{"text": "II. Mahmut", "isCorrect": true, "rationale": "Müsadere sistemini kaldıran, mukataaları merkeze bağlayan ve devlet teşkilatını modernleştiren köklü ıslahatlar yapmıştır."}, {"text": "Sultan Abdülmecit", "isCorrect": false, "rationale": "Tanzimat ve Islahat fermanlarını ilan eden Osmanlı padişahıdır."}, {"text": "II. Abdülhamit", "isCorrect": false, "rationale": "Kanun-i Esasi'yi ilan ederek Meşrutiyet dönemini başlatan padişahtır."}, {"text": "III. Selim", "isCorrect": false, "rationale": "Nizam-ı Cedit ordusunu kuran ancak Kabakçı Mustafa İsyanı ile tahttan indirilen yenilikçi padişahtır."}], "hint": "Yeniçeri Ocağı'nı kaldırarak 'Vaka-yı Hayriye'yi gerçekleştiren ıslahatçı padişahı düşününüz.", "type": "multiple_choice"}, {"question": "Mondros Ateşkes Antlaşması sonrasında İzmir'in Yunanistan tarafından işgal edilmesini ve ilhakını kabul etmeyerek bölgede direnişi örgütleyen cemiyet aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mavri Mira Cemiyeti", "isCorrect": false, "rationale": "Yunan hükümeti adına Büyük Yunanistan (Megali Idea) hayalini gerçekleştirmeye çalışan zararlı cemiyettir."}, {"text": "Doğu Anadolu Müdafaa-i Hukuk Cemiyeti", "isCorrect": false, "rationale": "Doğu vilayetlerinde bir Ermeni devleti kurulmasını engellemek amacıyla teşkilatlanmıştır."}, {"text": "Kilikyalılar Cemiyeti", "isCorrect": false, "rationale": "Çukurova bölgesinin Fransız ve Ermeni işgaline karşı savunulması için kurulmuştur."}, {"text": "Redd-i İlhak Cemiyeti", "isCorrect": true, "rationale": "İzmir ve çevresinin Yunanistan'a bağlanmasını önlemek amacıyla İzmirli yurtseverler tarafından kurulmuştur."}], "hint": "Adı doğrudan 'ilhakı/bağlanmayı reddetmek' anlamına gelen cemiyeti hatırlayınız.", "type": "multiple_choice"}, {"question": "21-22 Haziran 1919'da yayımlanan ve 'Vatanın bütünlüğü, milletin bağımsızlığı tehlikededir' ifadesiyle Millî Mücadele'nin gerekçesini ortaya koyan belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Amasya Genelgesi", "isCorrect": true, "rationale": "Mustafa Kemal Paşa ve arkadaşlarının hazırladığı, milletin bağımsızlığını yine milletin azim ve kararının kurtaracağını ilan eden ihtilal belgesidir."}, {"text": "Sevr Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonrasında Osmanlı Devleti'ne zorla kabul ettirilmek istenen ağır paylaşım antlaşmasıdır."}, {"text": "Misak-ı Millî", "isCorrect": false, "rationale": "Osmanlı Mebusan Meclisinde kabul edilen milli barış şartları belgesidir."}, {"text": "Havza Bildirisi", "isCorrect": false, "rationale": "İşgallere karşı ilk protesto mitinglerinin yapılmasını öngören kişisel bir çağrıdır."}], "hint": "Cevat Abbas Bey tarafından kaleme alınan ve Sivas'ta milli bir kongrenin toplanacağını müjdeleyen genelgeyi düşününüz.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sırasında İngiltere'nin Hint deniz yolunun güvenliğini sağlamak ve Abadan petrollerini korumak amacıyla açtığı cephe aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Irak Cephesi", "isCorrect": true, "rationale": "İngilizlerin Ortadoğu petrollerini denetim altına almak ve kuzeye ilerleyerek Rusya ile birleşmak gayesiyle açtığı taarruz cephesidir."}, {"text": "Kanal Cephesi", "isCorrect": false, "rationale": "Osmanlı Devleti'nin Mısır'ı İngilizlerden geri almak amacıyla açtığı taarruz cephesidir."}, {"text": "Hicaz-Yemen Cephesi", "isCorrect": false, "rationale": "Kutsal toprakları korumak amacıyla İngiliz desteğindeki isyancı gruplara karşı savunma yapılan cephedir."}, {"text": "Kafkasya Cephesi", "isCorrect": false, "rationale": "Enver Paşa komutasında Sarıkamış Harekâtı'nın gerçekleştiği Doğu cephesidir."}], "hint": "Basra Körfezi'nden çıkarak Bağdat yönünde ilerlemek isteyen İngiliz birliklerine karşı savaşılan cepheyi hatırlayınız.", "type": "multiple_choice"}, {"question": "13 Nisan 1909 (Rumi 31 Mart 1325) tarihinde II. Meşrutiyet yönetimine ve İttihat ve Terakki Cemiyeti'ne tepki olarak ortaya çıkan ayaklanma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "31 Mart Vakası", "isCorrect": true, "rationale": "Anayasal düzene ve Meşrutiyet rejimine karşı başlatılan, Mahmut Şevket Paşa komutasındaki Hareket Ordusu tarafından bastırılan isyandır."}, {"text": "Patrona Halil İsyanı", "isCorrect": false, "rationale": "Lale Devri'ni sona erdiren ve III. Ahmet'in tahttan indirilmesine yol açan isyandır."}, {"text": "Bab-ı Ali Baskını", "isCorrect": false, "rationale": "1913 yılında İttihatçıların hükûmet darbesiyle iktidarı tamamen ele geçirdiği olaydır."}, {"text": "Kabakçı Mustafa İsyanı", "isCorrect": false, "rationale": "III. Selim dönemi ıslahatlarını ve Nizam-ı Cedit ordusunu hedef alan isyandır."}], "hint": "Rumi takvime göre adlandırılan ve Hareket Ordusu tarafından bastırılan rejime karşı ilk isyanı düşününüz.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı'nın ardından müttefik devletlerin Osmanlı topraklarını paylaşma planlarını güncellemesiyle hazırlanan ve 10 Ağustos 1920'de imzalanan antlaşma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "St. Germen Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda İtilaf Devletleri ile Avusturya arasında imzalanan barış antlaşmasıdır."}, {"text": "Neuilly Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda İtilaf Devletleri ile Bulgaristan arasında imzalanan barış antlaşmasıdır."}, {"text": "Sevr Antlaşması", "isCorrect": true, "rationale": "İtilaf Devletleri tarafından Osmanlı Hükûmetine dikte ettirilen ve Türk milletine bağımsız yaşama hakkı tanımayan antlaşmadır."}, {"text": "Mondros Mütarekesi", "isCorrect": false, "rationale": "30 Ekim 1918'de imzalanan ve Osmanlı Devleti'ni fiilen işgale açık hale getiren ateşkestir."}], "hint": "Saltanat Şurası tarafından onaylanan ancak TBMM tarafından geçersiz kabul edilen antlaşmayı hatırlayınız.", "type": "multiple_choice"}]}, "5": {"unit": 5, "unitTitle": "Türk İstiklal Harbi", "title": "İnkılap Tarihi Testi", "questions": [{"question": "Osmanlı Mebusan Meclisinde 28 Ocak 1920 tarihinde kabul edilen ve Türk vatanının sınırları ile siyasi ve ekonomik bağımsızlığın asgari şartlarını belirleyen bildiri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kanun-i Esasi", "isCorrect": false, "rationale": "1876 yılında ilan edilen ve Osmanlı Devleti'nin anayasal düzene geçişini sağlayan ilk temel anayasadır."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında Ayanlar ile padişah II. Mahmud arasında yapılan ve padişahın yetkilerini ilk kez kısıtlayan bir sözleşmedir."}, {"text": "Misak-ı Milli", "isCorrect": true, "rationale": "Son Osmanlı Mebusan Meclisi tarafından kabul edilen bu metin, vatanın bölünmez bütünlüğünü ve tam bağımsızlık esaslarını ilan eden temel belgedir."}, {"text": "Amasya Genelgesi", "isCorrect": false, "rationale": "Millî Mücadele'nin amaç, gerekçe ve yöntemini ilk kez açıklayan ihtilal bildirisi niteliğindedir ancak Mebusan Meclisi kararı değildir."}], "hint": "Ahd-ı Milli veya Milli And olarak da bilinen bu metin, Kurtuluş Savaşı'nın hedeflerini çizen nihai belgedir.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde Ankara'da TBMM Hükûmetinin yarı resmî yayın organı işlevini üstlenen ve 1934 yılından itibaren 'Ulus' adıyla yayımlanan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi'nin ardından mücadelenin sesini duyurmak amacıyla Sivas'ta çıkarılmaya başlanan ilk gazetedir."}, {"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Ankara'da çıkarılan ve Millî Mücadele'nin kamuoyuna duyurulmasında TBMM'nin sözcüsü konumunda olan temel yayın organıdır."}, {"text": "Minber", "isCorrect": false, "rationale": "Mütareke döneminde İstanbul'da Mustafa Kemal Paşa ve Ali Fethi Bey tarafından ortaklaşa çıkarılan gazetedir."}, {"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Şinasi tarafından Tanzimat döneminde İstanbul'da yayımlanmaya başlayan klasik Osmanlı gazetelerinden biridir."}], "hint": "İsmi milli egemenlik vurgusu taşıyan ve Ankara merkezli yürütülen haberciliğin simgesi olan yayın organını düşününüz.", "type": "multiple_choice"}, {"question": "I. TBMM açıldıktan sonra iç huzuru sağlamak, bozgunculuğu önlemek ve TBMM'ye karşı çıkan ayaklanmaları bastırmak amacıyla 29 Nisan 1920'de kabul edilen yasal düzenleme aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Takrir-i Sükûn Kanunu", "isCorrect": false, "rationale": "Şeyh Sait İsyanı sonrasında 1925 yılında ülke genelinde asayişi yeniden kurmak amacıyla çıkarılmıştır."}, {"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "TBMM'nin çalışma usul ve esaslarını, iç tüzüğünü belirlemek üzere çıkarılan ilk düzenlemedir."}, {"text": "Men-i Müskirat Kanunu", "isCorrect": false, "rationale": "Savaş dönemi bütçesine katkı sağlamak ve içki kullanımını yasaklamak amacıyla çıkarılan kanundur."}, {"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "TBMM'nin otoritesini korumak ve vatana ihanet eden isyancıları cezalandırmak için çıkarılan ilk sert önlem kanunudur."}], "hint": "Meclisin varlığına ve meşruiyetine kasteden hareketleri vatan hainliği kapsamında değerlendiren yasayı hatırlayınız.", "type": "multiple_choice"}, {"question": "Mondros Mütarekesi'nin ardından İstanbul'da siyasi faaliyetlerini sürdüren Mustafa Kemal Paşa'nın Ali Fethi (Okyar) Bey ile birlikte çıkardığı gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sabah", "isCorrect": false, "rationale": "Mütareke döneminde İstanbul'da yayımlanan ve genellikle Millî Mücadele karşıtı tutumuyla bilinen basın organlarından biridir."}, {"text": "Ceride-i Havadis", "isCorrect": false, "rationale": "İngiliz William Churchill tarafından çıkarılan yarı resmî Osmanlı gazetesidir."}, {"text": "Minber", "isCorrect": true, "rationale": "Mütareke İstanbul'unda halkı bilinçlendirmek ve fikirlerini yaymak amacıyla iki yakın arkadaşın sermayesiyle kurulan gazetedir."}, {"text": "Tercüman-ı Ahvâl", "isCorrect": false, "rationale": "Şinasi ve Agâh Efendi tarafından çıkarılan ilk özel Türkçe gazetedir."}], "hint": "Camiilerde hatiplerin konuşma yaptığı yüksekçe yeri ifade eden kelime ile aynı adı taşıyan gazeteyi arayınız.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sonunda Bulgaristan'ın İttifak Devletleri yanında yer alması nedeniyle kaybettiği toprakları düzenleyen ve Bulgaristan'ın Ege Denizi ile bağlantısını kesen barış antlaşması aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Versailles (Versay) Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda Almanya ile İtilaf Devletleri arasında imzalanan barış antlaşmasıdır."}, {"text": "Neuilly (Nöyi) Antlaşması", "isCorrect": true, "rationale": "Bulgaristan ile müttefikler arasında imzalanarak ülkenin Ege Denizi kıyılarını Yunanistan'a bırakan ağır şartlı antlaşmadır."}, {"text": "St. Germen Antlaşması", "isCorrect": false, "rationale": "Savaş sonrasında Avusturya İmparatorluğu'nun parçalanmasını ve yeni sınırlarını belirleyen antlaşmadır."}, {"text": "Trianon Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonucunda Macaristan ile İtilaf Devletleri arasında imzalanan barış antlaşmasıdır."}], "hint": "Balkan Savaşları'nda elde edilen toprakların bir kısmının kaybedilmesine ve Trakya sınırlarının daralmasına yol açan antlaşmadır.", "type": "multiple_choice"}, {"question": "Bütün bölgesel yararlı cemiyetlerin 'Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti' adı altında tek bir çatı altında birleştirildiği ve Manda-Himaye fikrinin kesin olarak reddedildiği kongre aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sivas Kongresi", "isCorrect": true, "rationale": "4-11 Eylül 1919 tarihlerinde toplanarak Millî Mücadele'yi ulusal çapta tek bir merkezden yönetme kararı alan kongredir."}, {"text": "Alaşehir Kongresi", "isCorrect": false, "rationale": "Yunan işgaline karşı Batı Anadolu'da direnişi organize etmek için toplanan bölgesel nitelikli toplantılardan biridir."}, {"text": "Erzurum Kongresi", "isCorrect": false, "rationale": "Toplanış bakımından bölgesel, aldığı kararlar bakımından milli bir kongre olup bölgesel birleşmeyi sağlamıştır."}, {"text": "Balıkesir Kongresi", "isCorrect": false, "rationale": "Batı Cephesi'ni örgütlemek amacıyla toplanan ancak Mustafa Kemal Paşa'nın liderliğini henüz doğrudan tanımayan bölgesel bir kongredir."}], "hint": "Anadolu'nun her bakımdan en güvenli yeri olarak görülen ve ulusal ölçekte temsilcilerin katıldığı merkezdeki kongredir.", "type": "multiple_choice"}, {"question": "Millî Mücadele sürecinde düzenli ordunun kurulması kararına karşı çıkarak kendi otoritesini korumak amacıyla I. TBMM'ye karşı ayaklanan Kuvayı Milliye lideri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Demirci Mehmet Efe", "isCorrect": true, "rationale": "Güneybatı Anadolu'da direniş gösteren ancak emir altına girmek istemeyerek düzenli ordu kararına karşı isyan eden milis komutanıdır."}, {"text": "Anzavur Ahmet", "isCorrect": false, "rationale": "Marmara bölgesinde Doğrudan İstanbul Hükûmeti tarafından desteklenen Kuvayı İnzibatiye kökenli bir isyancıdır."}, {"text": "Milli Aşiret", "isCorrect": false, "rationale": "Doğu ve Güneydoğu Anadolu bölgesinde Fransız kışkırtmasıyla TBMM'ye karşı ayaklanan bir aşirettir."}, {"text": "Çopur Musa", "isCorrect": false, "rationale": "Afyon bölgesinde Yunan teşviki ve hilafet yanlısı propaganda ile çıkarılan yerel bir ayaklanmanın lideridir."}], "hint": "Ege bölgesinde işgale karşı milis birlikleri yöneten ancak disiplinli ordu yapısına geçişi kabullenmeyen efe liderlerinden biridir.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sırasında Osmanlı ordusunun Britanya birliklerine karşı büyük bir başarı elde ederek General Townshend ve birliklerini esir aldığı muharebe aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kutü'l-Amâre Muharebesi", "isCorrect": true, "rationale": "Irak Cephesi'nde Halil Paşa komutasındaki Osmanlı kuvvetlerinin İngiliz ordusunu kuşatarak büyük bir zafer kazandığı muharebedir."}, {"text": "Kerevizdere Muharebesi", "isCorrect": false, "rationale": "Çanakkale Cephesi'nde Fransız ve İngiliz kuvvetlerine karşı verilen çetin kanat savunmalarından biridir."}, {"text": "Sarıkamış Harekâtı", "isCorrect": false, "rationale": "Kafkas Cephesi'nde Rus iklim ve arazi koşulları nedeniyle büyük kayıpların verildiği taarruz harekâtıdır."}, {"text": "Kirte Muharebeleri", "isCorrect": false, "rationale": "Çanakkale Kara Savaşları sırasında Gelibolu Yarımadası'nda gerçekleşen savunma muharebelerindendir."}], "hint": "Irak Cephesi'nde gerçekleşen ve İngiliz kuvvetlerinin ağır bir mağlubiyet aldığı tarihi zaferi hatırlayınız.", "type": "multiple_choice"}, {"question": "Rumi takvimle 31 Mart 1325 (13 Nisan 1909) tarihinde meşrutiyet düzenine ve İttihat ve Terakki Cemiyetine karşı bir tepki olarak İstanbul'da patlak veren ayaklanma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "31 Mart Vakası", "isCorrect": true, "rationale": "Osmanlı tarihinde mevcut anayasal rejimi değiştirmeye yönelik gerçekleşen ilk gerici (irticai) nitelikli isyandır."}, {"text": "Patrona Halil İsyanı", "isCorrect": false, "rationale": "1730 yılında Lale Devri'ne ve III. Ahmed'in saltanatına son veren ayaklanmadır."}, {"text": "Kabakçı Mustafa İsyanı", "isCorrect": false, "rationale": "1807 yılında Nizam-ı Cedit yeniliklerine karşı çıkıp III. Selim'i tahtından indiren ayaklanmadır."}, {"text": "Bab-ı Ali Baskını", "isCorrect": false, "rationale": "1913 yılında İttihat ve Terakki üyelerinin Hükûmet darbesi yaparak iktidarı tamamen ele geçirdiği askerî olaydır."}], "hint": "Selanik'ten gelen Hareket Ordusu tarafından bastırılan ve II. Abdülhamit'in tahttan indirilmesine yol açan olaydır.", "type": "multiple_choice"}, {"question": "23 Aralık 1876 tarihinde ilan edilen, Batılı devletlerin iç işlerine karışmasını önlemeyi hedefleyen ve Osmanlı Devleti'nin ilk anayasası olan belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tanzimat Fermanı", "isCorrect": false, "rationale": "1839'da ilan edilen, kanun üstünlüğünü ve tüm vatandaşların can, mal, namus güvenliğini devlet güvencesine alan fermandır."}, {"text": "Islahat Fermanı", "isCorrect": false, "rationale": "1856'da Paris Antlaşması öncesinde özellikle gayrimüslim tebaaya ekstra haklar sağlayan mülki düzenlemedir."}, {"text": "Kanun-i Esasi", "isCorrect": true, "rationale": "I. Meşrutiyet ile birlikte yürürlüğe giren ve Osmanlı halkına kısıtlı da olsa ilk kez seçme-seçilme hakkı tanıyan anayasadır."}, {"text": "Teşkilat-ı Esasiye", "isCorrect": false, "rationale": "1921 yılında I. TBMM tarafından kabul edilen yeni Türk devletinin ilk kurucu anayasasıdır."}], "hint": "Tersane (İstanbul) Konferansı toplandığı gün ilan edilen meşrutiyet dönemi anayasasını düşününüz.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde işgalcilerin kendi düşmanı olması ve kendi sınırları içindeki Türk-Müslüman halka sempatik görünmek amacıyla Ankara Hükûmetine maddi yardım sağlayan dış güç aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Almanya", "isCorrect": false, "rationale": "I. Dünya Savaşı'ndan yenik ayrılıp Versay Antlaşması ile ağır kısıtlamalar altına girdiğinden Millî Mücadele'ye yardım edecek durumda değildir."}, {"text": "Fransa", "isCorrect": false, "rationale": "Güney Anadolu topraklarını bizzat işgal eden İtilaf devletlerinden biri olup Ankara Antlaşması'na kadar mücadele edilen taraftır."}, {"text": "Sovyet Rusya", "isCorrect": true, "rationale": "İtilaf Devletleri'nin Doğu Avrupa ve Kafkaslar üzerindeki baskısını kırmak ve dostça ilişkiler kurmak amacıyla mali ve askerî destek veren devlettir."}, {"text": "Bulgaristan", "isCorrect": false, "rationale": "Savaş sonrası kendi iç meseleleri ve toprak kayıplarıyla uğraşan, mali yardım yapabilecek konumda olmayan bir Balkan ülkesidir."}], "hint": "1917 Bolşevik İhtilali sonrası Çarlık rejimini yıkarak İtilaf Devletleri ile bağlarını koparan yönetimi düşününüz.", "type": "multiple_choice"}, {"question": "XVII. yüzyıl Osmanlı ıslahat düşünürlerinden Kâtip Çelebi'nin, devlet adamlarının yetersizliğini eleştirerek bozulan devlet düzenine çözüm yolları aradığı eseri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Keşfü'z-Zünûn", "isCorrect": false, "rationale": "Kâtip Çelebi'ye ait olmakla birlikte, binlerce eseri ve yazarı tanıtan devasa bir biyografik-bibliyografik ansiklopedidir."}, {"text": "Cihannüma", "isCorrect": false, "rationale": "Kâtip Çelebi'nin coğrafya alanında kaleme aldığı dünya coğrafyasını ve haritaları inceleyen eseridir."}, {"text": "Düstûrü'l-Amel li Islahı'l-Halel", "isCorrect": true, "rationale": "Kâtip Çelebi'nin devlet bütçesindeki açıkları, askerî ve idari bozulmaları analiz edip çözüm tavsiyeleri sunduğu risalesidir."}, {"text": "Asafnâme", "isCorrect": false, "rationale": "XVI. yüzyılda Kanuni Sultan Süleyman'ın sadrazamı Lûtfi Paşa tarafından yazılan devlet yönetimi risalesidir."}], "hint": "'Bozuklukların düzeltilmesi için çalışma düsturu' anlamına gelen idari eleştiri risalesini hatırlayınız.", "type": "multiple_choice"}]}, "6": {"unit": 6, "unitTitle": "Lozan Barış Antlaşması", "title": "Tarih Testi", "questions": [{"question": "XVII. yüzyıl Osmanlı ıslahatçılarından Kâtip Çelebi'nin, devlet idaresindeki aksaklıkları ve devlet adamlarının yönetim yetersizliklerini eleştirerek çözüm önerileri sunduğu risale aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Asafnâme", "isCorrect": false, "rationale": "Bu eser Kâtip Çelebi'ye değil, XVI. yüzyıl sadrazamlarından Lûtfî Paşa'ya aittir."}, {"text": "Keşfü'z-zünûn", "isCorrect": false, "rationale": "Bu eser Kâtip Çelebi'nin ünlü bir bibliyografik çalışması olup devlet yönetimi ve idari ıslahat risalesi niteliğinde değildir."}, {"text": "Düstûrü'l-Amel li Islahı'l-Halel", "isCorrect": true, "rationale": "Kâtip Çelebi bu eserinde devlet yapısındaki bozulmaları ve idarecilerin basiretsizliğini eleştirerek çözüm yolları sunmuştur."}, {"text": "Künhü’l-Ahbar", "isCorrect": false, "rationale": "Bu eser Gelibolulu Mustafa Âlî tarafından kaleme alınmış genel bir tarih çalışmasıdır."}], "hint": "Yazarın bozulmaları teşhis edip düzeni iyileştirme amacını taşıyan öğüt ve analiz risalesini düşününüz.", "type": "multiple_choice"}, {"question": "Kanuni Sultan Süleyman döneminde sadrazamlık yapmış olan Lûtfî Paşa'nın, devlet teşkilatındaki bozulmaları ve idari ıslahat gereksinimlerini ele aldığı eser aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Asafnâme", "isCorrect": true, "rationale": "XVI. yüzyılda Sadrazam Lûtfî Paşa tarafından devlet adamlarına öğütler vermek ve idari aksaklıkları eleştirmek amacıyla kaleme alınmıştır."}, {"text": "Cihannüma", "isCorrect": false, "rationale": "Bu eser Kâtip Çelebi tarafından yazılmış coğrafya türünde bir çalışmadır."}, {"text": "Düstûrü'l-Amel li Islahı'l-Halel", "isCorrect": false, "rationale": "XVII. yüzyılda Kâtip Çelebi tarafından kaleme alınan bir ıslahat risalesidir."}, {"text": "Usulü'l-Hikem", "isCorrect": false, "rationale": "Bu eser İbrahim Müteferrika'nın devlet düzenine ve askeri yeniliklere dair yazdığı bir metindir."}], "hint": "Hz. Süleyman'ın ünlü vezirinin adıyla anılan ve devlet adamlarına rehberlik eden metni hatırlayınız.", "type": "multiple_choice"}, {"question": "3 Kasım 1839 tarihinde Gülhane Parkı'nda okunan Tanzimat Fermanı'nın içerdiği temel esaslar düşünüldüğünde, aşağıdakilerden hangisi bu fermanda doğrudan yer alan konulardan biri değildir?", "answerOptions": [{"text": "Vergilerin herkesin gücüne göre düzenlenmesi", "isCorrect": false, "rationale": "Mali adaleti sağlamak adına her vatandaştan gelirine göre vergi alınması ilkesi fermanın temel maddelerindendir."}, {"text": "Devlet yönetiminin ilk kez anayasal parlamenter sisteme geçirilmesi", "isCorrect": true, "rationale": "Anayasal parlamenter düzene geçiş 1876 Kanun-i Esasi ile gerçekleşmiş olup Tanzimat Fermanı anayasa niteliği taşımayan mülki bir ıslahat programıdır."}, {"text": "Mülkiyet hakkı, mal ve namus güvenliğinin teminat altına alınması", "isCorrect": false, "rationale": "Kişi haklarının korunması, can, mal ve namus güvenliğinin sağlanması fermanın öncelikli maddelerindendir."}, {"text": "Askerlik hizmetinin adil kurallara bağlanarak ıslah edilmesi", "isCorrect": false, "rationale": "Askerlik işlerinin belirli kurallara ve süreye bağlanarak bir vatan görevi sayılması hedeflenmiştir."}], "hint": "Osmanlı Devleti'nin ilk yazılı anayasasının ilan edildiği tarih ile bu fermanın ilan tarihi arasındaki farkı dikkate alınız.", "type": "multiple_choice"}, {"question": "III. Selim döneminde devletin gerilemesini önlemek amacıyla devlet adamları ve aydınlardan alınan ıslahat layihalarında (raporlarında) en fazla vurgulanan ve ortak görüş sağlanan alan aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Eğitim ve kültür politikaları", "isCorrect": false, "rationale": "Eğitimdeki yenilikler bu dönemde genel bir sivil eğitim reformundan ziyade askerî okulların açılmasıyla sınırlı kalmıştır."}, {"text": "Askerî sistem", "isCorrect": true, "rationale": "III. Selim dönemi layihalarının ortak paydası, devletin varlığını koruması için öncelikle askerî yapının modernleştirilmesi gerektiği fikridir."}, {"text": "Mali düzenlemeler", "isCorrect": false, "rationale": "Maliye alanındaki tedbirler daha çok yenilenen ordunun ve askerî ocakların finansmanını sağlamak amacına hizmet etmiştir."}, {"text": "Mülki ve idari yapı", "isCorrect": false, "rationale": "İdari konular layihalarda yer bulmakla birlikte acil çözüm aranan birincil odak noktası değildir."}], "hint": "Nizam-ı Cedit ordusunun kurulması ve askerî mühendishanelerin açılması kararlarının arkasındaki temel ihtiyacı düşününüz.", "type": "multiple_choice"}, {"question": "II. Meşrutiyet'in ilan edilmesinden sonra, Rumi 31 Mart 1325 (13 Nisan 1909) tarihinde İttihat ve Terakki Cemiyeti'nin politikalarına bir tepki olarak ortaya çıkan gerici nitelikli ayaklanma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kabakçı Mustafa İsyanı", "isCorrect": false, "rationale": "Bu isyan III. Selim'i tahttan indiren ve Nizam-ı Cedit yeniliklerini sona erdiren XVIII. yüzyıl isyanıdır."}, {"text": "Vaka-i Hayriye", "isCorrect": false, "rationale": "II. Mahmud döneminde Yeniçeri Ocağı'nın kaldırılması olayına verilen isimdir."}, {"text": "31 Mart Vakası", "isCorrect": true, "rationale": "Rumi takvime göre 31 Mart 1325'te meşrutiyet rejimine ve İttihat ve Terakki Cemiyeti'ne tepki olarak başlayan isyandır."}, {"text": "Patrona Halil İsyanı", "isCorrect": false, "rationale": "Bu olay Lale Devri'ni sona erdiren 1730 tarihli ayaklanmadır."}], "hint": "Olayın meydana geldiği Rumi takvim tarihinin adıyla anılan isyanı hatırlayınız.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı devam ederken 1916 yılında İtilaf Devletleri arasında yapılan ve Irak'ın güneyini İngiltere'ye, Suriye kıyıları ile Adana ve Mersin çevresini ise Fransa'ya bırakan gizli antlaşma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Petrograt Protokolü", "isCorrect": false, "rationale": "Bu protokol Çarlık Rusyası'na Doğu Anadolu ve Boğazlar çevresinde pay ayrılmasını öngörür."}, {"text": "Sykes-Picot Antlaşması", "isCorrect": true, "rationale": "1916 yılında İngiltere ve Fransa diplomatları arasında Orta Doğu Osmanlı topraklarının paylaşılması amacıyla imzalanmıştır."}, {"text": "Mc Mahon Antlaşması", "isCorrect": false, "rationale": "İngiltere ile Hicaz Emiri Şerif Hüseyin arasında Arap Yarımadası'na yönelik yapılan gizli görüşmelerdir."}, {"text": "St. Jean de Maurienne Antlaşması", "isCorrect": false, "rationale": "İtalya'ya Batı Anadolu ve İzmir çevresini vaat eden gizli antlaşmadır."}], "hint": "İngiliz ve Fransız diplomatların soyadlarıyla anılan paylaşım antlaşmasını düşününüz.", "type": "multiple_choice"}, {"question": "Milli Mücadele Dönemi'nde Ankara'da yayımlanan, TBMM Hükûmeti'nin yarı resmi yayın organı konumunda bulunan ve 1934 yılından itibaren 'Ulus' adıyla yayın hayatına devam eden gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Minber", "isCorrect": false, "rationale": "Mustafa Kemal Paşa'nın Mondros sonrasında İstanbul'da Ali Fethi Bey ile birlikte çıkardığı gazetedir."}, {"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Bu gazete Sivas Kongresi sonrasında Sivas'ta çıkarılmaya başlanan ilk Milli Mücadele gazetesidir."}, {"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Ankara'da çıkarılan, TBMM Hükûmeti'nin yarı resmi organı işlevini gören ve sonradan Ulus adını alan gazetedir."}, {"text": "Albayrak", "isCorrect": false, "rationale": "Erzurum'da Doğu Anadolu Müdafaa-i Hukuk Cemiyeti bünyesinde yayımlanan yerel gazetedir."}], "hint": "Milletin egemenliğini vurgulayan ve Ankara'daki meclisin sesini duyuran gazete adını hatırlayınız.", "type": "multiple_choice"}, {"question": "Mondros Mütarekesi'nin 'İtilaf Devletleri güvenliklerini tehdit eden bir durum hâlinde stratejik noktaları işgal edebilecektir' hükmünü içeren 7. maddesine dayanarak İngilizler tarafından işgal edilen ilk Osmanlı toprağı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Musul", "isCorrect": true, "rationale": "İngilizler, ateşkesin 7. maddesini gerekçe göstererek mütareke sonrasındaki ilk işgali petrol zengini Musul'da gerçekleştirmişlerdir."}, {"text": "İskenderun", "isCorrect": false, "rationale": "İskenderun stratejik bir liman olarak mütareke sonrası işgal edilmiş olsa da ilk işgal edilen nokta değildir."}, {"text": "Maraş", "isCorrect": false, "rationale": "Maraş önce İngilizler ardından Fransızlarca işgal edilmiş olup ilk işgal bölgesi değildir."}, {"text": "Halep", "isCorrect": false, "rationale": "Halep, ateşkes imzalanmadan hemen önce Suriye cephesi askeri harekâtının hattında yer almaktaydı."}], "hint": "Irak cephesi sınırlarında yer alan ve zengin petrol yataklarına sahip şehri hatırlayınız.", "type": "multiple_choice"}, {"question": "Mondros Mütarekesi sonrasında başlayan işgallere karşı Türk milletinin kendiliğinden oluşturduğu Kuva-yı Milliye hareketi ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "answerOptions": [{"text": "Düzensiz milis kuvvetleri şeklinde bölgesel savunma yapmışlardır.", "isCorrect": false, "rationale": "Düzenli ordu kurulana kadar bölgesel ve gayrinizami harp taktikleriyle mücadele etmişlerdir."}, {"text": "İlk olarak İstanbul ve çevresinde teşkilatlanarak Anadolu'ya yayılmışlardır.", "isCorrect": true, "rationale": "Kuva-yı Milliye İstanbul merkezli değil, işgallere doğrudan maruz kalan Anadolu ve Trakya taşrasında halk tarafından kurulmuştur."}, {"text": "İşgalci güçlere ve azınlık taşkınlıklarına karşı direnç göstermişlerdir.", "isCorrect": false, "rationale": "İşgallere ve yerel tehditlere karşı halkın direnişini organize etmişlerdir."}, {"text": "Türk subayları ve sivil devlet memurlarının yönlendirmeleriyle güçlenmişlerdir.", "isCorrect": false, "rationale": "Subaylar ve mülki idareciler halkın örgütlenmesinde ve direniş güçlerinin bir araya gelmesinde rol oynamışlardır."}], "hint": "Direniş birliklerinin başkentin otoritesinden mi yoksa işgale uğrayan taşra bölgelerinden mi doğduğunu düşününüz.", "type": "multiple_choice"}, {"question": "Osmanlı Mebusan Meclisi'nde 28 Ocak 1920'de kabul edilen, Türk vatanının sınırlarını çizen ve Milli Mücadele'nin temel hedeflerini ortaya koyan tarihî belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Teşkilat-ı Esasiye", "isCorrect": false, "rationale": "1921 yılında TBMM tarafından kabul edilen yeni Türk devletinin ilk anayasasıdır."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında II. Mahmud ile âyanlar arasında imzalanan belge olup Milli Mücadele ile ilgisi yoktur."}, {"text": "Misak-ı Milli", "isCorrect": true, "rationale": "Son Osmanlı Mebusan Meclisi'nde kabul edilen, vatanın bütünlüğünü ve siyasi/ekonomik bağımsızlık şartlarını belirleyen Milli Ant'tır."}, {"text": "Amasya Genelgesi", "isCorrect": false, "rationale": "Milli Mücadele'nin amaç, gerekçe ve yöntemini belirleyen ilk ihtilal bildirisi niteliğindedir."}], "hint": "'Milli Yemin' veya 'Peyman-ı Milli' olarak da bilinen bağımsızlık bildirisini düşününüz.", "type": "multiple_choice"}, {"question": "TBMM'nin açılmasının ardından Anadolu'da çıkan iç ayaklanmaları bastırmak, meclisin otoritesini sağlamak ve iç huzuru tesis etmek amacıyla 29 Nisan 1920'de çıkarılan kanun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "TBMM'ye karşı çıkan isyanları önlemek, vatan hainliğini cezalandırmak ve otoriteyi korumak için 29 Nisan 1920'de kabul edilmiştir."}, {"text": "Men-i Müskirat Kanunu", "isCorrect": false, "rationale": "Savaş döneminde içki imalatı ve tüketimini yasaklamaya yönelik kanundur."}, {"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "TBMM'nin çalışma esaslarını ve toplantı yeter sayısını düzenleyen kanundur."}, {"text": "Takrir-i Sükun Kanunu", "isCorrect": false, "rationale": "Bu kanun 1925 yılında Şeyh Sait İsyanı sonrasında kamu düzenini sağlamak için çıkarılmıştır."}], "hint": "Meclisin varlığına ve vatanın bütünlüğüne karşı gelen eylemleri cezalandıran yasayı hatırlayınız.", "type": "multiple_choice"}, {"question": "10 Ağustos 1920'de imzalanan Sevr Barış Antlaşması'nın hukuken geçersiz sayılması ve hiçbir zaman yürürlüğe girememesinin temel nedeni aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İtilaf Devletleri'nin antlaşma şartlarında uzlaşmaya varamaması", "isCorrect": false, "rationale": "Müttefik devletler metin üzerinde anlaşarak Osmanlı heyetine antlaşmayı imzalatmışlardır."}, {"text": "Osmanlı Mebusan Meclisi tarafından onaylanmaması ve Ankara Hükûmeti'nce reddedilmesi", "isCorrect": true, "rationale": "Bir uluslararası antlaşmanın geçerli olması için parlamentonun onaylaması gerekir; Mebusan Meclisi kapatıldığı için antlaşmayı onaylayacak yetkili organ kalmamış ve antlaşma hukuken ölü doğmuştur."}, {"text": "Yunanistan'ın antlaşmayı imzalamaktan vazgeçmesi", "isCorrect": false, "rationale": "Yunanistan antlaşmayı ilk onaylayan ve elde ettiği toprakları işgale başlayan devletlerden biridir."}, {"text": "San Remo Konferansı'nda antlaşma şartlarının değiştirilmesi", "isCorrect": false, "rationale": "San Remo Konferansı antlaşmanın şartlarının belirlendiği aşamadır; hukuki geçersizliğin nedeni değildir."}], "hint": "Bir uluslararası antlaşmanın anayasal olarak yürürlüğe girmesi için meclis onayından geçmesi gerekliliğini düşününüz.", "type": "multiple_choice"}]}, "7": {"unit": 7, "unitTitle": "Atatürk Dönemi İç Politika", "title": "Tarih Testi", "questions": [{"question": "Osmanlı Devleti'nde 28 Ocak 1920 tarihinde Son Osmanlı Mebusan Meclisi tarafından kabul edilen, millî sınırları çizen ve 'Ahd-ı Milli' olarak da bilinen tarihî belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Sened-i İttifak", "isCorrect": false, "rationale": "Sened-i İttifak, 1808 yılında Sultan II. Mahmut ile ayanlar arasında imzalanan merkezin otoritesini sınırlayan sözleşmedir."}, {"text": "Misak-ı Milli", "isCorrect": true, "rationale": "Misak-ı Milli, Son Osmanlı Mebusan Meclisi tarafından onaylanan ve Milli Mücadele'nin asgari barış şartları ile vatan sınırlarını belirleyen temel belgedir."}, {"text": "Amasya Tamimi", "isCorrect": false, "rationale": "Amasya Tamimi, Haziran 1919'da Mustafa Kemal Paşa ve arkadaşları tarafından yayımlanan ihtilal beyannamesi niteliğindeki genelgedir."}, {"text": "Teşkilat-ı Esasiye Kanunu", "isCorrect": false, "rationale": "Teşkilat-ı Esasiye Kanunu, 1921 yılında I. TBMM tarafından kabul edilen yeni Türk devletinin ilk anayasasıdır."}], "hint": "Türk vatanının asgari barış şartlarını ve ayrılmaz sınırlarını ilan eden millî anddır.", "type": "multiple_choice"}, {"question": "Milli Mücadele Dönemi'nde Ankara'da yayımlanan, TBMM Hükûmetinin gayriresmî yayın organı olarak kabul edilen ve 1934 yılında 'Ulus' adını alan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İrade-i Milliye", "isCorrect": false, "rationale": "İrade-i Milliye gazetesi Ankara'da değil, Sivas Kongresi sonrasında Sivas'ta yayımlanmaya başlayan ilk mücadele gazetesidir."}, {"text": "Peyam-ı Sabah", "isCorrect": false, "rationale": "Peyam-ı Sabah, Milli Mücadele'ye ve Ankara Hükûmetine karşı tutum sergileyen İstanbul merkezli muhalif bir gazetedir."}, {"text": "Minber", "isCorrect": false, "rationale": "Minber gazetesi, Mustafa Kemal Paşa'nın Ali Fethi Bey ile birlikte Mondros sonrasında İstanbul'da çıkardığı gazetedir."}, {"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Hâkimiyet-i Milliye, Ankara'da TBMM'nin görüş ve kararlarını halka duyurmak amacıyla çıkarılmış, daha sonra Ulus adını almış gazetedir."}], "hint": "Ankara'da çıkarılan ve ismi ulusal egemenlik ilkesini doğrudan temsil eden yayındır.", "type": "multiple_choice"}, {"question": "XVII. yüzyıl Osmanlı ıslahatçı düşünürlerinden biri olan ve 'Düstûrü'l-Amel li Islahı'l-Halel' adlı eserinde devlet organlarındaki bozulmaları ve idarecilerin basiretsizliğini eleştiren mütefekkir kimdir?", "answerOptions": [{"text": "Naima", "isCorrect": false, "rationale": "Naima, Osmanlı Devleti'nin ilk resmî vakanüvisi olup XVII. yüzyıl sonu ve XVIII. yüzyıl başında tarih yazıcılığı yapmıştır."}, {"text": "Katip Çelebi", "isCorrect": true, "rationale": "Katip Çelebi, söz konusu eserinde Osmanlı devlet yapısındaki aksaklıkları tespit etmiş ve çözüm yolları önermiştir."}, {"text": "Gelibolulu Mustafa Âlî", "isCorrect": false, "rationale": "Gelibolulu Mustafa Âlî, XVI. yüzyıl sonlarında eser vermiş ve 'Künhü'l-Ahbar' adlı tarih çalışmasıyla tanınmıştır."}, {"text": "Lûtfî Paşa", "isCorrect": false, "rationale": "Lûtfî Paşa, XVII. yüzyılda değil XVI. yüzyılda Kanuni Sultan Süleyman döneminde yaşamış ve 'Asafnâme'yi kaleme almıştır."}], "hint": "Keşfü'z-Zünûn ve Cihannüma gibi eserleriyle de bilinen kâtip sınıfı temsilcisidir.", "type": "multiple_choice"}, {"question": "23 Temmuz 1908'de II. Meşrutiyet'in ilan edilmesinden sonra, İttihat ve Terakki Cemiyetinin politikalarına tepki olarak 13 Nisan 1909'da meydana gelen ayaklanma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Vaka-i Hayriye", "isCorrect": false, "rationale": "Vaka-i Hayriye, 1826 yılında II. Mahmut tarafından Yeniçeri Ocağı'nın kaldırılması olayına verilen isimdir."}, {"text": "Patrona Halil İsyanı", "isCorrect": false, "rationale": "Patrona Halil İsyanı, 1730 yılında Lale Devri'ni ve III. Ahmet saltanatını sona erdiren olaydır."}, {"text": "31 Mart Vakası", "isCorrect": true, "rationale": "Rumi takvimle 31 Mart 1325 tarihine denk gelen bu ayaklanma, İttihat ve Terakki iktidarına ve meşrutiyet rejimine karşı gerçekleşmiştir."}, {"text": "Kabakçı Mustafa İsyanı", "isCorrect": false, "rationale": "Kabakçı Mustafa İsyanı, 1807 yılında III. Selim'i tahttan indiren ve Nizam-ı Cedid ıslahatlarını sonlandıran ayaklanmadır."}], "hint": "Miladi ve Rumi takvim farkından dolayı Rumi ayın son günüyle anılan gerici kalkışmadır.", "type": "multiple_choice"}, {"question": "21-22 Haziran 1919'da yayımlanan ve 'Vatanın bütünlüğü, milletin bağımsızlığı tehlikededir' kararıyla Milli Mücadele'nin gerekçesini ilan eden belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Erzurum Kongresi Kararları", "isCorrect": false, "rationale": "Erzurum Kongresi, Doğu Anadolu'daki cemiyetlerin birleştiği ve bölgesel toplanıp ulusal kararlar alan bir kongredir."}, {"text": "Amasya Genelgesi", "isCorrect": true, "rationale": "Amasya Genelgesi, Cevat Abbas Bey tarafından kaleme alınan ve Kurtuluş Savaşı'nın gerekçe, amaç ve yöntemini sunan bildiridir."}, {"text": "Havza Bildirisi", "isCorrect": false, "rationale": "Havza Bildirisi, Mustafa Kemal Paşa'nın işgallere karşı protesto mitingleri yapılmasını istediği ilk kişisel çağrısıdır."}, {"text": "Sivas Kongresi Beyannamesi", "isCorrect": false, "rationale": "Sivas Kongresi, Amasya Genelgesi'nde alınan karar uyarınca Eylül 1919'da toplanan ulusal temsil kongresidir."}], "hint": "Mustafa Kemal Paşa'nın yaveri Cevat Abbas Bey tarafından kaleme alınan ihtilal çağrısıdır.", "type": "multiple_choice"}, {"question": "4-11 Eylül 1919 tarihleri arasında toplanan Sivas Kongresi'nde bütün milli cemiyetlerin tek çatı altında birleştirildiği organizasyonun adı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Milli Karakol Cemiyeti", "isCorrect": false, "rationale": "Milli Karakol Cemiyeti, İstanbul'dan Anadolu'ya silah, mühimmat ve insan aktarımını sağlayan gizli bir örgüttür."}, {"text": "Trakya-Paşaeli Müdafaa-i Hukuk Cemiyeti", "isCorrect": false, "rationale": "Trakya-Paşaeli Cemiyeti, Trakya bölgesinin işgalini engellemek için kurulan bölgesel bir direniş cemiyetidir."}, {"text": "Redd-i İlhak Cemiyeti", "isCorrect": false, "rationale": "Redd-i İlhak Cemiyeti, İzmir ve çevresinin Yunanistan'a katılmasını önlemek amacıyla kurulan yerel bir cemiyettir."}, {"text": "Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti", "isCorrect": true, "rationale": "Sivas Kongresi'nde dağınık halde bulunan tüm direniş cemiyetleri Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adı altında birleştirilmiştir."}], "hint": "Milli direnişi tek bir merkezden yürütmek amacıyla kurulan kapsayıcı cemiyettir.", "type": "multiple_choice"}, {"question": "TBMM'nin açılmasından sonra Anadolu'da çıkan iç ayaklanmaları bastırmak ve Meclisin otoritesini korumak amacıyla 29 Nisan 1920'de çıkarılan kanun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Men-i Müskirat Kanunu", "isCorrect": false, "rationale": "Men-i Müskirat Kanunu, içki imalatı ve tüketimini yasaklamaya yönelik sosyal ve iktisadi bir düzenlemedir."}, {"text": "Takrir-i Sükun Kanunu", "isCorrect": false, "rationale": "Takrir-i Sükun Kanunu, 1925 yılında Şeyh Sait İsyanı sonrası huzuru sağlamak amacıyla çıkarılmış bir yasadır."}, {"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "Nisab-ı Müzakere Kanunu, TBMM'nin çalışma usul ve esaslarını düzenleyen ilk içtüzük niteliğindeki kanundur."}, {"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "Hıyanet-i Vataniye Kanunu, I. TBMM'nin meşruiyetine karşı çıkan asker kaçakları ve isyancıları yargılamak üzere yürürlüğe konmuştur."}], "hint": "Vatana ihanet suçlamalarını engellemeye ve iç huzuru temin etmeye dönük ilk hukuki adımdır.", "type": "multiple_choice"}, {"question": "Kanuni Sultan Süleyman döneminde sadrazamlık yapmış olan ve Osmanlı devlet yapısındaki bozulmaları ele alan 'Asafnâme' adlı eserin yazarı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Koçi Bey", "isCorrect": false, "rationale": "Koçi Bey, XVII. yüzyılda IV. Murat ve Sultan İbrahim'e sunduğu risaleleri ile tanınmaktadır."}, {"text": "Defterdar Sarı Mehmed Paşa", "isCorrect": false, "rationale": "Defterdar Sarı Mehmed Paşa, XVII. yüzyıl sonlarında 'Zübde-i Vekayi'at' ve devlet yönetimi risaleleri kaleme almıştır."}, {"text": "Lûtfî Paşa", "isCorrect": true, "rationale": "Lûtfî Paşa, başvezirlik tecrübesinden hareketle devlet yönetimi ve idari ıslahatlar hakkında Asafnâme'yi yazmıştır."}, {"text": "Katip Çelebi", "isCorrect": false, "rationale": "Katip Çelebi, XVII. yüzyılda Düstûrü'l-Amel li Islahı'l-Halel adlı eseri kaleme alan bilginimizdir."}], "hint": "XVI. yüzyılda vezirlik yapmış, devlet adamlarına ahlak ve idare tavsiyeleri sunmuş paşadır.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti'nde 23 Aralık 1876 tarihinde ilan edilen, I. Meşrutiyet Dönemi'ni başlatan ve Türk tarihinin ilk yazılı anayasası kabul edilen belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Tanzimat Fermanı", "isCorrect": false, "rationale": "Tanzimat Fermanı (1839), hukukun üstünlüğü ilkesini getiren fakat bir anayasa niteliği taşımayan feryat ve fermandır."}, {"text": "Islahat Fermanı", "isCorrect": false, "rationale": "Islahat Fermanı (1856), gayrimüslimlere verilen hakları genişleten bir reform belgesidir."}, {"text": "Teşkilat-ı Esasiye Kanunu", "isCorrect": false, "rationale": "Teşkilat-ı Esasiye Kanunu, 1921 yılında Ankara'da TBMM tarafından ilan edilen anayasadır."}, {"text": "Kanun-i Esasi", "isCorrect": true, "rationale": "Kanun-i Esasi, 1876'da yürürlüğe giren Osmanlı Devleti ve Türk tarihinin ilk anayasasıdır."}], "hint": "Tersane Konferansı devam ederken ilan edilerek Avrupalıların müdahalesini engellemek istenen metindir.", "type": "multiple_choice"}, {"question": "Sultan II. Mahmut döneminde gerçekleştirilen idari yapı reformları kapsamında atılan en önemli adımlardan biri aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mühendishane-i Berr-i Hümayun matbaasının açılması", "isCorrect": false, "rationale": "Mühendishane matbaası III. Selim döneminde devlet eliyle kurulan ilk matbaalardandır."}, {"text": "Divan-ı Hümayun'un kaldırılarak yerine nezaretlerin kurulması", "isCorrect": true, "rationale": "II. Mahmut, geleneksel Divan-ı Hümayun sistemini ilga ederek batı tarzı bakanlıklar (nezaretler) usulünü getirmiştir."}, {"text": "Nizam-ı Cedid adıyla yeni bir ordunun kurulması", "isCorrect": false, "rationale": "Nizam-ı Cedid ordusu ve yenilikleri III. Selim dönemine ait askerî adımlardır."}, {"text": "Evkaf Vekaletinin kurulması", "isCorrect": false, "rationale": "Evkaf Vekaleti (Bakanlığı) Cumhuriyet döneminde kurulan, II. Mahmut döneminde ise sadece Evkaf Nezareti olarak düzenlenen kurumdur."}], "hint": "Geleneksel karar ve danışma organının yerini bakanlıklar sistemine bıraktığı idari yeniliktir.", "type": "multiple_choice"}, {"question": "15 Mayıs 1919'da İzmir'in işgali üzerine Sultanahmet'te düzenlenen protesto mitinginde yaptığı etkileyici konuşmayla kitleleri direnişe teşvik eden kadın yazarımız kimdir?", "answerOptions": [{"text": "Nezihe Muhiddin", "isCorrect": false, "rationale": "Nezihe Muhiddin, Cumhuriyet’in ilk yıllarında Kadınlar Halk Fırkası ve kadın hakları hareketi öncülerindendir."}, {"text": "Afet İnan", "isCorrect": false, "rationale": "Afet İnan, Cumhuriyet döneminin ilk kadın tarih profesörlerinden olup Mitingler döneminde genç yaştaydı."}, {"text": "Şüküfe Nihal", "isCorrect": false, "rationale": "Şüküfe Nihal da mitinglerde yer almakla birlikte Sultanahmet'teki simgeleşen ana nutku Halide Edip vermiştir."}, {"text": "Halide Edip Adıvar", "isCorrect": true, "rationale": "Halide Edip Adıvar, Sultanahmet Mitingi'nde yaptığı tarihi konuşmayla milli bilincin uyanmasında simgeleşmiştir."}], "hint": "Sultanahmet kürsüsünden işgale karşı halka seslenen ünlü Edebiyatçı ve Onbaşı unvanlı kadın kahramandır.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sırasında Çanakkale Savaşı'nın kazanılmasının uluslararası siyasi dengeler üzerindeki en önemli etkisi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Osmanlı Devleti'nin savaştan en erken çekilen taraf olması", "isCorrect": false, "rationale": "Çanakkale Zaferi Osmanlı Devleti'nin savaştaki ömrünü uzatmış ve savaştan hemen çekilmesini engellemiştir."}, {"text": "Çarlık Rusyası'na yardım ulaştırılamaması sonucu Bolşevik İhtilali'nin gelişmesi ve Çarlığın yıkılması", "isCorrect": true, "rationale": "Çanakkale Boğazı'nın kapatılması İtilaf Devletleri'nin Rusya'ya yardım etmesini engellemiş ve Rusya'da rejim değişikliğine yol açmıştır."}, {"text": "Avusturya-Macaristan İmparatorluğu'nun parçalanmasını önlemesi", "isCorrect": false, "rationale": "Avusturya-Macaristan İmparatorluğu I. Dünya Savaşı sonunda yine dağılmaktan kurtulamamıştır."}, {"text": "ABD'nin savaşa girmesini kesin olarak engellemesi", "isCorrect": false, "rationale": "ABD, Çanakkale Savaşı'ndan sonra 1917 yılında İtilaf Devletleri yanında savaşa dahil olmuştur."}], "hint": "Müttefiklerin Boğazlar üzerinden yardım ulaştıramadığı Doğu Avrupa ülkesinde yaşanan rejim değişikliğidir.", "type": "multiple_choice"}]}, "8": {"unit": 8, "unitTitle": "Atatürk Dönemi Türk Dış Politikası", "title": "Tarih Quiz", "questions": [{"question": "Milli Mücadele Dönemi'nde Ankara'da yayımlanan, TBMM Hükûmetinin gayriresmî yayın organı olarak kabul edilen ve 1934 yılından sonra 'Ulus' adını alan gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi kararları doğrultusunda Sivas'ta yayımlanmaya başlayan ilk gazetedir."}, {"text": "Hâkimiyet-i Milliye", "isCorrect": true, "rationale": "Ankara'da çıkarılan ve Millî Mücadele'nin gayriresmî yayın organı kabul edilen bu gazete 1934'te Ulus adını almıştır."}, {"text": "Minber", "isCorrect": false, "rationale": "Mütareke döneminde İstanbul'da Mustafa Kemal Paşa ve Ali Fethi Bey tarafından çıkarılmıştır."}, {"text": "Albayrak", "isCorrect": false, "rationale": "Doğu Anadolu Müdafaa-i Hukuk Cemiyeti'nin Erzurum'daki yayın organıdır."}], "hint": "Gazetenin adı 'Milli Egemenlik' anlamına gelmektedir.", "type": "multiple_choice"}, {"question": "Osmanlı Mebusan Meclisinde 28 Ocak 1920 tarihinde kabul edilen ve Türk vatanının sınırlarını çizerek tam bağımsızlık esasını belirleyen tarihî belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Amasya Genelgesi", "isCorrect": false, "rationale": "Millî Mücadele'nin amaç, gerekçe ve yönteminin ilkesel olarak açıklandığı ilk ihtilal bildirgesidir."}, {"text": "Sened-i İttifak", "isCorrect": false, "rationale": "1808 yılında merkezi otorite ile ayanlar arasında yapılan yetki sözleşmesidir."}, {"text": "Misak-ı Millî", "isCorrect": true, "rationale": "Son Osmanlı Mebusan Meclisi tarafından onaylanan ve Millî Mücadele'nin asgari barış şartlarını içeren belgedir."}, {"text": "Teşkilat-ı Esasiye", "isCorrect": false, "rationale": "1921 yılında I. TBMM tarafından kabul edilen ilk Türk anayasasıdır."}], "hint": "'Milli And' veya 'Peyman-ı Milli' adlarıyla da bilinir.", "type": "multiple_choice"}, {"question": "Osmanlı Devleti tarihinde ilan edilen ilk anayasa olma özelliğine sahip, 23 Aralık 1876 tarihinde yürürlüğe giren belge aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Teşkilat-ı Esasiye", "isCorrect": false, "rationale": "1921 Anayasası olup Türkiye Devleti'nin ilk anayasasıdır."}, {"text": "Tanzimat Fermanı", "isCorrect": false, "rationale": "1839'da ilan edilen ve hukukun üstünlüğünü getiren ferman olup henüz bir anayasa niteliği taşımaz."}, {"text": "Kanun-i Esasi", "isCorrect": true, "rationale": "Tersane Konferansı toplandığı sırada ilan edilen Osmanlı Devleti'nin ilk anayasasıdır."}, {"text": "Islahat Fermanı", "isCorrect": false, "rationale": "1856'da gayrimüslim haklarını genişletmek amacıyla ilan edilmiş fermandır."}], "hint": "II. Abdülhamit döneminde ilan edilen meşrutiyet düzeninin temel metnidir.", "type": "multiple_choice"}, {"question": "TBMM Hükûmetinin kurulmasının ardından artan iç ayaklanmaları bastırmak ve iç huzuru sağlamak amacıyla 29 Nisan 1920 tarihinde çıkarılan kanun aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Men-i Müskirat Kanunu", "isCorrect": false, "rationale": "İçki üretim ve tüketimini yasaklamaya yönelik ekonomik/sosyal bir kanundur."}, {"text": "Nisab-ı Müzakere Kanunu", "isCorrect": false, "rationale": "Meclisin çalışma ve toplanma usullerini düzenleyen iç tüzük niteliğinde bir kanundur."}, {"text": "Hıyanet-i Vataniye Kanunu", "isCorrect": true, "rationale": "Ayaklanmaları önlemek ve meclisin otoritesini tesis etmek amacıyla ilk çıkarılan kanunlardandır."}, {"text": "Takrir-i Sükun Kanunu", "isCorrect": false, "rationale": "1925 yılında Şeyh Sait İsyanı sonrasında huzuru sağlamak amacıyla çıkarılmıştır."}], "hint": "Vatana ihanet suçlamalarını ve asker kaçaklarını yargılamayı hedefler.", "type": "multiple_choice"}, {"question": "I. Dünya Savaşı sonrasında Almanya'nın sömürgelerini kaybetmesine ve ağır askerî ile ekonomik yükümlülükler altına girmesine yol açan antlaşma aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Trianon Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda Macaristan ile imzalanan barış antlaşmasıdır."}, {"text": "Neuilly (Nöyi) Barış Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda Bulgaristan ile imzalanan antlaşmadır."}, {"text": "Versailles (Versay) Barış Antlaşması", "isCorrect": true, "rationale": "İtilaf Devletleri ile Almanya arasında imzalanan ve ağır yaptırımlar içeren antlaşmadır."}, {"text": "St. Germain Barış Antlaşması", "isCorrect": false, "rationale": "I. Dünya Savaşı sonunda Avusturya ile imzalanan antlaşmadır."}], "hint": "Fransa'da imzalanan ve İkinci Dünya Savaşı'nın sebeplerinden sayılan antlaşmadır.", "type": "multiple_choice"}, {"question": "XVII. yüzyıl ıslahatçı düşünürlerinden biri olan ve 'Düstûrü'l-Amel li Islahı'l-Halel' adlı eserinde devlet adamlarının basiretsizliğini eleştirerek çözüm yolları sunan bilgin aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Evliya Çelebi", "isCorrect": false, "rationale": "Gezip gördüğü yerleri Seyahatname adlı eserinde toplayan ünlü seyyahtır."}, {"text": "Naima", "isCorrect": false, "rationale": "Osmanlı Devleti'nin ilk resmi vakanüvisi (tarihçisi) olarak görev yapmıştır."}, {"text": "Koçi Bey", "isCorrect": false, "rationale": "IV. Murad ve Sultan İbrahim'e devletin bozulma nedenlerini açıklayan risaleler sunmuştur."}, {"text": "Katip Çelebi", "isCorrect": true, "rationale": "Osmanlı idari ve sosyal yapısındaki bozulmaları eleştirerek çözüm yolları öneren XVII. yüzyıl düşünürdür."}], "hint": "'Keşfü'z-zünûn' ve 'Cihannüma' eserleriyle de tanınan Osmanlı bilginidir.", "type": "multiple_choice"}, {"question": "İzmir'in işgalinden sonra Ege bölgesinde Yunanistan'a katılımı kabul etmeyerek direniş gösteren halk ve aydınlar tarafından kurulan cemiyet aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Kilikyalılar Cemiyeti", "isCorrect": false, "rationale": "Çukurova bölgesini Fransız ve Ermeni işgallerine karşı savunmak amacıyla kurulmuştur."}, {"text": "Doğu Anadolu Müdafaa-i Hukuk Cemiyeti", "isCorrect": false, "rationale": "Doğu vilayetlerinde Ermeni devleti kurulmasını engellemek amacıyla teşkilatlanmıştır."}, {"text": "Trakya-Paşaeli Cemiyeti", "isCorrect": false, "rationale": "Trakya bölgesini Yunan işgaline karşı savunmayı hedefleyen milli cemiyettir."}, {"text": "Redd-i İlhak Cemiyeti", "isCorrect": true, "rationale": "İzmir ve çevresinin Yunanistan'a bağlanmasını engellemek amacıyla kurulan direniş örgütüdür."}], "hint": "Cemiyetin adı doğrudan 'toprakların başka ülkeye katılmasına karşı çıkma' anlamı taşır.", "type": "multiple_choice"}, {"question": "Mondros Mütarekesi sonrasında İstanbul'da Mustafa Kemal Paşa ile Ali Fethi (Okyar) Bey'in birlikte çıkardıkları gazete aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Hâkimiyet-i Milliye", "isCorrect": false, "rationale": "TBMM'nin açılmasından sonra Ankara'da çıkarılmaya başlanan yayın organıdır."}, {"text": "Tasvir-i Efkâr", "isCorrect": false, "rationale": "Şinasi tarafından Tanzimat Dönemi'nde çıkarılmaya başlanan gazetedir."}, {"text": "İrade-i Milliye", "isCorrect": false, "rationale": "Sivas Kongresi'nden sonra kamuoyunu bilgilendirmek amacıyla Sivas'ta çıkarılmıştır."}, {"text": "Minber", "isCorrect": true, "rationale": "Mustafa Kemal Paşa ve Ali Fethi Bey'in Mütareke döneminde İstanbul'da çıkardıkları fikri ve siyasi gazetedir."}], "hint": "Mustafa Kemal'in İstanbul'daki siyasi mücadele döneminde çıkardığı yayındır.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi I. TBMM'nin taşıdığı temel niteliklerden biri değildir?", "answerOptions": [{"text": "Meclisin sürekliliği ilkesini benimsemesi", "isCorrect": false, "rationale": "Milli mücadeleyi yürütmek adına kesintisiz çalışma esasına dayanmıştır."}, {"text": "Meclis hükûmeti sistemini benimsemesi", "isCorrect": false, "rationale": "Ayrı bir başbakanlık olmayıp Meclis Başkanı aynı zamanda hükûmet başkanı olarak görev yapmıştır."}, {"text": "İstanbul Hükûmeti ile tam uyum ve koordinasyon içinde çalışması", "isCorrect": true, "rationale": "I. TBMM, İstanbul Hükûmeti'nin teslimiyetçi politikalarına karşı bağımsız hareket etmiş ve onunla uyum içinde çalışmamıştır."}, {"text": "Olağanüstü yetkilere sahip olması", "isCorrect": false, "rationale": "Savaş koşulları nedeniyle yasama, yürütme ve yargı yetkilerini bünyesinde toplamıştır."}], "hint": "Ankara'daki meclisin İstanbul'daki işbirlikçi ve teslimiyetçi tutuma karşı yaklaşımını değerlendirin.", "type": "multiple_choice"}, {"question": "XIX. yüzyılda Osmanlı Devleti'ni dağılmaktan kurtarmak amacıyla ortaya atılan; din, dil ve ırk farkı gözetmeksizin tüm unsurları eşit kabul eden ilk siyasi fikir akımı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Osmanlıcılık", "isCorrect": true, "rationale": "Tanzimat ve Meşrutiyet dönemlerinde imparatorluğu bir arada tutmak için geliştirilen ilk resmi fikir akımıdır."}, {"text": "Türkçülük", "isCorrect": false, "rationale": "Türkleri milli bir bilinç altında toplamayı hedefleyen daha sonraki fikir akımıdır."}, {"text": "İslamcılık", "isCorrect": false, "rationale": "II. Abdülhamit döneminde Müslüman tebaayı halife etrafında birleştirmeyi amaçlayan akımdır."}, {"text": "Adem-i Merkeziyetçilik", "isCorrect": false, "rationale": "Prens Sabahattin tarafından savunulan yerinden yönetim fikridir."}], "hint": "Genç Osmanlılar tarafından savunulan ve tüm Osmanlı uyruklarını kapsayan yaklaşımdır.", "type": "multiple_choice"}, {"question": "Millî Mücadele Dönemi'nde işgalci güçlerin kendi ortak düşmanı olması sebebiyle TBMM Hükûmetine mali ve askerî yardım sağlayan ülke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Almanya", "isCorrect": false, "rationale": "I. Dünya Savaşı'ndan yenik çıkmış ve ağır antlaşma şartları altında ezilmiştir."}, {"text": "Arnavutluk", "isCorrect": false, "rationale": "Kendi bağımsızlık ve iç sorunlarıyla uğraşan Balkan ülkesidir."}, {"text": "Bulgaristan", "isCorrect": false, "rationale": "Savaş sonrası sınırlandırılmış ve yardım ulaştıracak durumda bulunmamıştır."}, {"text": "Sovyet Rusya", "isCorrect": true, "rationale": "İtilaf Devletleri'ne karşı Ankara Hükûmeti ile iş birliği yaparak mali ve askeri destekte bulunmuştur."}], "hint": "1917 devrimi sonrası İtilaf Devletleri ile ilişkileri kesilen kuzey komşumuz.", "type": "multiple_choice"}, {"question": "III. Selim Dönemi'nde (Nizam-ı Cedid) hazırlanan ıslahat layihalarında (raporlarında) yenilik yapılması gerektiği konusunda birleşilen öncelikli alan aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Mali", "isCorrect": false, "rationale": "İrad-ı Cedid hazinesi kurulmuş fakat bu yeni ordunun masraflarını karşılamak amacını taşımıştır."}, {"text": "İdari", "isCorrect": false, "rationale": "İdari reformlar yapılsa da layihaların merkezinde ordunun durumu yer almaktaydı."}, {"text": "Askerî", "isCorrect": true, "rationale": "III. Selim dönemi raporları ve yapılan düzenlemeler öncelikli olarak ordunun ıslahı ve Nizam-ı Cedid'in kurulmasına odaklanmıştır."}, {"text": "Kültürel", "isCorrect": false, "rationale": "Matbaa kullanımı ve tercüme faaliyetleri artırılmış olsa da temel odak askerliktir."}], "hint": "Nizam-ı Cedid ordusunun kurulması bu dönemin en belirgin özelliğidir.", "type": "multiple_choice"}]}}, "osmanlica-1": {"1": {"unit": 1, "unitTitle": "Osmanlı Türkçesi Alfabesi", "title": "Osmanlı Türkçesi Quiz", "questions": [{"question": "Batı Türkçesinin 13. yüzyıldan İstanbul'un fethine (15. yüzyıl ortası) kadar süren ilk dönemine ne ad verilir?", "answerOptions": [{"text": "Yeni Osmanlı Türkçesi", "isCorrect": false, "rationale": "Yeni Osmanlı Türkçesi veya Türkiye Türkçesi dönemi Batı Türkçesinin üçüncü ve son aşamasını temsil eder."}, {"text": "Klâsik Osmanlı Türkçesi", "isCorrect": false, "rationale": "Klâsik dönem, İstanbul'un fethinden (15. yüzyıl ortası) 19. yüzyıla kadar süren ikinci ana evreyi ifade eder."}, {"text": "Eski Anadolu Türkçesi", "isCorrect": true, "rationale": "Anadolu Selçukluları, Beylikler Çağı ve Osmanlı'nın İstanbul'un fethine kadar olan ilk evresi Eski Anadolu Türkçesi (Eski Osmanlıca) olarak adlandırılır."}, {"text": "Çağatay Türkçesi", "isCorrect": false, "rationale": "Çağatay Türkçesi Batı Türkçesi koluna değil, Doğu Türkçesi gelişme alanına aittir."}], "hint": "Bu dönem Anadolu Selçukluları ve Beylikler Çağı'nı kapsayan kuruluş evresidir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesi alfabesi 28 harfli Arap alfabesine dayanmakla birlikte Türklerin ve İranlıların katkılarıyla genişletilmiştir. Aşağıdakilerden hangisi bu ilave edilen harflerden biridir?", "answerOptions": [{"text": "pe (پ)", "isCorrect": true, "rationale": "Arap alfabesinde bulunmayan 'p' sesi için Türk ve İranlıların ilavesiyle 'pe' harfi alfabeye dahil edilmiştir."}, {"text": "re (ر)", "isCorrect": false, "rationale": "Re harfi Arap alfabesinin temel harflerinden biridir."}, {"text": "te (ت)", "isCorrect": false, "rationale": "Te harfi asıl Arap alfabesinin 28 harfi arasında zaten yer almaktadır."}, {"text": "fe (ف)", "isCorrect": false, "rationale": "Fe harfi Arap alfabesinin asıl kadrosunda bulunan bir ünsüzdür."}], "hint": "Arapça kökenli kelimelerde bulunmayan ve altına üç nokta konularak türetilen harfi hatırlayınız.", "type": "multiple_choice"}, {"question": "Harfin üstüne konulan ve ilgili harfi /o/, /ö/, /u/ veya /ü/ sesleriyle okutmaya yarayan hareke aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Esre (kesre)", "isCorrect": false, "rationale": "Esre işareti harfin altına konur ve düz-dar ünlüleri (/ı/, /i/) ifade eder."}, {"text": "Ötre (damme)", "isCorrect": true, "rationale": "Ötre işareti harfin üstüne konur ve yuvarlak ünlü seslerini (/o/, /ö/, /u/, /ü/) temsil eder."}, {"text": "Cezm (sükûn)", "isCorrect": false, "rationale": "Cezm işareti ünlü okutmaz, harfi harekesiz yani ünsüz (sakin) duruma getirir."}, {"text": "Üstün (fetha)", "isCorrect": false, "rationale": "Üstün işareti harfin üstüne konarak düz-geniş ünlüleri (/a/, /e/) okutur."}], "hint": "Arapça ismi 'damme' olan ve yuvarlak ünlülere karşılık gelen harekeyi düşününüz.", "type": "multiple_choice"}, {"question": "Kelime sonundaki harfi \"ın / in\" sesleriyle okutmayı sağlayan hareke/tenvin işareti aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Ötreli tenvin", "isCorrect": false, "rationale": "Ötreli tenvin harfin üstüne konur ve 'un/ün' seslerini üretir."}, {"text": "Esreli tenvin", "isCorrect": true, "rationale": "Kelime sonundaki harfin altına çift çizgi şeklinde konan esreli tenvin, kelime sonunu 'ın/in' sesleriyle okutur."}, {"text": "Şedde", "isCorrect": false, "rationale": "Şedde tenvin türü değildir; ünsüzün ikizleşmesini (iki defa okunmasını) sağlar."}, {"text": "Üstünlü tenvin", "isCorrect": false, "rationale": "Üstünlü tenvin harfin üstüne konur ve 'an/en' sesleriyle okunmasını sağlar."}], "hint": "Tek başına /ı/i/ sesi veren esre harekesinin kelime sonunda çift yazılmış hâlini değerlendiriniz.", "type": "multiple_choice"}, {"question": "Elif harfinin üzerine konularak kelimeye uzun \"â\" sesi kazandıran ve Türkçe kelimelerin başında da (örneğin \"ak\" kelimesinde) kullanılan yardımcı işaret aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Şedde", "isCorrect": false, "rationale": "Şedde harfi uzatmaya değil, aynı ünsüzü iki kez okutmaya yarar."}, {"text": "Med", "isCorrect": true, "rationale": "Med işareti elif üzerine konarak harfin uzun 'â' şeklinde okunmasını sağlar ve Türkçe ilk sesi 'a' olan kelimelerde de kullanılır."}, {"text": "Tenvin", "isCorrect": false, "rationale": "Tenvin kelime sonlarına genizcil 'n' sesi getiren çift harekedir."}, {"text": "Cezm", "isCorrect": false, "rationale": "Cezm uzatma yapmaz, harfin sesini keserek ünsüz olarak kalmasını sağlar."}], "hint": "Dalgalı bir çizgi şeklinde elifin üzerine yerleştirilen uzatma işaretini hatırla.", "type": "multiple_choice"}, {"question": "Arapça kelimelerde yan yana gelen aynı ünsüzü tek harfle yazıp iki defa okutmak için kullanılan yardımcı işaret aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Med", "isCorrect": false, "rationale": "Med işareti sesleri ikizleştirmek için değil, ünlüyü uzatmak için kullanılır."}, {"text": "Tenvin", "isCorrect": false, "rationale": "Tenvin kelime sonuna /n/ sesi ekleyen hareke biçimidir."}, {"text": "Cezm", "isCorrect": false, "rationale": "Cezm harfi ikizleştirmez, sadece durağan/sakin okutur."}, {"text": "Şedde", "isCorrect": true, "rationale": "Şedde işareti üzerine konduğu harfin çift ünsüz (ikiz) olarak okunmasını sağlar."}], "hint": "'Cennet' veya 'millet' gibi kelimelerde aynı ünsüzün tekrarlanmasını sağlayan işareti düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdaki harflerden hangisi kendisinden sonra gelen harfle bitişmeyen (birleşmeyen) harflerden biridir?", "answerOptions": [{"text": "ز (ze)", "isCorrect": true, "rationale": "Elif, dal, zel, re, ze, je, vav ve hâ-i resmiye kendinden sonraki harflerle bitişmeyen gruptadır."}, {"text": "ب (be)", "isCorrect": false, "rationale": "Be harfi hem kendinden önceki hem de kendinden sonraki harfle bitişen bir harftir."}, {"text": "س (sin)", "isCorrect": false, "rationale": "Sin harfi hem sağındaki hem de solundaki harfe bağlanabilir."}, {"text": "ف (fe)", "isCorrect": false, "rationale": "Fe harfi iki tarafa da bitişme özelliğine sahiptir."}], "hint": "Sadece sağındaki harfe bağlanan ve soluna çizgi uzatmayan 8 temel harften birini seçiniz.", "type": "multiple_choice"}, {"question": "Aşağıdaki harflerden hangisi hem kendisinden önceki hem de kendisinden sonraki harfle birleşebilen (bitişen) harflerdendir?", "answerOptions": [{"text": "د (dal)", "isCorrect": false, "rationale": "Dal harfi kendinden sonra gelen harfe bitiştirilmez."}, {"text": "ش (şin)", "isCorrect": true, "rationale": "Şin harfi kelime başında, ortasında ve sonunda formu değişerek iki taraftaki harflerle de bitişir."}, {"text": "ر (re)", "isCorrect": false, "rationale": "Re harfi solundaki (kendisinden sonraki) harfle birleşmez."}, {"text": "و (vav)", "isCorrect": false, "rationale": "Vav harfi kendisinden sonra gelen harfe bağlanmayan gruptadır."}], "hint": "Kendinden sonraki ile birleşmeyen 8 harf (ا, د, ذ, ر, ز, ژ, و, ه) dışındaki bir seçeneğe odaklanın.", "type": "multiple_choice"}, {"question": "Şekilce birbirine benzeyen harf grupları düşünüldüğünde, gövde yapısı aynı olup altındaki üç nokta ile \"ج\" (cim), \"ح\" (ha) ve \"خ\" (hı) harflerinden ayrılan harf hangisidir?", "answerOptions": [{"text": "şin (ش)", "isCorrect": false, "rationale": "Şin harfi üç noktalıdır fakat 'sin' ailesine dahil bir harftir."}, {"text": "pe (پ)", "isCorrect": false, "rationale": "Pe harfi üç noktalıdır ancak 'be' ailesine (yayvan gövdeli harflere) aittir."}, {"text": "çe (چ)", "isCorrect": true, "rationale": "Cim ailesinde yer alan çe harfi, karın kısmına koyulan üç nokta ile diğer kardeş harflerden ayrılır."}, {"text": "se (ث)", "isCorrect": false, "rationale": "Peltek se harfi üç noktalıdır ancak 'be-te' grubuyla aynı gövde şekline sahiptir."}], "hint": "Cim harfinin ortasında tek nokta varken, bu harfin içinde/altında üç nokta bulunur.", "type": "multiple_choice"}, {"question": "Cezm (sakin/sükûn) işareti ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "answerOptions": [{"text": "Harfin altına konur ve harfi /ı/ veya /i/ sesleriyle okutur.", "isCorrect": false, "rationale": "Harfin altına konup /ı/i/ sesi veren işaret esre (kesre) harekesidir."}, {"text": "Kelimenin son harfine konarak /an/ veya /en/ sesi ekler.", "isCorrect": false, "rationale": "Kelime sonuna /an/en/ sesi katan işaret üstünlü tenvindir."}, {"text": "Harfin üzerine konarak aynı ünsüzün iki kez tekrarlanmasını sağlar.", "isCorrect": false, "rationale": "Ünsüzü ikizleştiren işaret şeddendir."}, {"text": "Harfin üstüne konur ve üzerine geldiği harfi ünsüz (sakin) okutur.", "isCorrect": true, "rationale": "Cezm işareti bir harfin üzerinde yer alarak o harfin ünlü almadan duraklayıp ünsüz sesiyle kapanmasını sağlar."}], "hint": "Kelime içinde kapalı hecelerin sonundaki ünsüzün Harekeksiz (sakin) okunduğunu belirten simgedir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde kelime sonunda ünlü (e/a) yerine kullanıldığında kendisinden sonraki ekle bitişmeyen ve \"hâ-i resmiye\" olarak adlandırılan harf aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ك (kef)", "isCorrect": false, "rationale": "Kef harfi ünsüz işaretler; okutucu hâ-i resmiye adını almaz."}, {"text": "ت (te)", "isCorrect": false, "rationale": "Te harfi asli ünsüzdür, okutucu he ile karıştırılmamalıdır."}, {"text": "ه (he)", "isCorrect": true, "rationale": "Kelime sonunda okutucu/ünlü görevi üstlenen 'he' harfine hâ-i resmiye denir ve bu işlevdeyken kendinden sonrakine bitişmez."}, {"text": "ى (ye)", "isCorrect": false, "rationale": "Ye harfi dar ünlüler için kullanılır ve kelime sonunda sonrakiyle bitişme kuralı farklı değerlendirilir."}], "hint": "Şekilce 'he' olup Türkçe kelimelerin sonunda e/a ünlüsünü göstermeye yarayan harfi hatırlayınız.", "type": "multiple_choice"}, {"question": "Türkçeye özgü genizsil \"n\" sesini (kâf-ı nûnî / sağır kef) göstermek için Osmanlı Türkçesi alfabesinde kullanılan özel harf aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ق", "isCorrect": false, "rationale": "Kaf (ق) harfi kalın 'k' seslerini ifade etmek için kullanılır."}, {"text": "ڭ", "isCorrect": true, "rationale": "Üzerinde üç nokta bulunan kef biçimindeki 'kâf-ı nûnî' (ڭ) harfi genizden gelen 'n' sesini gösterir."}, {"text": "گ", "isCorrect": false, "rationale": "Üzerinde çizgi bulunan 'kâf-ı fârisî' (گ) 'g' ve 'ğ' sesleri için kullanılır."}, {"text": "ك", "isCorrect": false, "rationale": "Yalın kef (ك) öncelikle 'k' sesini temsil eder."}], "hint": "Kef harfinin üzerine üç nokta konularak oluşturulan ve genizsel n sesini veren işareti arayınız.", "type": "multiple_choice"}]}, "2": {"unit": 2, "unitTitle": "Türkçe Ünlü ve Ünsüzlerin Yazılışı", "title": "Osmanlı Türkçesi Testi", "questions": [{"question": "Osmanlı Türkçesinde Türkçe kelimelerin yazımında, bugünkü alfabede tek sesle gösterilen bazı ünsüzlerin kalın ve ince hâlleri için ayrı harfler kullanılır. Buna göre \"t\" ünsüzünün kalın ve ince hâlleri aşağıdakilerin hangisinde sırasıyla doğru verilmiştir?", "answerOptions": [{"text": "ظ - ز", "isCorrect": false, "rationale": "Bu harf çifti 'z' ünsüzünün kalın (zı) ve ince (ze) biçimlerini karşılar."}, {"text": "ق - ك", "isCorrect": false, "rationale": "Bu harf çifti 'k' ünsüzünün kalın (kaf) ve ince (kef) karşılıklarıdır."}, {"text": "ط - ت", "isCorrect": true, "rationale": "Osmanlı Türkçesi alfabesinde 't' sesinin kalın şekli tı (ط), ince şekli ise te (ت) harfi ile temsil edilir."}, {"text": "ص - س", "isCorrect": false, "rationale": "Bu harf çifti 's' ünsüzünün kalın (sad) ve ince (sin) şekillerini göstermek için kullanılır."}], "hint": "Kelime başındaki 'tat' ve 'ter' kelimelerinin ilk harflerini göz önüne getiriniz.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin başındaki \"s\" ünsüzü yazılırken, kendisinden sonra gelen ünlünün kalın veya ince oluşuna dikkat edilir. Buna göre, birinci hecesinde kalın ünlü bulunan bir Türkçe kelimenin başındaki \"s\" sesi aşağıdaki harflerden hangisiyle gösterilir?", "answerOptions": [{"text": "ث", "isCorrect": false, "rationale": "Peltek se harfi yalnızca Arapça kökenli kelimelerin yazımında yer alır, Türkçe kelimelerin kökünde bulunmaz."}, {"text": "س", "isCorrect": false, "rationale": "Sin harfi, Türkçe kelimelerde ince ünlülerle birlikte veya kelime içinde ince sırayı belirtmek için kullanılır."}, {"text": "ظ", "isCorrect": false, "rationale": "Zı harfi 'z' sesinin kalın karşılığı olup 's' sesini temsil etmez."}, {"text": "ص", "isCorrect": true, "rationale": "Türkçe kelime başında 's' sesinden sonra kalın ünlü gelirse, kalın sırayı göstermek üzere sad (ص) harfi tercih edilir."}], "hint": "'Sat' veya 'sar' kelimelerinin yazımında kullanılan ilk harfi hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde genizsi \"n\" (kâf-ı nûnî / sağır kef) sesini göstermek için kullanılan temel harf aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ن", "isCorrect": false, "rationale": "Nun harfi diş sesi olan standart 'n' ünsüzünü göstermede kullanılır."}, {"text": "غ", "isCorrect": false, "rationale": "Gayn harfi kalın 'ğ' sesini temsil eden bir ünsüzdür."}, {"text": "ق", "isCorrect": false, "rationale": "Kaf harfi kalın 'k' sesini gösteren bir ünsüz harftir."}, {"text": "ڭ / ك", "isCorrect": true, "rationale": "Genizsi 'n' sesi Osmanlı Türkçesi alfabesinde kef (ك / ڭ) harfiyle gösterilir ve sağır kef olarak adlandırılır."}], "hint": "Bu harf yazılış biçimi bakımından 'kef' ile aynı tabana sahiptir.", "type": "multiple_choice"}, {"question": "Ders kitabındaki bilgilere göre, aşağıdaki kelimelerden hangisinin yazımında genizsi \"n\" (kâf-ı nûnî / sağır kef) harfi kullanılır?", "answerOptions": [{"text": "dün", "isCorrect": false, "rationale": "Kelimedeki 'n' sesi diş sesi 'n' kategorisinde yer aldığı için nun (ن) harfi tercih edilir."}, {"text": "göz", "isCorrect": false, "rationale": "'Göz' kelimesinde genizsi n sesi yoktur; گوز şeklinde yazılır."}, {"text": "gün", "isCorrect": false, "rationale": "Bu kelimedeki 'n' sesi genizsi olmayıp standart diş sesi olan nun (ن) harfi ile yazılır."}, {"text": "deniz", "isCorrect": true, "rationale": "Metindeki örneklere göre 'deniz' kelimesi Osmanlı Türkçesinde 'دكز' şeklinde sağır kef ile yazılan kelimeler arasındadır."}], "hint": "İçinde 'kef' görünümünde sağır n sesi barındıran 'ön', 'son' ve 'beniz' gibi örneklere benzer bir sözcüktür.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin başında bulunan \"a\" ünlüsü Osmanlı Türkçesi yazımında genel olarak nasıl gösterilir?", "answerOptions": [{"text": "Elif ve Ye (اي)", "isCorrect": false, "rationale": "Elif ve ye harfleri kelime başında 'ı' ve 'i' ünlülerini gösterir."}, {"text": "Elif ve Vav (او)", "isCorrect": false, "rationale": "Elif ve vav birlikteliği kelime başında yuvarlak ünlüleri (o, ö, u, ü) karşılamak içindir."}, {"text": "Hemzeli elif (أ)", "isCorrect": false, "rationale": "Hemzeli elif kelime başında genellikle 'e' sesini veya ince yuvarlak ünlüleri ayırt etmek için kullanılır."}, {"text": "Medli elif (آ)", "isCorrect": true, "rationale": "Türkçe kelimelerin başında 'a' ünlüsü 'at', 'aş', 'az' örneklerinde olduğu gibi medli elif (آ) ile yazılır."}], "hint": "'At', 'aş' ve 'az' gibi kelimelerin ilk harfindeki işareti düşününüz.", "type": "multiple_choice"}, {"question": "Bazı Türkçe kelimelerde günümüzde \"e\" olarak kullanılan ses, Osmanlı Türkçesi metinlerinde tarihî olarak \"ى\" (ye) harfi ile gösterilmiştir. Aşağıdakilerden hangisi bu duruma örnek gösterilebilecek kelimelerden biridir?", "answerOptions": [{"text": "emek", "isCorrect": false, "rationale": "Bu kelimenin ortasındaki 'e' sesi yazılmayıp 'امك' şeklinde gösterilir."}, {"text": "gerek", "isCorrect": false, "rationale": "Kelimedeki 'e' ünlüleri kelime içinde yazılmayarak 'كرك' biçiminde ifade edilir."}, {"text": "vermek", "isCorrect": true, "rationale": "'Vermek' kelimesi metindeki özel listede belirtildiği üzere tarihî yazımda 'ويرمك' şeklinde ye (ى) harfi barındırarak yazılan kelimelerdendir."}, {"text": "bebek", "isCorrect": false, "rationale": "Bu kelimede 'e' sesleri kelime içinde harfle gösterilmeyip 'ببك' şeklinde yazılır."}], "hint": "'Demek', 'gece', 'elçi' ve 'etmek' gibi kökünde 'ye' harfi muhafaza edilen fiillerden birini arayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin başında yer alan \"ı\" ve \"i\" ünlüleri Osmanlı Türkçesinde aşağıdaki harf birleşimlerinden hangisiyle gösterilir?", "answerOptions": [{"text": "Elif ve Ye (اي)", "isCorrect": true, "rationale": "'İp', 'it', 'iz' ve 'iş' örneklerinde görüldüğü gibi kelime başındaki 'ı' ve 'i' sesleri elif + ye (اي) harfleriyle yazılır."}, {"text": "Elif ve Güzel He (اه)", "isCorrect": false, "rationale": "Kelime başında bu birleşim Türkçe düz dar ünlüler için standart bir gösterim değildir."}, {"text": "Elif ve Vav (او)", "isCorrect": false, "rationale": "Elif ve vav harfleri kelime başında yuvarlak sesleri (o, ö, u, ü) temsil eder."}, {"text": "Medli Elif ve Ye (آى)", "isCorrect": false, "rationale": "Kelime başında düz dar ünlüleri gösterirken med işareti kullanılmaz."}], "hint": "'İş' ve 'ip' kelimelerinin ilk iki harfinin dizilimini hatıralayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin başında bulunan \"o, ö, u, ü\" yuvarlak ünlülerini göstermek için aşağıdaki birleşimlerden hangisi kullanılır?", "answerOptions": [{"text": "Elif ve Ye (اي)", "isCorrect": false, "rationale": "Bu birleşim kelime başındaki düz dar ünlüleri (ı, i) gösterir."}, {"text": "Sadece Vav (و)", "isCorrect": false, "rationale": "Kelime başında ünlünün yazılabilmesi için destekleyici elif harfine ihtiyaç duyulur."}, {"text": "Medli Elif (آ)", "isCorrect": false, "rationale": "Medli elif kelime başında uzun 'â' veya Türkçe 'a' sesini gösterir."}, {"text": "Elif ve Vav (او)", "isCorrect": true, "rationale": "'Ok', 'ot', 'uç' ve 'öz' örneklerinde olduğu gibi kelime başındaki tüm yuvarlak ünlüler elif ve vav (او) birleşimiyle yazılır."}], "hint": "'Ok' veya 'un' yazarken kelime başında yan yana gelen iki harfi düşününüz.", "type": "multiple_choice"}, {"question": "Kelime başındaki yuvarlak ince ünlüleri (ö, ü) kalın yuvarlak ünlülerden (o, u) ayırt etmek amacıyla elif harfi yerine veya elif üzerinde kullanılan özel işaret hangisidir?", "answerOptions": [{"text": "Cezm ( ْ )", "isCorrect": false, "rationale": "Cezm işareti harfin sessiz (sakin) okunmasını sağlar."}, {"text": "Şedde ( ّ )", "isCorrect": false, "rationale": "Şedde işareti aynı ünsüzün iki kez okunmasını sağlar, ünlü çeşidini belirlemez."}, {"text": "Hemze (ء)", "isCorrect": true, "rationale": "İnce yuvarlak ünlülü kelimeleri ('öcü', 'ölü') kalınlarından ayırmak için elif yerine veya üzerinde hemze (أ / ئ) kullanılır."}, {"text": "Tenvin ( ً )", "isCorrect": false, "rationale": "Tenvin kelime sonlarına genizcil 'n' sesi ekleyen bir hareke işaretidir."}], "hint": "'Ölü' veya 'öcü' kelimelerinin başındaki elif üzerine ince sesi vurgulamak için konan işareti hatırlayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin yazımında \"k\" sesinin kalın ünlülerin yanında ve ince ünlülerin yanında kullanılan karşılıkları sırasıyla aşağıdakilerin hangisinde verilmiştir?", "answerOptions": [{"text": "ق - ك", "isCorrect": true, "rationale": "Kalın ünlülerin yanında kaf (ق), ince ünlülerin yanında ise kef (ك) harfi kullanılır (örneğin 'ak' - 'ek')."}, {"text": "ط - ت", "isCorrect": false, "rationale": "Bu harfler 't' sesinin kalın ve ince biçimleridir."}, {"text": "ظ - ز", "isCorrect": false, "rationale": "Bu harfler 'z' sesinin kalın ve ince karşılıklarıdır."}, {"text": "غ - گ", "isCorrect": false, "rationale": "Bu harfler 'ğ' sesinin kalın (gayn) ve ince (gef) halleridir."}], "hint": "'Ak' kelimesinde kullanılan harf ile 'ek' kelimesinde kullanılan harfi kıyaslayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin sonunda yer alan \"e\" ünlüsü Osmanlı Türkçesi alfabesinde genel olarak hangi harfle gösterilir?", "answerOptions": [{"text": "Ye (ى)", "isCorrect": false, "rationale": "Ye harfi kelime sonunda 'ı' ve 'i' ünlülerini göstermek için tercih edilir."}, {"text": "Güzel he (ه)", "isCorrect": true, "rationale": "'Anne', 'nine' ve 'dere' örneklerinde olduğu gibi Türkçe kelime sonundaki 'e' sesleri güzel he (ه) ile yazılır."}, {"text": "Elif (ا)", "isCorrect": false, "rationale": "Elif harfi kelime sonunda temel olarak 'a' ünlüsünü gösterir."}, {"text": "Vav (و)", "isCorrect": false, "rationale": "Vav harfi kelime sonunda yuvarlak ünlüleri (o, ö, u, ü) temsil eder."}], "hint": "'Dere' ve 'dede' kelimelerinin sonundaki okutucu harfi hatırlayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerin içindeki (ortasındaki) \"e\" ünlüsünün yazılışı ile ilgili genel kural aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Her zaman güzel he (ه) harfi ile gösterilir.", "isCorrect": false, "rationale": "Güzel he kelime içinde 'e' sesi için nadiren kullanılır, temel yeri kelime sonudur."}, {"text": "Genellikle harfle gösterilmez, yazılmaz.", "isCorrect": true, "rationale": "'Gerek' (كرك), 'emek' (امك) ve 'bebek' (ببك) örneklerinde görüldüğü gibi kelime içindeki 'e' sesi kural olarak yazılmaz."}, {"text": "Her zaman vav (و) harfi ile gösterilir.", "isCorrect": false, "rationale": "Vav harfi sadece yuvarlak ünlüleri gösterir, 'e' sesi için kullanılmaz."}, {"text": "Her zaman elif (ا) harfi ile gösterilir.", "isCorrect": false, "rationale": "Kelime içinde elif harfi 'a' ünlüsünü göstermek için kullanılır."}], "hint": "'Bebek' ve 'emek' kelimelerinin harf dizilimini ve ortadaki 'e' seslerinin yazılıp yazılmadığını düşününüz.", "type": "multiple_choice"}]}, "3": {"unit": 3, "unitTitle": "Türkçe Kelimelerin Yapısı, Türkçe Kiplerin ve Edatların Yazılışı", "title": "Osmanlı Türkçesi Testi", "questions": [{"question": "Türkçe kelimelerin yapısı ve ünsüz özellikleri göz önüne alındığında, aşağıdakilerden hangisi Türkçe kökenli kelimelerin başında yer almayan ünsüz harflerden biridir?", "answerOptions": [{"text": "k", "isCorrect": false, "rationale": "Türkçe kökenli kelimeler 'k' ünsüzü ile başlayabilir."}, {"text": "r", "isCorrect": true, "rationale": "Türkçe kelimeler ğ, l, m, n, ñ, r, z ünsüzleriyle başlamaz."}, {"text": "t", "isCorrect": false, "rationale": "Türkçe kökenli kelimeler 't' ünsüzü ile başlayabilir."}, {"text": "s", "isCorrect": false, "rationale": "Türkçe kökenli kelimeler 's' ünsüzü ile başlayabilir."}], "hint": "Türkçe kelime başlarında bulunmayan sekiz ünsüz harf grubunu (ğ, l, m, n, ñ, r, z) hatırlayınız.", "type": "multiple_choice"}, {"question": "Türkçe kelimelerde tonlu-tonsuz ünsüz benzeşmesi kuralına örnek gösterilen 'it-ti' fiilinin Osmanlı Türkçesindeki doğru yazılışı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ايتى", "isCorrect": false, "rationale": "Bu yazımda görülen geçmiş zaman ekinin 'dal' harfi eksiktir."}, {"text": "ايتتى", "isCorrect": false, "rationale": "Okunuştaki sertleşmeyi imlaya yansıtarak 'te' harfiyle yazmak Osmanlı Türkçesi ek imla geleneğine uymaz."}, {"text": "ايتدى", "isCorrect": true, "rationale": "Türkçe 'it-ti' fiilinde kökten sonra gelen görülen geçmiş zaman eki imlada 'dal' harfiyle korunarak 'ايتدى' biçiminde yazılır fakat okunuşta benzeşmeye uğrar."}, {"text": "ايتديك", "isCorrect": false, "rationale": "Bu biçim teklik 3. şahıs 'it-ti' çekimini değil, çokluk 1. şahıs eki almış halini gösterir."}], "hint": "Türkçe eklerdeki tonlu-tonsuz ünsüz değişiminde fiil kökünden sonra gelen 'd' harfinin imladaki kalıbını göz önüne getiriniz.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde Türkçe dilek-şart kipi eki olan '-sa / -se' aşağıdakilerden hangisi şeklinde tek kalıp olarak yazılır?", "answerOptions": [{"text": "سو", "isCorrect": false, "rationale": "Dilek-şart eki yuvarlak ünlü taşıyan bir harfle gösterilmez."}, {"text": "سي", "isCorrect": false, "rationale": "Dilek-şart eki imlasında 'ye' harfi standart ek kalıbı değildir."}, {"text": "سه", "isCorrect": true, "rationale": "Dilek-şart eki ses uyumlarına göre okunsa da imlada standart olarak 'sin' ve güzel 'he' (سه) birleşimiyle yazılır."}, {"text": "سا", "isCorrect": false, "rationale": "Kalın ünlülü fiillerde 'sa' okunsa dahi ek imlasında elif kullanılmaz."}], "hint": "Ek ünlü uyumuna göre -sa veya -se olarak okunsa da yazımda sonuna güzel he getirilerek tek kalıp olarak gösterilir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesi dilek-şart kipinde ince ünlülü fiillerin teklik 2. şahıs yazılışı ile aşağıdaki şahıslardan hangisinin yazılışı aynıdır (örneğin كلسه ك)?", "answerOptions": [{"text": "Teklik 1. şahıs", "isCorrect": false, "rationale": "Teklik 1. şahıs çekimi sonuna mim harfi alarak 'كلسه م' biçiminde biter."}, {"text": "Çokluk 3. şahıs", "isCorrect": false, "rationale": "Çokluk 3. şahıs çekiminde ek sonunda çokluk eki 'لر' bulunur."}, {"text": "Çokluk 1. şahıs", "isCorrect": true, "rationale": "İnce ünlülü fiillerde 'gelsen' (teklik 2. şahıs) ile 'gelsek' (çokluk 1. şahıs) çekimlerinin ikisi de 'كلسه ك' şeklinde yazılır."}, {"text": "Çokluk 2. şahıs", "isCorrect": false, "rationale": "Çokluk 2. şahıs çekiminde ek sonunda kef-zeyn 'كز' birleşimi yer alır."}], "hint": "'كلسه ك' (gelsen / gelsek) örneğinde olduğu gibi cümledeki bağlamdan ayırt edilen şahıs çekimini düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdaki fiillerden hangisi dilek-şart kipinin olumsuz şekliyle yazılmıştır?", "answerOptions": [{"text": "اويوسه ق", "isCorrect": false, "rationale": "Bu kelime olumsuzluk eki içermeyen olumlu 'uyusak' çekimidir."}, {"text": "كلسه م", "isCorrect": false, "rationale": "Bu kelime olumsuzluk eki içermeyen olumlu 'gelsem' çekimidir."}, {"text": "بيلسه", "isCorrect": false, "rationale": "Bu kelime olumsuzluk eki içermeyen olumlu 'bilse' çekimidir."}, {"text": "دونمه سه", "isCorrect": true, "rationale": "'Dönmese' fiili olumsuzluk eki 'مه' ve dilek-şart eki 'سه' ile 'دونمه سه' biçiminde yazılır."}], "hint": "Dilek-şart kipinde olumsuzluk için ince ünlülü fiillerde مه, kalın ünlülü fiillerde ما ekinin eklendiğini hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde gereklilik kipi eki olan '-malı / -meli' standart olarak aşağıdakilerden hangisi biçiminde yazılır?", "answerOptions": [{"text": "ملى", "isCorrect": true, "rationale": "Gereklilik kipi eki standart olarak mim-lam-ye (ملى) harfleriyle yazılır."}, {"text": "ملو", "isCorrect": false, "rationale": "Gereklilik eki son harf olarak vav değil ye alır."}, {"text": "مالى", "isCorrect": false, "rationale": "Elif kullanımı bazı kalın örneklerde görülse de ek temel standart kalıbı elifsiz yazılır."}, {"text": "مه لى", "isCorrect": false, "rationale": "Ayrı güzel he kullanımı standart gereklilik eki imlası değildir."}], "hint": "Mim, lam ve ye harflerinden oluşan standart ek kalıbını hatırlayınız.", "type": "multiple_choice"}, {"question": "Gereklilik kipinin olumsuz çekimine örnek olan 'bitirmemeliyiz' ifadesinin Osmanlı Türkçesi imlası aşağıdakilerden hangisidir?", "answerOptions": [{"text": "بيتيرمه مكده يز", "isCorrect": false, "rationale": "Bu yazım gereklilik kipi değil şimdiki zaman kipinin olumsuz çekimidir."}, {"text": "بيتيرمه ملى يز", "isCorrect": true, "rationale": "Fiil tabanı ile gereklilik eki arasına olumsuzluk eki -me (مه) getirilerek 'بيتيرمه ملى يز' şeklinde yazılır."}, {"text": "بيتيرملى يز", "isCorrect": false, "rationale": "Bu yazım olumsuzluk eki içermeyen olumlu 'bitirmeliyiz' çekimidir."}, {"text": "بيتيرمه سه ك", "isCorrect": false, "rationale": "Bu yazım gereklilik kipi değil, dilek-şart kipindeki 'bitirmesek' çekimidir."}], "hint": "Fiil kökü ile '-malı/-meli' eki arasına 'me' (مه) olumsuzluk ekinin girdiği şekli arayınız.", "type": "multiple_choice"}, {"question": "Türkçedeki şimdiki zaman eki olan '-makta / -mekte' eklerinin Osmanlı Türkçesindeki temel yazılış biçimi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "مقدا / مكدا", "isCorrect": false, "rationale": "Ekin sonundaki geniş ünlü elif ile değil güzel he ile gösterilir."}, {"text": "مقتى / مكتى", "isCorrect": false, "rationale": "Ek sonundaki bulunma hali 'dal-he' birleşimi yerine 'te-ye' ile yazılmaz."}, {"text": "مقده / مكده", "isCorrect": true, "rationale": "Şimdiki zaman eki kalın fiillerde 'مقده', ince fiillerde 'مكده' biçiminde fiil tabanına eklenir."}, {"text": "ماقده / ميكده", "isCorrect": false, "rationale": "Mastar ekindeki ünlüler elif veya ye ile uzatılarak yazılmaz."}], "hint": "Fiil tabanına eklenen mastar eki (-mak/-mek) üzerine bulunma hali ekinin (-ta/-te) gelmesiyle oluşan kalıbı düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdaki ifadelerin hangisinde Farsça kökenli 'ez' (از) ön edatının Türkçe karşılığı doğru verilmiştir?", "answerOptions": [{"text": "ez-cân u dil (از جان و دل) - Can ile gönül", "isCorrect": false, "rationale": "Birliktelik (ile) anlamını sağlayan edat 'ez' değil 'ba' edatıdır."}, {"text": "ez-cân u dil (از جان و دل) - Cana ve gönüle", "isCorrect": false, "rationale": "Yönelme (-a, -e) anlamını sağlayan edat 'ez' değil 'be' edatıdır."}, {"text": "ezber (از بر) - Yüzünden, başkası adına", "isCorrect": false, "rationale": "'Ezber' kelimesindeki 'ez' edatıyla oluşan yapı 'zihinden, göğüsten' anlamına gelir."}, {"text": "ez-cân u dil (از جان و دل) - Candan ve gönülden", "isCorrect": true, "rationale": "Farsça 'ez' (از) ön edatı Türkçe isim çekimindeki '-dan, -den' ayrılma halinin işlevini görür."}], "hint": "'ez' (از) ön edatının Türkçe isim çekimindeki ayrılma (-dan / -den) haline karşılık geldiğini hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesi metinlerinde 'üzerine, üzerinde, üzere' anlamlarına gelen Farsça ön edat aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ba (با)", "isCorrect": false, "rationale": "'Ba' edatı vasıta/birliktelik gösteren 'ile, -lı, -li' anlamı katar."}, {"text": "ber (بر)", "isCorrect": true, "rationale": "'Ber' edatı 'üzerine, üzerinde, üzere' anlamı katar (örneğin ber-kemâl, ber-dâr)."}, {"text": "be (به)", "isCorrect": false, "rationale": "'Be' edatı yönelme gösteren '-a, -e' anlamı katar."}, {"text": "der (در)", "isCorrect": false, "rationale": "'Der' edatı bulunma hali olan '-da, -de, içinde' anlamı katar."}], "hint": "'ber-kemâl' (kemal üzere) veya 'ber-dâr' (asılmış) kelimelerindeki edatı hatırlayınız.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi Osmanlı Türkçesinde sıklıkla kullanılan ünlem (nidâ) kelimelerinden biridir?", "answerOptions": [{"text": "zihî (زهى)", "isCorrect": true, "rationale": "'Zihî' (ne güzel, ne hoş) Osmanlı Türkçesinde metinlerde sıkça yer alan ünlemlerdendir."}, {"text": "ancak (انجق)", "isCorrect": false, "rationale": "'Ancak' kelimesi bir bağlama edatıdır."}, {"text": "gayrı (غيرى)", "isCorrect": false, "rationale": "'Gayrı' kelimesi ünlem değil, 'başka, artık' anlamında kullanılan bir kelimedir."}, {"text": "berây-ı (براى)", "isCorrect": false, "rationale": "'Berây-ı' tamlaması 'için' anlamına gelen bir ön edattır."}], "hint": "Coşku, şaşırma veya beğeni ifade eden, 'ey' veya 'yâ' gibi ünlem grubunda yer alan sözcüğü düşününüz.", "type": "multiple_choice"}, {"question": "Aşağıdaki fiil çekimlerinden hangisi '-makta / -mekte' şimdiki zaman ekiyle oluşturulmuştur?", "answerOptions": [{"text": "اوشودم", "isCorrect": false, "rationale": "Bu kelime görülen geçmiş zamanla çekimlenmiş 'üşüdüm' biçimidir."}, {"text": "اوشومكده يم", "isCorrect": true, "rationale": "'Üşü-' fiiline -mekte (مكده) şimdiki zaman eki ve teklik 1. şahıs eki (يم) eklenerek 'üşümekteyim' elde edilir."}, {"text": "اوشوملى يز", "isCorrect": false, "rationale": "Bu kelime gereklilik eki (-meli) ile oluşturulmuş 'üşümeliyiz' çekimidir."}, {"text": "اوشوسه م", "isCorrect": false, "rationale": "Bu kelime dilek-şart eki (-se) ile oluşturulmuş 'üşüsem' çekimidir."}], "hint": "Fiil tabanından sonra mim-kef-dal-he (مكده) ekini ve şahıs ekini içeren seçeneği arayınız.", "type": "multiple_choice"}]}, "4": {"unit": 4, "unitTitle": "Türkçe Ek, Zamir, Zarf ve Sayıların Yazılışı", "title": "Osmanlı Türkçesi Testi", "questions": [{"question": "Osmanlı Türkçesinde şahıs zamirlerinin yönelme (yaklaşma) hâli çekiminde belirgin bir imlâ kuralı uygulanmaktadır. Buna göre \"bana\" ve \"sana\" kelimelerinin doğru yazılışı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "بكا / سکا", "isCorrect": true, "rationale": "Şahıs zamirlerinin yönelme hâlinde kökteki genizsi/damaksı 'n' sesi 'ك' (kef/sağır nun) harfi kullanılarak yazılır."}, {"text": "بيا / سيا", "isCorrect": false, "rationale": "'Ye' harfi yönelme ekindeki kaynaştırma sesiyle karıştırılmış olup kökteki damaksı 'n' yapısını yansıtmamaktadır."}, {"text": "بگا / سگا", "isCorrect": false, "rationale": "'Gef' harfi yumuşak 'g' veya 'g' seslerini temsil ettiğinden zamir yönelme çekimindeki damaksı 'n' sesini karşılamaz."}, {"text": "بنا / سنا", "isCorrect": false, "rationale": "Standart 'nun' harfiyle yazım, günümüz okunuşuna uygun görünse de klasik Osmanlı Türkçesi zamir imlâ kalıbına uymamaktadır."}], "hint": "Zamirlerde yönelme hâli eki getirilirken kökte damaksı/genizsi n (sağır nun) harfi tercih edilir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesi metinlerinde geçen \"fi'l-hâl\" (فى الحال) zarfının Türkçe karşılığı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Arada sırada", "isCorrect": false, "rationale": "'Arada sırada' anlamı Osmanlı Türkçesinde 'akîbinde' veya benzeri zaman zarflarıyla ifade edilir."}, {"text": "Hemen, o anda", "isCorrect": true, "rationale": "Arapça kökenli 'fi'l-hal' birleşik zarfı metinlerde 'o anda, hemen, gecikmeksizin' anlamında kullanılır."}, {"text": "Yıldan yıla", "isCorrect": false, "rationale": "'Yıldan yıla' ifadesinin Osmanlı Türkçesindeki karşılığı 'sal be-sâl' zarfıdır."}, {"text": "Kara yoluyla", "isCorrect": false, "rationale": "'Kara yoluyla' anlamını taşıyan zarf 'berren' kelimesidir."}], "hint": "Bu zarf, 'hal' (mevcut durum/an) kelimesiyle bağlantılı olup eylemin anındalığını ifade eder.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde \"başka\" anlamında kullanılan Türkçe kökenli zarf aşağıdakilerden hangisidir?", "answerOptions": [{"text": "اشته (işte)", "isCorrect": false, "rationale": "'İşte' kelimesi bir gösterme edatıdır, 'başka' anlamına gelmez."}, {"text": "ايرق (ayrık)", "isCorrect": true, "rationale": "Eski Türkçe kökenli 'ayrık' kelimesi Osmanlı metinlerinde 'başka, ayrı, diğer' anlamında zarf olarak kullanılır."}, {"text": "بولدر (boldur)", "isCorrect": false, "rationale": "'Boldur' veya 'bıldır' kelimesi zaman zarfı olup 'geçen yıl' anlamına gelir."}, {"text": "قنده (kanda)", "isCorrect": false, "rationale": "'Kanda' kelimesi yer-yön/soru zarfı olup 'nerede' anlamında kullanılır."}], "hint": "'Ayrı' kökünden türemiş, günümüz Türkiye Türkçesinde yerini 'başka' kelimesine bırakmış tarihî bir kelimedir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde \"yirmi\" ve \"bin\" sayılarının imlâsı kalıplaşmış özel yapılara sahiptir. Aşağıdakilerin hangisinde bu iki sayının yazılışı doğru sıralanmıştır?", "answerOptions": [{"text": "يكرمی – بين", "isCorrect": false, "rationale": "'Yirmi' doğru yazılmasına rağmen 'bin' kelimesinin son harfi 'nun' değil damaksı n temsilcisi olan 'kef' olmalıdır."}, {"text": "يرمى – بين", "isCorrect": false, "rationale": "'Bin' kelimesinde 'nun' harfi kullanımı Arapça 'bint/bin' kelimeleriyle karıştırılmasından kaynaklanır; Türkçe 'bin' kelimesi kef (sağır nun) ile yazılır."}, {"text": "يكرمی – بيك", "isCorrect": true, "rationale": "'Yirmi' kelimesi 'يكرمی' ve 'bin' kelimesi 'بيك' biçiminde kalıplaşmış tarihî imlâlarıyla yazılır."}, {"text": "يرمى – بيك", "isCorrect": false, "rationale": "'Yirmi' kelimesinde ortadaki 'kef' harfinin yazılmaması kalıplaşmış imlâ kuralının ihlal edilmesine yol açar."}], "hint": "Her iki kelimede de günümüzde 'n' veya sesli olan yerlerde tarihî imlâ gereği 'kef' (ك) harfi bulunur.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde rakamların yazılışı ve biçimsel özellikleri ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "answerOptions": [{"text": "Metinler sağdan sola yazılmasına rağmen rakamlar soldan sağa doğru yazılır.", "isCorrect": true, "rationale": "Osmanlı Türkçesi yazısı sağdan sola doğru akarken sayısal rakamlar soldan sağa dizilir."}, {"text": "İki (۲) ve altı (٦) rakamları aynı yöne bakar.", "isCorrect": false, "rationale": "İki rakamı sağa bakarken, altı rakamı sola bakacak şekilde yazılır."}, {"text": "Çok basamaklı rakamlar yazılırken önce birler sonra onlar basamağı sağdan sola dizilir.", "isCorrect": false, "rationale": "Basamaklar soldan sağa doğru sıralanır ve okuma düzeni buna göre gerçekleşir."}, {"text": "Yedi (٧) rakamı ters v harfine, sekiz (٨) ise düz v harfine benzer.", "isCorrect": false, "rationale": "Yedi rakamı düz 'v' harfine benzerken, sekiz rakamı 'v' harfinin ters dönmüş biçimine benzer."}], "hint": "Arap alfabesi temelli metin akış yönü ile sayısal dizilim yönünün birbirinden farklı olduğunu hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde \"bu\" ve \"şu\" işaret zamirlerinin yükleme (belirtme) hâlindeki doğru yazılışları aşağıdakilerin hangisinde birlikte verilmiştir?", "answerOptions": [{"text": "بونده – شونده", "isCorrect": false, "rationale": "'بونده' ve 'شونده' biçimleri bulunma hâli çekimleridir."}, {"text": "بوندن – شوندن", "isCorrect": false, "rationale": "Bu yazım yükleme değil ayrılma hâlindeki 'bundan, şundan' biçimidir."}, {"text": "بونك – شونك", "isCorrect": false, "rationale": "'بونك' ve 'شونك' biçimleri yükleme değil, ilgi (tamlayan) hâli çekimleridir."}, {"text": "بونى – شونى", "isCorrect": true, "rationale": "İşaret zamirlerinin yükleme hâli 'بونى' (bunu) ve 'شونى' (şunu) biçiminde yazılır."}], "hint": "İşaret zamirlerinin yükleme hâli kalıplaşmış kısa yazımlara sahiptir ve ek kelimeye bitişik durur.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde isimlere getirilen bildirme eklerinden 2. tekil şahıs eki (örneğin \"talebesin\", \"boşsun\") imlâda hangi harf birleşimiyle temsil edilir?", "answerOptions": [{"text": "سن", "isCorrect": false, "rationale": "Günümüz Türkçesindeki 'sen' kelimesi 'سن' şeklinde yazılsa da şahıs bildirme eki imlâda 'سک' olarak kalıplaşmıştır."}, {"text": "سم", "isCorrect": false, "rationale": "'سم' harf birleşimi 1. tekil şahıs ekinin veya şart kipinin çekimlerinde yer alır."}, {"text": "سک", "isCorrect": true, "rationale": "2. şahıs bildirme ekleri 'sin/sun' imlâda 'sin' ve damaksı n olan 'kef' harflerinin birleşimiyle (سک) yazılır."}, {"text": "سز", "isCorrect": false, "rationale": "'سز' harf birleşimi 2. çoğul şahıs ekini temsil eder."}], "hint": "İkinci şahıs eklerinde genellikle kullanılan damaksı n (kef) harfini düşününüz.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesi metinlerinde sıklıkla karşılaşılan \"berren\" (برًا) zarfının anlamı aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Dostça", "isCorrect": false, "rationale": "'Dostça' anlamını veren zarf 'muhibbâne' kelimesidir."}, {"text": "Kara yoluyla", "isCorrect": true, "rationale": "Arapça 'berr' (kara) kökünden tenvin ile türetilen 'berren' zarfı metinlerde 'kara yoluyla' anlamına gelmektedir."}, {"text": "Bilerek", "isCorrect": false, "rationale": "'Bilerek, kasten' anlamı 'bi'l-iltizâm' zarfı ile ifade edilir."}, {"text": "Gecikmeksizin", "isCorrect": false, "rationale": "'Gecikmeksizin' anlamı 'der-akab' zarfı ile karşılanır."}], "hint": "Kelimenin kökü deniz veya hava yolunun zıttı olan coğrafi mekânı ifade eder.", "type": "multiple_choice"}, {"question": "Metinlerde geçen \"vakı'a\" (واقعا) zarfı Türkçe cümle içinde hangi anlama gelmektedir?", "answerOptions": [{"text": "Ne kadar", "isCorrect": false, "rationale": "'Ne kadar' miktar sorusu Osmanlı Türkçesinde 'niçe' ile gösterilir."}, {"text": "Gerçi", "isCorrect": true, "rationale": "'Vakı'a' kelimesi zarf olarak kullanıldığında 'gerçi, nitekim, her ne kadar' anlamını taşır."}, {"text": "Aceleyle", "isCorrect": false, "rationale": "'Aceleyle' anlamı 'ber-vech-i ta'cîl' veya 'ale'l-acele' ifadeleriyle sağlanır."}, {"text": "Dışarı", "isCorrect": false, "rationale": "'Dışarı' anlamındaki zarf 'bîrûn' kelimesidir."}], "hint": "Cümlede bir durumu kabullenip ardından zıt bir düşünceye geçiş yaparken kullanılan 'gerçi' bağlamını düşününüz.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde görülen geçmiş zaman 1. çoğul şahıs fiil çekiminde (örneğin \"bulduk\") fiil gövdesine getirilen eklerin yazılışı aşağıdakilerin hangisinde doğru verilmiştir?", "answerOptions": [{"text": "بولدك", "isCorrect": false, "rationale": "'بولدك' kelimesi 1. çoğul değil, 2. tekil şahıs ('buldun') çekimidir."}, {"text": "بولديلر", "isCorrect": false, "rationale": "'بولديلر' kelimesi 3. çoğul şahıs ('buldular') çekimidir."}, {"text": "بولدم", "isCorrect": false, "rationale": "'بولدم' kelimesi 1. tekil şahıs ('buldum') çekimidir."}, {"text": "بولدق", "isCorrect": true, "rationale": "Görülen geçmiş zaman eki 'dal' harfi ve 1. çoğul şahıs eki olan 'kaf' (kalın fiillerde) birleşimiyle 'بولدق' biçiminde yazılır."}], "hint": "1. çoğul şahıs ekinde kalın fiillere 'kaf' (ق), ince fiillere 'kef' (ك) getirilir.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde zaman bildiren zarflardan \"boldur\" (veya \"bıldır\") kelimesi ne anlama gelmektedir?", "answerOptions": [{"text": "Geçen yıl", "isCorrect": true, "rationale": "Eski Türkçe ve halk ağzında yaşayan 'boldur/bıldır' zarfı 'bir önceki yıl, geçen yıl' anlamında kullanılır."}, {"text": "Yıldan yıla", "isCorrect": false, "rationale": "'Yıldan yıla' anlamını veren ifade Farsça kökenli 'sal be-sâl' birleşiğidir."}, {"text": "Daha önce", "isCorrect": false, "rationale": "'Daha önce' anlamını karşılayan zarf 'akdemce' kelimesidir."}, {"text": "Nerede", "isCorrect": false, "rationale": "'Nerede' anlamı soru zarfı olan 'kanda' ile sağlanır."}], "hint": "Bir önceki seneyi ifade eden geleneksel zaman zarfını hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı alfabesinde kullanılan rakamlar incelendiğinde, birbirinin zıttı yönlere bakan 7 ve 8 rakamlarının doğru gösterimi sırasıyla aşağıdakilerden hangisidir?", "answerOptions": [{"text": "٧ – ٨", "isCorrect": true, "rationale": "7 rakamı 'v' harfi biçiminde (٧), 8 rakamı ise onun ters çevrilmiş hâli biçiminde (٨) yazılır."}, {"text": "٨ – ٧", "isCorrect": false, "rationale": "Bu seçenekte rakamların sırası karıştırılmış olup ilk sembol 8, ikinci sembol 7'dir."}, {"text": "٦ – ۲", "isCorrect": false, "rationale": "Bu semboller sırasıyla 6 ve 2 rakamlarını temsil etmektedir."}, {"text": "٤ – ٥", "isCorrect": false, "rationale": "Bu semboller sırasıyla 4 ve 5 rakamlarını temsil etmektedir."}], "hint": "Yedi rakamı Latin alfabesindeki 'v' harfine benzer, sekiz ise onun tepe noktası yukarıda olan hâlidir.", "type": "multiple_choice"}]}, "5": {"unit": 5, "unitTitle": "Arapça ve Farsça Kelimelerde Ünlüler ve Yazılışları", "title": "Osmanlı Türkçesi Testi", "questions": [{"question": "Arapça ve Farsça kelimelerdeki uzun \"â\" ünlüsünü göstermek için metin içerisinde aşağıdaki harflerden hangisi kullanılır?", "answerOptions": [{"text": "Vav (و)", "isCorrect": false, "rationale": "Bu harf uzun \"â\" sesini değil, uzun \"û\" ünlüsünü veya ünsüz olan \"v\" sesini göstermek için kullanılır."}, {"text": "Elif (ا)", "isCorrect": true, "rationale": "Arapça ve Farsça kökenli sözcüklerde uzun \"â\" sesini temsil etmek için elif harfi bir uzatma harfi olarak görev yapar."}, {"text": "Ye (ى)", "isCorrect": false, "rationale": "Bu harf kelime içinde veya sonunda uzun \"î\" ünlüsünü veya ünsüz olan \"y\" sesini karşılar."}, {"text": "Güzel he (ه)", "isCorrect": false, "rationale": "Bu harf genellikle kelime sonunda kısa \"e\" ünlüsünü veya ünsüz olan \"h\" sesini göstermek için tercih edilir."}], "hint": "Arapça ve Farsçada uzun ünlüleri göstermek için kullanılan üç ana harften ilkidir.", "type": "multiple_choice"}, {"question": "Arapça ve Farsça kökenli kelimelerin başında bulunan \"u\" veya uzun \"û\" sesini ifade etmek için elif (ا) harfi hangi hareke ile birlikte kullanılır?", "answerOptions": [{"text": "Ötre", "isCorrect": true, "rationale": "Kelime başında \"u\" veya \"û\" sesini verebilmek için elif harfinin üzerine ötre harekesi konulur."}, {"text": "Üstün", "isCorrect": false, "rationale": "Elif harfi üzerine konulan üstün harekesi \"u\" sesini değil, \"a\" veya \"e\" seslerini üretir."}, {"text": "Esre", "isCorrect": false, "rationale": "Elif harfinin altına konulan esre harekesi \"u\" sesini değil, \"ı\" veya \"i\" seslerini verir."}, {"text": "Cezm", "isCorrect": false, "rationale": "Cezm bir ünlü harekesi olmayıp, harfin ünsüz ve harekesiz duraklama halini belirtir."}], "hint": "Sesin dudaklar büzülerek okunmasını sağlayan harekeyi hatırlayınız.", "type": "multiple_choice"}, {"question": "Farsların Arap alfabesini benimsedikten sonra eklediği ve Farsçaya özgü olan dört harfli grup aşağıdakilerden hangisidir?", "answerOptions": [{"text": "ث (se), ح (ha), ذ (zel), ض (dad)", "isCorrect": false, "rationale": "Bu harf grubu Farsçaya değil, doğrudan Arapça kelimelere özgü aslî ünsüzlerdir."}, {"text": "پ (pe), چ (çim), گ (gef), ژ (je)", "isCorrect": true, "rationale": "Arap alfabesinde bulunmayan bu dört harf Fars dili tarafından eklenerek alfabe 32 harfe çıkarılmıştır."}, {"text": "ع (ayın), غ (gayn), خ (hı), ك (kaf)", "isCorrect": false, "rationale": "Bu harfler Arapçanın temel harfleridir ve Farsların alfabeye sonradan kazandırdığı sesler değildir."}, {"text": "ص (sad), ض (dad), ط (tı), ظ (zı)", "isCorrect": false, "rationale": "Bu harfler Farsların eklediği harfler olmayıp Arapçadaki kalın ünsüz grubunu oluşturur."}], "hint": "Arap alfabesini 32 harfe çıkaran ek sesleri düşününüz.", "type": "multiple_choice"}, {"question": "Farsça kelimelerde \"خ\" (hı) harfinden sonra yazıldığı halde okunmayan \"و\" (vav) harfine ne ad verilir?", "answerOptions": [{"text": "Vâv-ı mef'ûl", "isCorrect": false, "rationale": "Arapça türetme kalıplarında yer alan ve nesne durumu bildiren bir terim olup yazılıp okunmayan vavı açıklamaz."}, {"text": "Vâv-ı nisbet", "isCorrect": false, "rationale": "Aitlik gösteren ekler veya yapısal durumlar için kullanılan bir kavramdır, okunmayan vav terimi değildir."}, {"text": "Vâv-ı atıf", "isCorrect": false, "rationale": "Bu kavram kelimeleri veya cümleleri birbirine bağlayan bağlaç görevindeki vav için kullanılır."}, {"text": "Vâv-ı ma'dûle", "isCorrect": true, "rationale": "Yazıda yer aldığı halde okunmayan veya özel bir sesle telaffuz edilmeyen bu vav harfi vâv-ı ma'dûle olarak adlandırılır."}], "hint": "\"Uyku\" anlamına gelen \"خواب\" (hˇâb) ve \"sofra\" anlamına gelen \"خوان\" (hˇân) kelimelerindeki yazılıp okunmayan vavı hatırlayınız.", "type": "multiple_choice"}, {"question": "Aşağıdaki harflerden hangisi yalnızca Arapça kelimelerde bulunan ve Türkçede ses karşılığı olmadığı için genellikle \"z\" (nadiren \"d\") sesiyle okunan harftir?", "answerOptions": [{"text": "ژ (je)", "isCorrect": false, "rationale": "Farsça ve Batı dillerinden geçen kelimelerde görülen bu harf j sesini temsil eder."}, {"text": "پ (pe)", "isCorrect": false, "rationale": "Bu harf Arapçaya değil, Farsçaya özgüdür ve p sesiyle okunur."}, {"text": "چ (çim)", "isCorrect": false, "rationale": "Bu harf Farsça kökenli olup ç sesini karşılar, z veya d sesiyle okunmaz."}, {"text": "ض (dad)", "isCorrect": true, "rationale": "Arapçaya özgü bir ses olan dad harfi, Türkçeye geçen kelimelerde z sesiyle telaffuz edilir."}], "hint": "Türkçeye geçen Arapça kelimelerde z sesiyle telaffuz edilen kalın ünsüz harfi düşününüz.", "type": "multiple_choice"}, {"question": "Bir kelimenin yapısında veya başında \"ژ\" (je) harfinin yer alması, o kelimenin kökeni hakkında aşağıdaki yargılardan hangisini kesinleştirir?", "answerOptions": [{"text": "Kelimenin Arapça bükünlü bir kökten türediğini gösterir.", "isCorrect": false, "rationale": "Arap alfabesinde j (ژ) harfi yer almadığı için Arapça sözcüklerde bulunamaz."}, {"text": "Kelimenin Farsça (veya Batı dillerinden geçmiş) olduğunu gösterir.", "isCorrect": true, "rationale": "Je harfi Arapçada ve öz Türkçe kelimelerde bulunmaz; yalnızca Farsça ve Batı kökenli sözcüklerde yer alır."}, {"text": "Kelimenin Göktürkçe dönemine ait bir ek aldığını kanıtlar.", "isCorrect": false, "rationale": "Tarihî Türkçe dönemlerinde j sesi yer almamaktadır."}, {"text": "Kelimenin öz Türkçe bir kökten geldiğini doğrular.", "isCorrect": false, "rationale": "Öz Türkçe kelimelerin yapısında ve başında j sesi/harfi bulunmaz."}], "hint": "Arapçada bulunmayan, Fars alfabesine eklenip Osmanlıcaya geçen sesin kullanım alanını hatırlayınız.", "type": "multiple_choice"}, {"question": "Hicrî-Kamerî takvim sisteminde bir ayın ilk gününü ifade etmek için kullanılan kalıp terim aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Gurre", "isCorrect": true, "rationale": "Hicrî ayların ilk gününü belirtmek amacıyla resmî ve edebî metinlerde gurre terimi kullanılır."}, {"text": "Selh", "isCorrect": false, "rationale": "Selh terimi ayın ilk gününü değil, tam aksine ayın son gününü ifade etmek için tercih edilir."}, {"text": "Evâsıt", "isCorrect": false, "rationale": "Evâsıt kavramı ayın ikinci on günlük (11-20) dönemini ifade eder."}, {"text": "Evâ'il", "isCorrect": false, "rationale": "Evâ'il terimi tek bir günü değil, ayın ilk on günlük (1-10) zaman dilimini kapsar."}], "hint": "Ayın son günü olan \"selh\" veya ilk on günü olan \"evâ'il\" terimleri ile karıştırmayınız.", "type": "multiple_choice"}, {"question": "Hicrî takvimde ayın 11 ile 20. günleri arasındaki ikinci on günlük dönemi tanımlamak için kullanılan terim aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Evâ'il", "isCorrect": false, "rationale": "Evâ'il terimi ayın birinci on günlük (1-10) başlangıç dönemini kapsar."}, {"text": "Evâhir", "isCorrect": false, "rationale": "Evâhir terimi ayın son on günlük (21-30) bitiş dönemini tanımlar."}, {"text": "Evâsıt", "isCorrect": true, "rationale": "Arapçada \"orta\" kökünden gelen evâsıt terimi, ayın ortasındaki ikinci on günlük zaman dilimini ifade eder."}, {"text": "Gurre", "isCorrect": false, "rationale": "Gurre terimi on günlük bir dönemi değil, yalnızca ayın birinci gününü gösterir."}], "hint": "Arapçada \"orta\" anlamına gelen kökten türeyen kavrama odaklanınız.", "type": "multiple_choice"}, {"question": "Hicrî ay adlarının resmî belgelerde kullanılan rumuz veya kısaltmalarında \"رمضان\" (Ramazan) ayı hangi harf ile temsil edilir?", "answerOptions": [{"text": "ر (rı)", "isCorrect": false, "rationale": "Rı harfi Ramazan ayının değil, Rebî'ü'l-âhire ayının kısaltmasıdır."}, {"text": "ص (sad)", "isCorrect": false, "rationale": "Sad harfi Ramazan ayını değil, Safer ayını temsil eden kısaltmadır."}, {"text": "ش (şın)", "isCorrect": false, "rationale": "Şın harfi Ramazan ayının değil, Şa'bân ayının resmî kısaltmasıdır."}, {"text": "ن (nun)", "isCorrect": true, "rationale": "Ramazan ayının resmî belge ve yazışmalardaki geleneksel kısaltması kelimenin sonundaki \"ن\" harfidir."}], "hint": "Ramazan kelimesinin son harfi olan işaretin kısaltma olarak kullanıldığını hatırlayınız.", "type": "multiple_choice"}, {"question": "Farsçada \"gün\" anlamına gelen \"şenbe\" kelimesinden hareketle, \"Düşenbe\" ifadesi günümüz Türkçesinde hangi güne karşılık gelmektedir?", "answerOptions": [{"text": "Çarşamba", "isCorrect": false, "rationale": "Çarşamba günü Farsçada \"Çehârşenbe\" (dördüncü gün) olarak isim almaktadır."}, {"text": "Pazartesi", "isCorrect": true, "rationale": "Farsçada \"dü\" (iki) ve \"şenbe\" (gün) kelimelerinin birleşimiyle oluşan Düşenbe, haftanın ikinci günü kabul edilen Pazartesi günüdür."}, {"text": "Pazar", "isCorrect": false, "rationale": "Pazar günü Farsçada \"Yekşenbe\" (birinci gün) şeklinde adlandırılır."}, {"text": "Salı", "isCorrect": false, "rationale": "Salı günü Farsçada \"Seşenbe\" (üçüncü gün) ifadesiyle karşılanır."}], "hint": "Farsça sıra sayılarında \"dü\" iki demektir; haftanın ikinci günü olarak değerlendirilen günü seçiniz.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde metin içinde geçen \"خمسه و مائه والف\" (Hamse ve mi'e ve elf) ifadesinin rakamla gösterimi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "١٢٠٨", "isCorrect": false, "rationale": "Bu rakam dizilimi (1208) \"semâniye ve mi'eteyn ve elf\" ifadesinin karşılığıdır."}, {"text": "١١٠٥", "isCorrect": true, "rationale": "Arapça sayılarda elf (1000) + mi'e (100) + hamse (5) toplamı 1105 eder ve rakamlar soldan sağa \"١١٠٥\" şeklinde yazılır."}, {"text": "١٠٠٥", "isCorrect": false, "rationale": "Bu sayı 1005 olup yüzlük basamağı belirten \"mi'e\" sözcüğünü içermez."}, {"text": "١١١٨", "isCorrect": false, "rationale": "Bu rakam dizilimi (1118) \"semâniye ve aşara mi'e ve elf\" ifadesine karşılık gelir."}], "hint": "Sayı isimleri soldan sağa basamak değerlerine göre çözümlenir: hamse (5), mi'e (100), elf (1000).", "type": "multiple_choice"}, {"question": "Aşağıdaki harf çiftinden hangisi yabancı (Arapça veya Farsça) kökenli kelimeleri tanımada kullanılır ve birkaç istisna dışında öz Türkçe kelimelerde yer almaz?", "answerOptions": [{"text": "ب (be) ve ت (te)", "isCorrect": false, "rationale": "Be ve te harfleri öz Türkçe sözcüklerin imlasında da sıkça kullanılan temel harflerdendir."}, {"text": "خ (hı) ve ذ (zel)", "isCorrect": true, "rationale": "Hı ve zel harfleri Arapça ve Farsça kelimelere özgüdür; Türkçe kelimelerde birkaç istisna (\"han\" gibi) dışında kullanılmazlar."}, {"text": "ك (kaf) ve ل (lam)", "isCorrect": false, "rationale": "Kef ve lam harfleri Türkçe kökenli sözcüklerin yazımında yaygın olarak yer alır."}, {"text": "د (dal) ve ر (rı)", "isCorrect": false, "rationale": "Dal ve rı harfleri Türkçe kelimelerde geniş bir kullanım alanına sahiptir."}], "hint": "Biri \"h\" sesine yakındır, diğeri ise peltek okunan ve Türkçe kökenli sözcüklerde bulunmayan harflerdendir.", "type": "multiple_choice"}, {"question": "Arapça ve Farsça kökenli kelimelerin sonunda yer alan kısa \"e\" sesini göstermek için aşağıdaki harflerden hangisi tercih edilir?", "answerOptions": [{"text": "Güzel he (ه)", "isCorrect": true, "rationale": "Arapça ve Farsça kelimelerin sonunda yer alan kısa \"e\" ünlüsü güzel he harfi ile gösterilir (çeşme - چشمه gibi)."}, {"text": "Elif (ا)", "isCorrect": false, "rationale": "Kelime sonundaki elif harfi kısa \"e\" ünlüsünü değil, uzun \"â\" ünlüsünü temsil eder."}, {"text": "Ye (ى)", "isCorrect": false, "rationale": "Kelime sonundaki ye harfi kısa \"e\" sesini değil, uzun \"î\" veya kısa \"i\" seslerini karşılar."}, {"text": "Vav (و)", "isCorrect": false, "rationale": "Kelime sonundaki vav harfi \"e\" ünlüsünü değil, \"u/ü/o/ö\" veya uzun \"û\" seslerini gösterir."}], "hint": "\"Çeşme\" (چشمه) ve \"beyhûde\" (بيهوده) kelimelerinin son harfini düşününüz.", "type": "multiple_choice"}]}, "6": {"unit": 6, "unitTitle": "Arapça Kelimelerin Yapısı", "title": "Arapça Bilgisi Testi", "questions": [{"question": "Arap dilinin genel yapısı ve kelime türetme mantığı ile ilgili aşağıdakilerden hangi ifade doğrudur?", "answerOptions": [{"text": "Kelime kökleri hiçbir zaman değişikliğe uğramaz ve yalnızca sonuna getirilen eklerle yeni kelimeler elde edilir.", "isCorrect": false, "rationale": "Bu durum bitişken (eklemeli) diller için geçerlidir; Arapçada ise kelime kökünün iç yapısı kırılarak veya genişletilerek türetme yapılır."}, {"text": "Kelimelerin anlamını değiştirmek ve yeni manalar türetmek için kelime kökünün başına, ortasına veya sonuna zâid sesler getirilerek bükünlü (tasrîfli) bir yapı oluşturulur.", "isCorrect": true, "rationale": "Arapça bükünlü bir dil olduğu için kelime kökü içerisindeki ses değişimi ve eklenen zâid harfler vasıtasıyla yeni kavramlar türetilir."}, {"text": "Arapçada kelimeler türetilirken aslî harfler tamamen çıkarılır ve sadece zâid harflerden oluşan yeni kelimeler kurulur.", "isCorrect": false, "rationale": "Kelime türetiminde aslî (kök) harfler korunur veya kalıba göre düzenlenir; aslî harflerin tamamen atılması söz konusu değildir."}, {"text": "Osmanlı Türkçesinde Arapça kökenli fiiller çekimlenerek ve cümle içinde yüklem yapılarak yoğun şekilde kullanılmıştır.", "isCorrect": false, "rationale": "Osmanlı Türkçesinde Arapçadan fiiller çekimli halleriyle değil, çoğunlukla isim ve masdar formlarıyla ödünç alınmıştır."}], "hint": "Arapçanın bükünlü (tasrîfli) yapısını ve köke eklenen zâid seslerin işlevini düşününüz.", "type": "multiple_choice"}, {"question": "Arapça kelimelerin vezinleri çıkarılırken kelimenin birinci, ikinci ve üçüncü aslî (kök) harflerinin yerine sırasıyla hangi harfler yazılır?", "answerOptions": [{"text": "ف (fe) – ع (ayn) – ل (lam)", "isCorrect": true, "rationale": "Arapçada vezin kalıbı oluşturulurken birinci kök harf fe, ikinci kök harf ayn, üçüncü kök harf ise lam temsilci harfleriyle gösterilir."}, {"text": "س (sin) – ت (te) – م (mim)", "isCorrect": false, "rationale": "Söz konusu harfler vezin kalıbını oluşturmak için kök harfleri temsil etmez, türetme ekleri olarak zâid harflerde kullanılır."}, {"text": "ا (elif) – ب (be) – ت (te)", "isCorrect": false, "rationale": "Bu harfler alfabenin ilk harfleri olup gramerde vezin temsili için kullanılan standart sembol harfler değildir."}, {"text": "م (mim) – ن (nun) – ه (he)", "isCorrect": false, "rationale": "Bu harfler genellikle kelimelere türetme aşamasında eklenen zâid harfler arasında yer alır."}], "hint": "Arap gramerinde vezin kalıbı oluşturulurken standart olarak seçilen üç sembolik kök harfi hatırlayınız.", "type": "multiple_choice"}, {"question": "Arapçada \"كرم\" (k-r-m) kökünden türetilen \"اِكْرَام\" (ikrâm) kelimesinin vezni aşağıdakilerden hangisidir?", "answerOptions": [{"text": "إفعال (if‘âl)", "isCorrect": true, "rationale": "Kök harfler (k-r-m) yerlerine fe-ayn-lam konulup baştaki esreli elif ve dördüncü sıradaki üstünlü elif zâid harfleri eklendiğinde if'âl kalıbı elde edilir."}, {"text": "مَفْعُول (mef‘ûl)", "isCorrect": false, "rationale": "Bu kalıp başında mim ve dördüncü harfinde vav bulunan edilgen sıfat (ism-i mef'ûl) kalıbıdır."}, {"text": "فَعَل (fa‘al)", "isCorrect": false, "rationale": "Bu kalıp üç aslî harften oluşan ve zâid harf içermeyen yalın masdar kalıbıdır."}, {"text": "تَفَعُّل (tefa‘‘ul)", "isCorrect": false, "rationale": "Bu kalıp başında te bulunan ve ikinci kök harfi şeddeli olan farklı bir masdar babıdır."}], "hint": "Kelimenin başındaki elif (ا) ve dördüncü sırasındaki uzun elif (ا) zâid harflerdir.", "type": "multiple_choice"}, {"question": "\"مَجْهُول\" (mechûl) kelimesinin aslî ve zâid harfleri dikkate alındığında vezni aşağıdakilerden hangisi olur?", "answerOptions": [{"text": "اِفْتِعَال (ifti‘âl)", "isCorrect": false, "rationale": "İfti'âl kalıbı beş harfli bir mezidünfih masdar veznidir."}, {"text": "فَاعِل (fâ‘il)", "isCorrect": false, "rationale": "Fâ'il kalıbı etken sıfat yapısında olup ilk harfinden sonra elif alan üç kök harfli yapıdır."}, {"text": "مَفْعُول (mef‘ûl)", "isCorrect": true, "rationale": "Kök harfleri 'c-h-l' olan kelimenin başına ötreli mim ve üçüncü harfinden sonra vav gelerek mef'ûl vezni oluşmuştur."}, {"text": "فَعَلَة (fe‘ale)", "isCorrect": false, "rationale": "Fe'ale kalıbı çoğul veya isim kalıbı olarak kullanılır ve mim/vav zâid harflerini barındırmaz."}], "hint": "Mim harfiyle başlayan ve dördüncü harfinde uzun u (و) barındıran edilgen sıfat kalıbını hatırlayınız.", "type": "multiple_choice"}, {"question": "Aşağıdakilerden hangisi Arapça isimlerde dişil (müennes) yapıyı gösteren açık alametlerden biri değildir?", "answerOptions": [{"text": "Kelime sonunda kısa elif (elif-i maksûre, ى) bulunması", "isCorrect": false, "rationale": "Kelime sonunda 'a' sesini veren ve 'ye' şeklinde yazılan elif-i maksûre belirgin bir müenneslik ekidir."}, {"text": "Kelimenin başında zâid mim (م) harfinin bulunması", "isCorrect": true, "rationale": "Baştaki mim harfi müenneslik eki değildir; genellikle mekân, zaman, alet isimleri veya ism-i mef'ûl yapımında kullanılan bir zâid harftir."}, {"text": "Kelime sonunda uzun elif (elif-i memdûde, اء / ا) bulunması", "isCorrect": false, "rationale": "Kelime sonundaki uzatılan elif (elif-i memdûde) sıfatlarda ve isimlerde dişilik gösteren alametlerdendir."}, {"text": "Kelime sonunda kapalı te (ة / ت) veya he (ه) bulunması", "isCorrect": false, "rationale": "Kelime sonundaki kapalı te veya okutucu he harfi en yaygın dişil (müennes) alametidir."}], "hint": "Dişilik belirten son ekler ile isim türetmede kullanılan ön ekleri ayırt ediniz.", "type": "multiple_choice"}, {"question": "Kendisinde herhangi bir müenneslik alameti bulunmadığı hâlde anlamı veya sözlüksel kullanımı gereği dişil kabul edilen \"mü'ennes-i ma'nevî\" veya \"semâî müennes\" kelimelere aşağıdakilerden hangisi örnektir?", "answerOptions": [{"text": "kâtib (كاتب) ve me'mûr (مأمور)", "isCorrect": false, "rationale": "Bu kelimeler eril (müzekker) yapıda olup isim/sıfat kategorisindedir."}, {"text": "mu'allim (معلم) ve sâbir (صابر)", "isCorrect": false, "rationale": "Her iki sözcük de dişil eki taşımayan kurallı eril sıfatlardır."}, {"text": "ارض (arz) ve نار (nâr)", "isCorrect": true, "rationale": "Arz (yer) ve nâr (ateş) kelimeleri biçimsel bir dişilik eki taşımamalarına rağmen semâî müennes kabul edilen sözcüklerdendir."}, {"text": "ahmer (احمر) ve esved (اسود)", "isCorrect": false, "rationale": "Bu kelimeler renk bildiren eril (müzekker) sıfat kalıbındadır; dişil halleri hamrâ ve sevdâ şeklindedir."}], "hint": "Sözlükten veya işitilerek dişil kabul edilen coğrafi ve tabiat unsurlarını içeren örnekleri düşününüz.", "type": "multiple_choice"}, {"question": "Arapçada iki nesneyi veya kavramı ifade etmek için kullanılan \"tesniye\" (ikilik) yapısı Osmanlı Türkçesinde çoğunlukla hangi ek ile sağlanır?", "answerOptions": [{"text": "–în (ين)", "isCorrect": false, "rationale": "Uzun i sesi veren –în eki cem'-i müzekker-i sâlim (eril çoğul) yapımında kullanılır."}, {"text": "–eyn (ـَيْن)", "isCorrect": true, "rationale": "Osmanlı Türkçesinde iki kavramı bir arada ifade etmek için tekil ismin sonuna –eyn eki getirilir (örn. devleteyn, tarafeyn)."}, {"text": "–iyye (يه)", "isCorrect": false, "rationale": "–iyye eki nispet ve soyut masdar yapımında kullanılır, ikilik anlamı katmaz."}, {"text": "–ât (ات)", "isCorrect": false, "rationale": "–ât eki ikilik değil, çoğul (cem'-i mü'ennes-i sâlim) yapmak için kullanılır."}], "hint": "Arapçada iki nesne veya durum için kullanılan özel ikilik ekini hatırlayınız.", "type": "multiple_choice"}, {"question": "\"Taraf\" (طرف) kelimesinin tesniye (ikilik) biçimi aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Etrâf (اطراف)", "isCorrect": false, "rationale": "Etrâf kelimesi taraf sözcüğünün ikilik değil, çoğul (cem'-i mükesser) halidir."}, {"text": "Tarafeyn (طرفين)", "isCorrect": true, "rationale": "Taraf kelimesine ikilik eki olan –eyn getirilerek 'iki taraf' anlamına gelen tarafeyn yapısı oluşturulur."}, {"text": "Tarafûn (طرفون)", "isCorrect": false, "rationale": "–ûn eki eril çoğul yapımında kullanılır, ikilik bildiren cezm kalıbından farklıdır."}, {"text": "Tarafât (طرفات)", "isCorrect": false, "rationale": "Dişil çoğul eki olan –ât ile yapılan bu form ikilik anlamı taşımaz."}], "hint": "Doğu ve batı için kullanılan 'maşrıkeyn' veya iki deniz için kullanılan 'bahreyn' örneklerindeki eki hatırlayınız.", "type": "multiple_choice"}, {"question": "Akıllı varlıklara (zevi'l-ukūl) ait eril sıfatların ve isimlerin cem'-i müzekker-i sâlim (düzenli eril çoğul) yapılması için kelime sonuna yaygın olarak hangi ek getirilir?", "answerOptions": [{"text": "–în (ين) / –ûn (ون)", "isCorrect": true, "rationale": "Osmanlı Türkçesinde akıllı varlıkların eril sıfatları ve isimleri tekil halin sonuna –în (veya –ûn) eki getirilerek kurallı çoğul yapılır (örn. me'mûrîn, mü'minîn)."}, {"text": "–eyn (ين - cezmli)", "isCorrect": false, "rationale": "Cezmli okunarak eyn sesini veren yapı çoğul değil, tesniye (ikilik) bildirir."}, {"text": "–ât (ات)", "isCorrect": false, "rationale": "–ât eki dişil varlıkların ve masdarların kurallı çoğulunda kullanılır."}, {"text": "–ân (ان)", "isCorrect": false, "rationale": "–ân eki Farsça çoğul eki veya Arapça tesniye alternatifi olup standart eril çoğul biçimi değildir."}], "hint": "Memur, mümin ve muallim gibi akıllı varlıkların kurallı çoğul yapılma şeklini hatırlayınız.", "type": "multiple_choice"}, {"question": "Osmanlı Türkçesinde masdarların ve dişil isimlerin sonuna \"–ât\" (ات) eki getirilerek yapılan çoğul türü aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Cem‘-i Mükesser", "isCorrect": false, "rationale": "Cem'-i mükesser düzensiz (kırık) çoğul olup eklerle değil, vezin değişimiyle elde edilir."}, {"text": "Tesniye", "isCorrect": false, "rationale": "Tesniye iki adedi gösteren ikilik yapısıdır, çoğul kategorisinde yer almaz."}, {"text": "Cem‘-i Mü’ennes-i Sâlim", "isCorrect": true, "rationale": "Düzenli dişil çoğul olarak adlandırılan cem'-i mü'ennes-i sâlim, kelimelerin sonuna –ât eki getirilerek oluşturulur (örn. hissiyyât, nakliyyât)."}, {"text": "Cem‘-i Müzekker-i Sâlim", "isCorrect": false, "rationale": "Cem'-i müzekker-i sâlim yapısı –ât ile değil, –în veya –ûn ekleri ile kurulur."}], "hint": "Hissiyyât, neşriyyât ve edebiyyât örneklerinde görülen kurallı çoğul türünü hatırlayınız.", "type": "multiple_choice"}, {"question": "\"Kâtib\" (katip) -> \"Küttâb\" (katipler), \"Hâkim\" -> \"Hükkâm\", \"Tâlib\" -> \"Tullâb\" çoğul kelimeleri hangi cem'-i mükesser (kırık çoğul) veznindedir?", "answerOptions": [{"text": "Fu‘‘âl (فُعَّال)", "isCorrect": true, "rationale": "Fâ'il veznindeki meslek ve sıfat isimlerinin kırık çoğulu çoğunlukla ilk harfi ötreli, ikinci harfi şeddeli fu‘‘âl vezninde yapılır (küttâb, hükkâm, tullâb)."}, {"text": "Fi‘âl (ِفَعاْل)", "isCorrect": false, "rationale": "Fi'âl kalıbının ilk harfi esreli olup cebel -> cibâl veya recül -> ricâl kelimelerinde görülür."}, {"text": "Mefâ‘il (َمَفاِعل)", "isCorrect": false, "rationale": "Mefâ'il kalıbı meclis -> mecâlis örneğinde olduğu gibi mim ile başlayan dört harfli kelimelerin çoğul kalıbıdır."}, {"text": "Ef‘âl (َافْـَعال)", "isCorrect": false, "rationale": "Ef'âl kalıbı başı elifli olan farklı bir kırık çoğul veznidir (örn. eser -> âsâr)."}], "hint": "Fâ'il veznindeki meslek veya sıfat isimlerinin çoğullaştırılmasında kullanılan ve ikinci harfi şeddeli olan kalıbı düşününüz.", "type": "multiple_choice"}, {"question": "Tekil kelimenin yapısı ve vezni değiştirilerek oluşturulan \"Cem'-i Mükesser\" (kırık çoğul) ile ilgili aşağıdakilerden hangi ifade doğrudur?", "answerOptions": [{"text": "Kurallı bir ek getirmek yerine tekil kelimenin kök yapısına ve veznine müdahale edilerek elde edilen semâî çoğullardır.", "isCorrect": true, "rationale": "Cem'-i mükesser, ek ekleyerek değil kelimenin iç ses düzenini ve veznini değiştirerek yapılan semâî (işitilerek öğrenilen) kırık çoğuldur."}, {"text": "Sadece akılsız varlıkların ikili (tesniye) durumlarını göstermek için kullanılır.", "isCorrect": false, "rationale": "Cem'-i mükesser iki adedi değil, üç ve daha fazla çoğul durumları ifade eder."}, {"text": "Osmanlı Türkçesinde fiil çekimlerini çoğul yapmak için kullanılan temel kuraldır.", "isCorrect": false, "rationale": "Cem'-i mükesser fiillere değil, Arapça isim ve sıfatlara uygulanan bir çoğaltma yöntemidir."}, {"text": "Yalnızca –ât eki kullanılarak tekil kelimenin sonuna ek yapılmasıyla elde edilir.", "isCorrect": false, "rationale": "–ât eki ile yapılan çoğullar kırık çoğul değil, kurallı (sâlim) dişil çoğuldur."}], "hint": "Kırık çoğulun kurala bağlı eklerle değil, kelime kalıbının değiştirilmesiyle (semâî) oluştuğunu dikkate alınız.", "type": "multiple_choice"}, {"question": "\"Meclis\" (مجلس) kelimesinin cem'-i mükesser (kırık çoğul) biçimi olan \"Mecâlis\" (مجالس) kelimesinin vezni aşağıdakilerden hangisidir?", "answerOptions": [{"text": "Fe‘âlîl (فَعَالِيل)", "isCorrect": false, "rationale": "Fe'âlîl kalıbı kandîl -> kanâdîl örneğinde olduğu gibi uzun i sesi barındıran beş harfli çoğul yapısıdır."}, {"text": "Ef‘ile (أَفْعِلَة)", "isCorrect": false, "rationale": "Ef'ile kalıbı mekân -> emkine veya cevâb -> ecvibe örneklerinde görülen başında elif bulunan kalıptır."}, {"text": "Mefâ‘il (مَفَاعِل)", "isCorrect": true, "rationale": "Meclis kelimesindeki m-c-l-s düzeni kırık çoğul kalıbına sokulduğunda mefâ'il vezni (mecâlis) ortaya çıkar."}, {"text": "Fu‘alâ (فُعَلَاء)", "isCorrect": false, "rationale": "Fu'alâ kalıbı şerîk -> şürekâ örneğinde görülen sonu hemzeli çoğul yapısıdır."}], "hint": "İlk harfi mim (m) ile başlayan isimlerin çoğullaştırılmasında kullanılan mefâ'il kalıbını hatırlayınız.", "type": "multiple_choice"}]}, "7": {"unit": 7, "unitTitle": "Aksâm-ı Seb'a, Mücerred Masdarlar, İsm-i Fâil ve İsm-i Mef'ûl", "title": "Arapça Dilbilgisi Testi", "questions": [{"question": "Arapça kelime yapısında aslî harflerinde illet harfi (ا، و، ی), hemze veya şedde/harf tekrarı bulunmayan sahih kelimelere ne ad verilir?", "answerOptions": [{"text": "Misâl", "isCorrect": false, "rationale": "Misâl kelimeler sahih değil, ilk harfi illetli olan mu'tell kelimelerdendir."}, {"text": "Mehmûz", "isCorrect": false, "rationale": "Mehmûz kelimelerin aslî harflerinden biri hemze içerdiği için bu tanıma uymaz."}, {"text": "Muzâ'af", "isCorrect": false, "rationale": "Muzâ'af kelimelerde ikinci ve üçüncü aslî harfler aynı olup şeddeli tekrar oluşturur."}, {"text": "Sâlim", "isCorrect": true, "rationale": "Aslî harflerinde illet harfi, hemze ve şeddeli harf tekrarı bulunmayan kelimeler sahih grubunun sâlim kısmını oluşturur."}], "hint": "Sahih kelimelerin herhangi bir illet, hemze veya harf tekrarı barındırmayan en yalın türünü düşünün.", "type": "multiple_choice"}, {"question": "Aksâm-ı seb'a sınıflandırmasına göre 'vakt' (وقت) kelimesi ilk aslî harfi illetli olduğu için hangi grupta yer almaktadır?", "answerOptions": [{"text": "Misâl", "isCorrect": true, "rationale": "Kök harflerinden birincisi 'vav' veya 'ye' olan illetli kelimeler misâl kategorisindedir."}, {"text": "Nâkıs", "isCorrect": false, "rationale": "Nâkıs kelimelerde illet harfi birinci konumda değil, son (üçüncü) aslî harf konumundadır."}, {"text": "Ecvef", "isCorrect": false, "rationale": "Ecvef kelimelerin ilk harfi değil, orta (ikinci) aslî harfi illetlidir."}, {"text": "Lefîf", "isCorrect": false, "rationale": "Lefîf kelimelerde tek bir illet harfi değil, iki ayrı aslî illet harfi yer alır."}], "hint": "Kelimenin başındaki ilk kök harfin illetli olmasına odaklanın.", "type": "multiple_choice"}, {"question": "'Edeb' (أدب) ve 'emr' (امر) kelimelerinde olduğu gibi kök harflerinden biri hemze olan sahih kelimeler aksâm-ı seb'ada nasıl adlandırılır?", "answerOptions": [{"text": "Sâlim", "isCorrect": false, "rationale": "Sâlim kelimelerde hemze bulunmaması şartı vardır."}, {"text": "Muzâ'af", "isCorrect": false, "rationale": "Muzâ'af kelimeler kök harflerinin ikincisi ve üçüncüsü aynı olan kelimelerdir."}, {"text": "Ecvef", "isCorrect": false, "rationale": "Ecvef sınıfı sahih kelimeleri değil, orta harfi illetli kelimeleri kapsar."}, {"text": "Mehmûz", "isCorrect": true, "rationale": "Aslî harflerinden biri hemze olan sahih kelimeler mehmûz olarak adlandırılır."}], "hint": "Terimin kökeni Arapçada 'hemze' barındırma durumuna dayanmaktadır.", "type": "multiple_choice"}, {"question": "Aksâm-ı seb'a kurallarına göre 'nevm' (نوم) kelimesi orta harfi illetli ('vav') olduğu için hangi gruba girer?", "answerOptions": [{"text": "Misâl", "isCorrect": false, "rationale": "Misâl grubunda illet harfi kelimenin ortasında değil ilk harfindedir."}, {"text": "Nâkıs", "isCorrect": false, "rationale": "Nâkıs grubundaki kelimelerin illet harfi son kök harfidir."}, {"text": "Ecvef", "isCorrect": true, "rationale": "İkinci (orta) aslî harfi illetli olan kelimeler ecvef olarak sınıflandırılır."}, {"text": "Sâlim", "isCorrect": false, "rationale": "Sâlim kelimelerde hiç illet harfi bulunmaz."}], "hint": "Kelimenin 'içi/ortası oyuk' anlamına da gelen, orta harfi illetli kelime türünü hatırlayın.", "type": "multiple_choice"}, {"question": "Aşağıdaki kelimelerden hangisi kökünün başına eklenen zâid 'mîm' (م) harfiyle oluşturulmuş bir mimli masdardır?", "answerOptions": [{"text": "Müdâvemet (مداومت)", "isCorrect": false, "rationale": "'Müdâvemet' kelimesi mufâ'ale babından bir mezîdünfih masdardır."}, {"text": "Metrûk (متروك)", "isCorrect": false, "rationale": "'Metrûk' kelimesi masdar olmayıp mef'ûl vezninde bir ism-i mef'ûldür."}, {"text": "Maksad (مقصد)", "isCorrect": true, "rationale": "'Maksad' kelimesi kasd kökünün başına zâid mîm getirilerek yapılmış bir mimli masdardır."}, {"text": "Mükrim (مكرم)", "isCorrect": false, "rationale": "'Mükrim' kelimesi masdar değil, fâil (yapan) anlamı taşıyan ism-i fâildir."}], "hint": "Yalın kök harflerinin önüne eklenen mîm harfiyle masdarlaşan yapılara odaklanın.", "type": "multiple_choice"}, {"question": "Arapçada kelimelerin sonuna 'iyyet' (يت) eki getirilerek oluşturulan yapay masdarlara ne ad verilir?", "answerOptions": [{"text": "Mimli masdar", "isCorrect": false, "rationale": "Mimli masdarlar kelimenin sonuna ekle değil, başına zâid mîm getirilerek yapılır."}, {"text": "Rubâ'î masdar", "isCorrect": false, "rationale": "Rubâ'î masdarlar ekle değil, doğrudan dört kök harfle kurulan mastarlardır."}, {"text": "Mec'ûl masdar", "isCorrect": true, "rationale": "Kelime sonuna 'iyyet' eki eklenerek sonradan yapılan mastarlara mec'ûl masdar denir."}, {"text": "Sülâsî mücerred masdar", "isCorrect": false, "rationale": "Sülâsî mücerred masdarlar ek almamış üç kök harfli yalın masdarlardır."}], "hint": "Yapay olarak sonradan oluşturulmuş, kurgulanmış masdar anlamındaki terimi hatırlayın.", "type": "multiple_choice"}, {"question": "'Vaz'iyet' (وضعيت) kelimesi masdar yapısı bakımından aşağıdakilerden hangisine bir örnektir?", "answerOptions": [{"text": "Sülâsî mücerred masdar", "isCorrect": false, "rationale": "Yalın üç harfli kök halinde kalmayıp ek aldığı için mücerred sayılmaz."}, {"text": "Mimli masdar", "isCorrect": false, "rationale": "Kelimenin başında zâid bir mîm harfi yer almadığı için mimli masdar değildir."}, {"text": "Rubâ'î masdar", "isCorrect": false, "rationale": "Dört aslî kök harfe sahip olmayıp ekle türetilmiştir."}, {"text": "Mec'ûl masdar", "isCorrect": true, "rationale": "'Vaz'' kelimesine 'iyyet' eki eklenerek yapay masdar üretildiği için mec'ûl masdardır."}], "hint": "Kelimenin sonundaki '-iyet / -iyyet' ekine dikkat edin.", "type": "multiple_choice"}, {"question": "Sülâsî mücerred masdarlardan işi yapanı gösteren 'ism-i fâ'il' türetilirken aşağıdaki vezinlerden hangisi kullanılır?", "answerOptions": [{"text": "Mufa'lel (مُفَعْلَل)", "isCorrect": false, "rationale": "Mufa'lel vezni rubâ'î masdarların ism-i mef'ûlü için kullanılır."}, {"text": "Mufa'lil (مُفَعْلِل)", "isCorrect": false, "rationale": "Mufa'lil vezni sülâsî değil, rubâ'î mücerred masdarların ism-i fâ'ilidir."}, {"text": "Fâ'il (فَاعِل)", "isCorrect": true, "rationale": "Üç kök harfli sülâsî mücerred masdarların etken özne biçimi (ism-i fâ'ili) fâ'il vezniyle yapılır."}, {"text": "Mef'ûl (مَفْعُول)", "isCorrect": false, "rationale": "Mef'ûl vezni işi yapanı değil, işten etkileneni (ism-i mef'ûlü) gösterir."}], "hint": "'Kâtib', 'şâkir', 'hâfız' gibi kelimelerin ortak kalıbını düşünün.", "type": "multiple_choice"}, {"question": "Sülâsî mücerred bir masdardan yapılan işten etkilenen unsuru gösteren 'ism-i mef'ûl' hangi vezin ile elde edilir?", "answerOptions": [{"text": "Fâ'il (فَاعِل)", "isCorrect": false, "rationale": "Fâ'il kalıbı edilgen nesneyi değil, etken özneyi türetmek için kullanılır."}, {"text": "Mufa'lel (مُفَعْلَل)", "isCorrect": false, "rationale": "Mufa'lel kalıbı üç harfli masdarların değil, dört kök harfli rubâ'î masdarların ism-i mef'ûlüdür."}, {"text": "Fu'ûl (فُعُول)", "isCorrect": false, "rationale": "Fu'ûl bir ism-i mef'ûl kalıbı değil, sülâsî masdar kalıplarından biridir."}, {"text": "Mef'ûl (مَفْعُول)", "isCorrect": true, "rationale": "Üç harfli yalın masdarların edilgen nesne hali (ism-i mef'ûlü) mef'ûl kalıbıyla türetilir."}], "hint": "'Mektûb', 'mahfûz', 'maktu'' gibi kelimelerin türetildiği standart kalıbı hatırlayın.", "type": "multiple_choice"}, {"question": "Dört kök harfli (rubâ'î) mücerred masdarların ism-i fâ'ilini türetmek için aşağıdaki vezinlerden hangisi kullanılır?", "answerOptions": [{"text": "Mufa'lel (مُفَعْلَل)", "isCorrect": false, "rationale": "Mufa'lel vezni rubâ'î masdarların ism-i fâ'ili değil, ism-i mef'ûlüdür."}, {"text": "Mufa'lil (مُفَعْلِل)", "isCorrect": true, "rationale": "Rubâ'î mücerred masdarların etken yapanı (ism-i fâ'ili) mufa'lil vezni ile yapılır."}, {"text": "Mef'ûl (مَفْعُول)", "isCorrect": false, "rationale": "Mef'ûl vezni sülâsî masdarların edilgen nesne halidir."}, {"text": "Fâ'il (فَاعِل)", "isCorrect": false, "rationale": "Fâ'il vezni rubâ'î masdarlar için değil, sülâsî (üç harfli) masdarlar için kullanılır."}], "hint": "Başı 'mu-' ile başlayıp son harekesi esreli olan dört harfli kök kalıbını arayın.", "type": "multiple_choice"}, {"question": "Aşağıdaki kelimelerden hangisi dört aslî kök harften oluşan bir 'rubâ'î masdar' örneğidir?", "answerOptions": [{"text": "Mansıb (منصب)", "isCorrect": false, "rationale": "'Mansıb' kelimesi zâid mîm içeren mimli masdardır."}, {"text": "Maslahat (مصلحت)", "isCorrect": false, "rationale": "'Maslahat' mimli masdar yapısındadır, rubâ'î masdar değildir."}, {"text": "Saltanat (سلطنت)", "isCorrect": true, "rationale": "'Saltanat' kelimesi bünyesinde dört aslî kök harf barındıran mücerred rubâ'î masdardır."}, {"text": "Vaz'iyet (وضعيت)", "isCorrect": false, "rationale": "'Vaz'iyet' türetilmiş bir mec'ûl masdardır."}], "hint": "Kökünde üç değil, dört asli harf bulunduran kelimeler grubunu düşünün.", "type": "multiple_choice"}, {"question": "Aksâm-ı seb'ada 'nâkıs' kelime grubu ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "answerOptions": [{"text": "Kelimenin üçüncü (son) aslî harfi illetlidir.", "isCorrect": true, "rationale": "Nâkıs kelimelerde sonuncu kök harfi 'vav', 'ye' veya 'elif' olan illetli harftir."}, {"text": "Kelimenin ikinci (orta) aslî harfi illetlidir.", "isCorrect": false, "rationale": "Orta harfi illetli olanlar nâkıs değil, ecvef kelimelerdir."}, {"text": "Kelimenin iki aslî harfi birden illetlidir.", "isCorrect": false, "rationale": "İki aslî harfi illetli olan kelimeler lefîf kategorisindedir."}, {"text": "Kelimenin birinci aslî harfi illetlidir.", "isCorrect": false, "rationale": "Birinci aslî harfi illetli olan kelimeler nâkıs değil, misâl kelimelerdir."}], "hint": "İllet harfinin kelimenin en sonunda bulunması durumunu göz önüne alın.", "type": "multiple_choice"}]}, "8": {"unit": 8, "unitTitle": "Mezîdünfih Masdarlar (I)", "title": "Arapça Bâblar Quiz", "questions": [{"question": "Sülâsî mücerred bir kelime İf‘âl bâbına aktarıldığında oluşan etken sıfat (ism-i fâ‘il) hangi vezinde gelir?", "answerOptions": [{"text": "mufa‘‘il", "isCorrect": false, "rationale": "Mufa‘‘il vezni şeddeli orta harfiyle Tef‘îl bâbının ism-i fâ‘il kalıbıdır."}, {"text": "müf‘il", "isCorrect": true, "rationale": "İf‘âl bâbının etken yapıda işi yapanı gösteren ism-i fâ‘ili, başa ötreli mîm getirilip aynü'l-fiilin esrelenmesiyle müf‘il vezninde oluşur."}, {"text": "mütefa‘‘il", "isCorrect": false, "rationale": "Mütefa‘‘il vezni başında 'müte-' eki bulunan Tefa‘‘ul bâbının ism-i fâ‘il kalıbıdır."}, {"text": "müf‘al", "isCorrect": false, "rationale": "Müf‘al vezni, İf‘âl bâbının etken ismi değil edilgen yapıdaki ism-i mef‘ûlüne ait kalıptır."}], "hint": "Baştaki ötreli mîm harfinden sonra ortadaki aslî harfin esreli okunduğu kalıbı düşünün.", "type": "multiple_choice"}, {"question": "İf‘âl bâbından türetilen ve 'idare eden' anlamına gelen 'müdîr' kelimesi, ecvef (orta harfi illetli) köklerde hangi ism-i fâ‘il veznindedir?", "answerOptions": [{"text": "müfîl", "isCorrect": true, "rationale": "Ecvef fiiller İf‘âl bâbında ism-i fâ‘il yapılırken orta harf uzatıcı 'yâ' sesine dönüşerek müfîl veznini alır."}, {"text": "mû‘il", "isCorrect": false, "rationale": "Mû‘il vezni misâl veya mehmûzü'l-fâ fiillerin İf‘âl bâbı ism-i fâ‘il veznidir."}, {"text": "müf‘î", "isCorrect": false, "rationale": "Müf‘î vezni nâkıs fiillerin İf‘âl bâbındaki ism-i fâ‘il veznidir."}, {"text": "müfi‘‘", "isCorrect": false, "rationale": "Müfi‘‘ vezni muzâ‘af fiillerin İf‘âl bâbındaki ism-i fâ‘il veznidir."}], "hint": "Kelimedeki 'î' sesinin, orta harf olan illetli harfin uzatılmasıyla ortaya çıktığını dikkate alın.", "type": "multiple_choice"}, {"question": "Aşağıdaki kelimelerden hangisi Tef‘îl bâbının ism-i fâ‘il kalıbına (mufa‘‘il) örnek gösterilebilir?", "answerOptions": [{"text": "mütekebbir", "isCorrect": false, "rationale": "Mütekebbir kelimesi Tefa‘‘ul bâbının (tekebbür) mütefa‘‘il veznindeki ism-i fâ‘ilidir."}, {"text": "mürekkeb", "isCorrect": false, "rationale": "Mürekkeb kelimesi Tef‘îl bâbının ism-i fâ‘ili değil, mufa‘‘al veznindeki ism-i mef‘ûlüdür."}, {"text": "mu‘allim", "isCorrect": true, "rationale": "'Öğreten' anlamına gelen mu‘allim kelimesi, ta‘lîm (Tef‘îl) masdarının şeddeli ve esreli orta harfe sahip mufa‘‘il kalıbındaki ism-i fâ‘ilidir."}, {"text": "muhzır", "isCorrect": false, "rationale": "Muhzır kelimesi İf‘âl bâbının (ihzâr) müf‘il veznindeki ism-i fâ‘ilidir."}], "hint": "Şeddeli orta harfi esreli okunan ve 'öğreten / ders veren' gibi eylemi yapanı gösteren kelimeyi arayın.", "type": "multiple_choice"}, {"question": "Tef‘îl bâbında nâkıs (son harfi illetli) kelimelerin ism-i mef‘ûlü hangi özel vezinde gelir?", "answerOptions": [{"text": "mufa‘‘î", "isCorrect": false, "rationale": "Mufa‘‘î vezni nâkıs kelimelerin Tef‘îl bâbındaki ism-i fâ‘il veznidir."}, {"text": "mütefe‘‘î", "isCorrect": false, "rationale": "Mütefe‘‘î vezni Tefa‘‘ul bâbındaki nâkıs kelimelerin ism-i fâ‘il veznidir."}, {"text": "müf‘al", "isCorrect": false, "rationale": "Müf‘al vezni İf‘âl bâbının genel ism-i mef‘ûl veznidir."}, {"text": "mufa‘‘â", "isCorrect": true, "rationale": "Nâkıs fiiller Tef‘îl bâbında ism-i mef‘ûl yapılırken son illet harfi üstünleşerek mufa‘‘â (müberrâ, müsemmâ gibi) veznini oluşturur."}], "hint": "Müsemmâ ve müberrâ gibi sonu uzun 'â' sesi ile biten edilgen kalıbı hatırlayın.", "type": "multiple_choice"}, {"question": "Tefa‘‘ul bâbı (تَـَفعُّْل) sülâsî mücerred masdarlara aktarıldığında genel olarak hangi anlam özelliğini kazandırır?", "answerOptions": [{"text": "Sadece dışa dönük ettirgenlik ve geçişlilik", "isCorrect": false, "rationale": "Ettirgenlik ve dışa dönük geçişlilik daha çok İf‘âl ve Tef‘îl bâblarının temel işlevidir."}, {"text": "Sadece edilgenlik ve nesnesizlik", "isCorrect": false, "rationale": "Tefa‘‘ul bâbı doğrudan edilgenlikten ziyade dönüşlülük veya geçişsiz/bazen geçişli fiil türetmede kullanılır."}, {"text": "İki kişi arasında karşılıklı işteşlik", "isCorrect": false, "rationale": "İki veya daha fazla kişi arasındaki işteşlik eylemleri ağırlıklı olarak Tefâ‘ul ve Müfâ‘ale bâblarının özelliğidir."}, {"text": "Dönüşlülük ve eylemin kendinde gerçekleşmesi", "isCorrect": true, "rationale": "Tefa‘‘ul bâbı, eylemin öznenin kendi üzerinde gerçekleştiğini gösteren dönüşlülük anlamı ve bazen de yapmacıklık katar."}], "hint": "Bu bâbın 'tahassul' veya 'tekebbür' örneklerinde olduğu gibi eylemin kişinin kendisinde meydana gelmesini ifade ettiğini düşünün.", "type": "multiple_choice"}, {"question": "Tefa‘‘ul bâbının etken nitelik taşıyan ism-i fâ‘il vezni aşağıdakilerden hangisidir?", "answerOptions": [{"text": "mütefa‘‘il", "isCorrect": true, "rationale": "Tefa‘‘ul bâbının etken ismi olan ism-i fâ‘ili, başında 'müte-' eki ve şeddeli esreli orta harfiyle mütefa‘‘il (örneğin mütekebbir) veznindedir."}, {"text": "mütefâ‘il", "isCorrect": false, "rationale": "Mütefâ‘il vezni Tefâ‘ul bâbının ism-i fâ‘ilidir."}, {"text": "mütefa‘‘al", "isCorrect": false, "rationale": "Mütefa‘‘al vezni Tefa‘‘ul bâbının ism-i mef‘ûl veznidir."}, {"text": "mufa‘‘il", "isCorrect": false, "rationale": "Mufa‘‘il vezni Tef‘îl bâbının ism-i fâ‘ilidir."}], "hint": "Başında 'müte-' eki bulunan ve ikinci aslî harfi şeddeli olan etken kalıbı değerlendirin.", "type": "multiple_choice"}, {"question": "Tefa‘‘ul bâbının ism-i mef‘ûlünün (mütefa‘‘al) dilde son derece az kullanılmasının temel sebebi nedir?", "answerOptions": [{"text": "Bâbın temel işlevinin dönüşlülük olması ve nesne almaması", "isCorrect": true, "rationale": "Tefa‘‘ul bâbı dönüşlülük bildirdiğinden eylem öznenin üzerinde kalır; bu yüzden nesne alan edilgen yapıdaki ism-i mef‘ûlüne pek ihtiyaç duyulmaz."}, {"text": "Bâbın sadece geçişli fiillerden oluşması", "isCorrect": false, "rationale": "Bu bâb aksine çoğunlukla geçişsiz ve dönüşlü fiiller türetir."}, {"text": "Bâbın yalnızca isim türetmek için kullanılması", "isCorrect": false, "rationale": "Bu bâbdan hem masdar hem de ism-i fâ‘il gibi sıfat türleri yaygın olarak türetilmektedir."}, {"text": "Bâbda hiçbir zaman ism-i fâ‘il türetilememesi", "isCorrect": false, "rationale": "Bâbın mütekebbir, mütehassıl gibi dilde son derece yaygın kullanılan ism-i fâ‘illeri bulunmaktadır."}], "hint": "Eylemin özneye geri dönmesi ile dışarıdan bir nesne gereksinimi arasındaki ilişkiyi düşünün.", "type": "multiple_choice"}, {"question": "'Bakışmak, yardımlaşmak' gibi işteşlik eylemlerinin yanı sıra bazen var olmayan bir durumu varmış gibi gösterme (yapmacıklık) anlamı da katan bâb hangisidir?", "answerOptions": [{"text": "Tef‘îl Bâbı", "isCorrect": false, "rationale": "Tef‘îl bâbı çoğunlukla geçişlilik ve pekiştirme ifade eder."}, {"text": "Müfâ‘ale Bâbı", "isCorrect": false, "rationale": "Müfâ‘ale bâbı işteşlik ve geçişlilik sağlasa da sahtelik/yapmacıklık anlamı katma özelliği Tefâ‘ul bâbına aittir."}, {"text": "Tefâ‘ul Bâbı", "isCorrect": true, "rationale": "Tefâ‘ul bâbı (تَـَفاُعْل), birden fazla kişi arasında işteşlik sağladığı gibi 'tecâhül' örneğindeki gibi yapmacıklık ve sahtelik anlamı da taşır."}, {"text": "İf‘âl Bâbı", "isCorrect": false, "rationale": "İf‘âl bâbı geçişlilik ve ettirgenlik ifade eder."}], "hint": "Tecâhül (bilmezlikten gelme) ve tenâzur (bakışma) örneklerinin ait olduğu bâbı hatırlayın.", "type": "multiple_choice"}, {"question": "Tefâ‘ul bâbının ism-i fâ‘ili olan ve 'olgunlaşmış' anlamına gelen 'mütekâmil' kelimesi hangi vezinde türetilmiştir?", "answerOptions": [{"text": "müfâ‘il", "isCorrect": false, "rationale": "Müfâ‘il vezni Müfâ‘ale bâbının ism-i fâ‘il veznidir."}, {"text": "mütefa‘‘il", "isCorrect": false, "rationale": "Mütefa‘‘il vezni şeddeli orta harfe sahiptir ve Tefa‘‘ul bâbına aittir."}, {"text": "mütefâ‘al", "isCorrect": false, "rationale": "Mütefâ‘al vezni Tefâ‘ul bâbının ism-i mef‘ûl veznidir."}, {"text": "mütefâ‘il", "isCorrect": true, "rationale": "Tekâmül (Tefâ‘ul) masdarının ism-i fâ‘ili olan mütekâmil, mütefâ‘il vezninde türetilmiştir."}], "hint": "Başında 'müte-' eki olan ve ilk aslî harften sonra uzatıcı elif bulunan etken kalıbı arayın.", "type": "multiple_choice"}, {"question": "Müfâ‘ale bâbı (ُمَفاَعَله) masdarları ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "answerOptions": [{"text": "Yalnızca tek taraflı ettirgenlik ve edilgenlik anlamları oluşturur.", "isCorrect": false, "rationale": "Ettirgenlik ve edilgenlik bu bâbın temel işlevi değildir."}, {"text": "Genellikle işteşlik (karşılıklılık) ve geçişlilik anlamı taşır.", "isCorrect": true, "rationale": "Müfâ‘ale bâbı eylemin karşılıklı yapılmasını (işteşlik) sağlar ve geçişli/geçişsiz yapıda bulunabilir."}, {"text": "Başındaki mîm harfi kelimenin aslî kök harflerinden biridir.", "isCorrect": false, "rationale": "Başındaki ötreli mîm (mü-) harfi bâbın zâid (eklenmiş) harfidir, kök harf değildir."}, {"text": "Bâbın ism-i fâ‘il ve ism-i mef‘ûlleri dilde hiç kullanılmaz.", "isCorrect": false, "rationale": "Müşâhed, muhâtab, mübârek gibi ism-i mef‘ûller dilde sıklıkla kullanılır."}], "hint": "Muhâtabe (karşılıklı konuşma) ve mücâdele gibi kelimelerin kattığı eylem biçimini dikkate alın.", "type": "multiple_choice"}, {"question": "'İnkâr edilmiş' anlamına gelen 'münker' ve 'sağlamlaştırılmış' anlamına gelen 'muhkem' kelimeleri İf‘âl bâbının hangi kalıbındadır?", "answerOptions": [{"text": "mufa‘‘al", "isCorrect": false, "rationale": "Mufa‘‘al vezni Tef‘îl bâbının ism-i mef‘ûlüdür."}, {"text": "müf‘al", "isCorrect": true, "rationale": "İf‘âl bâbının edilgen nitelikteki ism-i mef‘ûlü, aynü'l-fiili üstünlü olan müf‘al veznindedir."}, {"text": "mütefa‘‘al", "isCorrect": false, "rationale": "Mütefa‘‘al vezni Tefa‘‘ul bâbının ism-i mef‘ûlüdür."}, {"text": "müf‘il", "isCorrect": false, "rationale": "Müf‘il vezninde aynü'l-fiil esrelidir ve etken (ism-i fâ‘il) anlam verir."}], "hint": "Baştaki ötreli mîmden sonra ortadaki kök harfi üstünlü okunarak edilgen nitelik kazanan kalıbı düşünün.", "type": "multiple_choice"}, {"question": "Tef‘îl bâbının ism-i mef‘ûlü olan 'mürekkeb' (birleştirilmiş) ve 'müşerref' (şereflendirilmiş) kelimeleri hangi vezinde türetilmiştir?", "answerOptions": [{"text": "mufa‘‘il", "isCorrect": false, "rationale": "Mufa‘‘il vezni Tef‘îl bâbının etken sıfatı olan ism-i fâ‘il veznidir."}, {"text": "mufa‘‘al", "isCorrect": true, "rationale": "Tef‘îl bâbının ism-i mef‘ûlü, ikinci aslî harfi şeddeli ve üstünlü okunan mufa‘‘al veznindedir."}, {"text": "mütefa‘‘al", "isCorrect": false, "rationale": "Mütefa‘‘al vezni Tefa‘‘ul bâbının ism-i mef‘ûlüdür."}, {"text": "müf‘al", "isCorrect": false, "rationale": "Müf‘al vezni İf‘âl bâbının ism-i mef‘ûlüdür."}], "hint": "Ortadaki aslî harfi hem şeddeli hem de üstünlü okunarak yapılan edilgen sıfat kalıbını hatırlayın.", "type": "multiple_choice"}]}}, "teknik-gelistirim": {"1": {"unit": 1, "unitTitle": "Program Orientation and IFS Cloud Oracle Architecture", "title": "Oracle Architecture Quiz", "questions": [{"question": "In the Oracle Multitenant Architecture utilized by IFS enterprise applications, what is the primary role of the root container database (CDB$ROOT)?", "answerOptions": [{"text": "It stores isolated application-specific schemas and business data tablespaces exclusively for production workloads.", "isCorrect": false, "rationale": "Application-specific schemas and business data tablespaces reside in dedicated user PDBs rather than in the root container database."}, {"text": "It manages background processes, shared system metadata, and global memory allocations across the container database structure.", "isCorrect": true, "rationale": "The CDB$ROOT container database acts as the master management structure handling background processes, shared system metadata, and global memory for all connected pluggable databases."}, {"text": "It serves as a system-provided template PDB used to clone new non-production environments.", "isCorrect": false, "rationale": "Template cloning for new environments is the specific responsibility of PDB$SEED, not CDB$ROOT."}, {"text": "It enforces user-level UI session persistence and external identity provider authentication tokens.", "isCorrect": false, "rationale": "UI session persistence and authentication protocols are managed at the middle-tier and IAM layers rather than at the root database container layer."}], "hint": "Focus on the centralized architecture component that manages system metadata and background processes.", "type": "multiple_choice"}, {"question": "What is the primary administrative function of PDB$SEED within an IFS Oracle Multitenant environment?", "answerOptions": [{"text": "To act as a system-provided template PDB used for rapidly provisioning new user PDBs such as DEV, TEST, or PROD.", "isCorrect": true, "rationale": "PDB$SEED is a read-only system template provided by Oracle to enable fast provisioning of new pluggable database instances."}, {"text": "To store backup catalog records and Block Change Tracking (BCT) metadata.", "isCorrect": false, "rationale": "RMAN catalog metadata and BCT files are maintained separately within the database storage layer and recovery catalog."}, {"text": "To manage global memory allocations under Automatic Shared Memory Management (ASMM).", "isCorrect": false, "rationale": "Memory allocation under ASMM is managed at the CDB instance level via parameter configuration, not by PDB$SEED."}, {"text": "To offload read-only reporting queries and batch generation jobs from the primary database instance.", "isCorrect": false, "rationale": "Read-only reporting workloads are offloaded using Active Data Guard physical standby instances rather than PDB$SEED."}], "hint": "Consider how new development or test environments are generated within a container database.", "type": "multiple_choice"}, {"question": "How do Release Updates (RU) differ from Release Update Revisions (RUR) in the Oracle patch management lifecycle?", "answerOptions": [{"text": "Release Updates (RU) contain major database release upgrades, whereas Release Update Revisions (RUR) contain emergency one-off PL/SQL scripts.", "isCorrect": false, "rationale": "Major release upgrades represent distinct version transitions (e.g., 19c to 26ai), while RUs and RURs are quarterly maintenance updates within an existing release."}, {"text": "Release Updates (RU) require full database re-creation, while Release Update Revisions (RUR) are applied dynamically without stopping database services.", "isCorrect": false, "rationale": "Neither patch type requires database re-creation, and both follow standard patching windows and procedures."}, {"text": "Release Updates (RU) are quarterly cumulative patches with bug fixes and enhancements that increment the minor release version, whereas Release Update Revisions (RUR) extend an existing RU with security and regression fixes without adding new functional bug fixes.", "isCorrect": true, "rationale": "RUs increment the minor release version quarterly with new enhancements and fixes, while RURs focus strictly on extending stability via security and regression patches for a specific RU."}, {"text": "Release Updates (RU) are applied exclusively to non-production environments, while Release Update Revisions (RUR) are applied exclusively to CDB$ROOT.", "isCorrect": false, "rationale": "Both RU and RUR patch types are part of the maintenance cycle applicable to CDB and PDB structures across non-production and production environments."}], "hint": "Think about which patch type increments minor release versions versus which focus solely on targeted security and regression stability.", "type": "multiple_choice"}, {"question": "Which initialization parameter is configured under Automatic Shared Memory Management (ASMM) to dynamically balance the Buffer Cache, Shared Pool, and Large Pool?", "answerOptions": [{"text": "processes", "isCorrect": false, "rationale": "The processes parameter determines the maximum number of operating system user processes that can simultaneously connect, rather than memory allocations."}, {"text": "open_cursors", "isCorrect": false, "rationale": "The open_cursors parameter sets the maximum number of open cursors a session can have concurrently, not memory pool sizes."}, {"text": "sga_target", "isCorrect": true, "rationale": "Configuring sga_target under ASMM enables Oracle to automatically adjust memory distributions across the Buffer Cache, Shared Pool, and Large Pool to handle OLTP transaction loads."}, {"text": "pga_aggregate_target", "isCorrect": false, "rationale": "The pga_aggregate_target parameter controls per-process private memory allocation for operations like sort and hash join, rather than SGA pools."}], "hint": "Identify the parameter that specifically targets the System Global Area pool allocations.", "type": "multiple_choice"}, {"question": "What critical operational issue during large batch runs is prevented by properly tuning pga_aggregate_target?", "answerOptions": [{"text": "Buffer cache buffer busy waits during high-volume insert statements.", "isCorrect": false, "rationale": "Buffer busy waits occur when multiple sessions attempt to access the same data block in the Buffer Cache within the SGA."}, {"text": "Temporary tablespace spilling during sort operations and hash joins.", "isCorrect": true, "rationale": "Adequate PGA allocation ensures sorting and hash join operations complete in workarea memory rather than spilling over to disk-based temporary tablespaces."}, {"text": "Exclusive row-locking contention on core application tables.", "isCorrect": false, "rationale": "Row-locking contention is caused by uncommitted transactions or concurrent updates, not PGA memory constraints."}, {"text": "Un-recompiled invalid database objects following a delivery deployment.", "isCorrect": false, "rationale": "Invalid database objects are resolved via compilation maintenance scripts like Light Cleanup rather than memory tuning parameters."}], "hint": "Recall which memory area handles per-process memory for sort and join operations.", "type": "multiple_choice"}, {"question": "In a shared Container Database hosting production and non-production PDBs, how does Oracle Resource Manager prevent lower environments from starving production resources?", "answerOptions": [{"text": "By enforcing CREATE_CDB_PLAN policies that allocate CPU shares and utilization limits at the container level.", "isCorrect": true, "rationale": "Resource Manager plans configured via CREATE_CDB_PLAN establish explicit CPU shares and utilization limits to protect production PDBs from resource consumption spikes in non-production PDBs."}, {"text": "By restricting network connection pool requests exclusively to the primary Application Owner account.", "isCorrect": false, "rationale": "Connection pool management is handled by mid-tier configuration limits, not Resource Manager CPU share policies."}, {"text": "By automatically terminating non-production database sessions when system memory exceeds 80%.", "isCorrect": false, "rationale": "Resource Manager allocates shares and caps limits dynamically rather than executing unhandled session terminations."}, {"text": "By enforcing fine-grained striping across dedicated RECO disk groups.", "isCorrect": false, "rationale": "Striping across disk groups is an Automatic Storage Management (ASM) storage layout design rather than a CPU governance policy."}], "hint": "Consider the specific SQL directive used to construct Resource Manager governance plans across PDBs.", "type": "multiple_choice"}, {"question": "Which combination of database operational limits must be tuned to support concurrent connection pools from IFS mid-tier application servers?", "answerOptions": [{"text": "db_create_file_dest and asm_diskgroups", "isCorrect": false, "rationale": "These parameters govern file creation locations and storage group targets, not application connection pool concurrency limits."}, {"text": "log_archive_dest_1 and standby_file_management", "isCorrect": false, "rationale": "These parameters manage archive log destinations and standby database file synchronization within Data Guard configurations."}, {"text": "open_cursors and processes", "isCorrect": true, "rationale": "Tuning open_cursors and processes ensures the database tier can accommodate concurrent session requests and cursor handles generated by mid-tier connection pools."}, {"text": "audit_trail and recyclebin", "isCorrect": false, "rationale": "These parameters control system auditing options and dropped object retention mechanisms."}], "hint": "Look for parameters controlling maximum process connections and concurrent cursor statements.", "type": "multiple_choice"}, {"question": "Which SQL statement changes an administrative session context from CDB$ROOT to an isolated pluggable database named ifsprod?", "answerOptions": [{"text": "SWITCH DATABASE TO ifsprod;", "isCorrect": false, "rationale": "This statement is invalid syntax for changing container contexts in Oracle Multitenant."}, {"text": "CONNECT TO PDB ifsprod AS SYSDBA;", "isCorrect": false, "rationale": "Container context switching within an active SQL session uses the ALTER SESSION command rather than a CONNECT string command."}, {"text": "ALTER PLUGGABLE DATABASE ifsprod SET CONTEXT;", "isCorrect": false, "rationale": "This command syntax is incorrect for establishing a session container connection."}, {"text": "ALTER SESSION SET CONTAINER = ifsprod;", "isCorrect": true, "rationale": "Executing ALTER SESSION SET CONTAINER changes the session context to the targeted pluggable database container."}], "hint": "Focus on the standard ALTER SESSION clause used to specify a container target.", "type": "multiple_choice"}, {"question": "Which dynamic performance view allows an administrator connected to CDB$ROOT to inspect the open status of all pluggable databases?", "answerOptions": [{"text": "v$instance_pdbs", "isCorrect": false, "rationale": "This is not the standard dynamic performance view used to check pluggable database open modes."}, {"text": "v$containers_list", "isCorrect": false, "rationale": "This view name does not represent the standard Oracle performance view for pluggable verifications."}, {"text": "v$pdbs", "isCorrect": true, "rationale": "Querying v$pdbs lists the container IDs, names, and current open modes (e.g., READ WRITE, MOUNTED) of all pluggable databases."}, {"text": "dba_pdbs", "isCorrect": false, "rationale": "While static data dictionary views contain metadata, v$pdbs is the real-time dynamic performance view showing active open states."}], "hint": "Recall the specific v$ view designed to display PDB names and open modes.", "type": "multiple_choice"}, {"question": "When a target IFS PDB named ifsprod is in MOUNTED state following a restart, which SQL command transitions it to operational status for application transactions?", "answerOptions": [{"text": "ALTER DATABASE ifsprod OPEN READ ONLY;", "isCorrect": false, "rationale": "Opening in READ ONLY mode prevents transactional write operations required for active ERP transactions."}, {"text": "EXECUTE DBMS_PDB.OPEN('ifsprod');", "isCorrect": false, "rationale": "PL/SQL procedure execution is not the required standard DDL statement for opening pluggable databases."}, {"text": "STARTUP PDB ifsprod FORCE;", "isCorrect": false, "rationale": "STARTUP PDB FORCE is a recovery/restart command syntax rather than the standard state transition statement within an active root session."}, {"text": "ALTER PLUGGABLE DATABASE ifsprod OPEN;", "isCorrect": true, "rationale": "The ALTER PLUGGABLE DATABASE <pdb_name> OPEN command changes the PDB state from MOUNTED to OPEN (READ WRITE), enabling transactions."}], "hint": "Identify the standard DDL command targeting a pluggable database to change its state to open.", "type": "multiple_choice"}, {"question": "What is the key objective of aligning Oracle quarterly patch release cycles with IFS update schedules?", "answerOptions": [{"text": "To automatically convert single-instance databases into multi-node RAC clusters.", "isCorrect": false, "rationale": "Clustering transitions are structural infrastructure implementations, not outcomes of patch lifecycle alignment."}, {"text": "To eliminate the requirement for testing patches in non-production environments prior to production rollout.", "isCorrect": false, "rationale": "Patch alignment reinforces structured testing across non-production environments rather than skipping validation steps."}, {"text": "To replace standard RMAN backup routines with automated application patch scripts.", "isCorrect": false, "rationale": "Database backup routines remain mandatory and are independent of software patching alignment strategies."}, {"text": "To coordinate infrastructure maintenance windows across non-production and production environments with application maintenance updates.", "isCorrect": true, "rationale": "Aligning Oracle quarterly patching (RU/RUR) with IFS software release/update cycles ensures stable validation across non-production tiers before applying fixes to production."}], "hint": "Consider why maintenance windows across both the database engine and the ERP application need to be synchronized.", "type": "multiple_choice"}, {"question": "What architectural advantage is provided by placing distinct IFS application environments (such as DEV, TEST, and PROD) into isolated user PDBs under a single CDB?", "answerOptions": [{"text": "They remove the need for system parameters such as open_cursors or processes.", "isCorrect": false, "rationale": "System parameters like open_cursors and processes remain critical for controlling mid-tier connection limits."}, {"text": "They bypass the need for PGA memory configuration by sharing a single execution workarea across all tenants.", "isCorrect": false, "rationale": "PGA memory must still be tuned via pga_aggregate_target to manage per-process memory requirements regardless of tenant layout."}, {"text": "They automatically replicate production data changes to test environments in real time.", "isCorrect": false, "rationale": "Real-time data replication requires Data Guard or replication tools; Multitenant isolation explicitly maintains data separation."}, {"text": "They isolate transactional schema objects and application data while sharing underlying server hardware and background process infrastructure.", "isCorrect": true, "rationale": "Oracle Multitenant enables tenant isolation at the logical schema and tablespace level, allowing distinct environments to co-exist efficiently on shared hardware resources."}], "hint": "Think about how Multitenant architecture optimizes physical server usage while keeping environment data separate.", "type": "multiple_choice"}]}, "10": {"unit": 10, "unitTitle": "Backup, Recovery and Operational Practice", "title": "RMAN Quiz", "questions": [{"question": "Starting in Oracle Database 19c, which feature and its associated RMAN commands have been deprecated with no direct replacement?", "answerOptions": [{"text": "Storage Snapshot Optimization, including commands like ALTER DATABASE BEGIN BACKUP", "isCorrect": false, "rationale": "Storage Snapshot Optimization using database backup mode remains supported, though specific snapshot recovery clauses were deprecated."}, {"text": "Data Recovery Advisor (DRA), including commands like LIST FAILURE, ADVISE FAILURE, REPAIR FAILURE, and CHANGE FAILURE", "isCorrect": true, "rationale": "Oracle Database 19c deprecated the Data Recovery Advisor and its associated RMAN failure commands without providing a replacement feature."}, {"text": "Block Change Tracking (BCT), including commands like ALTER DATABASE ENABLE BLOCK CHANGE TRACKING", "isCorrect": false, "rationale": "Block Change Tracking remains a fully supported feature for accelerating incremental backups in Oracle Database 19c."}, {"text": "Incrementally Updated Backups, including commands like BACKUP FOR RECOVER OF COPY", "isCorrect": false, "rationale": "Incrementally updated backup strategies remain supported in RMAN for rolling forward image copies."}], "hint": "Consider RMAN diagnostic and automated repair commands deprecated in 19c.", "type": "multiple_choice"}, {"question": "In Oracle Database 19c, what is the Oracle-recommended alternative to the deprecated `RECOVER...SNAPSHOT TIME` command when performing storage snapshot recovery?", "answerOptions": [{"text": "Use `FLASHBACK DATABASE TO SNAPSHOT TIME` directly", "isCorrect": false, "rationale": "Flashback Database serves point-in-time state returns using flashback logs rather than storage snapshot media recovery."}, {"text": "Use `RESTORE CONTROLFILE FROM SNAPSHOT TIME` with `RECOVER DATABASE`", "isCorrect": false, "rationale": "Restoring a control file from a snapshot does not replace the required online backup mode workflow recommended by Oracle."}, {"text": "Use `ALTER DATABASE BEGIN/END BACKUP` around snapshot creation followed by `RECOVER...UNTIL TIME`", "isCorrect": true, "rationale": "Oracle recommends putting data files into online backup mode before taking storage snapshots and using point-in-time recovery to an SCN after `END BACKUP` completion."}, {"text": "Use `BACKUP AS COPY` combined with `RECOVER COPY OF DATABASE`", "isCorrect": false, "rationale": "Image copies are an RMAN-managed backup mechanism rather than a third-party storage snapshot method."}], "hint": "Look for the procedure that puts the database into backup mode during snapshot creation.", "type": "multiple_choice"}, {"question": "According to the Oracle Database 19c RMAN documentation, what is the maximum length allowed for an RMAN command on a single line?", "answerOptions": [{"text": "8192 characters", "isCorrect": false, "rationale": "This value exceeds the maximum single-line character length specified in RMAN syntax rules."}, {"text": "4000 characters", "isCorrect": true, "rationale": "RMAN limits single-line command text to 4000 characters, requiring longer commands to be split or span multiple lines."}, {"text": "1024 characters", "isCorrect": false, "rationale": "While a common string limit in some command utilities, RMAN allows single lines up to 4000 characters."}, {"text": "2048 characters", "isCorrect": false, "rationale": "This value is lower than the actual 4000-character single-line limit documented for RMAN statements."}], "hint": "Think about standard single-line character buffer limits in RMAN syntax.", "type": "multiple_choice"}, {"question": "When manually allocating channels within an RMAN `RUN` block, what is the maximum number of channels that can be allocated?", "answerOptions": [{"text": "128 channels", "isCorrect": false, "rationale": "This value is below the maximum capacity limit for manually allocated RMAN channels."}, {"text": "64 channels", "isCorrect": false, "rationale": "The number 64 represents the maximum number of files a single channel can read in parallel, not the total channel limit."}, {"text": "1024 channels", "isCorrect": false, "rationale": "This number exceeds the maximum channel allocation limit supported by RMAN."}, {"text": "255 channels", "isCorrect": true, "rationale": "RMAN permits up to 255 channels to be allocated simultaneously within a single job."}], "hint": "Recall the upper bound on manual channel connections in a single RMAN job.", "type": "multiple_choice"}, {"question": "According to the incident preparation notes for IFS Cloud, which database view holds background deferred job history?", "answerOptions": [{"text": "DEFERRED_JOB", "isCorrect": true, "rationale": "IFS Cloud stores background job execution records and history in the DEFERRED_JOB view."}, {"text": "V$DIAG_ALERT_EXT", "isCorrect": false, "rationale": "This view extracts Oracle diagnostic alert log messages rather than IFS application deferred job entries."}, {"text": "IFS_BACKGROUND_JOB", "isCorrect": false, "rationale": "While logically named, this is not the view name specified for IFS Cloud deferred background jobs."}, {"text": "DBA_SCHEDULER_JOB_RUN_DETAILS", "isCorrect": false, "rationale": "This standard Oracle view tracks Oracle Scheduler jobs rather than IFS application deferred jobs specifically."}], "hint": "Focus on the specific view used in IFS Cloud for tracking background job history.", "type": "multiple_choice"}, {"question": "Based on the Oracle Database 19c Backup and Recovery Reference, when was the desupport of Oracle Secure Backup (OSB) 19.1 announced?", "answerOptions": [{"text": "October 2026", "isCorrect": false, "rationale": "This date reflects the publishing date of the user guide release, not the OSB 19.1 announcement."}, {"text": "May 1, 2026", "isCorrect": true, "rationale": "Documentation explicitly notes that OSB 19.1 desupport was announced on May 1, 2026."}, {"text": "September 30, 2027", "isCorrect": false, "rationale": "September 30, 2027, represents the premier support end date for OSB 19.1, not the announcement date."}, {"text": "November 6, 2026", "isCorrect": false, "rationale": "This timestamp comes from training test session log data rather than product lifecycle notices."}], "hint": "Identify the date specified in the RMAN reference notes regarding OSB 19.1 lifecycle changes.", "type": "multiple_choice"}, {"question": "Which option in the RMAN `BACKUP` command tests data and index blocks that pass physical corruption checks for logical corruption?", "answerOptions": [{"text": "CHECK LOGICAL", "isCorrect": true, "rationale": "Specifying CHECK LOGICAL tests both physical and logical block consistency, recording any detected logical errors to the alert log and trace files."}, {"text": "VALIDATE", "isCorrect": false, "rationale": "The VALIDATE keyword initiates a dry-run check without writing output files, but only performs physical checks unless CHECK LOGICAL is added."}, {"text": "CONSISTENT", "isCorrect": false, "rationale": "CONSISTENT instructs RMAN to create consistent backup sets for databases or PDBs, not block corruption detection."}, {"text": "NOCHECKSUM", "isCorrect": false, "rationale": "NOCHECKSUM disables standard block checksum calculations during backup creation rather than enabling logical tests."}], "hint": "Think of the parameter that expands corruption checks beyond physical block validation.", "type": "multiple_choice"}, {"question": "How does the `@@` (double at sign) command differ from the `@` (at sign) command when executed from inside an RMAN command file?", "answerOptions": [{"text": "It forces RMAN to search strictly in the default Oracle Home directory (`?/dbs`)", "isCorrect": false, "rationale": "The @@ command searches relative to the calling script directory rather than forcing an ORACLE_HOME lookup."}, {"text": "It executes the specified command file in parallel across all allocated channels", "isCorrect": false, "rationale": "Command file invocation syntax does not affect channel allocation or parallel execution."}, {"text": "It bypasses RMAN syntax validation and sends raw SQL to the database instance", "isCorrect": false, "rationale": "RMAN parses all command files using standard RMAN syntax checks regardless of invocation syntax."}, {"text": "It directs RMAN to look for the specified script in the same directory as the calling command file", "isCorrect": true, "rationale": "The @@ command resolves relative file paths relative to the directory containing the current script file."}], "hint": "Consider how relative path resolution works for nested command files.", "type": "multiple_choice"}, {"question": "How many of the most recent backups does the Block Change Tracking (BCT) file retain block change data for before overwriting the oldest bitmap?", "answerOptions": [{"text": "16 most recent backups", "isCorrect": false, "rationale": "Oracle Database overwrites the oldest bitmap once the 8-backup capacity limit is reached."}, {"text": "8 most recent backups", "isCorrect": true, "rationale": "Oracle Database automatically manages space in the change tracking file to store bitmaps covering up to the 8 most recent backups."}, {"text": "4 most recent backups", "isCorrect": false, "rationale": "This number is lower than the actual 8-backup bitmap depth managed by Block Change Tracking."}, {"text": "32 most recent backups", "isCorrect": false, "rationale": "This value exceeds the maximum historical bitmap capacity supported in the change tracking file."}], "hint": "Identify the maximum number of historical backup bitmaps managed inside the change tracking file.", "type": "multiple_choice"}, {"question": "Which RMAN `REPORT` command identifies data files that lack sufficient backups to satisfy a specific time-based retention requirement?", "answerOptions": [{"text": "`REPORT NEED BACKUP RECOVERY WINDOW OF n DAYS`", "isCorrect": true, "rationale": "This command reports data files that do not have sufficient backups to perform point-in-time recovery across the specified number of days."}, {"text": "`REPORT OBSOLETE RECOVERY WINDOW OF n DAYS`", "isCorrect": false, "rationale": "REPORT OBSOLETE identifies backups that are no longer needed, whereas REPORT NEED BACKUP identifies files lacking coverage."}, {"text": "`REPORT SCHEMA UNRECOVERABLE n DAYS`", "isCorrect": false, "rationale": "REPORT SCHEMA lists data files and tablespaces at a given time point, not missing backup windows."}, {"text": "`REPORT NEED BACKUP REDUNDANCY n DAYS`", "isCorrect": false, "rationale": "Redundancy filtering evaluates the total count of existing backup copies rather than measuring a time window."}], "hint": "Look for the clause under `REPORT NEED BACKUP` that checks against a target timeframe.", "type": "multiple_choice"}, {"question": "According to the incident review preparation document, which diagnostic view can be queried directly by a DBA to check for ORA- errors and deadlocks without requiring Diagnostic or Tuning Pack licenses?", "answerOptions": [{"text": "V$DIAG_ALERT_EXT", "isCorrect": true, "rationale": "V$DIAG_ALERT_EXT exposes alert log messages directly from the diagnostic repository without requiring optional pack licenses."}, {"text": "V$RMAN_OUTPUT", "isCorrect": false, "rationale": "V$RMAN_OUTPUT records memory-buffered RMAN command outputs rather than database alert logs."}, {"text": "DBA_HIST_ACTIVE_SESS_HISTORY", "isCorrect": false, "rationale": "DBA_HIST views belong to the AWR repository and require an Oracle Diagnostics Pack license."}, {"text": "V$SESSION_LONGOPS", "isCorrect": false, "rationale": "V$SESSION_LONGOPS tracks long-running database operations rather than searching alert log messages."}], "hint": "Think of the diagnostic view exposed directly from the Automatic Diagnostic Repository.", "type": "multiple_choice"}, {"question": "Which subclause of the `BACKUP` command creates a cross-platform consistent backup of a PDB while storing the plug-in metadata into a specified XML file?", "answerOptions": [{"text": "`FOR TRANSPORT UNPLUG INTO 'filename'`", "isCorrect": true, "rationale": "This subclause creates a consistent cross-platform backup set of a closed PDB and saves its plug-in metadata to an XML file."}, {"text": "`TO PLATFORM EXPORT XML 'filename'`", "isCorrect": false, "rationale": "TO PLATFORM specifies target platform conversion options, but does not use EXPORT XML syntax."}, {"text": "`ALLOW INCONSISTENT UNPLUG 'filename'`", "isCorrect": false, "rationale": "ALLOW INCONSISTENT allows online tablespace backups during cross-platform transport rather than closed PDB unplugs."}, {"text": "`DATAPUMP UNPLUG METADATA 'filename'`", "isCorrect": false, "rationale": "DATAPUMP exports metadata for transportable tablespace sets rather than whole PDB unplug operations."}], "hint": "Look for the command option that unplugs the PDB into a target metadata file during cross-platform backup.", "type": "multiple_choice"}]}, "2": {"unit": 2, "unitTitle": "Multitenant Database Administration: CDB and PDB", "title": "Oracle Multitenant Quiz", "questions": [{"question": "What is the primary structural role of the root container database (CDB$ROOT) in an Oracle Multitenant architecture?", "answerOptions": [{"text": "It enforces connection pool parameters exclusively for mid-tier application sessions.", "isCorrect": false, "rationale": "Mid-tier application connection pools interact directly with dedicated PDB services rather than managing root settings."}, {"text": "It functions as a system-supplied template used to provision new pluggable databases.", "isCorrect": false, "rationale": "The system-supplied template for provisioning new containers is PDB$SEED, not CDB$ROOT."}, {"text": "It stores dedicated application schemas and tablespaces for individual IFS tenant environments.", "isCorrect": false, "rationale": "User-created application schemas and tablespaces reside within individual User PDBs rather than the root container."}, {"text": "It stores Oracle system metadata, common user accounts, and global initialization parameters.", "isCorrect": true, "rationale": "The root container centrally manages Oracle system metadata, common users, and global memory/background processes for the entire CDB."}], "hint": "Consider where global database initialization parameters and common user accounts reside versus application-specific data.", "type": "multiple_choice"}, {"question": "In an Oracle Multitenant environment supporting IFS Applications, what is the specific role of PDB$SEED?", "answerOptions": [{"text": "It serves as a system-supplied template PDB used to rapidly provision new pluggable databases.", "isCorrect": true, "rationale": "Oracle Multitenant includes PDB$SEED specifically as a template for rapidly creating additional PDB instances."}, {"text": "It stores mid-tier connection configurations to prevent session leakage between environments.", "isCorrect": false, "rationale": "Mid-tier context switching and connection isolation are managed by service routing and PDB isolation, not PDB$SEED."}, {"text": "It manages global background processes and shared SGA allocations across host memory.", "isCorrect": false, "rationale": "Global background processes and shared memory structures are managed by CDB$ROOT."}, {"text": "It contains active production ERP transaction data and user schemas.", "isCorrect": false, "rationale": "Active production schemas and business transaction data reside within dedicated User PDBs."}], "hint": "Think about how new PDBs are rapidly provisioned when adding environments to a multitenant structure.", "type": "multiple_choice"}, {"question": "Which sys_context call retrieves the name of the current container for an active database session?", "answerOptions": [{"text": "sys_context('DATABASE', 'PDB_NAME')", "isCorrect": false, "rationale": "The namespace DATABASE is invalid for container identification in Oracle environment context calls."}, {"text": "sys_context('USERENV', 'DB_NAME')", "isCorrect": false, "rationale": "The parameter DB_NAME returns the global database name rather than the specific container name in context."}, {"text": "sys_context('USERENV', 'CON_NAME')", "isCorrect": true, "rationale": "The USERENV namespace parameter CON_NAME returns the exact name of the container context associated with the active session."}, {"text": "sys_context('SESSION', 'CONTAINER_ID')", "isCorrect": false, "rationale": "Retrieving container attributes requires querying the standard USERENV namespace with parameters such as CON_NAME or CON_ID."}], "hint": "Focus on the USERENV namespace attributes used to identify container names.", "type": "multiple_choice"}, {"question": "Which pair of memory parameters can be configured per PDB to prevent runaway queries from exhausting host memory?", "answerOptions": [{"text": "common_user_prefix and global_names", "isCorrect": false, "rationale": "These settings relate to naming conventions and global database identification, not memory resource management."}, {"text": "sga_target and pga_aggregate_limit", "isCorrect": true, "rationale": "Setting sga_target and pga_aggregate_limit on a PDB establishes explicit memory boundaries to protect host resources from non-production workloads."}, {"text": "open_mode and container_id", "isCorrect": false, "rationale": "These attributes represent operational state and container identification numbers in dynamic views, not configurable memory limits."}, {"text": "db_create_file_dest and log_archive_dest", "isCorrect": false, "rationale": "These parameters govern file system storage locations and redo log archiving destinations rather than memory caps."}], "hint": "Think about SGA and PGA allocation settings used to restrict memory per container.", "type": "multiple_choice"}, {"question": "Which dynamic performance view is queried to inspect container IDs, names, and open modes for pluggable databases?", "answerOptions": [{"text": "v$instance", "isCorrect": false, "rationale": "The v$instance view provides status and operational state for the database instance as a whole rather than individual PDBs."}, {"text": "v$containers", "isCorrect": false, "rationale": "The source material specifically demonstrates checking pluggable database states using v$pdbs."}, {"text": "v$pdbs", "isCorrect": true, "rationale": "The v$pdbs view provides container IDs, PDB names, and their operational open modes."}, {"text": "v$session", "isCorrect": false, "rationale": "While v$session tracks active user sessions and session container IDs, it does not list pluggable database structures and open modes."}], "hint": "Recall the dynamic performance view specifically named after pluggable databases.", "type": "multiple_choice"}, {"question": "Which SQL command successfully switches an administrative session's context from CDB$ROOT to a pluggable database named ifsprod?", "answerOptions": [{"text": "CONNECT / AS SYSDBA CONTAINER = ifsprod;", "isCorrect": false, "rationale": "The CONNECT command syntax does not accept a CONTAINER keyword clause in this manner; context switching occurs via ALTER SESSION."}, {"text": "ALTER SYSTEM SET CONTAINER = ifsprod;", "isCorrect": false, "rationale": "The ALTER SYSTEM statement modifies system-wide initialization parameters rather than session-level container contexts."}, {"text": "ALTER PLUGGABLE DATABASE ifsprod OPEN;", "isCorrect": false, "rationale": "This command modifies the operational state of the PDB to open it for connections, but it does not alter the active session container context."}, {"text": "ALTER SESSION SET CONTAINER = ifsprod;", "isCorrect": true, "rationale": "Executing ALTER SESSION SET CONTAINER switches the current session context to the targeted PDB."}], "hint": "Look for the ALTER statement used to adjust session-level environment settings.", "type": "multiple_choice"}, {"question": "In an Oracle Multitenant database, where are user-created tables, indexes, and application-specific metadata stored?", "answerOptions": [{"text": "In the private data dictionary of each dedicated User PDB.", "isCorrect": true, "rationale": "Each User PDB maintains its own private data dictionary to isolate application schemas, tables, and indexes from other tenants."}, {"text": "In the central CDB$ROOT system catalog.", "isCorrect": false, "rationale": "CDB$ROOT manages system metadata and common objects across the container database, not individual application user schemas."}, {"text": "In global SGA shared memory structures accessible by all containers.", "isCorrect": false, "rationale": "Data dictionary definitions are stored within container-specific tablespaces on disk, not merely in volatile shared memory."}, {"text": "In the PDB$SEED template dictionary.", "isCorrect": false, "rationale": "PDB$SEED is a read-only template database used exclusively for provisioning new PDBs."}], "hint": "Recall where independent schema objects and user tables reside versus common system metadata.", "type": "multiple_choice"}, {"question": "How can database administrators control CPU shares, parallel execution queues, and session limits for specific PDBs?", "answerOptions": [{"text": "By assigning PDB Resource Manager Profiles.", "isCorrect": true, "rationale": "PDB Resource Manager Profiles allow administrators to enforce specific allocations of CPU, parallel execution queues, and session thresholds per container."}, {"text": "By consolidating all transactional schemas into CDB$ROOT.", "isCorrect": false, "rationale": "Consolidating schemas into CDB$ROOT breaks multitenant isolation and does not provide per-PDB resource controls."}, {"text": "By setting open_mode to read-only across all non-production instances.", "isCorrect": false, "rationale": "Changing open modes restricts write access but does not regulate CPU allocation or parallel execution queues for active sessions."}, {"text": "By creating unique PDB$SEED templates for every environment.", "isCorrect": false, "rationale": "Templates facilitate rapid provisioning but do not manage runtime CPU or session execution limits."}], "hint": "Consider the profiles used to restrict CPU, parallel queues, and session limits per container.", "type": "multiple_choice"}, {"question": "What lifecycle advantage does pluggable database isolation offer when performing maintenance on individual IFS environments?", "answerOptions": [{"text": "Updating one PDB automatically updates the database kernel across all host servers.", "isCorrect": false, "rationale": "PDB operations isolate schema and lifecycle tasks; they do not automatically modify underlying host kernels."}, {"text": "PDB isolation requires all non-production environments to be shut down whenever Release Updates are applied to CDB$ROOT.", "isCorrect": false, "rationale": "Multitenant architecture simplifies patch alignment while preserving independent lifecycle management per PDB."}, {"text": "DBAs can unplug, clone, or drop an individual PDB without interrupting operations on sibling PDBs.", "isCorrect": true, "rationale": "Logical and operational isolation allows independent maintenance tasks on one PDB without impacting sibling PDBs on the same container database."}, {"text": "Dropping a PDB deletes common user accounts centrally maintained in CDB$ROOT.", "isCorrect": false, "rationale": "Common user accounts are stored in CDB$ROOT and remain intact even if individual User PDBs are dropped."}], "hint": "Think about how tenant isolation affects maintenance tasks on sibling containers.", "type": "multiple_choice"}, {"question": "Why is resource management critical across PDBs in a shared physical hardware environment supporting IFS Applications?", "answerOptions": [{"text": "To force all test scripts to execute directly inside CDB$ROOT.", "isCorrect": false, "rationale": "Test scripts and non-production instances must run in isolated PDBs to avoid contaminating central system metadata or production data."}, {"text": "To automate the synchronization of Release Updates between DEV and PROD data dictionaries.", "isCorrect": false, "rationale": "Resource management governs host resource consumption (CPU, SGA/PGA), not release update dictionary synchronization."}, {"text": "To prevent non-production workloads from degrading critical OLTP Production performance.", "isCorrect": true, "rationale": "Resource management caps memory, CPU, and process usage on non-production containers to safeguard production ERP transactions from resource starvation."}, {"text": "To ensure that all PDBs consume identical memory limits regardless of workload size.", "isCorrect": false, "rationale": "Resource management allows precise, custom allocation of memory and CPU shares per container rather than uniform caps."}], "hint": "Focus on the primary operational goal of separating non-production workloads from production OLTP environments.", "type": "multiple_choice"}]}, "3": {"unit": 3, "unitTitle": "Release Lifecycle and Patching: RU, RUR and Upgrades", "title": "Oracle Quiz", "questions": [{"question": "In the Oracle Database patching lifecycle, what primary content distinguishes a Release Update Revision (RUR) from a standard Release Update (RU)?", "answerOptions": [{"text": "RURs deliver strictly critical security fixes and regression fixes for a specific RU without incorporating new functional bug fixes from subsequent RUs.", "isCorrect": true, "rationale": "RURs are designed to extend an existing RU's lifespan by providing essential security and regression fixes while maintaining stability."}, {"text": "RURs modify major release numbers, while RUs only increment the database patch revision digit.", "isCorrect": false, "rationale": "RUs increment the minor release version number, whereas RURs increment the patch revision digit."}, {"text": "RURs include new functional bug fixes from subsequent RUs, whereas RUs only contain security patches.", "isCorrect": false, "rationale": "Release Updates (RUs) contain new functional bug fixes alongside security patches, whereas RURs exclude new functional bug fixes from subsequent RUs."}, {"text": "RURs replace binary files in $ORACLE_HOME without requiring datapatch to update SQL dictionary metadata.", "isCorrect": false, "rationale": "Both RUs and RURs require running datapatch to update data dictionary metadata after applying binary updates."}], "hint": "Think about which patch type is designed to extend an existing RU's lifespan with minimal functional change.", "type": "multiple_choice"}, {"question": "How does applying a Release Update Revision (RUR) impact the Oracle Database version string compared to applying a Release Update (RU)?", "answerOptions": [{"text": "Applying an RU increments the minor version digit (e.g., 19.11 to 19.12), whereas an RUR increments the revision digit (e.g., 19.11.0 to 19.11.1).", "isCorrect": true, "rationale": "RUs advance the database minor version, whereas RURs track maintenance iterations of a specific baseline RU."}, {"text": "Applying an RU increments the revision digit, while an RUR increments the minor version digit.", "isCorrect": false, "rationale": "RUs increment the minor release version (such as 19.11 to 19.12), whereas RURs increment the revision digit."}, {"text": "Applying an RU increments the major release version, while an RUR increments the minor release version.", "isCorrect": false, "rationale": "Major release version upgrades represent separate database releases rather than quarterly patch updates."}, {"text": "Applying an RUR removes the version string completely from the dba_registry_sqlpatch view.", "isCorrect": false, "rationale": "Database view dba_registry_sqlpatch records and displays detailed version and patch registry entries for both RUs and RURs."}], "hint": "Consider which digit changes when staying on a baseline RU while applying critical maintenance revisions.", "type": "multiple_choice"}, {"question": "During the two-stage Oracle Database patching process, what is the primary role of the datapatch utility?", "answerOptions": [{"text": "It automates the upgrade of the OPatch binary utility to its minimum required version.", "isCorrect": false, "rationale": "DBAs must manually update OPatch to the minimum version specified in the patch Readme before running patch commands."}, {"text": "It updates SQL metadata, data dictionary objects, and PL/SQL packages inside CDB$ROOT and all pluggable databases after reopening the database.", "isCorrect": true, "rationale": "Datapatch automates post-patch SQL execution against data dictionary objects once the database is open."}, {"text": "It performs pre-patch conflict detection against active background processes while the database is mounted.", "isCorrect": false, "rationale": "Conflict detection is an opatch pre-installation check performed prior to stopping services and applying binaries."}, {"text": "It replaces executable binaries, libraries, and header files inside $ORACLE_HOME while database services are stopped.", "isCorrect": false, "rationale": "Binary replacement within the Oracle home is performed by opatch apply while database services are down."}], "hint": "Recall which step occurs after binary patching has finished and database services are started.", "type": "multiple_choice"}, {"question": "Which prerequisite action must a database administrator perform prior to executing binary patch installation using opatch apply?", "answerOptions": [{"text": "Convert the Oracle ASFU database license to an FU license to grant binary modification permissions.", "isCorrect": false, "rationale": "Licensing models govern usage rights and third-party access, not binary patching mechanics."}, {"text": "Compile all PL/SQL packages across all pluggable databases using Oracle Data Pump.", "isCorrect": false, "rationale": "Data Pump is used for data migration and export/import rather than pre-patch validation."}, {"text": "Execute datapatch while the database is shut down to clear existing patch registry entries.", "isCorrect": false, "rationale": "Datapatch requires the database to be open and cannot run while database services are down."}, {"text": "Verify that OPatch meets the minimum required version in the Readme and perform conflict detection against $ORACLE_HOME.", "isCorrect": true, "rationale": "Ensuring OPatch version compatibility and running conflict checks prevents partial patch applications and software issues."}], "hint": "Consider what must be checked regarding the patching tool itself and existing software components before stopping services.", "type": "multiple_choice"}, {"question": "Which database views allow a database administrator to inspect and confirm applied RU or RUR revision history in an Oracle Database environment?", "answerOptions": [{"text": "registry$history and dba_registry_sqlpatch", "isCorrect": true, "rationale": "These views maintain records of applied patch histories, SQL patch execution statuses, and database registry updates."}, {"text": "v$instance and v$database", "isCorrect": false, "rationale": "Views v$instance and v$database show general database instance status but do not track detailed SQL patch execution history."}, {"text": "opatch_log_history and dba_patch_conflicts", "isCorrect": false, "rationale": "These are not valid system views for inspecting applied database SQL patches."}, {"text": "dba_tablespaces and dba_data_files", "isCorrect": false, "rationale": "These catalog views store physical storage layout details rather than software patching registry information."}], "hint": "Look for dictionary views specifically dedicated to registry history and SQL patch information.", "type": "multiple_choice"}, {"question": "According to the patching lifecycle guidelines for IFS/Oracle environments, what is the primary recommendation for production systems with strict change-management policies?", "answerOptions": [{"text": "Deploy RUs exclusively in production while applying RURs in non-production development environments.", "isCorrect": false, "rationale": "RUs are recommended for non-production environments to test and validate functional updates before major upgrades."}, {"text": "Skip binary patching entirely and apply SQL updates only via datapatch.", "isCorrect": false, "rationale": "Binary patching with opatch apply is required to update underlying executables before SQL scripts can be run."}, {"text": "Apply Release Update Revisions (RURs) to lock core execution behavior while maintaining security compliance between major upgrade windows.", "isCorrect": true, "rationale": "RURs deliver critical security and regression fixes without altering broad application behavior or query execution plans."}, {"text": "Apply Release Updates (RUs) quarterly to introduce new functional enhancements immediately.", "isCorrect": false, "rationale": "Broad functional changes in RUs increase execution plan variance, making them less ideal for locked production baselines."}], "hint": "Reflect on which strategy minimizes change scope and execution plan variance for mission-critical production systems.", "type": "multiple_choice"}, {"question": "According to the table of contents of Oracle Database Database Upgrade Guide 19c, which tool is featured in Chapter 3 for database upgrades?", "answerOptions": [{"text": "Oracle Data Pump", "isCorrect": false, "rationale": "Data migration using Oracle Data Pump is covered in Chapter 9."}, {"text": "Parallel Upgrade Utility", "isCorrect": false, "rationale": "Manual upgrades using Parallel Upgrade Utility are detailed in Chapter 4."}, {"text": "Database Upgrade Assistant (DBUA)", "isCorrect": false, "rationale": "Upgrading with Database Upgrade Assistant (DBUA) is covered in Appendix C."}, {"text": "AutoUpgrade", "isCorrect": true, "rationale": "Chapter 3 is dedicated to using AutoUpgrade for Oracle Database upgrades."}], "hint": "Appendix C covers DBUA and Chapter 4 covers the Parallel Upgrade Utility, so think about what Chapter 3 specifically focuses on.", "type": "multiple_choice"}, {"question": "In Procedure 3 of cloud database migration for SAP on Oracle, which RMAN command creates an exact copy of the source database in the cloud without requiring a backup buffer?", "answerOptions": [{"text": "opatch apply", "isCorrect": false, "rationale": "The opatch apply command is used for applying software patches to an Oracle home, not database copying."}, {"text": "duplicate database from active database", "isCorrect": true, "rationale": "RMAN duplicate database from active database transfers data over the network directly from the active source to the target."}, {"text": "brbackup", "isCorrect": false, "rationale": "The brbackup tool relies on backup files staged on file systems or cloud object storage."}, {"text": "cross platform transportable tablespaces", "isCorrect": false, "rationale": "Transportable tablespaces require staging backup files and metadata exports to a shared filesystem."}], "hint": "This procedure allows building an active copy directly over the network without stage-buffering export files or backups.", "type": "multiple_choice"}, {"question": "Which procedure should be used when migrating an SAP Oracle database to Oracle Cloud Infrastructure across platforms with different endian types?", "answerOptions": [{"text": "RMAN cross platform transportable tablespaces command", "isCorrect": true, "rationale": "Cross platform transportable tablespaces enable data movement between platforms with differing endianness."}, {"text": "BR*Tools brbackup with Object Storage", "isCorrect": false, "rationale": "Standard BR*Tools backup and restore requires compatible operating system platform types."}, {"text": "RMAN duplicate database from active database", "isCorrect": false, "rationale": "Direct active database duplication requires compatible source and target platform endian formats."}, {"text": "OPatch binary staging procedure", "isCorrect": false, "rationale": "OPatch updates executable software binaries in an Oracle home rather than migrating user database data across platforms."}], "hint": "Focus on the RMAN feature specifically designed to handle platform architecture differences like endianness.", "type": "multiple_choice"}, {"question": "Which cloud database migration method for SAP on Oracle enables a transparent database upgrade as part of the data movement process?", "answerOptions": [{"text": "OPatch binary replacement method", "isCorrect": false, "rationale": "OPatch applies interim patches and updates to an existing release rather than performing database release upgrades."}, {"text": "Oracle Lifecycle Migration Service (O2O / OOO)", "isCorrect": true, "rationale": "O2O creates a new target database in the cloud, allowing transparent database upgrades during data transfer."}, {"text": "Procedure 1 (RMAN via Object Storage)", "isCorrect": false, "rationale": "Procedure 1 performs standard restore and recovery without executing transparent database version upgrades."}, {"text": "RMAN duplicate database from active database", "isCorrect": false, "rationale": "Database duplication creates an exact replica and does not support release upgrades during the duplication process."}], "hint": "This service generates custom scripts to create a target database, allowing structural and feature adjustments during migration.", "type": "multiple_choice"}, {"question": "What key functional difference distinguishes an Oracle Database with an Application Specific Full Use (ASFU) license from one with a Full Use (FU) license?", "answerOptions": [{"text": "ASFU databases cannot be deployed on Oracle Exadata hardware.", "isCorrect": false, "rationale": "ASFU databases are fully supported on Oracle Exadata systems and Oracle Cloud Infrastructure."}, {"text": "ASFU databases lack support for Oracle Advanced Security encryption features.", "isCorrect": false, "rationale": "Oracle Advanced Security encryption is fully included in the SAP ASFU database license."}, {"text": "ASFU databases may only be used by SAP ECC/NetWeaver applications, whereas FU databases allow access by non-SAP tools and third-party applications.", "isCorrect": true, "rationale": "ASFU licensing restricts direct database access exclusively to the bundled SAP application suite."}, {"text": "ASFU license fees are calculated per processor core, whereas FU licenses are based on SAP contract percentages.", "isCorrect": false, "rationale": "ASFU fees are calculated as a fixed percentage of the SAP contract, whereas FU licensing is based on processor cores."}], "hint": "Consider how license scope affects access to data from non-SAP software.", "type": "multiple_choice"}, {"question": "What benefit is gained by incorporating Oracle GoldenGate into the Oracle Lifecycle Migration Service (changing O2O into the OOO procedure)?", "answerOptions": [{"text": "It eliminates the requirement to execute post-patch SQL automation via datapatch.", "isCorrect": false, "rationale": "Datapatch remains mandatory for updating dictionary metadata after binary patching regardless of data replication."}, {"text": "It performs automatic cross-platform byte swapping without pausing database operations.", "isCorrect": false, "rationale": "Byte swapping is handled by RMAN transportable tablespaces, not GoldenGate replication."}, {"text": "It automatically converts an ASFU database license into a public cloud FU subscription.", "isCorrect": false, "rationale": "GoldenGate is a replication technology and does not alter database license classification rules."}, {"text": "It captures changes made during data transfer, enabling online migration and reducing SAP downtime to a short switchover.", "isCorrect": true, "rationale": "GoldenGate continuously replicates transactions so that the application remains online until the final switchover."}], "hint": "GoldenGate's real-time data replication allows application activity to continue while initial data movement is taking place.", "type": "multiple_choice"}]}, "4": {"unit": 4, "unitTitle": "Storage, ASM and Capacity Management", "title": "Oracle Storage", "questions": [{"question": "In Oracle Automatic Storage Management (ASM), which striping configuration and Allocation Unit (AU) subdivision pattern is assigned to Online Redo Logs (ORLs), Control Files, and Flashback Logs?", "answerOptions": [{"text": "Coarse-grained striping with 128 KB Allocation Units optimized for RMAN backup sets", "isCorrect": false, "rationale": "Coarse-grained striping uses full Allocation Units rather than 128 KB subdivisions, and RMAN backups use coarse-grained striping."}, {"text": "Fine-grained striping with 1 MB Allocation Units optimized for parallel database table scans", "isCorrect": false, "rationale": "Fine-grained striping subdivides Allocation Units into 128 KB chunks rather than whole 1 MB blocks."}, {"text": "Coarse-grained striping with full 1 MB to 4 MB Allocation Units optimized for large sequential reads", "isCorrect": false, "rationale": "Coarse-grained striping uses full Allocation Units of 1 MB or larger and is intended for sequential files like data files and RMAN backups."}, {"text": "Fine-grained striping with 128 KB stripe sets optimized for low-latency write operations", "isCorrect": true, "rationale": "Fine-grained striping breaks Allocation Units into 128 KB stripe sets to distribute rapid, small-payload concurrent write operations across physical devices."}], "hint": "Consider which striping strategy subdivides Allocation Units into smaller 128 KB chunks to handle rapid, small write operations.", "type": "multiple_choice"}, {"question": "Which failure group configuration and mirroring strategy defines High Redundancy in Oracle ASM?", "answerOptions": [{"text": "3-way mirroring requiring a minimum of three Failure Groups", "isCorrect": true, "rationale": "High Redundancy enforces 3-way mirroring across at least three Failure Groups, making it standard for mission-critical IFS setups."}, {"text": "Delegated hardware-level RAID 10 mirroring with zero Failure Groups", "isCorrect": false, "rationale": "Delegating protection entirely to underlying enterprise SAN controllers without ASM mirroring represents External Redundancy."}, {"text": "2-way mirroring requiring a minimum of two Failure Groups", "isCorrect": false, "rationale": "Two-way mirroring across a minimum of two Failure Groups defines Normal Redundancy rather than High Redundancy."}, {"text": "4-way mirroring requiring a minimum of two Failure Groups", "isCorrect": false, "rationale": "ASM High Redundancy specifies 3-way mirroring and requires at least three distinct Failure Groups."}], "hint": "Think about the number of data copies created in mission-critical environments needing protection against multiple failures.", "type": "multiple_choice"}, {"question": "According to ASM disk group architecture guidelines for IFS Applications, which files should be placed in the RECO disk group to isolate recovery operations from core transactional disk I/O?", "answerOptions": [{"text": "Archive logs, RMAN backup sets, control file copies, Flashback logs, and multiplexed copies of online redo logs", "isCorrect": true, "rationale": "The RECO (or FRA) disk group is dedicated to recovery assets to prevent archive and backup processes from competing for primary transactional bandwidth."}, {"text": "Primary online redo log groups, active index tablespaces, and user tablespace data files", "isCorrect": false, "rationale": "Active tablespaces and primary online redo logs reside in DATA to maintain high transactional throughput."}, {"text": "System tablespaces, temporary files, and primary operational data files only", "isCorrect": false, "rationale": "System and temporary data files are active operational assets assigned to the DATA disk group."}, {"text": "Active data files, index tablespaces, system tablespaces (SYSTEM, SYSAUX), and temporary files", "isCorrect": false, "rationale": "Primary database assets supporting active online processing belong in the DATA disk group."}], "hint": "Focus on storage files specifically used for backup, historical recovery, and archive tracking.", "type": "multiple_choice"}, {"question": "What is the primary operational objective of implementing Hash Partitioning on high-concurrency staging or interface tables in an IFS database?", "answerOptions": [{"text": "To distribute data evenly across a specified number of partitions and prevent I/O hotspots", "isCorrect": true, "rationale": "Hash partitioning applies a hashing algorithm on key columns to spread writes uniformly, eliminating physical disk bottlenecks on write-heavy tables."}, {"text": "To group rows into partitions based on discrete ranges of transaction timestamps", "isCorrect": false, "rationale": "Mapping rows by date ranges describes Range Partitioning rather than Hash Partitioning."}, {"text": "To allow instant removal of historical partitions without performing SQL DELETE operations", "isCorrect": false, "rationale": "Instant dropping of old chronological data partitions is an operational benefit of Range Partitioning."}, {"text": "To organize rows explicitly by categorical business units or regional site codes", "isCorrect": false, "rationale": "Assigning data by specific discrete key values represents List Partitioning."}], "hint": "Recall which partitioning algorithm spreads incoming rows uniformly to avoid single-disk bottlenecks.", "type": "multiple_choice"}, {"question": "How do Local Indexes behave during Partition Maintenance Operations (PMO), such as dropping or splitting a table partition?", "answerOptions": [{"text": "They span all table partitions independently and lock the entire table during maintenance", "isCorrect": false, "rationale": "Local indexes do not span across all partitions independently; each index partition corresponds to exactly one table partition."}, {"text": "They require manual conversion into global indexes prior to executing any maintenance command", "isCorrect": false, "rationale": "Local indexes maintain their partitioned alignment automatically during maintenance commands."}, {"text": "They become UNUSABLE across all partitions and require a mandatory full index rebuild", "isCorrect": false, "rationale": "Global indexes, rather than local indexes, typically require rebuilding or maintenance after specific partition operations."}, {"text": "They update automatically in alignment with table partitions without rebuilding the entire index tree", "isCorrect": true, "rationale": "Local indexes share the partitioning schema of the target table, allowing individual index partition maintenance without invalidating the rest of the index tree."}], "hint": "Consider how index structure alignment with underlying partitions affects maintenance overhead.", "type": "multiple_choice"}, {"question": "In Oracle Enterprise Manager (OEM) metric threshold management, what standard utilization percentages are recommended for Warning and Critical alerts on storage targets?", "answerOptions": [{"text": "75% capacity for Warning Thresholds and 90% capacity for Critical Thresholds", "isCorrect": false, "rationale": "Standard storage administration baselines in OEM utilize 85% for early warning and 95% for urgent intervention."}, {"text": "85% capacity for Warning Thresholds and 95% capacity for Critical Thresholds", "isCorrect": true, "rationale": "Setting warning alerts at 85% and critical alerts at 95% enables proactive capacity expansion before complete storage exhaustion occurs."}, {"text": "90% capacity for Warning Thresholds and 99% capacity for Critical Thresholds", "isCorrect": false, "rationale": "A 90% warning threshold leaves inadequate time for planned maintenance compared to the standard 85% threshold."}, {"text": "80% capacity for Warning Thresholds and 100% capacity for Critical Thresholds", "isCorrect": false, "rationale": "Critical thresholds are established at 95% so DBAs can act before reaching 100% capacity and suffering database halts."}], "hint": "Identify the standard two percentage boundaries that provide early maintenance notice and urgent outage prevention.", "type": "multiple_choice"}, {"question": "Which PL/SQL procedure and metric constant are used to programmatically register tablespace warning and critical alert boundaries in Oracle Database?", "answerOptions": [{"text": "DBMS_STORAGE_MGMT.SET_ALERT with DBMS_STORAGE_MGMT.TABLESPACE_USAGE", "isCorrect": false, "rationale": "Oracle Database utilizes the DBMS_SERVER_ALERT package rather than a non-existent DBMS_STORAGE_MGMT package."}, {"text": "DBMS_MONITOR.SET_ALERT_THRESHOLD with DBMS_MONITOR.SPACE_LIMIT", "isCorrect": false, "rationale": "The DBMS_MONITOR package is used for application tracing and statistics gathering, not for setting tablespace alerts."}, {"text": "DBMS_SERVER_ALERT.SET_THRESHOLD with DBMS_SERVER_ALERT.TABLESPACE_SPACE_USAGE", "isCorrect": true, "rationale": "Executing DBMS_SERVER_ALERT.SET_THRESHOLD with the TABLESPACE_SPACE_USAGE metric constant configures automated alerts for logical tablespace capacity."}, {"text": "DBMS_ASM_ALERT.MODIFY_THRESHOLD with DBMS_ASM_ALERT.DISK_FREE_SPACE", "isCorrect": false, "rationale": "Logical tablespace thresholds inside the database engine are maintained via DBMS_SERVER_ALERT."}], "hint": "Look for the server alert package that manages database threshold parameters.", "type": "multiple_choice"}, {"question": "Which dynamic performance view can a DBA query when connected to an ASM instance (+ASM) to inspect total MB, free MB, and redundancy models across disk groups?", "answerOptions": [{"text": "V$ASM_ALIAS", "isCorrect": false, "rationale": "V$ASM_ALIAS maps user-defined file names and aliases to internal ASM file numbers."}, {"text": "V$ASM_DISKGROUP", "isCorrect": true, "rationale": "Querying V$ASM_DISKGROUP returns capacity metrics, free space, Allocation Unit sizes, and redundancy settings for all mounted ASM disk groups."}, {"text": "DBA_THRESHOLDS", "isCorrect": false, "rationale": "DBA_THRESHOLDS displays alert threshold parameters registered in the database, not physical ASM storage metrics."}, {"text": "V$ASM_FILE", "isCorrect": false, "rationale": "V$ASM_FILE details individual file striping, space consumption, and file types rather than aggregate disk group totals."}], "hint": "Select the view whose name directly references aggregate ASM disk group metrics.", "type": "multiple_choice"}, {"question": "According to technical documentation for IFS Cloud (Release 25R1), what structural limitation applies when deploying Oracle Database Standard Edition 2?", "answerOptions": [{"text": "It is limited to 1 CDB, 3 PDBs, and 16 threads", "isCorrect": true, "rationale": "IFS Cloud documentation specifies that Standard Edition 2 deployment is limited to 1 Container Database, up to 3 Pluggable Databases, and a maximum of 16 threads."}, {"text": "It is restricted strictly to non-production development environments", "isCorrect": false, "rationale": "Oracle Database Express Edition (XE), not Standard Edition 2, is documented as restricted strictly to development usage."}, {"text": "It is limited to 1 CDB, 1 PDB, and 8 threads", "isCorrect": false, "rationale": "Standard Edition 2 support guidelines permit up to 3 PDBs and 16 threads."}, {"text": "It requires an extra license for Oracle RAC One Node in all environments", "isCorrect": false, "rationale": "Oracle RAC One Node is included with Standard Edition 2, whereas it incurs an extra cost in Enterprise Edition."}], "hint": "Recall the exact constraints listed for Standard Edition 2 regarding CDB count, PDB count, and processing threads.", "type": "multiple_choice"}, {"question": "According to technical documentation for IFS Applications 10, what constraint governs the Multitenant architecture deployment?", "answerOptions": [{"text": "Up to sixteen pluggable databases per container are supported", "isCorrect": false, "rationale": "Multiple PDBs per container are not supported for IFS Applications 10."}, {"text": "Oracle Multitenant is not supported or verified for IFS Applications 10", "isCorrect": false, "rationale": "Oracle Multitenant is supported and verified for IFS Applications 10 under the single-PDB restriction."}, {"text": "Up to three pluggable databases per container are supported", "isCorrect": false, "rationale": "While Oracle SE2 allows 3 PDBs generally, IFS Applications 10 support specifically limits deployment to one PDB per CDB."}, {"text": "Only one pluggable database per container is supported", "isCorrect": true, "rationale": "IFS Applications 10 documentation explicitly notes that although Oracle Multitenant is supported, only single-PDB container setups are verified."}], "hint": "Check the specific container-to-pluggable database ratio stated in the IFS Applications 10 compatibility matrix.", "type": "multiple_choice"}, {"question": "Which Oracle Management Pack is documented as required for generating Automatic Workload Repository (AWR) and Automatic Database Diagnostic Monitor (ADDM) reports?", "answerOptions": [{"text": "Oracle Diagnostics Pack", "isCorrect": true, "rationale": "IFS documentation states that Oracle Diagnostics Pack is verified on IFS Applications 9 and 10 and is required for AWR and ADDM."}, {"text": "Oracle Tuning Pack", "isCorrect": false, "rationale": "Oracle Tuning Pack requires Diagnostics Pack and provides SQL Tuning Advisor and Access Advisor, but AWR/ADDM fundamental data collection depends on Diagnostics Pack."}, {"text": "Oracle Database Lifecycle Management Pack", "isCorrect": false, "rationale": "Database Lifecycle Management Pack is not tested or verified for IFS Cloud and does not generate AWR or ADDM."}, {"text": "Oracle Cloud Management Pack for Oracle Database", "isCorrect": false, "rationale": "Oracle Cloud Management Pack is marked as not tested or verified for IFS Cloud."}], "hint": "Identify the management pack responsible for core performance data collection and diagnostic reports.", "type": "multiple_choice"}, {"question": "According to IFS Cloud documentation, which Oracle Database option is required to enable In-Memory column store functionality in IFS Applications 10?", "answerOptions": [{"text": "Oracle Real Application Clusters (Oracle RAC)", "isCorrect": false, "rationale": "Oracle RAC provides multi-node database clustering rather than column-store memory acceleration."}, {"text": "Oracle Advanced Compression", "isCorrect": false, "rationale": "Oracle Advanced Compression provides features like Advanced Row and LOB compression, not the In-Memory column store."}, {"text": "Oracle Database In-Memory", "isCorrect": true, "rationale": "The documentation specifies that utilizing In-Memory capabilities in IFS Applications 10 explicitly requires the Oracle Database In-Memory option."}, {"text": "Oracle Active Data Guard", "isCorrect": false, "rationale": "Active Data Guard provides read-only standby database replication, not in-memory processing."}], "hint": "Look for the specific option named after the feature required for column-store memory execution.", "type": "multiple_choice"}]}, "5": {"unit": 5, "unitTitle": "RAC and Grid Infrastructure", "title": "Oracle Quiz", "questions": [{"question": "Which component of the Oracle Grid Infrastructure stack is specifically responsible for managing cluster node membership and executing node evictions to prevent split-brain scenarios?", "answerOptions": [{"text": "Event Manager (EVM)", "isCorrect": false, "rationale": "EVM is tasked with publishing cluster events and alerts to initiate downstream routines rather than making membership and node eviction decisions."}, {"text": "Global Enqueue Service Daemon (LMD)", "isCorrect": false, "rationale": "LMD operates at the database instance layer to manage incoming remote resource requests rather than managing Grid Infrastructure node membership."}, {"text": "Cluster Ready Services (CRS)", "isCorrect": false, "rationale": "CRS focuses on managing high-availability resources such as VIPs, listeners, and database services rather than tracking raw node membership and split-brain eviction."}, {"text": "Cluster Synchronization Services (CSS)", "isCorrect": true, "rationale": "CSS tracks node membership across the cluster and handles eviction if a node loses communication or becomes unresponsive to maintain cluster integrity."}], "hint": "Think of the lower-level Clusterware daemon responsible for heartbeat monitoring and keeping nodes in sync.", "type": "multiple_choice"}, {"question": "How does Oracle RAC Cache Fusion share modified data blocks between active database instances in the cluster?", "answerOptions": [{"text": "By transmitting modified block updates over the public network via Virtual IP (VIP) addresses.", "isCorrect": false, "rationale": "The public network and VIPs are reserved for client connections, while Cache Fusion is strictly isolated to the private Interconnect."}, {"text": "By converting block updates into SQL statements and broadcasting them via Oracle GoldenGate.", "isCorrect": false, "rationale": "GoldenGate provides logical replication between separate databases, whereas Oracle RAC uses physical block synchronization across instances accessing the same database."}, {"text": "By forcing the holding instance to flush dirty blocks to ASM storage before the requesting node reads them.", "isCorrect": false, "rationale": "Forcing disk writes for block exchanges would introduce performance bottlenecks, which Cache Fusion explicitly avoids through inter-instance memory transfers."}, {"text": "By transferring data blocks directly memory-to-memory across a high-speed private Interconnect.", "isCorrect": true, "rationale": "Cache Fusion transfers data block images directly between instance SGAs over the private Interconnect without incurring disk write latency."}], "hint": "Consider how inter-instance memory sharing avoids slow storage I/O operations.", "type": "multiple_choice"}, {"question": "What is the primary role of the Global Resource Directory (GRD) in an active-active Oracle RAC environment?", "answerOptions": [{"text": "It routes client connections to the least-loaded database instance using TNS connection descriptors.", "isCorrect": false, "rationale": "Connection routing and workload distribution are performed by Oracle Net Services and SCAN listeners, not the GRD."}, {"text": "It tracks the state, location, and lock status of every cached data block across all cluster nodes.", "isCorrect": true, "rationale": "The GRD maintains global memory metadata to prevent dirty reads and guarantee transactional consistency across all active instances."}, {"text": "It acts as a lightweight log-forwarding service to asynchronous Data Guard standby databases.", "isCorrect": false, "rationale": "Log transport services are managed by Data Guard processes, whereas GRD coordinates internal cluster buffer cache resources."}, {"text": "It manages the physical space allocation of ASM disk groups across shared storage arrays.", "isCorrect": false, "rationale": "Physical storage extent allocation is handled by Automatic Storage Management (ASM), not by the GRD memory structures."}], "hint": "Focus on the shared memory tracking mechanism that prevents conflicting block updates.", "type": "multiple_choice"}, {"question": "Which background process in Oracle RAC records data file statuses, manages global data block access, and transmits block images between instance buffer caches?", "answerOptions": [{"text": "LMON (Global Enqueue Service Monitor)", "isCorrect": false, "rationale": "LMON monitors global enqueues and manages instance death and global resource recovery rather than handling block transfers."}, {"text": "ACMS (Atomic Controlfile to Memory Service)", "isCorrect": false, "rationale": "ACMS ensures distributed SGA updates are committed or terminated globally, but does not handle Cache Fusion block movement."}, {"text": "LMS (Global Cache Service Process)", "isCorrect": true, "rationale": "The LMS process handles message flow and transfers block images directly between SGA buffer caches as part of Cache Fusion."}, {"text": "LCK0 (Instance Enqueue Process)", "isCorrect": false, "rationale": "LCK0 handles non-Cache Fusion resource requests such as library and row cache locks rather than block transfers."}], "hint": "Look for the process designated specifically for Global Cache Service (GCS) messaging.", "type": "multiple_choice"}, {"question": "What primary recovery responsibility is assigned to the Global Enqueue Service Monitor (LMON) background process?", "answerOptions": [{"text": "Scrubbing bad sectors on ASM disks periodically to repair corruption.", "isCorrect": false, "rationale": "Automatic Hard Disk Scrub and Repair is an Exadata/ASM background function, not an LMON cluster daemon process."}, {"text": "Intercepting bad client connection requests and re-routing them to surviving SCAN listeners.", "isCorrect": false, "rationale": "SCAN listeners and client drivers manage connection failover, while LMON operates strictly inside the database cluster management layer."}, {"text": "Monitoring global resources across the cluster and managing recovery associated with instance deaths.", "isCorrect": true, "rationale": "LMON oversees cluster-wide health, handles instance death events, and orchestrates global resource reconfiguration following a failure."}, {"text": "Cleaning up dead client sessions and releasing uncommitted user transaction locks on local instances.", "isCorrect": false, "rationale": "Local session cleanup and lock releases are handled by standard database processes (like PMON/DGON), not LMON cluster recovery."}], "hint": "Recall which daemon manages global enqueue health and responds when an entire instance crashes.", "type": "multiple_choice"}, {"question": "Architecturally, how do storage requirements for an Oracle RAC database differ from a standard single-instance Oracle database?", "answerOptions": [{"text": "Redo log files must be stored locally on each node while data files are maintained on shared storage.", "isCorrect": false, "rationale": "Redo log threads must be stored on shared storage so surviving nodes can read a failed instance's redo logs during instance recovery."}, {"text": "Oracle RAC databases require cloud storage remote mirroring for basic data block updates.", "isCorrect": false, "rationale": "Oracle RAC requires cluster-aware shared disk access (such as ASM) within the data center, not cloud storage remote mirroring."}, {"text": "Each node in Oracle RAC must maintain an independent, mirrored copy of all data files on local non-networked storage.", "isCorrect": false, "rationale": "Storing separate local copies per instance describes a replicated or sharded topology, not the shared-everything architecture of RAC."}, {"text": "All data files, control files, SPFILEs, and redo logs must reside on cluster-aware shared storage accessible by all nodes.", "isCorrect": true, "rationale": "Oracle RAC uses a shared-everything storage model where every active instance must simultaneously access the shared set of database files."}], "hint": "Think about why surviving nodes need full access to all database structures during instance recovery.", "type": "multiple_choice"}, {"question": "Which two network communication protocols are supported for inter-instance messaging on the private Interconnect in Oracle RAC?", "answerOptions": [{"text": "Server Message Block (SMB) and Network File System (NFS)", "isCorrect": false, "rationale": "SMB and NFS are file-sharing protocols, not IPC communication protocols used for low-latency Cache Fusion transfers."}, {"text": "User Datagram Protocol (UDP) and Reliable Data Socket (RDS)", "isCorrect": true, "rationale": "Oracle RAC supports both UDP and RDS protocols for high-speed inter-instance IPC communication across the private Interconnect."}, {"text": "Transmission Control Protocol (TCP) and Hypertext Transfer Protocol (HTTP)", "isCorrect": false, "rationale": "TCP and HTTP are common application layer networks; they are not the supported high-efficiency IPC protocols for RAC Interconnect traffic."}, {"text": "Fibre Channel Protocol (FCP) and Internet Small Computer System Interface (iSCSI)", "isCorrect": false, "rationale": "FCP and iSCSI are storage transport protocols rather than IPC network protocols used between database instance SGAs."}], "hint": "Identify the low-latency network protocols designed specifically for interprocess communication (IPC).", "type": "multiple_choice"}, {"question": "According to the source documentation, how does Oracle RAC One Node operate differently from standard Oracle RAC during normal operation?", "answerOptions": [{"text": "Oracle RAC One Node requires local disk storage instead of shared ASM disk groups.", "isCorrect": false, "rationale": "Oracle RAC One Node uses shared storage to enable rapid instance failover and migration to another cluster node."}, {"text": "Oracle RAC One Node does not utilize Oracle Grid Infrastructure or Clusterware daemons.", "isCorrect": false, "rationale": "Oracle RAC One Node relies on the exact same Grid Infrastructure and Clusterware stack as standard Oracle RAC."}, {"text": "Oracle RAC One Node cannot perform rolling software maintenance across cluster nodes.", "isCorrect": false, "rationale": "During planned maintenance, Oracle RAC One Node allows two active instances temporarily to gracefully migrate workload with zero downtime."}, {"text": "Oracle RAC One Node runs only a single active database instance on one node at a time.", "isCorrect": true, "rationale": "Oracle RAC One Node is an active-passive failover solution that runs only one active instance under normal conditions, reducing memory overhead."}], "hint": "Consider the key operational difference between active-active multi-instance clustering and active-passive single-instance deployment.", "type": "multiple_choice"}, {"question": "How do Oracle integrated clients leverage Fast Application Notification (FAN) events during an unplanned database node failure?", "answerOptions": [{"text": "They trigger an automatic switchover of the primary role to a secondary disaster recovery site.", "isCorrect": false, "rationale": "Site-level switchovers are managed by Data Guard Fast-Start Failover or Oracle Site Guard, not by client FAN notifications."}, {"text": "They automatically repair block-level corruptions by requesting backup copies from the standby database.", "isCorrect": false, "rationale": "Automatic block repair is an Oracle Active Data Guard runtime feature, not a client-side FAN event routine."}, {"text": "They receive immediate state-change alerts to rapidly terminate dead connections and re-route connection pools.", "isCorrect": true, "rationale": "FAN events immediately notify connection pools of DOWN events, avoiding TCP timeout delays and enabling rapid client connection failover."}, {"text": "They initiate automated RMAN backup jobs on surviving cluster nodes to secure uncommitted transactions.", "isCorrect": false, "rationale": "RMAN backups are administrative database maintenance tasks unrelated to client application notification frameworks."}], "hint": "Think about how application connection pools avoid waiting on hung socket connections when a server abruptly crashes.", "type": "multiple_choice"}, {"question": "What is the primary administrative purpose of the SYSRAC privilege introduced in Oracle Database 12c Release 2 (12.2)?", "answerOptions": [{"text": "To enforce separation of duties by allowing clusterware agents to connect without requiring full SYSDBA privileges.", "isCorrect": true, "rationale": "SYSRAC provides designated administrative privileges for Oracle RAC utilities (like SRVCTL) and Clusterware agents, eliminating reliance on SYSDBA."}, {"text": "To allow external client applications to bypass Cache Fusion locking checks during bulk data loads.", "isCorrect": false, "rationale": "Cache Fusion lock checks cannot be bypassed by database privileges to ensure transactional consistency."}, {"text": "To permit read-only analytical queries on Reader Nodes without generating redo entries.", "isCorrect": false, "rationale": "Reader Nodes provide read-only reporting capabilities, but access to them does not depend on the SYSRAC administrative privilege."}, {"text": "To grant full operating system root access to database administrators during Clusterware installations.", "isCorrect": false, "rationale": "SYSRAC is a database administrative privilege, not an operating system root privilege."}], "hint": "Recall the security principle aimed at reducing excessive use of SYSDBA for routine cluster management.", "type": "multiple_choice"}, {"question": "Which action is taken by the Hang Manager (HM) background framework when a high-confidence database hang is detected in Oracle RAC?", "answerOptions": [{"text": "It analyzes process dependencies and automatically terminates the blocker process to preserve system availability.", "isCorrect": true, "rationale": "Hang Manager evaluates waiting sessions, identifies the root victim/blocker session, and terminates the blocker to resolve hangs automatically."}, {"text": "It dynamically allocates additional system RAM to the SGA to relieve memory pressure.", "isCorrect": false, "rationale": "Memory pressure management is handled by Memory Guard (by stopping service listeners), not by Hang Manager session termination."}, {"text": "It evicts the node from the Grid Infrastructure cluster immediately to trigger instance recovery.", "isCorrect": false, "rationale": "Node eviction is a Cluster Synchronization Services (CSS) action, whereas Hang Manager resolves hangs at the session level without evicting nodes when possible."}, {"text": "It immediately re-balances ASM disk extents across healthy storage failure groups.", "isCorrect": false, "rationale": "Rebalancing storage is an ASM disk management operation, whereas Hang Manager focuses on process blockages and deadlocks."}], "hint": "Focus on how Hang Manager resolves lock contention without requiring manual DBA intervention.", "type": "multiple_choice"}, {"question": "What benefit is provided by High Availability IP (HAIP) or Redundant Interconnect Usage within Oracle Grid Infrastructure?", "answerOptions": [{"text": "It provides active load balancing and seamless network failover across multiple physical NICs for Interconnect traffic.", "isCorrect": true, "rationale": "HAIP/Redundant Interconnect manages multiple private network interfaces to increase throughput and guarantee high availability if an Interconnect NIC fails."}, {"text": "It converts active-active RAC instances into single-instance active-passive failover nodes.", "isCorrect": false, "rationale": "HAIP optimizes internal private network traffic for RAC instances and does not alter the underlying database deployment model."}, {"text": "It enables synchronous block replication between primary and standby databases over WAN distances.", "isCorrect": false, "rationale": "WAN database replication is managed by Active Data Guard or Far Sync, not by Grid Infrastructure HAIP."}, {"text": "It automatically routes external application connections to the least busy SCAN listener.", "isCorrect": false, "rationale": "SCAN listener routing manages client public access, whereas HAIP operates strictly on the internal private Interconnect."}], "hint": "Consider how redundant physical network interface cards (NICs) are utilized for private cluster communication.", "type": "multiple_choice"}]}, "6": {"unit": 6, "unitTitle": "Data Guard, MAA Standards and Failover Operations", "title": "Oracle Quiz", "questions": [{"question": "Under Oracle Data Guard's Maximum Protection mode, what occurs to the primary database if network connectivity to all target standby databases is severed?", "answerOptions": [{"text": "The primary database falls back to asynchronous mode and continues servicing application transactions.", "isCorrect": false, "rationale": "Falling back to asynchronous mode while continuing transaction processing is the defining behavior of Maximum Availability mode, not Maximum Protection."}, {"text": "The primary database switches automatically to Maximum Performance mode without stopping transactions.", "isCorrect": false, "rationale": "Automated fallback to asynchronous transport without downtime describes Maximum Availability handling rather than Maximum Protection."}, {"text": "The primary database prompts mid-tier application connection pools to suspend threads while remaining online.", "isCorrect": false, "rationale": "Maximum Protection enforces a hard database instance shutdown rather than mid-tier thread suspension upon loss of synchronous standby connectivity."}, {"text": "The primary database automatically shuts down to prevent un-replicated commits and guarantee zero data loss.", "isCorrect": true, "rationale": "In Maximum Protection mode, if no qualified standby can acknowledge a synchronous redo write, the primary database halts immediately to ensure zero-data-loss compliance."}], "hint": "Consider how strict RPO = 0 enforcement impacts primary availability when network communication to the standby is completely lost.", "type": "multiple_choice"}, {"question": "According to Data Guard sizing rules, what is the standard formula for calculating the total number of Standby Redo Log (SRL) groups required for a RAC primary environment?", "answerOptions": [{"text": "(Threads × Online Groups) + 1 total", "isCorrect": false, "rationale": "Adding only one extra log group total across all threads fails to account for the rule of adding one extra group per individual thread."}, {"text": "(Threads × 2) + Online Groups per thread", "isCorrect": false, "rationale": "Adding double the thread count to online groups reverses the required multiplication of threads and online log groups."}, {"text": "(Threads × Online Groups) + 1 per thread", "isCorrect": true, "rationale": "The sizing guideline specifies configuring Standby Redo Log groups as the product of RAC threads and online log groups, plus one additional SRL group per thread."}, {"text": "(Threads + Online Groups) × 2", "isCorrect": false, "rationale": "Multiplying the sum of threads and groups by two miscalculates the required thread-by-group mapping formula."}], "hint": "Think about how online redo log groups per thread are multiplied and incremented based on each RAC thread.", "type": "multiple_choice"}, {"question": "What are the standard OEM warning and critical alert thresholds for Data Guard Apply Lag (Replication Lag)?", "answerOptions": [{"text": "Warning at 300 seconds (5 minutes) and Critical at 900 seconds (15 minutes)", "isCorrect": true, "rationale": "The OEM metric architecture specifies a 300-second warning threshold for apply lag and a 900-second threshold for critical alerts."}, {"text": "Warning at 900 seconds (15 minutes) and Critical at 3600 seconds (1 hour)", "isCorrect": false, "rationale": "A 900-second warning threshold misidentifies the level designated as critical in the OEM threshold architecture."}, {"text": "Warning at 60 seconds (1 minute) and Critical at 300 seconds (5 minutes)", "isCorrect": false, "rationale": "A 60-second warning and 300-second critical threshold setting is shorter than the 300/900 second standard detailed in the monitoring guidelines."}, {"text": "Warning at 150 seconds (2.5 minutes) and Critical at 600 seconds (10 minutes)", "isCorrect": false, "rationale": "Thresholds of 150 seconds and 600 seconds do not match the documented 5-minute (300s) and 15-minute (900s) boundaries."}], "hint": "Recall the metric thresholds measured in minutes (5 minutes for early warning, 15 minutes for critical severity).", "type": "multiple_choice"}, {"question": "Which component is introduced in the Oracle MAA Platinum Tier to enable zero-downtime online application schema upgrades alongside Active Data Guard and RAC?", "answerOptions": [{"text": "Single Client Access Name (SCAN) listeners", "isCorrect": false, "rationale": "SCAN listeners provide dynamic mid-tier connection failover, which is standard starting from RAC/Silver/Gold tiers."}, {"text": "Fast-Start Failover (FSFO)", "isCorrect": false, "rationale": "Fast-Start Failover is a feature of Data Guard Broker used to automate failover in Gold and Platinum tiers rather than an online schema redefinition tool."}, {"text": "Edition-Based Redefinition (EBR)", "isCorrect": true, "rationale": "MAA Platinum tier integrates Edition-Based Redefinition (EBR) and Oracle GoldenGate on top of Gold tier components to eliminate downtime during online application schema changes."}, {"text": "Standby Redo Logs (SRLs)", "isCorrect": false, "rationale": "Standby Redo Logs are standard components of physical standby replication in Data Guard (Gold tier) and do not handle online application redefinition."}], "hint": "Look for the database technology that allows new application editions to coexist with old editions during active operations.", "type": "multiple_choice"}, {"question": "In Oracle Database 19c Active Data Guard, which parameter controls the automatic redirection of DML statements from a read-only standby database to the primary database?", "answerOptions": [{"text": "STANDBY_FILE_MANAGEMENT", "isCorrect": false, "rationale": "STANDBY_FILE_MANAGEMENT=AUTO controls automatic datafile creation on the standby site when files are added to the primary."}, {"text": "LOG_ARCHIVE_CONFIG", "isCorrect": false, "rationale": "LOG_ARCHIVE_CONFIG defines the database unique names participating in Data Guard redo transport."}, {"text": "DG_BROKER_START", "isCorrect": false, "rationale": "DG_BROKER_START initializes the Data Guard Broker background processes (DMON) on database instances."}, {"text": "ADG_REDIRECT_DML", "isCorrect": true, "rationale": "ADG_REDIRECT_DML is the documented parameter introduced in Oracle 19c to enable and control DML redirection from Active Data Guard standby databases."}], "hint": "The parameter name explicitly combines the Active Data Guard abbreviation with its key redirection capability.", "type": "multiple_choice"}, {"question": "Prior to executing a planned switchover in Data Guard Broker (dgmgrl), which command checks database health and confirms readiness for role transition?", "answerOptions": [{"text": "SHOW REPLICATION HEALTH", "isCorrect": false, "rationale": "SHOW REPLICATION HEALTH is not a valid dgmgrl command; SHOW CONFIGURATION or VALIDATE DATABASE are used instead."}, {"text": "VALIDATE DATABASE <db_unique_name>", "isCorrect": true, "rationale": "Executing VALIDATE DATABASE in dgmgrl performs pre-flight readiness checks and reports whether a database is ready for switchover or failover."}, {"text": "ALTER DATABASE PREPARE SWITCHOVER", "isCorrect": false, "rationale": "ALTER DATABASE PREPARE SWITCHOVER is an older SQL command, whereas Broker management relies on dgmgrl commands such as VALIDATE DATABASE."}, {"text": "CHECK SWITCHOVER STATUS", "isCorrect": false, "rationale": "CHECK SWITCHOVER STATUS is not a valid dgmgrl command syntax; the broker uses VALIDATE DATABASE."}], "hint": "Think of the dgmgrl verb used to inspect specific database member readiness before initiating a role swap.", "type": "multiple_choice"}, {"question": "Setting STANDBY_FILE_MANAGEMENT=AUTO on a Data Guard physical standby database ensures which automated behavior?", "answerOptions": [{"text": "New datafiles created on the primary database are automatically created on the standby database.", "isCorrect": true, "rationale": "The STANDBY_FILE_MANAGEMENT=AUTO parameter configures Oracle to replicate datafile additions transparently without manual DBA intervention on the standby."}, {"text": "Database control files are automatically backed up whenever a tablespace is added.", "isCorrect": false, "rationale": "Control file auto-backups are managed by RMAN settings, not by STANDBY_FILE_MANAGEMENT."}, {"text": "Missing archive log gaps are automatically downloaded from remote RMAN backups.", "isCorrect": false, "rationale": "FAL (Fetch Archive Log) processes handle missing archive log gaps independently of STANDBY_FILE_MANAGEMENT."}, {"text": "Standby redo log files are resized automatically when online redo logs change on the primary.", "isCorrect": false, "rationale": "Resizing standby redo log files requires manual alter database commands or broker updates when online redo log sizes change."}], "hint": "Focus on how storage expansion operations for new data files on the primary affect the physical standby.", "type": "multiple_choice"}, {"question": "Which dynamic performance view is queried on an Active Data Guard standby database to monitor 'transport lag' and 'apply lag' metrics?", "answerOptions": [{"text": "V$DATABASE", "isCorrect": false, "rationale": "V$DATABASE provides overall database state such as database role and protection mode, but does not detail exact lag durations."}, {"text": "V$ARCHIVE_DEST_STATUS", "isCorrect": false, "rationale": "V$ARCHIVE_DEST_STATUS displays status and sequence numbers for archive destinations, but calculated lag durations are queried from V$DATAGUARD_STATS."}, {"text": "V$DATAGUARD_STATS", "isCorrect": true, "rationale": "V$DATAGUARD_STATS records current real-time metrics including transport lag, apply lag, and time computed on standby instances."}, {"text": "V$MANAGED_STANDBY", "isCorrect": false, "rationale": "V$MANAGED_STANDBY tracks recovery process activity rather than calculating discrete lag time statistics."}], "hint": "Look for the specific dynamic performance view name ending in STATS that tracks Data Guard replication latency.", "type": "multiple_choice"}, {"question": "What is the primary operational distinction between a Data Guard Switchover and a Data Guard Failover?", "answerOptions": [{"text": "Switchover requires database re-creation from RMAN backups afterward, whereas Failover preserves the original primary instance intact.", "isCorrect": false, "rationale": "Switchover requires no database re-creation, whereas a failed primary after failover may require flashback re-instantiation."}, {"text": "Switchover forces standby promotion after primary hardware failure, whereas Failover is performed for routine maintenance.", "isCorrect": false, "rationale": "Reversing the purposes of planned maintenance and emergency response contradicts the core definitions of switchover and failover."}, {"text": "Switchover operates strictly under Maximum Performance mode, whereas Failover requires Maximum Protection mode.", "isCorrect": false, "rationale": "Switchovers can occur in any protection mode, and failover is not restricted strictly to Maximum Protection mode."}, {"text": "Switchover is a planned, two-way role reversal with zero data loss, whereas Failover is an unplanned, one-way emergency promotion of a standby database.", "isCorrect": true, "rationale": "A switchover cleanly swaps primary and standby roles during planned events without data loss, while a failover forcibly promotes a standby following an unplanned primary outage."}], "hint": "Consider whether the event is planned or unplanned, and whether the role transition is two-way or one-way.", "type": "multiple_choice"}, {"question": "How does Transparent Application Continuity (TAC) mask database node failures from client applications in an MAA environment?", "answerOptions": [{"text": "TAC forces the application connection pool to abort uncommitted transactions and issue an immediate rollback to the user.", "isCorrect": false, "rationale": "Aborting transactions and exposing errors to users is what Application Continuity explicitly prevents."}, {"text": "TAC converts write operations into read-only queries during failover until the primary instance is restored.", "isCorrect": false, "rationale": "TAC does not alter SQL statement types; it safely replays transactions once connected to a healthy database instance."}, {"text": "TAC tracks session state inside the database, hides request errors, and replays in-flight transactions on a surviving instance.", "isCorrect": true, "rationale": "TAC rebuilds session state and replays held calls automatically without requiring application code changes, preventing mid-tier user-visible errors during node outages."}, {"text": "TAC buffers all SQL statements in mid-tier web server memory and resends them after a manual database restart.", "isCorrect": false, "rationale": "TAC operates inside the database and standard client drivers, rather than relying on custom mid-tier memory buffering logic."}], "hint": "Focus on how session state tracking inside the database enables in-flight call replay without application modifications.", "type": "multiple_choice"}, {"question": "In the Data Guard Broker command line interface (dgmgrl), which command executes a planned switchover to a target standby database named 'PRODSTBY'?", "answerOptions": [{"text": "FAILOVER TO 'PRODSTBY';", "isCorrect": false, "rationale": "FAILOVER TO initiates an unplanned emergency failover rather than a planned switchover role transition."}, {"text": "SET PRIMARY DATABASE TO 'PRODSTBY';", "isCorrect": false, "rationale": "SET PRIMARY DATABASE is invalid syntax in dgmgrl; SWITCHOVER TO is the required operational command."}, {"text": "ALTER DATABASE SWITCHOVER TO PRODSTBY;", "isCorrect": false, "rationale": "ALTER DATABASE SWITCHOVER TO... is SQL statement syntax, not the unified broker command used in dgmgrl."}, {"text": "SWITCHOVER TO 'PRODSTBY';", "isCorrect": true, "rationale": "In dgmgrl, issuing SWITCHOVER TO 'target_db' initiates the clean, automated role reversal process across both primary and standby databases."}], "hint": "Identify the concise dgmgrl verb designed specifically for planned role swaps to a target standby database.", "type": "multiple_choice"}, {"question": "According to the OEM metric threshold standards for database host infrastructure, what are the recommended Warning and Critical CPU utilization thresholds?", "answerOptions": [{"text": "Warning at 90% utilization and Critical at 99% utilization", "isCorrect": false, "rationale": "A 90% warning threshold delays early alerting, whereas the documented warning standard is set at 85%."}, {"text": "Warning at 75% utilization and Critical at 90% utilization", "isCorrect": false, "rationale": "75% and 90% do not match the documented 85% warning and 95% critical threshold values."}, {"text": "Warning at 85% utilization and Critical at 95% utilization", "isCorrect": true, "rationale": "OEM architecture rules set the host CPU warning alert at 85% over sustained intervals and the critical threshold at 95% CPU saturation."}, {"text": "Warning at 70% utilization and Critical at 85% utilization", "isCorrect": false, "rationale": "Setting a 70% warning threshold is lower than the 85% benchmark defined in the CPU threshold documentation."}], "hint": "Look for the pair of percentage values representing sustained high load (mid-80s) and severe saturation (mid-90s).", "type": "multiple_choice"}, {"question": "In Real-Time Redo Apply for Oracle Data Guard, which process on the standby database receives the incoming redo stream transmitted by the primary's LNS process?", "answerOptions": [{"text": "DMON (Data Guard Broker Monitor)", "isCorrect": false, "rationale": "DMON handles Data Guard Broker management configuration actions rather than log network transport."}, {"text": "RFS (Remote File Server)", "isCorrect": true, "rationale": "The RFS process runs on the standby database instance to receive redo data transmitted over the network by the primary's LNS process and write it into Standby Redo Logs."}, {"text": "DBW0 (Database Writer)", "isCorrect": false, "rationale": "DBW0 writes dirty database buffers to datafiles, not log network transport or standby log writing."}, {"text": "MRP0 (Managed Recovery Process)", "isCorrect": false, "rationale": "MRP0 (Managed Recovery Process) reads redo from Standby Redo Logs and applies changes to the standby database files."}], "hint": "Focus on the standby network background process whose acronym stands for Remote File Server.", "type": "multiple_choice"}]}, "7": {"unit": 7, "unitTitle": "Application Continuity and Resilience", "title": "Application Continuity Quiz", "questions": [{"question": "Which JDBC data source implementation class was introduced in Oracle Database 12c Release 2 (12.2.0.1) to support JDBC operation replay for XA-capable data sources paired with Universal Connection Pool (UCP) or WebLogic Active GridLink?", "answerOptions": [{"text": "oracle.jdbc.replay.OracleConnectionPoolDataSourceImpl", "isCorrect": false, "rationale": "This class is used for non-XA connection pool data sources in a standalone or pooled setup."}, {"text": "oracle.jdbc.replay.OracleDataSourceImpl", "isCorrect": false, "rationale": "This class provides non-XA standalone data source replay capabilities rather than XA-specific data source replay."}, {"text": "oracle.jdbc.replay.OracleXADataSourceFactory", "isCorrect": false, "rationale": "This class serves as the factory class for JNDI lookups rather than the concrete XA data source implementation class."}, {"text": "oracle.jdbc.replay.driver.OracleXADataSourceImpl", "isCorrect": true, "rationale": "Oracle Database 12c Release 2 introduced this specific class implementation for the XA Replay Data Source to support replay for applications using XA-capable data sources."}], "hint": "Focus on the implementation class under the driver sub-package specifically designated for XA data sources.", "type": "multiple_choice"}, {"question": "How does Transparent Application Continuity (TAC) primarily differ from standard Application Continuity (AC) regarding request boundary detection and application code modifications?", "answerOptions": [{"text": "Standard AC automatically tracks session state without Transaction Guard, whereas TAC strictly requires Transaction Guard to be disabled.", "isCorrect": false, "rationale": "Both AC and TAC depend on Transaction Guard (commit_outcome = TRUE) to enforce idempotence and verify commit status."}, {"text": "TAC requires manual call boundary declarations using beginRequest and endRequest APIs, whereas standard AC automates them completely.", "isCorrect": false, "rationale": "This statement reverses the boundary mechanisms; standard AC relies on explicit pool boundaries or explicit API calls, while TAC automates detection."}, {"text": "TAC disables session failover for all DML operations, whereas standard AC only replays SELECT queries.", "isCorrect": false, "rationale": "Both features support DML failover and replay; TAF was the legacy feature limited primarily to SELECT queries."}, {"text": "TAC utilizes a state-tracking infrastructure to discover implicit request boundaries automatically without code changes, whereas AC relies on explicit boundaries or connection pool check-in/check-out.", "isCorrect": true, "rationale": "TAC categorizes session state usage dynamically to detect implicit request boundaries, enabling session recovery without requiring knowledge of the application or code changes."}], "hint": "Consider how TAC achieves complete application transparency without requiring developer code changes.", "type": "multiple_choice"}, {"question": "When configuring an Oracle Database 19c database service using srvctl for Transparent Application Continuity (TAC), which combination of service parameter values is required?", "answerOptions": [{"text": "-failovertype TRANSACTION -failover_restore LEVEL1 -commit_outcome FALSE", "isCorrect": false, "rationale": "Setting failovertype to TRANSACTION configures standard manual Application Continuity, and commit_outcome must be TRUE for recovery."}, {"text": "-failovertype SELECT -failover_restore NONE -commit_outcome TRUE", "isCorrect": false, "rationale": "-failovertype SELECT configures legacy Transparent Application Failover (TAF) rather than Transparent Application Continuity."}, {"text": "-failovertype AUTO -failover_restore AUTO -commit_outcome TRUE", "isCorrect": true, "rationale": "Configuring -failovertype AUTO enables TAC, -failover_restore AUTO handles environment state restoration, and -commit_outcome TRUE activates Transaction Guard."}, {"text": "-failovertype AUTO -failover_restore NONE -commit_outcome FALSE", "isCorrect": false, "rationale": "TAC requires failover_restore to be AUTO to restore session state, and commit_outcome must be TRUE to enable Transaction Guard."}], "hint": "Recall the service attribute values that enable automated failover typing and environment restoration.", "type": "multiple_choice"}, {"question": "What core mechanism does Transaction Guard (TG) rely on to guarantee at-most-once transaction execution during failover replay?", "answerOptions": [{"text": "Disabling redo generation whenever an application borrows a connection from the pool.", "isCorrect": false, "rationale": "Redo log generation is essential for database logging and durability and is not disabled by Transaction Guard."}, {"text": "Forcing all DML calls to bypass the database buffer cache and write directly to secondary standby storage.", "isCorrect": false, "rationale": "Transaction Guard tracks logical transaction outcomes via LTXIDs rather than changing database memory buffer or block writing operations."}, {"text": "Assigning a globally unique Logical Transaction ID (LTXID) to each request to persistently store and check the commit outcome.", "isCorrect": true, "rationale": "Transaction Guard assigns an LTXID to session requests, enabling the database to verify whether a transaction committed before an outage occurred and preventing duplicate execution."}, {"text": "Rolling back all active transactions across the entire cluster as soon as a node crash is detected.", "isCorrect": false, "rationale": "Crashed nodes cannot actively execute rollbacks, and TG specifically inspects commit status to determine if replay is safe rather than blindly rolling back."}], "hint": "Look for the persistent identifier tracked across client and server to verify transaction outcomes.", "type": "multiple_choice"}, {"question": "How do standard Application Continuity (AC) and Transparent Application Continuity (TAC) handle external side effects (such as PL/SQL calls to UTL_SMTP or file transfers) by default during replay?", "answerOptions": [{"text": "Neither AC nor TAC allows any PL/SQL procedures or package calls to run during normal operation.", "isCorrect": false, "rationale": "PL/SQL execution is fully supported during normal operations under both AC and TAC."}, {"text": "Standard AC replays side effects by default unless explicitly disabled, whereas TAC detects side effects and suppresses capture/replay during their execution.", "isCorrect": true, "rationale": "Standard AC will replay side effects unless the application calls disableReplay(), whereas TAC automatically detects non-idempotent side effects and disables capture during those calls."}, {"text": "Both AC and TAC automatically replay all side effects without exception.", "isCorrect": false, "rationale": "TAC suppresses side-effect replay by default upon detecting external actions to prevent duplicate persistent changes."}, {"text": "Standard AC disables side-effect replay entirely, while TAC forces side effects to repeat until a confirmation signal is received.", "isCorrect": false, "rationale": "This reverses the default behaviors of both features regarding side-effect capture and execution."}], "hint": "Consider TAC's design principle regarding non-idempotent operations that leave persistent changes outside the database.", "type": "multiple_choice"}, {"question": "Which set of parameter values aligns with Oracle's High Availability connection string recommendations for Oracle Database 12.2 and higher client drivers?", "answerOptions": [{"text": "(CONNECT_TIMEOUT=3)(RETRY_COUNT=0)(RETRY_DELAY=0)(TRANSPORT_CONNECT_TIMEOUT=90)", "isCorrect": false, "rationale": "Zero retries and an excessively short CONNECT_TIMEOUT cause connection attempts to fail immediately during planned or unplanned outages."}, {"text": "(CONNECT_TIMEOUT=90)(RETRY_COUNT=50)(RETRY_DELAY=3)(TRANSPORT_CONNECT_TIMEOUT=3)", "isCorrect": true, "rationale": "This configuration sets a fast transport timeout to detect network issues quickly while allowing sufficient retries and connection time to navigate failovers cleanly."}, {"text": "(CONNECT_TIMEOUT=604800)(RETRY_COUNT=5)(RETRY_DELAY=300)(TRANSPORT_CONNECT_TIMEOUT=0)", "isCorrect": false, "rationale": "Setting an extremely high CONNECT_TIMEOUT (7 days) can cause middle-tier threads to hang indefinitely during major network disconnections."}, {"text": "(CONNECT_TIMEOUT=1)(RETRY_COUNT=1)(RETRY_DELAY=60)(TRANSPORT_CONNECT_TIMEOUT=0)", "isCorrect": false, "rationale": "A CONNECT_TIMEOUT of 1 second is too aggressive for pool requests, leading to frequent connection failures."}], "hint": "Identify the parameter combination that balances fast socket failure detection with patient attempt retries.", "type": "multiple_choice"}, {"question": "What key operational role does Fast Application Notification (FAN) play in High Availability connection management?", "answerOptions": [{"text": "It automatically creates missing indexes on foreign keys to prevent table lock contention.", "isCorrect": false, "rationale": "Foreign key indexing is a manual database design task, not a FAN event function."}, {"text": "It publishes out-of-band cluster status events so middle-tier connection pools immediately invalidate dead sessions and initiate session draining without waiting for TCP timeouts.", "isCorrect": true, "rationale": "FAN provides immediate notification of instance failures and maintenance events via ONS, allowing connection pools to terminate bad connections instantly and rebalance workloads."}, {"text": "It replays uncommitted transactions locally within the application server's heap memory.", "isCorrect": false, "rationale": "Replay logic is handled by the JDBC Replay Driver or OCI layer, not by FAN events."}, {"text": "It enforces source-side deduplicated backups for RMAN Level 1 incremental routines.", "isCorrect": false, "rationale": "RMAN backup optimizations rely on Block Change Tracking (BCT), not FAN notifications."}], "hint": "Focus on how FAN prevents client connection pools from hanging when network connections or nodes fail.", "type": "multiple_choice"}, {"question": "When using a Java ConnectionInitializationCallback with Application Continuity, when is the callback's initialize(Connection connection) method invoked?", "answerOptions": [{"text": "Asynchronously in a background thread after the replay request has fully committed.", "isCorrect": false, "rationale": "The callback must run synchronously prior to starting request replay so that the session initial state is identical to runtime."}, {"text": "At each successful reconnection following a recoverable error, before request replay begins.", "isCorrect": true, "rationale": "The initialization callback executes post-reconnection to re-establish the required initial session state (such as ALTER SESSION calls) before the replay driver replays saved calls."}, {"text": "Before every individual SELECT or DML statement executed inside a request.", "isCorrect": false, "rationale": "The callback is executed only during session recovery reconnection, not on every individual SQL call."}, {"text": "Only when the database instance is initially created during installation.", "isCorrect": false, "rationale": "Connection initialization callbacks are client-side objects executed when connections fail over at runtime."}], "hint": "Consider the exact moment when initial session states (like NLS settings or ALTER SESSION) must be established after failover.", "type": "multiple_choice"}, {"question": "What is the primary objective of service connection draining during planned maintenance on an Oracle RAC node?", "answerOptions": [{"text": "To convert transactional DML into read-only reporting queries automatically.", "isCorrect": false, "rationale": "Draining manages connection lifecycles during maintenance and does not modify SQL statement types."}, {"text": "To migrate physical datafiles from local ASM storage to remote Data Guard standby hosts.", "isCorrect": false, "rationale": "Datafile migration is a storage administration process separate from service session draining."}, {"text": "To allow active database requests to finish gracefully within the drain_timeout period while preventing new connections, before taking the service offline.", "isCorrect": true, "rationale": "Draining marks active sessions and waits for them to complete current requests naturally before stopping the service or instance per the stopoption."}, {"text": "To immediately abort all active middle-tier sessions and force an emergency switchover.", "isCorrect": false, "rationale": "Draining seeks to avoid abrupt session termination by allowing active work to conclude gracefully."}], "hint": "Think about how session draining hides planned maintenance by giving running requests time to complete.", "type": "multiple_choice"}, {"question": "Which diagnostic utility, included with Oracle ORAchk, analyzes application trace files or code to report Application Continuity protection coverage and flag deprecated concrete classes?", "answerOptions": [{"text": "TKPROF", "isCorrect": false, "rationale": "TKPROF formats SQL trace files for execution plan and timing performance analysis, not AC coverage analysis."}, {"text": "RMAN", "isCorrect": false, "rationale": "RMAN is Oracle's Recovery Manager for physical database backup, restore, and recovery."}, {"text": "srvctl", "isCorrect": false, "rationale": "srvctl is the Grid Infrastructure utility for managing cluster resources, services, and instances."}, {"text": "ACCHK (acchk)", "isCorrect": true, "rationale": "ACCHK evaluates application trace files and application binaries to calculate the percentage of calls protected by Application Continuity and check for incompatible concrete classes."}], "hint": "Identify the tool whose name explicitly refers to Application Continuity checking.", "type": "multiple_choice"}, {"question": "If an application uses mutable functions such as SYSDATE, SYS_GUID, or sequence.NEXTVAL, what must be done to retain original runtime values during an Application Continuity replay?", "answerOptions": [{"text": "Mutable functions must be called inside autonomous transactions with COMMIT_OUTCOME set to FALSE.", "isCorrect": false, "rationale": "Autonomous transactions do not automatically grant mutable retention permissions and can complicate replay."}, {"text": "The JDBC driver automatically changes the server system clock during replay without requiring database grants.", "isCorrect": false, "rationale": "Function results are kept and restored via database privileges; the driver does not manipulate server clocks."}, {"text": "The developer must replace all database sequences with random client-side UUID variables.", "isCorrect": false, "rationale": "Application Continuity explicitly supports database sequences when the KEEP clause or grant is applied."}, {"text": "The DBA must grant KEEP privileges (e.g., GRANT KEEP DATE TIME, KEEP SYSGUID, or ALTER SEQUENCE ... KEEP) to the relevant application user or sequence object.", "isCorrect": true, "rationale": "Granting KEEP privileges permits Application Continuity to save original function values at runtime and restore them during replay so key values match."}], "hint": "Recall the explicit SQL privilege clause required to preserve non-deterministic function results across failover replay.", "type": "multiple_choice"}, {"question": "Which feature introduced in Oracle Database 23ai enhances Application Continuity by enabling reliable session state checkpointing and restoration?", "answerOptions": [{"text": "Database Templates for session state restoration.", "isCorrect": true, "rationale": "Database Templates in 23ai provide automated checkpointing and restoration of session states, broadening AC applicability and reducing reliance on custom callbacks."}, {"text": "Mandatory deprecation of thin JDBC drivers in favor of thick OCI drivers.", "isCorrect": false, "rationale": "Oracle 23ai auto-enables AC in JDBC thin drivers rather than deprecating them."}, {"text": "Complete removal of Transaction Guard and Fast Application Notification.", "isCorrect": false, "rationale": "Transaction Guard and FAN remain vital components of the MAA high availability framework in 23ai."}, {"text": "Requirement to call disableReplay() before executing any standard SQL statement.", "isCorrect": false, "rationale": "disableReplay() is used selectively to prevent replay of specific side effects, not on standard SQL statements."}], "hint": "Think of the 23ai capability introduced to capture and re-establish complex session environments automatically during replay.", "type": "multiple_choice"}]}, "8": {"unit": 8, "unitTitle": "Performance Management and Tuning", "title": "Oracle Quiz", "questions": [{"question": "Which metric does the Automatic Database Diagnostic Monitor (ADDM) center its performance analysis around to evaluate the impact of system bottlenecks?", "answerOptions": [{"text": "Hard Parses per Second", "isCorrect": false, "rationale": "Hard parsing rates highlight library cache efficiency, but ADDM evaluates overall system impact through session work duration."}, {"text": "Redo Size per Second", "isCorrect": false, "rationale": "Redo generation rate reflects transactional throughput but is not the core metric ADDM uses to rank bottleneck impact."}, {"text": "DB Time", "isCorrect": true, "rationale": "ADDM quantifies performance issues based on the percentage of total non-idle session call time accumulated by the database."}, {"text": "Elapsed Time", "isCorrect": false, "rationale": "Elapsed Time represents total wall-clock time between snapshots, whereas ADDM specifically targets non-idle database session activity."}], "hint": "Consider the key metric that combines CPU time and non-idle wait time across active session calls.", "type": "multiple_choice"}, {"question": "Which Oracle background process is responsible for periodically flushing Active Session History (ASH) in-memory data into AWR repository tables on disk?", "answerOptions": [{"text": "RVWR (Recovery Writer)", "isCorrect": false, "rationale": "RVWR is dedicated to writing flashback database logs when Flashback Database is enabled."}, {"text": "DBWR (Database Writer)", "isCorrect": false, "rationale": "DBWR writes modified data blocks from the SGA buffer cache to physical data files."}, {"text": "MMON (Memory Monitor)", "isCorrect": true, "rationale": "The Memory Monitor process automatically transfers sampled active session data from SGA ring buffers to disk tables during snapshot operations."}, {"text": "LGWR (Log Writer)", "isCorrect": false, "rationale": "LGWR handles flushing redo log buffer contents to online redo log files, not SGA performance telemetry."}], "hint": "Identify the background process dedicated to managing background performance diagnostics and repository statistics.", "type": "multiple_choice"}, {"question": "Which SQL*Plus diagnostic script generates an AWR Compare Period report for single-instance Oracle environments to evaluate performance changes across patch updates?", "answerOptions": [{"text": "addmrpt.sql", "isCorrect": false, "rationale": "This script generates an ADDM root-cause analysis report for a single pair of AWR snapshots rather than comparing two distinct operational windows."}, {"text": "awrrpt.sql", "isCorrect": false, "rationale": "This standard script generates a baseline AWR report for a single snapshot range rather than a comparative diff between two windows."}, {"text": "awrddrpt.sql", "isCorrect": true, "rationale": "This script prompts for two distinct snapshot pairs to generate a side-by-side performance delta report in single-instance databases."}, {"text": "awrddrpi.sql", "isCorrect": false, "rationale": "This specific script variation is designed for Real Application Clusters (RAC) environments rather than single-instance databases."}], "hint": "Look for the standard reporting script name containing 'dd' to signify double-differential analysis for single instances.", "type": "multiple_choice"}, {"question": "What sampling interval does Active Session History (ASH) use to record active database session details inside the SGA ring buffer?", "answerOptions": [{"text": "Every 1 second", "isCorrect": true, "rationale": "ASH samples active sessions every second in memory, making it effective for catching transient performance spikes."}, {"text": "Every 60 minutes", "isCorrect": false, "rationale": "Hourly intervals correspond to the default frequency of AWR snapshots rather than real-time ASH sampling."}, {"text": "Every 5 seconds", "isCorrect": false, "rationale": "While granular, ASH's actual in-memory sampling engine runs at a faster frequency."}, {"text": "Every 10 seconds", "isCorrect": false, "rationale": "Ten-second intervals smooth out transient spikes that ASH's finer sampling granularity is designed to capture."}], "hint": "Think about the sub-minute rate needed to catch brief I/O or locking bottlenecks.", "type": "multiple_choice"}, {"question": "When diagnosing user I/O issues, which wait event typically signifies single-block data reads associated with index lookups or nested loop join operations?", "answerOptions": [{"text": "db file sequential read", "isCorrect": true, "rationale": "Single-block access paths reading contiguous index or table blocks generate this specific wait event."}, {"text": "db file scattered read", "isCorrect": false, "rationale": "This event indicates multi-block read operations typically associated with full table scans."}, {"text": "direct path read", "isCorrect": false, "rationale": "This event indicates read operations that bypass the SGA buffer cache directly into session PGA memory."}, {"text": "buffer busy waits", "isCorrect": false, "rationale": "This wait event indicates session contention when attempting to access a block currently pinned or read by another session."}], "hint": "Recall the wait event name used when blocks are read one by one sequentially into memory.", "type": "multiple_choice"}, {"question": "Which database wait event is raised when multiple sessions attempt to update or delete the same rows concurrently without committing?", "answerOptions": [{"text": "enq: ST - contention", "isCorrect": false, "rationale": "This event relates to space management allocation in dictionary-managed tablespaces."}, {"text": "latch: cache buffers chains", "isCorrect": false, "rationale": "This latch event indicates memory-level contention for hot blocks in the buffer cache hash buckets."}, {"text": "enq: TX - row lock contention", "isCorrect": true, "rationale": "Transaction enqueues in row lock mode occur when a session waits for another uncommitted transaction to release its row lock."}, {"text": "library cache pin", "isCorrect": false, "rationale": "This event controls object execution concurrency in the shared pool rather than application row locks."}], "hint": "Focus on the transaction enqueue event associated with row-level locking.", "type": "multiple_choice"}, {"question": "Exceeding which initialization parameter limit results in an ORA-00020 error in Oracle Database?", "answerOptions": [{"text": "open_cursors", "isCorrect": false, "rationale": "Exceeding the open_cursors per-session limit raises ORA-01000 rather than ORA-00020."}, {"text": "pga_aggregate_target", "isCorrect": false, "rationale": "PGA target limits cause work areas to spill to temporary tablespaces rather than rejecting new connection processes."}, {"text": "processes", "isCorrect": true, "rationale": "The static processes parameter caps total OS user processes connecting to the database; reaching this limit triggers ORA-00020."}, {"text": "sga_target", "isCorrect": false, "rationale": "Reaching SGA memory boundaries leads to allocation errors such as ORA-04031 rather than process rejection errors."}], "hint": "Select the static parameter that governs instance-wide operating system connection slots.", "type": "multiple_choice"}, {"question": "Which dynamic function call in the DBMS_XPLAN package allows a DBA to inspect runtime execution plan metrics, comparing Estimated Rows (E-Rows) against Actual Rows (A-Rows)?", "answerOptions": [{"text": "DBMS_STATS.GATHER_TABLE_STATS", "isCorrect": false, "rationale": "GATHER_TABLE_STATS collects schema statistics for the optimizer rather than displaying query execution plans."}, {"text": "DBMS_XPLAN.DISPLAY_SQLSET", "isCorrect": false, "rationale": "DISPLAY_SQLSET extracts plans stored within a SQL Tuning Set rather than runtime memory cursors."}, {"text": "DBMS_XPLAN.DISPLAY_CURSOR", "isCorrect": true, "rationale": "Using DISPLAY_CURSOR with the 'ALLSTATS LAST' format retrieves actual runtime row counts and execution statistics directly from memory."}, {"text": "DBMS_XPLAN.DISPLAY_AWR", "isCorrect": false, "rationale": "DISPLAY_AWR formats historical execution plans stored on disk rather than active cursor statistics from the SGA."}], "hint": "Identify the function used to fetch cursor plans directly out of the shared SQL area.", "type": "multiple_choice"}, {"question": "Which initialization parameter sets an instance-wide limit for non-shared memory allocated to session work areas such as sort operations and hash joins?", "answerOptions": [{"text": "db_cache_size", "isCorrect": false, "rationale": "db_cache_size specifies memory allocated exclusively to caching data blocks within the SGA."}, {"text": "sga_target", "isCorrect": false, "rationale": "sga_target manages shared memory structures including the buffer cache and shared pool."}, {"text": "pga_aggregate_target", "isCorrect": true, "rationale": "This parameter establishes an instance-wide target for total private process memory allocated across active database sessions."}, {"text": "open_cursors", "isCorrect": false, "rationale": "open_cursors defines the maximum statement handle count a single session can maintain simultaneously."}], "hint": "Look for the aggregate target parameter that controls Program Global Area allocations.", "type": "multiple_choice"}, {"question": "As a general rule of thumb, how much free disk space should be provisioned at the auxiliary destination during an RMAN Table Point-in-Time Recovery (PITR)?", "answerOptions": [{"text": "Space equal to the SGA and PGA memory parameters combined", "isCorrect": false, "rationale": "Auxiliary destination requirements dictate physical disk storage for data files rather than instance memory allocation limits."}, {"text": "Space for SYSTEM + SYSAUX + active UNDO + the target tablespace (approx. 2x the target tablespace)", "isCorrect": true, "rationale": "RMAN table PITR provisions an auxiliary instance requiring core system tablespaces alongside the tablespace housing the recovered table."}, {"text": "Space strictly equal to the size of the dropped table's export dump", "isCorrect": false, "rationale": "RMAN must reconstruct systemic data files during recovery, requiring significantly more space than just the target table."}, {"text": "Space equal to 10% of the entire database backup size", "isCorrect": false, "rationale": "Auxiliary space depends on specific tablespace data file sizes rather than a percentage of total database backups."}], "hint": "Consider all the system and undo data files required to create an auxiliary database instance alongside the target table's tablespace.", "type": "multiple_choice"}]}, "9": {"unit": 9, "unitTitle": "Monitoring, Alerting and Incident Management", "title": "IFS Quiz", "questions": [{"question": "In IFS Cloud 25R1 EFK stack log monitoring, what is the default data retention period for Elasticsearch logs before older records are deleted by the daily curator-cronjob?", "answerOptions": [{"text": "24 hours", "isCorrect": false, "rationale": "Although the curator-cronjob runs daily, it retains data for up to 7 full days rather than purging logs every 24 hours."}, {"text": "14 days", "isCorrect": false, "rationale": "This duration exceeds the standard 7-day retention period maintained by the daily curator cronjob."}, {"text": "7 days", "isCorrect": true, "rationale": "Elasticsearch data retention in IFS Cloud 25R1 is set to 7 days, after which a daily curator-cronjob checks and removes older log entries."}, {"text": "30 days", "isCorrect": false, "rationale": "This period is significantly longer than the 7-day log retention window configured for Elasticsearch storage."}], "hint": "Think about the daily scheduled cronjob that cleans up historical log data in Elasticsearch.", "type": "multiple_choice"}, {"question": "Which core Oracle Enterprise Manager (OEM) component runs as a middle-tier Java EE application on Oracle WebLogic Server to process metrics, render the management console, and dispatch administrative jobs?", "answerOptions": [{"text": "Oracle Management Agent (OMA)", "isCorrect": false, "rationale": "The OMA is a lightweight process deployed directly on host servers to collect target metrics rather than acting as the WebLogic middle-tier service."}, {"text": "Management Plug-in", "isCorrect": false, "rationale": "Plug-ins are modular software extensions used to extend monitoring capabilities rather than serving as the central middle-tier application server."}, {"text": "Oracle Management Repository (OMR)", "isCorrect": false, "rationale": "The OMR is a dedicated Oracle Database schema storing configuration and metric data rather than the Java EE middle-tier application."}, {"text": "Oracle Management Service (OMS)", "isCorrect": true, "rationale": "The OMS functions as the middle-tier Java EE application running on WebLogic Server to process agent metrics and render the browser-based Cloud Control management console."}], "hint": "Consider the middle-tier application server component responsible for rendering the administrative web interface.", "type": "multiple_choice"}, {"question": "When troubleshooting delayed telemetry following an IFS deployment, which command should an administrator execute on a host node to force immediate metric synchronization from the Oracle Management Agent (OMA) to the OMS?", "answerOptions": [{"text": "./emctl start oma", "isCorrect": false, "rationale": "The command to manage agent processes uses `emctl start agent` rather than `start oma`, and starting the agent does not manually trigger an immediate upload step."}, {"text": "./emctl status agent", "isCorrect": false, "rationale": "Running `status agent` inspects process health and upload connection status without forcing a manual payload transfer."}, {"text": "./emctl sync repository", "isCorrect": false, "rationale": "This is not a standard emctl command syntax for triggering agent metric uploads."}, {"text": "./emctl upload agent", "isCorrect": true, "rationale": "Executing `./emctl upload agent` forces immediate metric synchronization, transferring accumulated payload files directly to the OMS repository."}], "hint": "Focus on the specific emctl sub-command designed to push collected telemetry payload files immediately.", "type": "multiple_choice"}, {"question": "Which repository view inside the sysman schema can DBAs query to inspect recent critical incidents logged in the central Oracle Management Repository (OMR)?", "answerOptions": [{"text": "sysman.oem_events_hist", "isCorrect": false, "rationale": "Raw target events are managed separately from promoted actionable operational incidents stored in `em_incidents`."}, {"text": "sysman.mgmt_system_alerts", "isCorrect": false, "rationale": "OEM relies on the dedicated `sysman.em_incidents` view for tracking and querying critical incident records."}, {"text": "sysman.em_alert_logs", "isCorrect": false, "rationale": "This view name does not represent the repository table holding OEM operational incident lifecycle data."}, {"text": "sysman.em_incidents", "isCorrect": true, "rationale": "OEM logs tracked incidents, creation dates, and severity levels inside the `sysman.em_incidents` repository view."}], "hint": "Look for the specific view named directly after the incident management framework entities in OEM.", "type": "multiple_choice"}, {"question": "In IFS Cloud 26R2 Application Monitoring Metrics (AMM), what concept is defined as providing the operational health status (Critical, Warning, OK, or Unknown) for a metric based on supplied thresholds?", "answerOptions": [{"text": "Service Group", "isCorrect": false, "rationale": "A Service Group is used to group one or more services together to simplify administration and configuration."}, {"text": "Expression", "isCorrect": false, "rationale": "An Expression represents a logical description in documentation explaining how to determine a Service Group status rather than evaluating individual metric status."}, {"text": "Metric Group", "isCorrect": false, "rationale": "This term is not one of the formal AMM concepts defined for evaluating and reporting metric status."}, {"text": "Service", "isCorrect": true, "rationale": "In AMM concepts, a Service provides the operational health status for a metric by evaluating supplied threshold values."}], "hint": "Identify the structural element that evaluates metric values against threshold limits to determine health status.", "type": "multiple_choice"}, {"question": "In IFS Cloud 26R2 Application Monitoring Metrics (AMM), how frequently is the BATCH_QUEUE_CONFIG metric sampled to verify whether background work queues are defined?", "answerOptions": [{"text": "Every minute", "isCorrect": false, "rationale": "One-minute sampling intervals are utilized for rapid queue tracking metrics such as `QUEUE_EXEC` or `QUEUE_ERROR`."}, {"text": "Every 2 hours", "isCorrect": false, "rationale": "Two-hour intervals are used for longer-term monitoring metrics such as `DEFERRED_JOBS_EXECUTING_12H`."}, {"text": "Every 24 hours", "isCorrect": false, "rationale": "Daily sampling intervals are reserved for static checks like application system certificates (`CERT_APP_SYSTEM`)."}, {"text": "Every 10 minutes", "isCorrect": true, "rationale": "The `BATCH_QUEUE_CONFIG` metric is sampled every 10 minutes to verify whether any background work queues are defined in the system."}], "hint": "Recall the standard short interval shared by several batch queue configuration checks.", "type": "multiple_choice"}, {"question": "On the Custom Field Runtime Performance Overview screen in IFS Cloud 26R2, what automatic filtering criterion is applied to isolate slow SQL statements?", "answerOptions": [{"text": "Elapsed Time / Exec (s) greater than 2 seconds", "isCorrect": true, "rationale": "The Custom Field Runtime Performance screen automatically filters for custom field queries where the average elapsed time per execution exceeds 2 seconds."}, {"text": "CPU Time / Exec (s) greater than 10 seconds", "isCorrect": false, "rationale": "CPU time per execution is tracked in the table display, but the primary automatic filter criterion targets average elapsed time exceeding 2 seconds."}, {"text": "Accumulated physical I/O reads exceeding 1,000 blocks", "isCorrect": false, "rationale": "Physical I/O metrics are collected for database capacity trending, but do not form the filter logic for this custom field screen."}, {"text": "Blocked database sessions waiting over 5 seconds", "isCorrect": false, "rationale": "Database lock waits are monitored using specific database tier metrics (`BLOCKED_SESSIONS`) rather than the Custom Field Runtime Performance Overview screen."}], "hint": "Consider the specific threshold for average execution duration used by this custom field overview page.", "type": "multiple_choice"}, {"question": "In IFS Cloud 26R2 Server Alert Log Categories, which field specifies the duration for retaining log records when Heavy Cleanup runs?", "answerOptions": [{"text": "Cleanup Interval", "isCorrect": false, "rationale": "Cleanup interval refers to the schedule or frequency of cleanup tasks rather than the specific number of days log entries are kept."}, {"text": "Expiry Threshold", "isCorrect": false, "rationale": "This parameter name is not present in the IFS Cloud Server Alert Log Categories configuration interface."}, {"text": "Retention Period", "isCorrect": false, "rationale": "While describing log retention conceptually, the exact field name in the Server Log Categories form is 'Days to keep'."}, {"text": "Days to keep", "isCorrect": true, "rationale": "The 'Days to keep' column in the Server Log Categories configuration screen defines how many days a log is retained before Heavy Cleanup purges it."}], "hint": "Think of the specific column name in the Server Log Categories configuration table that specifies a number of days.", "type": "multiple_choice"}, {"question": "In IFS Cloud 26R2, which scheduled job controls the lifecycle of background tasks and updates their state so end users can receive Streams notifications upon completion?", "answerOptions": [{"text": "Batch_SYS.New_Batch_Schedule__", "isCorrect": false, "rationale": "This API posts new scheduled batch jobs rather than executing pending jobs and updating completion state information."}, {"text": "Transaction_SYS.Process_All_Pending__", "isCorrect": true, "rationale": "The `Transaction_SYS.Process_All_Pending__` procedure runs background jobs and updates their completion state to notify end users via Streams for Background Jobs and Reports."}, {"text": "Event_SYS.Execute_Actions__", "isCorrect": false, "rationale": "Event actions handle custom business event execution rather than background job lifecycle state updates."}, {"text": "Stream_SYS.Notify_User__", "isCorrect": false, "rationale": "Background job Streams notifications rely on underlying transaction processing jobs rather than a standalone `Stream_SYS` execution package."}], "hint": "Focus on the system procedure named for processing all pending transactions in the background job framework.", "type": "multiple_choice"}, {"question": "In Oracle Enterprise Manager Cloud Control, what feature should administrators configure during planned maintenance windows to temporarily suppress notifications and avoid false alerts?", "answerOptions": [{"text": "Administrative Blackouts", "isCorrect": true, "rationale": "Administrative Blackouts are scheduled during maintenance windows to suppress notification dispatches and prevent false-positive alerts across managed targets."}, {"text": "Subscriber Suppression Mode", "isCorrect": false, "rationale": "Suppressing alerts during maintenance is managed at the target or system level using Blackouts rather than modifying individual subscriber settings."}, {"text": "Notification Rules Override", "isCorrect": false, "rationale": "OEM relies on scheduled Blackouts rather than ad-hoc rule overrides to pause notification pipelines during maintenance."}, {"text": "Metric Disablement", "isCorrect": false, "rationale": "Disabling metrics stops metric collection entirely rather than scheduling a temporary suppression window for planned maintenance."}], "hint": "Look for the formal OEM feature designed specifically to temporarily pause monitoring alerts during scheduled downtime.", "type": "multiple_choice"}, {"question": "In IFS Cloud 25R1 EFK stack log monitoring, which query language is used within the Kibana interface to filter and query log data stored in Elasticsearch?", "answerOptions": [{"text": "Elasticsearch SQL (E-SQL)", "isCorrect": false, "rationale": "KQL is specifically designated in the documentation as the query language used for Kibana log discovery and filtering."}, {"text": "Fluentd Search Syntax (FSS)", "isCorrect": false, "rationale": "Fluentd acts as the log collection agent/shipper rather than providing a query language for Kibana."}, {"text": "Lucene Expression Language (LEL)", "isCorrect": false, "rationale": "The documentation specifies KQL (Kibana Query Language) for querying Elasticsearch log indices."}, {"text": "Kibana Query Language (KQL)", "isCorrect": true, "rationale": "KQL is the query language used inside Kibana search filter text boxes to query log data stored in Elasticsearch."}], "hint": "Recall the native query language abbreviation specific to Kibana interface search fields.", "type": "multiple_choice"}, {"question": "What default bidirectional TCP port is used by the Oracle Management Agent (OMA) to communicate securely with the central Oracle Management Service (OMS)?", "answerOptions": [{"text": "3872", "isCorrect": true, "rationale": "Oracle Management Agents communicate with the central OMS middle tier over default bidirectional TCP port 3872 using HTTP/HTTPS."}, {"text": "1521", "isCorrect": false, "rationale": "Port 1521 is the standard Oracle Database listener port rather than the OEM agent communication port."}, {"text": "8080", "isCorrect": false, "rationale": "Port 8080 is a generic HTTP port, whereas OEM agent telemetry communication defaults to port 3872."}, {"text": "7001", "isCorrect": false, "rationale": "Port 7001 is typically standard for WebLogic Server administration console connections rather than agent-to-OMS communication."}], "hint": "Identify the standard OEM agent port number referenced in the agent administration topology notes.", "type": "multiple_choice"}]}}};
